window.SITE_DATA = Object.assign(window.SITE_DATA || {}, {"errorCodes":[{"code":"0x800F0983","title":"CBS 매니페스트 손상 오류","overview":"누적 업데이트 설치 도중 구성 요소 기반 서비스(CBS) 매니페스트가 손상되었거나 일치하지 않을 때 나타나는 코드로, 설치가 진행되다 특정 지점에서 롤백되는 증상으로 이어집니다. 2026년 8월 패치 이후 신고가 늘었습니다.","summary":"누적 업데이트 설치 중 CBS 매니페스트 손상으로 설치가 롤백될 때 나타나는 코드입니다.","causes":["구성 요소 저장소(WinSxS)의 매니페스트 정보가 손상되었거나 이전 업데이트와 충돌하는 경우","이전 업데이트가 중간에 실패하거나 강제 종료되어 잔여 파일이 남아있는 경우","디스크 오류로 업데이트 패키지 파일 일부가 손상된 경우","타사 최적화 프로그램이 시스템 파일을 임의로 수정하거나 삭제한 경우","장기간 업데이트를 미뤄 여러 버전 차이가 누적된 경우"],"checks":["명령 프롬프트(관리자)에서 DISM /Online /Cleanup-Image /ScanHealth로 손상 여부를 확인하세요.","손상이 확인되면 DISM /Online /Cleanup-Image /RestoreHealth로 복구한 뒤 sfc /scannow를 실행하세요.","Windows Update 서비스를 중지하고 SoftwareDistribution·catroot2 폴더 이름을 바꿔 캐시를 초기화하세요.","복구 후에도 실패하면 업데이트 어시스턴트나 미디어 생성 도구로 최신 버전을 수동 설치해 보세요.","반복된다면 이벤트 뷰어의 CBS 로그(%windir%\\Logs\\CBS\\CBS.log)에서 구체적으로 손상된 구성 요소를 확인하세요."],"link":"error-code-0x800f0983.html","detailPage":"error-code-0x800f0983.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x800F0983)로 반복 실패한다면 무한정 재시도하기보다 DISM 복구와 업데이트 캐시 초기화를 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"2026년 8월 패치와 관련이 있나요?","a":"네, 2026년 8월 누적 업데이트(KB5121003 계열) 설치 이후 이 오류 신고가 늘었습니다. 구성 요소 저장소 손상이 주요 원인으로 지목되고 있습니다."}],"decisionSteps":[{"condition":"ScanHealth·RestoreHealth 복구로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"캐시 폴더 초기화로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"수동 설치로도 해결되지 않을 때","action":"CBS.log에서 손상된 구성 요소를 특정한 뒤 다음 단계를 판단하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["800f0983","0x800f0983"],"officialSource":{"title":"Microsoft Learn: Windows Update error code list","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x8007000D","title":"업데이트 파일 누락 또는 손상","overview":"업데이트 설치에 필요한 파일 중 일부가 없거나 손상되어 처리할 수 없는 데이터로 인식될 때 나타나는 코드입니다. \"일부 업데이트 파일이 없거나 문제가 있습니다\"라는 문구와 함께 표시되며, 2026년 8월 KB5120249 계열 업데이트에서 다수 보고되었습니다.","summary":"일부 업데이트 파일이 없거나 손상되어 설치를 진행할 수 없을 때 나타나는 오류입니다.","causes":["다운로드한 업데이트 패키지 파일 일부가 손상되었거나 불완전한 경우","업데이트 캐시(SoftwareDistribution)에 남아있는 이전 파일과 충돌하는 경우","디스크 오류나 갑작스러운 전원 차단으로 파일이 깨진 경우","네트워크 연결 불안정으로 다운로드가 중간에 끊긴 경우","구성 요소 저장소 일부가 손상되어 설치 파일 검증에 실패하는 경우"],"checks":["Windows Update 문제 해결사를 실행해 자동으로 손상 항목을 점검하세요.","SoftwareDistribution과 catroot2 폴더 이름을 바꿔 캐시를 초기화한 뒤 다시 시도하세요.","네트워크 연결을 유선으로 바꾸거나 안정적인 환경에서 다시 다운로드해 보세요.","DISM /Online /Cleanup-Image /RestoreHealth로 구성 요소 저장소를 복구하세요.","반복 실패하면 업데이트 어시스턴트나 미디어 생성 도구로 해당 KB를 수동 설치해 보세요."],"link":"error-code-0x8007000d.html","detailPage":"error-code-0x8007000d.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x8007000D)로 반복 실패한다면 무한정 재시도하기보다 업데이트 캐시 초기화와 네트워크 상태 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"2026년 8월 패치와 관련이 있나요?","a":"네, 2026년 8월 KB5120249 계열 업데이트에서 이 오류가 다수 보고되었습니다. 업데이트 파일 손상이나 캐시 문제가 주요 원인입니다."}],"decisionSteps":[{"condition":"문제 해결사 실행만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"캐시 폴더 이름 변경으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"DISM 복구로도 해결되지 않을 때","action":"설치 미디어를 이용한 인플레이스 업그레이드를 검토하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["8007000d","0x8007000d"],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_INVALID_DATA","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0xC000021A","title":"Critical System Process 종료","overview":"csrss.exe나 winlogon.exe 같은 핵심 시스템 프로세스가 예기치 않게 종료되면 운영체제 전체가 더 이상 정상 동작을 보장할 수 없다고 판단해 강제로 블루스크린을 띄웁니다. 로그인 화면 직전이나 직후에 자주 나타나며, 재부팅해도 같은 지점에서 반복되는 경우가 많습니다.","summary":"csrss.exe나 winlogon.exe 같은 핵심 시스템 프로세스가 예기치 않게 종료되면 운영체제 전체가 더 이상 정상 동작을 보장할 수 없다고 판단해 강제로 블루스크린을 띄웁니다.","causes":["그래픽 드라이버나 로그인 관련 셸 확장이 손상되어 로그인 프로세스가 강제로 죽는 경우","최근 윈도우 업데이트가 시스템 파일 일부를 덮어쓰면서 필수 프로세스와 충돌하는 경우","맬웨어나 신뢰할 수 없는 프로그램이 시스템 프로세스 메모리 영역을 건드리는 경우","디스크 배드섹터로 인해 csrss.exe, winlogon.exe 실행 파일 자체가 손상된 경우","타사 보안 소프트웨어가 시스템 프로세스를 오탐지해 강제로 종료시키는 경우"],"checks":["안전 모드로 부팅이 되는지 먼저 확인하세요. 안전 모드에서는 정상이라면 최근 설치한 드라이버나 프로그램이 원인일 가능성이 큽니다.","설정 > 업데이트 및 보안에서 최근 설치된 업데이트 날짜를 확인하고, 증상이 그 시점부터 시작됐다면 업데이트 제거를 시도하세요.","명령 프롬프트에서 sfc /scannow를 실행해 손상된 시스템 파일을 검사하고 복구합니다.","최근 설치한 보안 프로그램이 있다면 일시적으로 비활성화한 뒤 재부팅해 재현 여부를 확인하세요.","위 방법으로도 해결되지 않으면 복구 환경(고급 옵션)에서 시스템 복원 지점을 이용해 이전 상태로 되돌리는 것을 고려하세요."],"link":"error-code-0xc000021a.html","detailPage":"error-code-0xc000021a.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0xC000021A)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\\\Windows\\\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"최근 업데이트 제거로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"sfc /scannow로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"시스템 복원으로도 해결되지 않을 때","action":"디스크 상태 점검 도구로 물리적 손상 여부를 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["c000021a","0xc000021a"],"communityCases":[{"title":"그래픽 드라이버 충돌로 Winlogon 오류 해결","summary":"최신 그래픽 드라이버 업데이트 직후 로그인 화면에서 이 블루스크린이 반복됐던 사례가 있습니다. DDU(Display Driver Uninstaller)로 드라이버를 완전히 제거하고 이전 안정 버전으로 재설치한 뒤 문제가 사라졌습니다.","insight":"로그인 직후 반복되는 이 오류는 그래픽 드라이버나 로그인 셸 확장 충돌이 원인인 경우가 많습니다. 안전 모드로 진입해 최근 설치한 드라이버와 프로그램을 먼저 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xC000021A WINLOGON_FATAL_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xc000021a--winlogin-fatal-error"}},{"code":"0x0000007B","title":"INACCESSIBLE_BOOT_DEVICE","overview":"윈도우가 부팅 파티션이 있는 저장장치를 인식하지 못하거나 접근에 실패했을 때 나타나는 대표적인 부팅 오류입니다. 하드웨어를 교체하거나 BIOS 설정을 바꾼 직후에 특히 자주 발생합니다.","summary":"윈도우가 부팅 파티션이 있는 저장장치를 인식하지 못하거나 접근에 실패했을 때 나타나는 대표적인 부팅 오류입니다.","causes":["SATA/NVMe 케이블이 느슨하거나 슬롯 접촉이 불량해 부팅 디스크를 찾지 못하는 경우","BIOS/UEFI에서 저장장치 컨트롤러 모드(AHCI/RAID)를 최근에 변경한 경우","저장장치 드라이버가 손상되었거나 업데이트 후 호환되지 않게 바뀐 경우","디스크 파티션의 부팅 관련 정보(BCD)가 손상되어 부팅 경로를 찾지 못하는 경우","메인보드를 교체하거나 디스크를 다른 시스템에서 옮겨온 경우 드라이버 불일치로 발생하는 경우"],"checks":["PC 전원을 끄고 저장장치와 메인보드를 연결하는 케이블(또는 M.2 슬롯 장착 상태)을 다시 확인하세요.","BIOS로 진입해 저장장치 컨트롤러 모드가 최근에 바뀌었는지 확인하고, 바뀌었다면 원래 설정으로 되돌려 보세요.","설치 미디어로 부팅해 복구 환경에서 bootrec /fixmbr, bootrec /fixboot 명령으로 부팅 정보를 복구합니다.","디스크 관리 도구나 제조사 진단 툴로 디스크 상태(배드섹터, 온도, S.M.A.R.T)를 점검하세요.","최근 하드웨어를 변경했다면 변경 전 상태로 되돌려서 같은 증상이 재현되는지 확인해 원인을 좁히세요."],"link":"error-code-0x0000007b.html","detailPage":"error-code-0x0000007b.html","faq":[{"q":"SSD·NVMe를 바로 교체해야 하나요?","a":"이 문제(0x0000007B)만으로 저장장치 고장을 단정하기는 어렵습니다. 슬롯 재장착과 펌웨어 업데이트를 먼저 확인한 뒤에도 반복되면 다른 슬롯이나 드라이브로 교차 테스트해보는 것이 안전합니다."},{"q":"SSD 상태를 확인하는 무료 도구가 있나요?","a":"CrystalDiskInfo 같은 무료 프로그램으로 SSD의 건강 상태와 온도를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"케이블 재연결로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"BIOS 컨트롤러 모드 원복으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"bootrec으로도 해결되지 않을 때","action":"사례처럼 윈도우 재설치나 단계적 업그레이드를 고려하세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["7b","0000007b","0x7b"],"communityCases":[{"title":"윈도우10 → 11 업그레이드 우회로 해결한 사례","summary":"새로 조립한 PC에 윈도우 11을 USB로 직접 설치했을 때 계속 이 오류가 발생했던 사례가 있습니다. 드라이버 재설치, 복구 명령어, BIOS 설정 변경까지 다양한 시도를 했지만 해결되지 않았는데, 결국 윈도우 10을 먼저 설치한 뒤 온라인으로 윈도우 11까지 업그레이드하는 방식으로 우회해서 해결했습니다.","insight":"정확한 원인은 명확하지 않지만, USB로 최신 윈도우를 바로 설치하는 과정에서 특정 하드웨어 조합에 문제가 생길 수 있습니다."},{"title":"바이오스(CMOS) 초기화로 해결한 사례","summary":"오버클럭 설정을 건드린 직후 이 오류가 발생한 사례도 있었는데, CMOS 배터리를 잠시 분리했다가 다시 끼워 바이오스 설정을 초기화하는 것으로 해결됐습니다.","insight":"최근 오버클럭이나 BIOS 설정을 변경한 직후 이 오류가 나타났다면, 원인이 저장장치 자체보다 불안정해진 시스템 설정에 있을 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x7B INACCESSIBLE_BOOT_DEVICE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x7b--inaccessible-boot-device"}},{"code":"0x0000001E","title":"KMODE_EXCEPTION_NOT_HANDLED","overview":"커널 모드에서 실행 중이던 프로그램이 예외를 일으켰는데 그 예외를 처리할 핸들러가 없어서 나타나는 코드입니다. 이벤트 뷰어의 Kernel-Power(41) 이벤트 세부 정보에서 BugcheckCode 값이 30(10진수)으로 표시된다면 이 코드(0x1E, 16진수 1E=10진수 30)를 가리킵니다. 드라이버 결함이 가장 흔한 원인이지만, 램 자체의 하드웨어 결함으로도 발생할 수 있습니다.","summary":"커널 모드 프로그램이 처리되지 않은 예외를 일으켰을 때 나타나는 코드로, 드라이버 결함이나 램 하드웨어 결함이 흔한 원인입니다.","causes":["그래픽·저장장치·네트워크 등 특정 드라이버가 손상되었거나 최신 윈도우 빌드와 호환되지 않는 경우","램 모듈이 불안정하거나 슬롯 접촉이 불량한 경우","램 오버클럭(XMP)이 시스템 안정성 한계를 넘은 경우","디스크 오류로 인해 커널이 참조하는 파일이 손상된 경우","타사 보안·튜닝 소프트웨어가 커널 모드에서 충돌하는 경우"],"checks":["이벤트 뷰어(eventvwr.msc)에서 이 코드 발생 직전 어떤 드라이버나 서비스가 관여했는지 확인하세요.","장치 관리자에서 최근 설치·업데이트한 드라이버를 확인하고 이전 버전으로 롤백해 보세요.","메모리 진단 도구(mdsched.exe) 또는 MemTest86+로 램 상태를 점검하세요. <a href=\"memory-test-guide.html\">실제 검사 방법과 결과 해석 보기 →</a>","BIOS에서 XMP나 오버클럭 설정을 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","명령 프롬프트에서 sfc /scannow와 chkdsk /f 를 실행해 시스템 파일과 디스크 오류를 점검하세요."],"link":"error-code-0x0000001e.html","detailPage":"error-code-0x0000001e.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000001E)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 롤백으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"덤프에서 특정 드라이버가 확인될 때","action":"그 드라이버를 업데이트하거나 제거하세요."},{"condition":"오버클럭 해제로도 해결되지 않을 때","action":"안전 모드 재현 확인으로 넘어가세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["1e","0000001e","0x1e","30","bugcheckcode30"],"communityCases":[{"title":"무선 랜 드라이버 롤백으로 반복 블루스크린 해결","summary":"윈도우 업데이트 이후 무선 랜카드 관련 KMODE_EXCEPTION 블루스크린이 반복됐던 사례가 있습니다. 이벤트 뷰어에서 네트워크 드라이버 관련 오류 로그를 발견해 드라이버를 이전 버전으로 롤백하자 문제가 해결됐습니다.","insight":"이 오류가 특정 드라이버 업데이트 직후 시작됐다면 장치 관리자에서 해당 드라이버를 롤백하는 것이 가장 빠른 해결 방법입니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x1E KMODE_EXCEPTION_NOT_HANDLED","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x1e--kmode-exception-not-handled"}},{"code":"0x0000001A","title":"MEMORY_MANAGEMENT","overview":"메모리 관리자가 페이지 테이블이나 메모리 할당 과정에서 예상치 못한 상태를 발견했을 때 나타나는 코드입니다. 램 자체의 불량뿐 아니라 드라이버의 메모리 오용도 흔한 원인입니다.","summary":"메모리 관리자가 페이지 테이블이나 메모리 할당 과정에서 예상치 못한 상태를 발견했을 때 나타나는 코드입니다.","causes":["램 모듈이 물리적으로 불안정하거나 슬롯 접촉이 불량한 경우","듀얼 채널 구성 시 서로 다른 규격의 램을 혼용해 타이밍이 맞지 않는 경우","그래픽이나 네트워크 드라이버가 메모리를 잘못 참조하는 경우","디스크 오류로 인해 페이징 파일(가상 메모리)이 손상된 경우","램 오버클럭이나 XMP 프로파일 설정이 시스템 안정성 한계를 넘은 경우"],"checks":["메모리 진단 도구(mdsched.exe 또는 MemTest86+)를 실행해 램 자체의 불량 여부를 확인하세요. <a href=\"memory-test-guide.html\">실제 검사 방법과 결과 해석 보기 →</a>","램을 한 개씩 꽂아가며 재부팅해 특정 모듈이나 슬롯에서만 문제가 재현되는지 확인하세요.","BIOS에서 XMP나 오버클럭 설정을 끄고 기본 클럭으로 되돌린 뒤 증상이 사라지는지 확인하세요.","최근 설치하거나 업데이트한 드라이버가 있다면 제거 후 재현 여부를 확인하세요.","디스크 검사(chkdsk)를 실행해 페이징 파일이 저장된 디스크에 오류가 없는지 점검하세요."],"link":"error-code-0x0000001a.html","detailPage":"error-code-0x0000001a.html","faq":[{"q":"게임할 때만 재부팅되면 그래픽카드 문제인가요?","a":"이 문제(0x0000001A)는 그래픽 드라이버 문제일 가능성이 높지만 전원 공급이나 온도 문제와 겹치는 경우도 많아, 드라이버 재설치와 함께 온도·전력 상태도 함께 확인하는 것이 좋습니다."},{"q":"전원 공급 장치(PSU) 용량이 부족한지 어떻게 확인하나요?","a":"그래픽카드·CPU 권장 용량의 합을 계산해 PSU 정격 용량과 비교하면 부족 여부를 가늠할 수 있습니다."}],"decisionSteps":[{"condition":"XMP 해제로 해결될 때","action":"다시 적용하지 말고 낮은 클럭을 유지하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"해당 모듈을 교체하세요."},{"condition":"sfc /scannow로 해결될 때","action":"재발 여부만 지켜보면 됩니다."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["1a","0000001a","0x1a"],"communityCases":[{"title":"램 오버클럭(XMP) 낮춰서 해결한 사례","summary":"새로 조립한 PC에서 게임 중 반복적으로 이 블루스크린이 발생했던 사례가 있습니다. 램 자체는 정상으로 테스트됐지만, XMP로 설정된 고클럭(3600MHz)이 실제로는 불안정했던 것이 원인이었고, 클럭을 3200~3400MHz로 낮춘 뒤 재현되지 않았습니다.","insight":"메모리 진단 도구를 통과해도 XMP/오버클럭 설정 자체가 불안정의 원인일 수 있습니다. 기본 클럭에서 안정적이라면 XMP 프로파일을 의심해보세요."},{"title":"SFC로 시스템 파일 복구해 해결한 사례","summary":"램과 디스크 모두 정상으로 진단됐는데도 이 블루스크린이 반복됐던 사례에서는, sfc /scannow 명령이 손상된 시스템 파일을 발견해 복구한 뒤로 더 이상 블루스크린이 발생하지 않았습니다.","insight":"이름은 '메모리 관리' 오류지만 실제 원인이 하드웨어가 아니라 손상된 시스템 파일인 경우도 있습니다. 하드웨어 교체를 고려하기 전에 SFC 결과를 먼저 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x1A MEMORY_MANAGEMENT","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x1a--memory-management"}},{"code":"0x00000050","title":"PAGE_FAULT_IN_NONPAGED_AREA","overview":"시스템이 메모리에 상주해야 할 데이터를 찾지 못하고 디스크에서 읽으려다 실패했을 때 나타납니다. 드라이버 결함과 램 불량이 가장 흔한 두 원인으로 꼽힙니다.","summary":"시스템이 메모리에 상주해야 할 데이터를 찾지 못하고 디스크에서 읽으려다 실패했을 때 나타납니다.","screenshot":{"src":"assets/bsod-page-fault-nonpaged-area.jpg","alt":"PAGE_FAULT_IN_NONPAGED_AREA 블루스크린 실제 화면 — 하단에 중지 코드가 표시된 모습","width":617,"height":496},"causes":["최근 설치한 드라이버가 메모리 주소를 잘못 참조하는 경우","램 모듈 접촉 불량이나 물리적 결함이 있는 경우","바이러스 백신 등 커널 모드로 동작하는 보안 소프트웨어와의 충돌","디스크 캐시나 파일 시스템 손상으로 필요한 데이터를 읽지 못하는 경우","메모리 오버클럭으로 인한 불안정"],"checks":["장치 관리자에서 최근 업데이트되거나 설치된 드라이버(특히 그래픽, 네트워크, 저장장치)를 확인하고 이전 버전으로 롤백해 보세요.","메모리 진단 도구로 램 상태를 점검하고, 가능하면 램을 하나씩 꽂아 테스트해 보세요.","최근 설치한 보안 프로그램을 임시로 제거하거나 비활성화한 뒤 재현 여부를 확인하세요.","명령 프롬프트에서 chkdsk /f 를 실행해 디스크 오류를 점검하고 수정하세요.","오버클럭 설정이 있다면 기본값으로 되돌린 뒤 안정성이 개선되는지 확인하세요."],"link":"error-code-0x00000050.html","detailPage":"error-code-0x00000050.html","narrative":"PFN(Page Frame Number) 목록은 Windows가 물리 메모리의 각 페이지가 지금 어디에 쓰이고 있는지 추적하는 내부 장부입니다. 이 장부 자체가 깨졌다는 건 단순히 메모리가 부족한 게 아니라, 메모리를 관리하는 방식 자체에 신뢰할 수 없는 값이 끼어들었다는 뜻입니다. 그래서 램 모듈의 물리적 결함뿐 아니라 잘못된 주소를 계속 건드리는 드라이버, 오버클럭으로 인한 불안정한 타이밍까지 원인 후보가 넓습니다. 재부팅 한 번으로 사라졌다고 안심하기보다는, 같은 작업을 반복했을 때도 재현되는지를 먼저 봐야 진짜 원인에 가까워집니다.","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000050)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"최근에 설치한 프로그램이 원인일 수도 있나요?","a":"네, 최근 설치한 드라이버나 소프트웨어가 원인인 경우가 많아 시스템 복원 지점으로 되돌리는 것도 방법입니다."}],"decisionSteps":[{"condition":"드라이버 롤백으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"해당 모듈을 교체하세요."},{"condition":"chkdsk로도 해결되지 않을 때","action":"보안 프로그램을 다른 제품으로 교체하는 것을 검토하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["50","00000050","0x50"],"officialSource":{"title":"Microsoft Learn: Bug Check 0x50 PAGE_FAULT_IN_NONPAGED_AREA","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x50--page-fault-in-nonpaged-area"},"communityCases":[{"title":"램 교체로 해결한 사례","summary":"드라이버 롤백, 메모리 진단 도구, chkdsk까지 다 시도했지만 이 블루스크린이 며칠 간격으로 반복됐던 사례가 있습니다. Windows 자체 메모리 진단에서는 이상이 없었지만 MemTest86으로 여러 시간 검사하자 램 한 개에서 오류가 확인됐고, 해당 램을 교체한 뒤로는 재발하지 않았습니다.","insight":"Windows 메모리 진단 도구는 짧은 시간 안에 끝나는 만큼 간헐적인 불량을 놓칠 수 있습니다. 계속 반복된다면 MemTest86처럼 더 오래, 더 여러 패스로 검사하는 도구로 다시 확인해보세요."}]},{"code":"0x0000004E","title":"PFN_LIST_CORRUPT","overview":"윈도우가 물리 메모리 페이지 목록(PFN)의 상태가 서로 맞지 않다고 판단했을 때 나타나는 블루스크린입니다. 메모리 자체의 불안정성만을 의미하지 않고, 잘못된 메모리 설명자를 넘긴 드라이버나 DMA 장치의 문제도 원인이 될 수 있습니다.","summary":"물리 메모리 페이지 목록이 손상되었다는 뜻으로, 램 불안정과 커널 드라이버의 메모리 오용을 함께 확인해야 합니다.","causes":["램 모듈 불량이나 슬롯 접촉 불량으로 메모리 내용이 손상되는 경우","XMP/EXPO 또는 수동 메모리 오버클럭이 시스템에서 불안정한 경우","드라이버가 메모리 페이지를 잘못 잠그거나 해제하는 경우","가상화·보안·스토리지 필터 드라이버가 커널 메모리를 잘못 다루는 경우","PCIe 장치의 DMA 전송이나 메인보드 펌웨어 호환성 문제"],"checks":["중요 파일을 먼저 백업한 뒤 BIOS에서 XMP/EXPO와 오버클럭을 기본값으로 되돌리세요.","Windows 메모리 진단보다 긴 검사가 필요하면 MemTest86 등 부팅형 메모리 검사로 여러 패스를 진행하세요.","램을 한 개씩 꽂고 슬롯을 바꿔 재현 여부를 비교해 모듈과 슬롯을 분리하세요.","블루스크린 직전 설치한 그래픽·네트워크·저장장치·가상화 드라이버를 업데이트하거나 롤백하세요.","덤프 분석에서 특정 드라이버가 반복 지목되지 않는다면 메모리와 메인보드의 기본 설정 상태를 우선 확인하세요."],"link":"error-code-0x0000004e.html","detailPage":"error-code-0x0000004e.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000004E)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"XMP·EXPO 해제 후 해결될 때","action":"다시 적용하지 말고 기본 속도로 유지하세요."},{"condition":"램 재장착·슬롯 교차로 문제 모듈이 특정될 때","action":"해당 모듈 교체를 검토하세요."},{"condition":"드라이버 롤백으로도 해결되지 않을 때","action":"그래픽카드·캡처카드 등 PCIe 장치를 하나씩 제거해 DMA 충돌 여부를 확인하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["4e","0000004e","0x4e","pfn list corrupt","pfn_list_corrupt"],"communityCases":[{"title":"EXPO 해제 후 PFN 오류가 멈춘 사례","summary":"게임을 오래 실행할 때만 PFN_LIST_CORRUPT가 반복됐고, 램 검사에서는 초반에 이상이 보이지 않았습니다. BIOS에서 EXPO를 끄고 기본 메모리 속도로 사용하자 재현되지 않았습니다.","insight":"메모리 검사 결과가 한 번 정상이어도 고부하·장시간 조건에서만 불안정할 수 있습니다. 오버클럭을 해제한 상태와 비교하는 것이 부품 교체보다 먼저 할 수 있는 안전한 확인입니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x4E PFN_LIST_CORRUPT","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x4e--pfn-list-corrupt"}},{"code":"0x000000C5","title":"DRIVER_CORRUPTED_EXPOOL","overview":"커널 드라이버가 시스템 메모리 풀을 손상시키거나 높은 IRQL에서 잘못된 메모리에 접근했을 때 나타나는 블루스크린입니다. 오류 이름처럼 드라이버 가능성이 매우 높지만, 불안정한 메모리가 드라이버 동작을 깨뜨리는 경우도 함께 고려해야 합니다.","summary":"드라이버가 커널 메모리 풀을 손상시킨 상태를 가리키므로 최근 설치한 드라이버와 커널 수준 프로그램을 먼저 확인하세요.","causes":["그래픽·네트워크·저장장치 드라이버의 메모리 관리 결함","VPN, 백신, 튜닝 도구, 가상화 프로그램의 커널 드라이버 충돌","최근 업데이트된 드라이버가 현재 Windows 빌드와 맞지 않는 경우","램 불안정으로 드라이버가 잘못된 메모리를 참조하는 경우","손상된 드라이버 설치나 제거되지 않은 이전 버전의 잔여 파일"],"checks":["덤프 파일에서 !analyze 결과와 반복해서 언급되는 .sys 드라이버 이름을 먼저 기록하세요.","최근 설치·업데이트한 드라이버와 커널 수준 프로그램을 하나씩 롤백하거나 제조사 공식 버전으로 재설치하세요.","안전 모드에서 증상이 재현되는지 비교해 타사 드라이버 개입 여부를 좁히세요.","드라이버 변경으로도 해결되지 않으면 XMP/EXPO를 끄고 메모리 진단을 진행하세요.","Driver Verifier는 원인 드라이버를 찾는 고급 도구이므로 복구 환경 진입 방법과 해제 방법을 확인한 뒤 필요한 경우에만 사용하세요."],"link":"error-code-0x000000c5.html","detailPage":"error-code-0x000000c5.html","narrative":"이름에 'DRIVER'가 명시되어 있어 드라이버 문제로 단정하기 쉽지만, 실제로는 '어떤 드라이버가 메모리 풀에 잘못된 값을 써넣었다'는 결과만 알려줄 뿐, 그 드라이버가 원래 결함이 있었는지 아니면 불안정한 램 때문에 정상 드라이버가 오작동한 것인지는 구분해주지 않습니다. 그래서 최근 설치한 드라이버가 명확히 있다면 그것부터 의심하는 게 맞지만, 특별히 새로 설치한 것이 없는데 이 코드가 나타난다면 드라이버보다 메모리 진단을 먼저 해보는 것이 순서상 더 합리적입니다.","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000C5)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"덤프에서 지목된 드라이버를 롤백해 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"안전 모드에서는 재현되지 않을 때","action":"타사 드라이버가 원인이므로 최근 설치 순서대로 하나씩 제거하세요."},{"condition":"XMP 해제·메모리 진단으로도 해결되지 않을 때","action":"Driver Verifier 사용을 고려하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["c5","000000c5","0xc5","driver corrupted expool","driver_corrupted_expool"],"communityCases":[{"title":"가상 네트워크 드라이버 롤백으로 해결한 사례","summary":"VPN 클라이언트 업데이트 뒤 게임 실행 중 DRIVER_CORRUPTED_EXPOOL이 반복됐습니다. 안전 모드에서는 문제가 없었고, VPN 가상 어댑터와 관련 드라이버를 이전 버전으로 되돌린 뒤 재발하지 않았습니다.","insight":"안전 모드에서 정상이고 특정 프로그램 실행 직후 발생한다면 해당 프로그램의 커널 드라이버를 우선 의심하세요. 여러 드라이버를 동시에 바꾸지 말고 한 항목씩 비교해야 원인을 추적하기 쉽습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xC5 DRIVER_CORRUPTED_EXPOOL","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xc5--driver-corrupted-expool"}},{"code":"0x0000008E","title":"KERNEL_MODE_EXCEPTION_NOT_HANDLED","overview":"커널 모드에서 실행된 코드가 처리되지 않은 예외를 발생시켰을 때 나타나는 블루스크린입니다. 구형 Windows에서 자주 보이던 코드이며, 최신 시스템에서는 비슷한 상황이 0x7E나 0x1E로 표시될 수 있어 코드 번호와 함께 예외 코드·드라이버 이름을 확인해야 합니다.","summary":"커널 모드 예외가 처리되지 않았다는 뜻으로, 원인 드라이버와 예외 코드를 함께 확인해야 하는 구형·호환 진단 항목입니다.","causes":["그래픽·저장장치·네트워크 드라이버가 커널에서 예외를 일으킨 경우","램 불안정이나 메모리 충돌로 커널 코드가 잘못된 데이터를 받은 경우","BIOS 호환성이나 메모리 캐시 설정 문제","최근 설치한 하드웨어·드라이버·시스템 서비스의 호환성 문제","Windows 설치 또는 시스템 파일 손상과 디스크 공간 부족"],"checks":["블루스크린에 함께 표시된 예외 코드와 .sys 파일명을 기록하고, 같은 시각의 시스템 이벤트를 확인하세요.","안전 모드에서 정상이라면 최근 추가한 드라이버·서비스·보안 프로그램을 롤백하세요.","그래픽·칩셋·저장장치 드라이버를 제조사 공식 버전으로 업데이트하고, 업데이트 직후 시작됐다면 이전 버전과 비교하세요.","BIOS를 기본값으로 되돌리고 메모리 오버클럭을 해제한 뒤 메모리 검사를 진행하세요.","덤프에서 원인 드라이버를 특정하지 못하면 시스템 파일 검사와 디스크 여유 공간을 확인한 뒤 하드웨어 진단으로 범위를 넓히세요."],"link":"error-code-0x0000008e.html","detailPage":"error-code-0x0000008e.html","narrative":"이 코드는 최신 Windows보다 예전 버전에서 더 자주 쓰이던 코드라, 요즘 PC에서 이 코드를 만났다면 오히려 참고할 만한 최신 사례나 공식 문서가 상대적으로 적다는 점이 까다로운 부분입니다. 비슷한 상황이 최신 시스템에서는 0x0000007E(SYSTEM_THREAD_EXCEPTION_NOT_HANDLED)나 0x0000001E로 분류되는 경우가 많아서, 코드 번호 하나만 검색하기보다 화면에 함께 표시되는 예외 코드와 원인 드라이버 이름까지 같이 기록해두면 더 정확한 사례를 찾을 수 있습니다.","faq":[{"q":"0x8E은 왜 그렇게 많이 나타나나요?","a":"이 오류는 매우 광범위한 원인을 나타내기 때문입니다. 드라이버 오류부터 메모리 문제, 심지어 하드웨어 불안정성까지 다양한 원인을 포괄하므로, 가장 먼저 확인할 항목을 체계적으로 정렬하는 것이 중요합니다."},{"q":"이 오류가 자동 복구 루프를 만들 수도 있나요?","a":"네, 부팅 중에 발생하면 자동 복구 루프에 빠질 수 있습니다. 이 경우 안전 모드나 복구 환경에서 진단해야 합니다."}],"decisionSteps":[{"condition":"그래픽 드라이버 업데이트로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"해당 모듈을 교체하세요."},{"condition":"SFC·DISM으로도 해결되지 않을 때","action":"이벤트 뷰어에서 드라이버 이름을 확인해 개별 조치하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["8e","0000008e","0x8e","kernel mode exception not handled","kernel_mode_exception_not_handled"],"communityCases":[{"title":"구형 그래픽 드라이버 교체로 해결한 사례","summary":"오래된 Windows 설치 환경에서 그래픽 작업을 시작할 때 KERNEL_MODE_EXCEPTION_NOT_HANDLED가 발생했습니다. 이벤트 로그와 덤프에서 그래픽 드라이버가 반복 지목되어 기존 드라이버를 제거하고 제조사 호환 버전으로 재설치한 뒤 안정화됐습니다.","insight":"0x8E는 코드만으로 원인 부품을 확정할 수 없습니다. 예외 코드와 드라이버 이름을 함께 확인하고, 최신 시스템에서는 0x7E·0x1E와의 표시 차이도 고려하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x8E KERNEL_MODE_EXCEPTION_NOT_HANDLED","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x8e--kernel-mode-exception-not-handled"}},{"code":"0x80070002","title":"파일을 찾을 수 없음","overview":"윈도우 업데이트나 설치, 복구 과정에서 필요한 파일을 찾지 못했을 때 표시되는 오류입니다. 업데이트 캐시가 손상되었거나 경로 설정이 꼬였을 때 자주 나타납니다.","summary":"윈도우 업데이트나 설치, 복구 과정에서 필요한 파일을 찾지 못했을 때 표시되는 오류입니다.","causes":["윈도우 업데이트 캐시(SoftwareDistribution 폴더)가 손상된 경우","시스템 날짜/시간이 잘못 설정되어 업데이트 서버 인증에 실패하는 경우","이전에 중단된 업데이트나 설치 작업의 잔여 파일이 충돌하는 경우","그룹 정책이나 레지스트리 설정이 업데이트 경로를 잘못 가리키는 경우","디스크 여유 공간 부족으로 임시 파일을 만들지 못하는 경우"],"checks":["서비스 창(services.msc)에서 Windows Update 서비스를 중지한 뒤 SoftwareDistribution 폴더 이름을 바꾸고 서비스를 다시 시작해 캐시를 초기화하세요.","설정에서 날짜와 시간이 정확한지, 시간대가 올바른지 확인하세요.","디스크 정리 도구로 임시 파일과 이전 업데이트 잔여 파일을 정리하세요.","저장 공간이 최소 10GB 이상 남아있는지 확인하세요.","그래도 반복되면 Windows Update 문제 해결사(트러블슈터)를 실행해 자동 진단을 받아보세요."],"link":"error-code-0x80070002.html","detailPage":"error-code-0x80070002.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x80070002)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"자동 복구가 계속 실패하면 윈도우를 재설치해야 하나요?","a":"명령 프롬프트에서 부팅 복구 명령을 먼저 시도해보고, 그래도 안 되면 초기화나 재설치를 고려하는 것이 순서입니다."}],"decisionSteps":[{"condition":"캐시 초기화로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"날짜·시간 수정으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"문제 해결사로도 해결되지 않을 때","action":"그룹 정책이나 레지스트리의 업데이트 경로 설정을 확인하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["80070002","0x80070002"],"communityCases":[{"title":"SoftwareDistribution 초기화로 업데이트 오류 해결","summary":"윈도우 업데이트 항목이 이 오류로 반복 실패하던 사례가 있습니다. 업데이트 서비스를 중지하고 SoftwareDistribution 폴더를 이름 변경으로 초기화한 뒤 서비스를 재시작하자 업데이트가 정상 진행됐습니다.","insight":"이 오류는 대부분 업데이트 캐시 파일 손상이 원인입니다. 복잡한 복구 절차 전에 SoftwareDistribution 폴더 초기화를 먼저 시도해보세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_FILE_NOT_FOUND","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0xC000000E","title":"부팅 장치를 찾을 수 없음","overview":"Windows Boot Manager 또는 winload.exe가 부팅에 필요한 장치나 시스템 파티션에 접근하지 못할 때 나타나는 상태 코드입니다. SSD·HDD 연결 문제, BIOS 부팅 모드 변경, BCD 손상, 복구·복제 과정의 디스크 식별자 불일치가 주요 원인입니다.","summary":"Windows가 부팅에 필요한 디스크나 시스템 파티션에 접근하지 못할 때 나타나는 부팅 오류입니다.","causes":["SATA 케이블·전원 케이블 또는 M.2 SSD 접촉이 불안정한 경우","BIOS에서 UEFI·Legacy 또는 AHCI·RAID 설정이 설치 당시와 달라진 경우","BCD 부팅 구성 데이터가 손상되거나 잘못된 디스크를 가리키는 경우","디스크 복제·복구 뒤 EFI 시스템 파티션 또는 디스크 식별자가 올바르게 연결되지 않은 경우","SSD·HDD 자체의 읽기 오류나 갑작스러운 연결 끊김이 발생한 경우"],"checks":["전원을 끄고 부팅 디스크의 케이블·전원과 M.2 고정 상태를 확인하세요. 중요한 파일이 있다면 반복 부팅보다 먼저 백업을 고려하세요.","BIOS에서 부팅 디스크가 인식되는지 확인하고 Windows Boot Manager가 첫 번째 부팅 항목인지 살펴보세요.","최근 BIOS 설정을 바꿨다면 UEFI·Legacy, AHCI·RAID 설정을 설치 당시 값과 비교하세요. 모르는 설정을 무작정 바꾸지 마세요.","<a href=\"windows-repair-tools-guide.html#install-media-guide\">Windows 설치 USB</a>의 복구 환경에서 시동 복구를 먼저 실행하고, 필요하면 diskpart로 EFI 파티션과 운영체제 볼륨을 확인하세요.","복구 명령을 실행하기 전 디스크 상태와 파티션 정보를 기록하고, 디스크가 BIOS에서도 사라지거나 읽기 오류가 반복되면 저장장치 교체보다 데이터 복구를 우선하세요."],"link":"error-code-0xc000000e.html","detailPage":"error-code-0xc000000e.html","faq":[{"q":"BIOS에서 SSD가 보이면 디스크 고장은 아닌가요?","a":"BIOS에서 장치가 보이는 것만으로 Windows Boot Manager나 BCD가 정상이라는 뜻은 아닙니다. 부팅 순서와 EFI 시스템 파티션, 운영체제 볼륨 접근을 별도로 확인해야 합니다."},{"q":"복구 명령을 바로 실행해도 되나요?","a":"중요한 파일이 있다면 먼저 백업 가능성을 확인하세요. 디스크가 BIOS에서도 사라지거나 읽기 오류가 반복되면 BCD 수정보다 저장장치 상태와 데이터 보존을 우선해야 합니다."}],"decisionSteps":[{"condition":"BIOS에서 디스크가 보이지 않을 때","action":"케이블·전원 연결을 다시 점검하고, 다른 SATA 포트나 M.2 슬롯으로 옮겨 인식되는지 확인하세요. 여전히 안 보이면 디스크 고장 가능성을 우선하세요."},{"condition":"BIOS에는 보이지만 부팅이 안 될 때","action":"bootrec/bcdboot 명령으로 대부분 해결됩니다. UEFI/Legacy 모드가 설치 당시와 다른지부터 확인하세요."},{"condition":"bootrec·bcdboot로도 해결되지 않을 때","action":"파일 시스템 손상이 의심되므로 복구 환경에서 <code>chkdsk C: /f /r</code>을 실행하고, 그래도 안 되면 디스크 자체의 SMART 상태를 다른 PC에서 점검하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["c000000e","0xc000000e","8000000e","winload.exe 0xc000000e"],"communityCases":[{"title":"BIOS 부팅 순서 변경 뒤 발생한 사례","summary":"SSD를 교체한 뒤 BIOS가 새 디스크를 첫 번째로 선택하지 않아 0xC000000E가 표시됐습니다. BIOS에서 Windows Boot Manager를 올바른 디스크로 지정하자 부팅됐습니다.","insight":"부팅 오류가 하드웨어 교체나 BIOS 초기화 직후 시작됐다면 디스크 고장으로 단정하기 전에 부팅 순서와 UEFI 설정을 먼저 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Windows failed to start, status 0xc000000e","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/performance/windows-fail-to-start-status-0xc000000e"}},{"code":"0x803F7001","title":"Windows 라이선스를 찾을 수 없음","overview":"Windows가 현재 설치된 에디션을 활성화할 수 있는 디지털 라이선스나 제품 키를 찾지 못할 때 나타나는 정품 인증 오류입니다. 메인보드 교체 같은 하드웨어 변경, 잘못된 Home·Pro 에디션, Microsoft 계정 연결 문제, 처음 설치한 PC에서 흔히 확인됩니다.","summary":"Windows 활성화에 사용할 유효한 디지털 라이선스나 제품 키를 찾지 못할 때 나타납니다.","causes":["메인보드 교체 등으로 기존 디지털 라이선스와 하드웨어 구성이 달라진 경우","보유한 라이선스와 현재 설치된 Windows 에디션(Home·Pro)이 다른 경우","Microsoft 계정에 디지털 라이선스가 연결되어 있지 않거나 다른 계정으로 로그인한 경우","새 PC 또는 재설치 PC에 유효한 제품 키가 입력되지 않은 경우","인터넷 연결이나 Microsoft 활성화 서버 통신이 일시적으로 실패한 경우"],"checks":["설정 > 시스템 > 정품 인증에서 현재 Windows 에디션과 활성화 상태를 먼저 확인하세요.","최근 메인보드를 교체했다면 정품 인증 문제 해결사를 실행하고, 이전에 사용하던 Microsoft 계정으로 로그인했는지 확인하세요.","제품 키가 있다면 구매 확인 메일·패키지·정품 인증서의 25자리 키와 현재 설치 에디션이 일치하는지 확인하세요.","Home 라이선스로 Pro를 설치한 것처럼 에디션이 다르면 올바른 에디션을 설치하거나 유효한 Pro 라이선스를 사용해야 합니다.","키 생성기나 불법 인증 도구는 악성코드와 라이선스 문제를 만들 수 있으므로 사용하지 말고, 구매처·제조사·Microsoft 지원을 통해 라이선스를 확인하세요."],"link":"error-code-0x803f7001.html","detailPage":"error-code-0x803f7001.html","faq":[{"q":"메인보드를 바꾸면 Windows를 다시 구매해야 하나요?","a":"디지털 라이선스가 Microsoft 계정에 연결되어 있었다면 정품 인증 문제 해결사에서 하드웨어 변경 후 재활성화를 시도할 수 있습니다. 라이선스 종류와 약관에 따라 결과가 다르므로 새 키 구매를 먼저 결정하지 마세요."},{"q":"제품 키를 웹에서 찾아 입력해도 되나요?","a":"출처가 불분명한 키나 인증 우회 도구는 사용하지 마세요. 구매 증빙, PC 제조사, Microsoft 공식 지원을 통해 유효한 라이선스를 확인해야 합니다."}],"decisionSteps":[{"condition":"Microsoft 계정에 연결되어 있었을 때","action":"문제 해결사의 \"최근 이 장치의 하드웨어를 변경했습니다\" 옵션으로 대부분 자동 재인증됩니다."},{"condition":"계정에 연결된 적이 없을 때","action":"문제 해결사가 작동하지 않으므로 정품 제품 키를 직접 입력해야 합니다. 키를 찾을 수 없다면 구매처나 PC 제조사에 문의하세요."},{"condition":"복제된 이미지로 여러 PC에 설치했을 때","action":"같은 라이선스를 여러 대에서 동시에 쓰는 상태일 수 있습니다. 각 PC마다 정식 라이선스를 개별 구매해야 합니다."},{"condition":"가상머신 ↔ 물리 PC 이동이었을 때","action":"대부분 별도의 라이선스가 필요합니다. 같은 키를 계속 재사용하면 이 오류가 반복됩니다."}],"relatedSymptom":"windows-activation-error.html","aliases":["803f7001","0x803f7001","windows license not found","윈도우 정품 인증 안됨"],"communityCases":[{"title":"메인보드 교체 후 인증 문제 해결","summary":"정상 인증된 PC에서 메인보드를 교체한 뒤 라이선스를 찾을 수 없다는 메시지가 나타났습니다. 이전 디지털 라이선스가 연결된 Microsoft 계정으로 로그인하고 정품 인증 문제 해결사를 실행해 하드웨어 변경을 선택한 뒤 상태를 확인했습니다.","insight":"하드웨어 변경 뒤 발생한 인증 오류는 새 제품 키를 바로 구매하기보다 기존 디지털 라이선스와 Microsoft 계정 연결을 먼저 확인해야 합니다."}],"officialSource":{"title":"Microsoft Support: Get help with Windows activation errors","url":"https://support.microsoft.com/en-us/windows/activation/get-help-with-windows-activation-errors"}},{"code":"0xC004F050","title":"제품 키를 사용할 수 없음","overview":"입력한 Windows 제품 키가 현재 설치된 에디션이나 제품 유형에서 사용할 수 없을 때 표시되는 정품 인증 오류입니다. 키 오타뿐 아니라 Home·Pro 에디션 불일치, 다른 버전용 키, 업그레이드·재설치 과정의 라이선스 조건도 함께 확인해야 합니다.","summary":"Windows 제품 키가 현재 설치된 에디션이나 제품 유형에 맞지 않아 인증되지 않을 때 나타납니다.","causes":["Windows Home에 Pro 키를 입력하거나 반대로 입력한 경우","Windows 10·11 또는 일반·볼륨 라이선스 등 다른 제품 유형의 키를 사용한 경우","제품 키를 잘못 입력했거나 구매·제공처가 유효한 키를 발급하지 않은 경우","하드웨어 변경 뒤 기존 디지털 라이선스 대신 다른 키를 입력한 경우","업그레이드 서버나 Microsoft 활성화 서비스가 일시적으로 응답하지 않는 경우"],"checks":["설정 > 시스템 > 정품 인증에서 설치된 Windows 에디션을 확인하고 제품 키의 대상 에디션과 비교하세요.","관리자 명령 프롬프트에서 slmgr /dlv를 실행해 채널과 라이선스 상태를 확인하세요. 제품 키 전체를 공유하지 마세요.","제품 키를 다시 입력할 때 0·O, 1·I처럼 혼동하기 쉬운 문자를 확인하고 구매 증빙과 대조하세요.","최근 메인보드를 교체했다면 제품 키를 반복 입력하기보다 Microsoft 계정의 디지털 라이선스와 정품 인증 문제 해결사를 먼저 확인하세요.","출처가 불분명한 키나 인증 우회 프로그램은 사용하지 말고, 유효한 키를 판매처 또는 Microsoft 공식 경로에서 확인하세요."],"link":"error-code-0xc004f050.html","detailPage":"error-code-0xc004f050.html","narrative":"이 오류가 헷갈리는 이유는 '제품 키를 사용할 수 없다'는 문구만 보면 오타 문제로 보이기 쉽지만, 실제로는 키 자체는 정확해도 지금 설치된 Windows 에디션·버전·라이선스 유형과 맞지 않으면 똑같은 메시지가 뜨기 때문입니다. Home에 Pro용 키를, 또는 소매용 PC에 볼륨 라이선스용 키를 넣는 경우가 대표적입니다. 재설치나 업그레이드 과정에서 이 오류를 만났다면, 키 자체보다 지금 설치 중인 에디션이 원래 사용하던 에디션과 정확히 일치하는지부터 확인하는 것이 먼저입니다.","faq":[{"q":"Home에 Pro 제품 키를 입력해도 되나요?","a":"제품 키와 설치된 Windows 에디션이 맞아야 합니다. Home과 Pro가 다르면 키가 유효해도 0xC004F050이 발생할 수 있으므로 에디션을 먼저 확인하세요."},{"q":"제품 키를 공개해도 되나요?","a":"제품 키 전체는 공유하거나 게시하지 마세요. 구매 증빙과 키는 판매처 또는 Microsoft 공식 지원에만 제공하는 것이 안전합니다."}],"decisionSteps":[{"condition":"에디션이 다를 때","action":"Home용 키를 Pro에 넣었다면 오류가 계속됩니다. 에디션에 맞는 키를 구하거나, Windows Store에서 Pro 업그레이드를 정식 구매하세요."},{"condition":"OEM 키를 다른 PC에 입력했을 때","action":"OEM 키는 원래 제조사가 출하한 PC에서만 유효합니다. 해당 PC가 맞다면 Microsoft 지원에 문의하고, 다른 PC라면 리테일 키를 별도로 구매해야 합니다."},{"condition":"단순 오타였을 때","action":"재입력만으로 대부분 즉시 해결됩니다."},{"condition":"모든 조건이 맞는데도 반복될 때","action":"Microsoft 고객 지원(전화 활성화)으로 넘어가 오류 코드와 라이선스 채널을 함께 전달하세요."}],"relatedSymptom":"windows-activation-error.html","aliases":["c004f050","0xc004f050","invalid product key","제품 키 오류"],"communityCases":[{"title":"Home·Pro 에디션 불일치로 발생한 사례","summary":"Pro 제품 키를 보유했지만 PC에는 Home 에디션이 설치되어 있어 0xC004F050이 표시됐습니다. 설치 에디션을 라이선스와 맞춘 뒤 정품 인증을 다시 진행했습니다.","insight":"제품 키가 틀렸다고 판단하기 전에 설정 화면의 Windows 에디션과 키의 대상 에디션이 같은지 확인하는 것이 우선입니다."}],"officialSource":{"title":"Microsoft Support: Windows 10 activation error 0xC004F050","url":"https://support.microsoft.com/en-us/windows/windows-10-activation-error-0xc004f050-68e6850d-b0b7-fc3b-6776-36a62f47d3ea"}},{"code":"0x80070057","title":"매개 변수가 올바르지 않음","overview":"설치나 업데이트, 명령 실행 시 시스템이 받은 입력값이나 설정값을 처리할 수 없을 때 나타나는 오류입니다. 겉보기엔 단순해 보이지만 실제 원인은 다양할 수 있습니다.","summary":"설치나 업데이트, 명령 실행 시 시스템이 받은 입력값이나 설정값을 처리할 수 없을 때 나타나는 오류입니다.","causes":["업데이트 구성 파일이나 레지스트리 값이 손상된 경우","디스크 파티션 형식(MBR/GPT)이 설치 방식과 맞지 않는 경우","USB 설치 미디어 제작 시 파일 시스템(FAT32/NTFS) 설정이 잘못된 경우","그룹 정책에서 지원하지 않는 옵션을 강제로 지정한 경우","백업/복원 도구에서 지정한 경로나 옵션 형식이 맞지 않는 경우"],"checks":["최근 변경한 설정이나 정책이 있다면 기본값으로 되돌려 보세요.","설치 미디어를 사용 중이라면 공식 미디어 생성 도구로 새로 만들어 보세요.","디스크 관리에서 대상 디스크의 파티션 형식을 확인하고 설치 방식(UEFI/레거시)과 일치하는지 점검하세요.","업데이트 재시도 전에 SoftwareDistribution 캐시를 정리해 구성 파일을 초기화하세요.","명령어를 직접 입력하는 작업이었다면 옵션 철자와 형식을 다시 확인하세요."],"link":"error-code-0x80070057.html","detailPage":"error-code-0x80070057.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x80070057)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"복구 화면에서 명령 프롬프트는 어떻게 여나요?","a":"고급 옵션 → 문제 해결 → 고급 옵션 → 명령 프롬프트 순서로 진입할 수 있습니다."}],"decisionSteps":[{"condition":"파티션 형식 문제로 확인될 때","action":"UEFI는 GPT, 레거시는 MBR로 맞춰 다시 설치하세요."},{"condition":"SoftwareDistribution 정리로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"명령어 옵션 문제였을 때","action":"정확한 문법으로 다시 시도하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["80070057","0x80070057"],"communityCases":[{"title":"DISM 복구로 매개변수 오류 해결","summary":"업데이트뿐 아니라 일부 시스템 도구 실행 시에도 이 오류가 발생했던 사례가 있습니다. DISM /Online /Cleanup-Image /RestoreHealth 실행 후 sfc /scannow로 시스템 파일을 복구하자 오류가 사라졌습니다.","insight":"이 오류가 여러 시스템 기능에서 동시에 나타난다면 시스템 파일 손상이 원인일 가능성이 높습니다. DISM으로 시스템 이미지를 복구하는 것이 가장 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_INVALID_PARAMETER","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x800F0922","title":"Windows 업데이트 실패","overview":"업데이트 설치 마지막 단계에서 실패가 반복될 때 나타나는 코드로, 시스템 예약 파티션 용량 부족이나 VPN/프록시 네트워크 설정이 흔한 원인입니다.","summary":"업데이트 설치 마지막 단계에서 실패가 반복될 때 나타나는 코드로, 시스템 예약 파티션 용량 부족이나 VPN/프록시 네트워크 설정이 흔한 원인입니다.","causes":["시스템 예약 파티션(System Reserved) 여유 공간이 부족한 경우","VPN이나 프록시 설정이 업데이트 서버 연결을 방해하는 경우","이전 업데이트 실패 잔여 파일이 새 업데이트와 충돌하는 경우",".NET Framework 관련 구성 요소가 손상된 경우","디스크 여유 공간이 전체적으로 부족한 경우"],"checks":["디스크 관리에서 시스템 예약 파티션 용량을 확인하세요. 여유가 거의 없다면 파티션 확장이 필요할 수 있습니다.","VPN이나 프록시를 사용 중이라면 임시로 해제한 뒤 업데이트를 다시 시도하세요.","디스크 정리로 최소 10~15GB 이상의 여유 공간을 확보하세요.","Windows Update 문제 해결사를 실행해 자동으로 손상된 구성 요소를 점검하세요.","반복 실패한다면 업데이트 어시스턴트를 이용해 수동으로 최신 버전을 재설치해 보세요."],"link":"error-code-0x800f0922.html","detailPage":"error-code-0x800f0922.html","narrative":"이 코드가 설치 '마지막 단계'에서 자주 나타나는 이유는, Windows 업데이트가 새 파일을 받는 단계보다 그 파일들을 시스템 예약 파티션에 실제로 적용하는 단계에서 더 많은 여유 공간과 정상적인 네트워크 경로를 요구하기 때문입니다. 시스템 예약 파티션은 C드라이브와 별도로 아주 작게(보통 100MB~수백MB) 잡혀 있어서, 몇 년째 업데이트를 반복해온 PC일수록 이 파티션이 포화 상태에 가까워져 있는 경우가 흔합니다. VPN이나 회사 프록시를 사용 중이라면 파일을 받는 것 자체는 되더라도, 마지막에 Windows Update 서버와 주고받는 인증 절차가 막히면서 같은 지점에서 실패가 반복될 수 있습니다.","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x800F0922)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"외장 하드를 연결한 상태에서도 복구를 시도해도 되나요?","a":"외장 장치가 부팅 순서에 영향을 줄 수 있으므로, 복구 시도 전에는 분리하는 것이 좋습니다."}],"decisionSteps":[{"condition":"시스템 예약 파티션 확장으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"VPN·프록시 해제로 해결될 때","action":"업데이트 중에만 VPN을 끄는 습관을 들이세요."},{"condition":"업데이트 어시스턴트로도 실패할 때","action":"클린 설치를 고려하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["800f0922","0x800f0922"],"communityCases":[{"title":"시스템 예약 파티션 확장 후 업데이트 성공","summary":"대형 업데이트 설치 시 이 오류가 반복됐던 사례에서, 시스템 예약 파티션이 100MB로 작게 설정되어 업데이트 파일이 들어갈 공간이 부족한 것이 원인이었습니다. Diskpart로 파티션을 확장하자 업데이트가 정상적으로 완료됐습니다.","insight":"이 오류는 업데이트 파일을 시스템 예약 파티션에 쓸 수 없을 때 발생합니다. 파티션 크기가 250MB 미만이라면 확장을 고려하세요."}],"officialSource":{"title":"Microsoft Learn: Error code 0x800f0922 when installing Windows updates","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/error-0x800f0922-installing-windows-updates"}},{"code":"0x80070005","title":"Access Denied","overview":"관리자 권한이 필요한 작업을 일반 권한으로 시도했거나, 보안 소프트웨어가 접근을 차단했을 때 나타나는 권한 오류입니다.","summary":"관리자 권한이 필요한 작업을 일반 권한으로 시도했거나, 보안 소프트웨어가 접근을 차단했을 때 나타나는 권한 오류입니다.","causes":["관리자 권한 없이 시스템 파일이나 설정에 접근하려 한 경우","보안 소프트웨어(백신, 방화벽)가 해당 프로그램의 접근을 차단한 경우","폴더나 파일의 소유권이 다른 계정으로 되어 있는 경우","그룹 정책으로 특정 기능에 대한 접근이 제한된 경우","사용자 계정 컨트롤(UAC) 설정이 지나치게 엄격한 경우"],"checks":["해당 프로그램이나 명령 프롬프트를 마우스 우클릭 후 '관리자 권한으로 실행'으로 다시 시도하세요.","보안 프로그램을 임시로 비활성화한 뒤 같은 작업을 재현해 차단 여부를 확인하세요.","문제되는 폴더나 파일을 우클릭 > 속성 > 보안 탭에서 현재 계정의 권한을 확인하고 필요시 소유권을 가져오세요.","회사나 학교 PC라면 그룹 정책으로 제한된 기능인지 관리자에게 확인하세요.","UAC 설정을 기본값으로 되돌린 뒤 다시 시도해 보세요."],"link":"error-code-0x80070005.html","detailPage":"error-code-0x80070005.html","faq":[{"q":"프린터를 재설치하면 바로 해결되나요?","a":"이 문제(0x80070005)는 드라이버보다 서비스나 권한 문제인 경우가 많아, 재설치 전에 스풀러 서비스 상태부터 확인하는 것이 순서상 더 빠릅니다."},{"q":"프린터 스풀러 서비스를 재시작하면 도움이 되나요?","a":"네, services.msc에서 Print Spooler 서비스를 재시작하면 멈춰있던 인쇄 대기열이 정리되며 문제가 해결되는 경우가 많습니다."}],"decisionSteps":[{"condition":"관리자 권한으로 재실행해 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"보안 소프트웨어 예외 등록으로 해결될 때","action":"등록한 예외 항목을 잊지 말고 기록해 두세요."},{"condition":"소유권 변경이나 그룹 정책 확인으로도 해결되지 않을 때","action":"해당 드라이브의 NTFS 압축 설정을 점검하세요."}],"relatedSymptom":"windows-printer-add-freeze.html","aliases":["80070005","0x80070005"],"communityCases":[{"title":"드라이브 압축 해제로 해결한 사례","summary":"마이크로소프트 스토어 앱 설치가 이 오류로 계속 실패했던 사례가 있습니다. 관리자 권한, 폴더 권한 부여 등 일반적인 방법으로는 해결되지 않았는데, 앱을 설치하려던 보조 드라이브에 걸려 있던 NTFS 압축(디스크 공간 절약) 기능을 해제한 뒤 정상적으로 설치됐습니다.","insight":"C 드라이브가 아닌 다른 드라이브에 앱이나 프로그램을 설치할 때 이 오류가 난다면, 그 드라이브에 압축 기능이 켜져 있지 않은지 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_ACCESS_DENIED","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x80070522","title":"필요한 권한이 클라이언트에 없습니다","overview":"파일을 복사·저장·압축 해제하거나 Windows 업그레이드 중 필요한 권한이 없을 때 나타나는 오류입니다. 관리자 계정이라도 보호된 폴더 또는 드라이브 루트에서는 일반 권한으로 실행한 앱이 차단될 수 있습니다.","summary":"보호된 위치에서 작업하는 앱에 필요한 권한이 없어 발생하는 오류입니다.","plainExplanation":"관리자 계정으로 로그인했더라도 모든 앱이 항상 관리자 권한으로 실행되는 것은 아닙니다. 먼저 문서·다운로드 같은 사용자 폴더에 저장해 보고, 꼭 필요한 경우에만 신뢰할 수 있는 앱을 관리자 권한으로 다시 실행하세요.","causes":["C:\\ 또는 보조 드라이브 루트처럼 보호된 위치에 일반 권한 앱이 파일을 만들려는 경우","압축 해제·설치 프로그램이 관리자 권한 없이 시스템 폴더를 변경하려는 경우","회사·학교 PC의 정책 또는 보안 프로그램이 작업을 제한한 경우"],"checks":["먼저 파일을 문서·다운로드처럼 사용자 폴더에 저장하거나 압축을 푼 뒤 작업이 되는지 확인하세요.","신뢰할 수 있는 공식 설치 파일·도구에 한해 '관리자 권한으로 실행'을 한 번 시험하세요.","드라이브 전체의 소유권·권한을 일괄 변경하거나 UAC를 끄지 마세요. 회사·학교 PC라면 관리자에게 정책을 확인하세요."],"link":"security-access-errors.html?code=0x80070522","detailPage":"security-access-errors.html?code=0x80070522","relatedSymptom":"windows-app-not-launching.html","aliases":["80070522","0x80070522","필요한 권한","a required privilege is not held"],"communityCases":[{"title":"관리자 권한으로 실행하여 해결한 사례","summary":"특정 시스템 폴더에 파일을 복사하거나 업데이트를 적용할 때 이 오류가 나왔던 사례가 있습니다. 일반 계정으로 작업을 진행하다 발생했고, 관리자 권한으로 명령 프롬프트를 실행하거나 관리자 계정으로 전환하자 정상적으로 진행됐습니다.","insight":"이 오류는 권한 문제입니다. 실행 중인 계정이 로컬 관리자인지 확인하고, 로컬 관리자라도 관리자 권한으로 실행하지 않으면 이 오류가 발생할 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_PRIVILEGE_NOT_HELD","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1300-1699-"}},{"code":"0x80090016","title":"키 세트가 없습니다 (TPM·Windows Hello·회사 계정)","overview":"Windows Hello, Office·Teams 로그인, 회사·학교 계정 연결처럼 TPM 또는 인증 키를 쓰는 기능에서 필요한 키를 찾지 못할 때 나타납니다. 메인보드 교체나 조직 계정 등록 상태 변경 뒤에 특히 확인할 항목입니다.","summary":"TPM 또는 계정 인증에 필요한 키 세트를 찾지 못한 오류입니다.","plainExplanation":"비밀번호가 틀렸다는 뜻만은 아닙니다. PC의 보안 칩과 회사·학교 계정에 연결된 인증 키가 맞지 않을 수 있으므로, TPM을 지우기 전에 BitLocker 복구 키와 로그인 수단을 먼저 확보해야 합니다.","causes":["메인보드 교체·TPM 초기화 뒤 기존 계정 인증 키가 맞지 않는 경우","회사·학교 계정 또는 Microsoft 365 장치 등록 상태가 꼬인 경우","TPM 키에 접근하지 못해 Windows Hello·인증서 기반 로그인이 실패한 경우"],"checks":["BitLocker가 켜져 있다면 TPM 초기화 전에 복구 키를 반드시 백업하고, 다른 로그인 방법이 있는지 확인하세요.","설정의 계정 > 회사 또는 학교 액세스에서 해당 조직 계정 연결 상태를 확인하고, 조직 PC라면 임의 연결 해제 전에 관리자에게 문의하세요.","개인 PC에서 TPM 초기화가 필요하다는 제조사·Microsoft 안내가 확인된 경우에만 진행하고, 초기화 뒤 재부팅하여 계정·Windows Hello를 다시 설정하세요."],"link":"security-access-errors.html?code=0x80090016","detailPage":"security-access-errors.html?code=0x80090016","relatedSymptom":"windows-app-not-launching.html","aliases":["80090016","0x80090016","keyset does not exist","tpm malfunctioned","키 세트"],"communityCases":[{"title":"TPM 초기화 후 PIN 재설정으로 해결한 사례","summary":"윈도우 Hello PIN이 갑자기 작동하지 않고 이 오류가 발생했던 사례가 있습니다. 설정에서 PIN을 제거 후 재설정하려 해도 같은 오류가 났는데, TPM 관리 도구(tpm.msc)에서 TPM을 초기화한 뒤 PIN을 새로 설정하자 정상 작동했습니다.","insight":"TPM 키 세트 오류는 TPM 칩의 저장된 키 정보가 손상되거나 초기화가 필요한 상태일 때 발생합니다. 데이터 백업 후 TPM 초기화를 시도하는 것이 근본적인 해결 방법입니다."}],"officialSource":{"title":"Microsoft Learn: 0x80090016 TPM 키 문제 해결","url":"https://learn.microsoft.com/en-us/troubleshoot/mem/intune/comanage-configmgr/troubleshoot-co-management-auto-enrolling"}},{"code":"0x8009030D","title":"제공한 자격 증명을 인증 패키지가 인식하지 못했습니다","overview":"원격 데스크톱, 회사 네트워크, 도메인·Kerberos 같은 인증 환경에서 제공한 자격 증명을 보안 패키지가 인식하지 못할 때 나타날 수 있습니다. 일반 개인 PC보다 회사·학교 계정 환경에서 우선 확인합니다.","summary":"보안 인증 패키지가 제공된 자격 증명을 인식하지 못한 오류입니다.","causes":["저장된 회사·학교 계정 자격 증명이 오래되었거나 잘못된 경우","도메인·VPN·원격 데스크톱 대상의 계정 또는 대상 이름이 맞지 않는 경우","조직의 인증서·Kerberos·계정 정책 문제가 있는 경우"],"checks":["오류가 나는 서비스와 계정 종류(개인 Microsoft 계정·회사 계정·도메인 계정)를 먼저 구분하세요.","자격 증명 관리자에서 해당 서비스의 오래된 저장 자격 증명을 확인하되, 회사 계정 항목 삭제 전에는 IT 관리자 안내를 받으세요.","회사·학교 PC에서는 VPN 연결, 시스템 시간, 계정 상태를 확인하고 반복되면 오류 시각과 대상 서버 이름을 IT 관리자에게 전달하세요."],"link":"security-access-errors.html?code=0x8009030D","detailPage":"security-access-errors.html?code=0x8009030D","relatedSymptom":"windows-app-not-launching.html","aliases":["8009030d","0x8009030d","sec_e_unknown_credentials","unknown credentials","자격 증명 인식"],"communityCases":[{"title":"자격 증명 관리자 초기화로 인증 오류 해결","summary":"회사 계정으로 로그인할 때 이 오류가 발생했던 사례가 있습니다. 자격 증명 관리자에서 회사 관련 저장된 자격 증명을 모두 삭제한 뒤 다시 로그인하자 정상 인증됐습니다.","insight":"이 오류는 저장된 자격 증명이 만료되거나 손상됐을 때 자주 발생합니다. 자격 증명 관리자(제어판)에서 관련 항목을 삭제하고 재인증하는 것이 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: SEC_E_UNKNOWN_CREDENTIALS","url":"https://learn.microsoft.com/en-us/windows/win32/api/sspi/nf-sspi-importsecuritycontexta"}},{"code":"0x8009030E","title":"보안 패키지에 사용할 자격 증명이 없습니다","overview":"원격 데스크톱·VPN·도메인 인증처럼 Windows 보안 패키지가 사용할 계정 자격 증명을 찾지 못한 경우입니다. 단순 비밀번호 재입력보다 네트워크 연결, 계정 등록, 조직 인증 정책을 순서대로 확인해야 합니다.","summary":"보안 인증 패키지에 사용할 자격 증명이 없어 인증을 시작하지 못한 오류입니다.","causes":["회사·학교 계정 또는 도메인 로그인이 정상적으로 등록되지 않은 경우","VPN·네트워크 연결이 끊겨 필요한 인증 기관에 접근하지 못한 경우","저장된 인증서·자격 증명이 제거되었거나 정책으로 사용할 수 없는 경우"],"checks":["개인 계정 문제인지 회사·학교 계정 문제인지 먼저 구분하고, 필요한 VPN 연결 상태를 확인하세요.","설정의 계정 > 회사 또는 학교 액세스에서 조직 계정의 연결 상태를 확인하세요.","회사·학교 PC는 자격 증명·인증서 삭제나 레지스트리 수정 전에 IT 관리자에게 오류 시각과 서비스 이름을 전달하세요."],"link":"security-access-errors.html?code=0x8009030E","detailPage":"security-access-errors.html?code=0x8009030E","relatedSymptom":"windows-app-not-launching.html","aliases":["8009030e","0x8009030e","sec_e_no_credentials","no credentials","자격 증명 없음"],"communityCases":[{"title":"자격 증명 삭제 후 재입력으로 인증 오류 해결","summary":"네트워크 공유 폴더 접근 시 이 오류가 반복됐던 사례가 있습니다. 자격 증명 관리자에서 해당 네트워크 위치의 저장된 자격 증명을 삭제하고 다시 연결을 시도하자 정상 접속이 됐습니다.","insight":"이 오류는 인증 패키지가 올바른 자격 증명을 찾지 못할 때 발생합니다. 자격 증명 관리자에서 관련 항목을 삭제하고 재입력하는 것이 가장 간단한 해결책입니다."}],"officialSource":{"title":"Microsoft Learn: SEC_E_NO_CREDENTIALS","url":"https://learn.microsoft.com/en-us/windows/win32/api/sspi/nf-sspi-initializesecuritycontexta"}},{"code":"제어된 폴더 액세스 차단","title":"Windows 보안이 앱의 폴더 변경을 차단했습니다","overview":"Windows 보안의 랜섬웨어 방지 기능이 신뢰하지 않는 앱이 문서·바탕화면·사진 같은 보호 폴더를 변경하지 못하게 할 때 나타나는 알림입니다. 기능을 끄기보다 차단된 앱의 경로와 출처를 확인한 뒤 필요한 앱만 허용하세요.","summary":"제어된 폴더 액세스가 보호 폴더에 대한 앱의 저장·변경을 차단한 상태입니다.","plainExplanation":"파일을 저장하지 못해도 앱이나 파일이 고장 난 것은 아닐 수 있습니다. Windows 보안이 랜섬웨어 예방을 위해 해당 앱을 신뢰 목록에 넣지 않은 상태일 수 있습니다.","causes":["제어된 폴더 액세스가 켜진 상태에서 신뢰되지 않은 앱이 보호 폴더에 파일을 저장하려는 경우","새로 설치했거나 업데이트된 앱의 실행 파일 경로가 기존 허용 목록과 달라진 경우","앱의 파일 시스템 접근 권한 또는 보안 제품 정책이 제한된 경우"],"checks":["Windows 보안 알림에서 차단된 앱의 경로와 파일 이름을 확인하고, 출처를 모르면 허용하지 마세요.","신뢰할 수 있는 공식 앱이라면 Windows 보안 > 바이러스 및 위협 방지 > 랜섬웨어 방지 관리에서 해당 앱만 허용하세요.","급한 저장은 다른 사용자 폴더에 먼저 하고, 기능 전체를 끄거나 폴더 전체를 예외 처리하지 마세요."],"link":"security-access-errors.html?code=제어된%20폴더%20액세스%20차단","detailPage":"security-access-errors.html?code=제어된%20폴더%20액세스%20차단","relatedSymptom":"windows-app-not-launching.html","aliases":["제어된 폴더 액세스","controlled folder access","앱이 차단됨","랜섬웨어 방지","폴더 저장 차단"],"communityCases":[{"title":"허용 앱 목록 추가로 폴더 액세스 차단 해결","summary":"특정 백업 프로그램이 갑자기 지정 폴더에 파일을 저장하지 못하는 문제가 발생했던 사례가 있습니다. 윈도우 보안 알림을 보니 제어된 폴더 액세스 기능이 해당 앱을 차단하고 있었고, 허용 앱으로 등록하자 정상 동작했습니다.","insight":"제어된 폴더 액세스가 활성화되어 있다면 신뢰하는 앱도 차단될 수 있습니다. 알림에서 앱을 직접 허용하거나 윈도우 보안 설정의 허용 앱 목록에 추가하세요."}],"officialSource":{"title":"Microsoft 지원: Windows 보안의 제어된 폴더 액세스","url":"https://support.microsoft.com/en-us/windows/security/threat-malware-protection/virus-and-threat-protection-in-the-windows-security-app"}},{"code":"0x80004005","title":"Unspecified error","overview":"구글의 다른 코드처럼 특정 원인 하나로 좁혀지지 않는 포괄적인 오류 코드입니다. 캐시 손상, 권한 문제, 네트워크 문제 등 여러 상황에서 공통으로 나타날 수 있습니다.","summary":"구글의 다른 코드처럼 특정 원인 하나로 좁혀지지 않는 포괄적인 오류 코드입니다.","causes":["임시 파일이나 캐시가 손상되어 프로그램이 정상 동작을 못 하는 경우","보안 소프트웨어가 특정 동작을 차단한 경우","네트워크 드라이브나 공유 폴더 접근 권한이 꼬인 경우","레지스트리 값이 손상되었거나 이전 설치 잔여물이 남아있는 경우","타사 프로그램과의 호환성 문제"],"checks":["최근에 설치했거나 변경한 프로그램/설정이 있다면 먼저 되돌려 보세요.","브라우저나 앱 캐시, 임시 파일을 정리한 뒤 다시 실행해 보세요.","보안 프로그램을 임시로 비활성화하고 재현 여부를 확인하세요.","네트워크 드라이브 문제라면 연결을 끊었다가 다시 매핑해 보세요.","문제 프로그램을 완전히 제거한 뒤 재설치해 레지스트리 잔여물을 정리하세요."],"link":"error-code-0x80004005.html","detailPage":"error-code-0x80004005.html","narrative":"이 코드가 유난히 다루기 어려운 이유는 이름 그대로 '지정되지 않은 오류'라서, Windows가 원인을 세분화할 수 있는 더 구체적인 오류 코드를 찾지 못했을 때 마지막 수단으로 반환하는 값이기 때문입니다. 즉 이 코드 자체는 원인에 대해 알려주는 정보가 거의 없고, 어떤 프로그램·어떤 상황에서 떴는지가 훨씬 더 중요한 단서가 됩니다. 파일 탐색기에서 떴다면 캐시나 권한 문제일 가능성이, 특정 프로그램 설치 중에 떴다면 그 프로그램의 레지스트리 잔여물이나 백신 차단일 가능성이 높습니다. 코드만 검색해서 나오는 범용 해결법을 무작정 따라 하기보다, 정확히 어떤 동작(파일 복사, 설치, 네트워크 접근 등) 중에 떴는지부터 기록하는 것이 원인을 좁히는 첫걸음입니다.","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x80004005)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"자동 복구가 계속 실패하면 윈도우를 재설치해야 하나요?","a":"명령 프롬프트에서 부팅 복구 명령을 먼저 시도해보고, 그래도 안 되면 초기화나 재설치를 고려하는 것이 순서입니다."}],"decisionSteps":[{"condition":"캐시 정리로 해결될 때","action":"재발 방지를 위해 정기적으로 캐시를 정리하세요."},{"condition":"보안 프로그램 하나를 껐을 때 해결될 때","action":"그 프로그램의 예외 목록에 관련 프로그램을 등록하세요."},{"condition":"재설치 후에도 반복될 때","action":"여러 프로그램에서 동시에 발생하는지 확인해 시스템 파일 손상 여부를 sfc /scannow로 점검하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["80004005","0x80004005"],"communityCases":[{"title":"VirtualBox 재설치로 가상화 오류 해결","summary":"VirtualBox 버전을 업데이트한 뒤 가상 머신을 실행할 때 이 오류가 발생했던 사례가 있습니다. VirtualBox를 완전히 제거하고 최신 버전으로 재설치하자 정상 작동했습니다.","insight":"이 오류는 가상화 소프트웨어, 네트워크 공유, 업데이트 등 다양한 상황에서 발생합니다. 오류 발생 맥락(어떤 프로그램에서 발생했는지)을 먼저 파악하는 것이 해결 방향을 잡는 데 도움이 됩니다."}],"officialSource":{"title":"Microsoft Learn: Error 0x80004005","url":"https://learn.microsoft.com/en-us/answers/questions/5831913/0x80004005-error"}},{"code":"0xC000000F","title":"부팅 정보 읽기 실패","overview":"윈도우가 부팅에 필요한 BCD(Boot Configuration Data) 정보를 읽지 못했을 때 나타나는 오류로, 부팅 자체가 되지 않는 심각한 증상으로 이어집니다.","summary":"윈도우가 부팅에 필요한 BCD(Boot Configuration Data) 정보를 읽지 못했을 때 나타나는 오류로, 부팅 자체가 되지 않는 심각한 증상으로 이어집니다.","causes":["부트 레코드(BCD)가 손상되거나 삭제된 경우","저장장치 케이블이나 슬롯 접촉이 불량한 경우","듀얼 부팅 구성 중 다른 운영체제 설치가 부팅 정보를 덮어쓴 경우","정전이나 강제 종료로 부팅 파일이 손상된 경우","메인보드 펌웨어(BIOS/UEFI) 설정이 최근 변경된 경우"],"checks":["저장장치 연결 상태를 물리적으로 다시 확인하세요.","설치 미디어로 부팅해 복구 환경으로 진입한 뒤 bootrec /rebuildbcd 명령으로 부팅 정보를 재생성하세요.","듀얼 부팅 환경이라면 최근 설치한 다른 운영체제가 부팅 정보를 바꿨는지 확인하세요.","BIOS/UEFI 설정에서 부팅 순서와 모드(UEFI/레거시)가 원래대로인지 점검하세요.","복구로도 해결되지 않으면 시스템 복원 지점이나 백업을 통한 복구를 고려하세요."],"link":"error-code-0xc000000f.html","detailPage":"error-code-0xc000000f.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0xC000000F)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"복구 화면에서 명령 프롬프트는 어떻게 여나요?","a":"고급 옵션 → 문제 해결 → 고급 옵션 → 명령 프롬프트 순서로 진입할 수 있습니다."}],"decisionSteps":[{"condition":"bootrec /rebuildbcd로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"듀얼 부팅 환경에서 다른 OS 설치가 원인일 때","action":"부팅 메뉴 관리 도구로 BCD를 다시 구성하세요."},{"condition":"복구로도 해결되지 않을 때","action":"저장장치 자체의 물리적 문제일 수 있으므로 백업 후 디스크 상태를 점검하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["c000000f","0xc000000f"],"communityCases":[{"title":"bootrec 명령으로 BCD 재구성 후 해결","summary":"갑작스러운 정전 이후 부팅이 안 되고 이 오류가 나타났던 사례가 있습니다. 윈도우 복구 환경에서 bootrec /scanos, bootrec /rebuildbcd를 순서대로 실행하자 부팅 정보가 복구되어 정상 부팅이 가능해졌습니다.","insight":"이 오류는 BCD(부팅 구성 데이터)가 손상되거나 없을 때 발생합니다. 복구 환경(USB 설치 미디어)에서 bootrec 명령을 실행하는 것이 가장 빠른 해결 방법입니다."}],"officialSource":{"title":"Microsoft Learn: Windows startup issues troubleshooting","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/windows-boot-issues-troubleshooting"}},{"code":"0x000000EF","title":"CRITICAL_PROCESS_DIED","overview":"윈도우 핵심 프로세스가 예기치 않게 종료되며 나타나는 블루스크린으로, 0xC000021A와 증상이 유사하지만 커널 레벨에서 발생한다는 차이가 있습니다.","summary":"윈도우 핵심 프로세스가 예기치 않게 종료되며 나타나는 블루스크린으로, 0xC000021A와 증상이 유사하지만 커널 레벨에서 발생한다는 차이가 있습니다.","causes":["시스템 파일이 손상되어 핵심 프로세스가 비정상 종료되는 경우","최근 설치한 드라이버가 커널 프로세스와 충돌하는 경우","디스크 오류로 필요한 시스템 파일을 읽지 못하는 경우","맬웨어 감염으로 시스템 프로세스가 강제 종료되는 경우","업데이트 도중 강제 종료되어 파일이 일부만 반영된 경우"],"checks":["안전 모드 부팅이 가능한지 확인하고, 가능하다면 최근 설치 항목부터 점검하세요.","명령 프롬프트에서 sfc /scannow와 DISM /Online /Cleanup-Image /RestoreHealth를 차례로 실행하세요.","디스크 상태를 chkdsk로 점검하세요.","최근 설치한 드라이버나 프로그램을 제거한 뒤 재현 여부를 확인하세요.","백신 프로그램으로 전체 검사를 실행해 맬웨어 감염 여부를 확인하세요."],"link":"error-code-0x000000ef.html","detailPage":"error-code-0x000000ef.html","narrative":"CRITICAL_PROCESS_DIED는 이름 그대로 윈도우가 절대 잃어서는 안 되는 핵심 프로세스(csrss.exe, wininit.exe처럼 커널과 직접 맞닿은 프로세스)가 사라졌다는 뜻입니다. 일반 프로그램이 죽으면 그 창만 닫히고 시스템은 계속 동작하지만, 이 프로세스들은 윈도우 자체를 지탱하는 뼈대라서 하나라도 사라지면 더 이상 안전한 동작을 보장할 수 없어 곧바로 블루스크린으로 전환됩니다. 0xC000021A와 증상이 비슷해 보이는 것도 이 때문인데, 0xC000021A는 사용자 세션 쪽에서 프로세스 종료를 감지한 경우이고 0x000000EF는 커널이 더 이른 시점에 직접 포착한 경우라 접근 방법이 달라집니다. 부팅 직후에 반복된다면 시스템 파일 손상 쪽에, 특정 작업 중에만 발생한다면 그 순간 함께 실행되는 드라이버 쪽에 먼저 무게를 두고 좁혀가는 것이 효율적입니다.","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000EF)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"블루스크린 이후 데이터가 손상되나요?","a":"대부분은 강제 재시작만 발생할 뿐 저장된 파일이 곧바로 손상되지는 않지만, 저장하지 않은 작업 내용은 사라질 수 있습니다."}],"decisionSteps":[{"condition":"sfc·DISM으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"최근 드라이버·프로그램 제거로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"chkdsk·백신 검사로도 해결되지 않을 때","action":"사례처럼 다른 보조 저장장치를 분리해 테스트해보세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["ef","000000ef","0xef"],"communityCases":[{"title":"보조 하드디스크 제거로 해결한 사례","summary":"부팅 드라이브(SSD)가 재부팅 후 인식되지 않으면서 이 블루스크린이 반복됐던 사례가 있습니다. SSD 자체는 여러 진단에서 정상으로 나왔는데, 시스템에 함께 연결되어 있던 오래된 보조 하드디스크(HDD)를 완전히 분리한 뒤 문제가 사라졌습니다. 상태가 나빠진 보조 디스크가 SATA 컨트롤러 전체를 물고 늘어지면서 부팅 드라이브까지 응답하지 않게 만들었던 것으로 보입니다.","insight":"부팅 드라이브 자체는 정상으로 진단되는데도 이 오류가 반복된다면, 함께 연결된 다른 저장장치(특히 오래된 보조 하드디스크)를 하나씩 분리해보며 원인을 좁혀보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xEF CRITICAL_PROCESS_DIED","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xef--critical-process-died"}},{"code":"0x000000D1","title":"DRIVER_IRQL_NOT_LESS_OR_EQUAL","overview":"드라이버가 자신에게 허용되지 않은 높은 인터럽트 수준에서 메모리에 접근하려 할 때 발생하는 코드로, 대부분 특정 드라이버 하나가 원인입니다.","summary":"드라이버가 자신에게 허용되지 않은 높은 인터럽트 수준에서 메모리에 접근하려 할 때 발생하는 코드로, 대부분 특정 드라이버 하나가 원인입니다.","causes":["네트워크, 그래픽, 사운드 등 특정 드라이버가 최신 윈도우 빌드와 호환되지 않는 경우","드라이버 설치 파일 자체가 손상된 경우","보안 소프트웨어가 드라이버 동작을 간섭하는 경우","램 불안정으로 드라이버가 잘못된 메모리 주소를 참조하는 경우","USB 허브나 외장 장치의 드라이버 충돌"],"checks":["블루스크린 화면이나 이벤트 뷰어에서 어떤 드라이버 파일(.sys)이 언급되는지 확인하세요.","해당 드라이버를 제조사 최신 버전으로 재설치하거나, 최근 업데이트했다면 이전 버전으로 되돌리세요.","안전 모드에서 재현되지 않는다면 특정 드라이버가 원인일 가능성이 높습니다.","메모리 진단 도구로 램 상태를 점검하세요.","최근 연결한 외장 장치(USB, 프린터 등)를 분리한 뒤 재현 여부를 확인하세요."],"link":"error-code-0x000000d1.html","detailPage":"error-code-0x000000d1.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000D1)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\\\Windows\\\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"안전 모드에서는 재현되지 않을 때","action":"특정 드라이버가 원인으로 확정되므로 하나씩 롤백해 특정하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["d1","000000d1","0xd1"],"communityCases":[{"title":"VPN 클라이언트 드라이버 제거로 IRQL 오류 해결","summary":"VPN 프로그램을 설치한 뒤부터 DRIVER_IRQL_NOT_LESS_OR_EQUAL 블루스크린이 발생했던 사례가 있습니다. 블루스크린 덤프 파일을 분석하니 VPN 클라이언트의 가상 네트워크 어댑터 드라이버가 원인이었고, 해당 VPN을 제거한 뒤 문제가 사라졌습니다.","insight":"이 오류는 드라이버가 잘못된 IRQL에서 메모리에 접근할 때 발생합니다. 최근 설치한 프로그램(특히 VPN, 보안 소프트웨어, 네트워크 관련)의 드라이버를 우선 점검하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xD1 DRIVER_IRQL_NOT_LESS_OR_EQUAL","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xd1--driver-irql-not-less-or-equal"}},{"code":"0x0000009F","title":"DRIVER_POWER_STATE_FAILURE","overview":"절전 모드 진입이나 복귀, 혹은 종료 과정에서 특정 드라이버가 전원 상태 전환 요청에 제때 응답하지 못할 때 나타나는 코드입니다.","summary":"절전 모드 진입이나 복귀, 혹은 종료 과정에서 특정 드라이버가 전원 상태 전환 요청에 제때 응답하지 못할 때 나타나는 코드입니다.","causes":["네트워크 어댑터나 USB 장치의 절전 관련 드라이버가 응답하지 않는 경우","전원 관리 설정이 하드웨어와 맞지 않게 구성된 경우","그래픽 드라이버가 절전 복귀 시 초기화에 실패하는 경우","최근 연결한 외장 장치가 절전 신호를 제대로 처리하지 못하는 경우","바이오스 전원 관리 설정과 윈도우 전원 옵션이 충돌하는 경우"],"checks":["절전 모드에서 복귀한 직후에만 증상이 나타나는지 확인하세요.","장치 관리자에서 네트워크 어댑터의 전원 관리 탭에 있는 '전원 절약을 위해 이 장치를 끌 수 있음' 옵션을 해제해 보세요.","그래픽 드라이버를 최신 버전으로 업데이트하세요.","최근 연결한 USB 장치를 분리한 뒤 절전 모드 진입/복귀를 테스트하세요.","전원 옵션에서 절전 모드 대신 최대 절전 모드나 화면 끄기만 사용하도록 임시로 바꿔 재현 여부를 확인하세요."],"link":"error-code-0x0000009f.html","detailPage":"error-code-0x0000009f.html","faq":[{"q":"절전 모드를 아예 꺼야 하나요?","a":"이 문제(0x0000009F)가 반복된다면 절전 기능 자체를 끄기보다 관련 드라이버와 전원 설정을 먼저 점검해, 절전 기능을 그대로 쓸 수 있는지 확인하는 것이 좋습니다."}],"decisionSteps":[{"condition":"특정 USB 장치를 분리했을 때 재현되지 않을 때","action":"그 장치의 드라이버를 업데이트하거나 전원 관리 옵션을 해제하세요."},{"condition":"네트워크 어댑터 전원 관리 옵션을 껐을 때 해결될 때","action":"그 설정을 그대로 유지하세요."},{"condition":"그래픽 드라이버 업데이트 후에도 반복될 때","action":"<code>powercfg /a</code>로 최신 대기 모드(Modern Standby) 지원 여부를 확인하고, 해당된다면 관련 가이드를 참고하세요."}],"relatedSymptom":"windows-sleep-resume-fail.html","aliases":["9f","0000009f","0x9f"],"communityCases":[{"title":"USB 선택적 절전 해제로 절전 복귀 오류 해결","summary":"절전 모드에서 복귀할 때마다 DRIVER_POWER_STATE_FAILURE 블루스크린이 발생했던 사례가 있습니다. 연결된 모든 USB 장치를 분리해도 재현됐는데, 전원 옵션에서 USB 선택적 절전 설정을 비활성화한 뒤 문제가 해결됐습니다.","insight":"이 오류가 절전 복귀에서만 나타난다면 USB 선택적 절전 또는 특정 드라이버의 절전 상태 전환 실패가 원인인 경우가 많습니다. 전원 관련 설정부터 점검하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x9F DRIVER_POWER_STATE_FAILURE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x9f--driver-power-state-failure"}},{"code":"0x00000116","title":"VIDEO_TDR_FAILURE","overview":"그래픽 드라이버가 정해진 시간 안에 응답하지 못해 윈도우가 강제로 드라이버를 재시작(TDR)하려다 실패했을 때 나타나는 코드로, 게임이나 고사양 작업 중 자주 발생합니다.","summary":"그래픽 드라이버가 정해진 시간 안에 응답하지 못해 윈도우가 강제로 드라이버를 재시작(TDR)하려다 실패했을 때 나타나는 코드로, 게임이나 고사양 작업 중 자주 발생합니다.","causes":["그래픽 드라이버 자체의 버그나 최신 게임과의 호환성 문제","GPU가 부하 상황에서 과도하게 발열되는 경우","그래픽카드 보조 전원 케이블 연결이 불안정한 경우","GPU 오버클럭 설정이 안정성 한계를 넘은 경우","오래된 그래픽 드라이버와 최신 윈도우 업데이트의 충돌"],"checks":["그래픽 드라이버를 완전히 제거(DDU 등 클린 제거 도구 사용)한 뒤 최신 버전으로 재설치하세요. <a href=\"graphics-driver-guide.html\">무료 도구로 재설치하는 방법 보기 →</a>","GPU 온도를 모니터링 프로그램으로 확인하고, 부하 시 과열되는지 점검하세요.","그래픽카드 보조 전원 케이블(6핀/8핀)이 완전히 꽂혀 있는지 확인하세요.","GPU나 CPU를 오버클럭했다면 기본 클럭으로 되돌려 재현 여부를 확인하세요.","다른 게임이나 벤치마크 프로그램에서도 같은 증상이 나오는지 확인해 특정 게임 문제인지 하드웨어 문제인지 구분하세요."],"link":"error-code-0x00000116.html","detailPage":"error-code-0x00000116.html","narrative":"TDR(Timeout Detection and Recovery)은 그래픽 드라이버가 일정 시간(기본 2초) 안에 응답하지 않으면 윈도우가 드라이버를 강제로 재시작해 화면을 되살리는 보호 장치입니다. 평소라면 이 복구가 성공해서 화면이 잠깐 깜빡이고 끝나지만, 0x00000116은 그 복구 시도마저 실패했다는 뜻이라 단순한 드라이버 지연보다 심각한 상황입니다. 복구가 왜 실패했는지는 드라이버 자체의 결함일 수도 있고, GPU가 응답할 여력조차 없을 만큼 전력·발열 문제가 심각했을 수도 있어 원인이 갈립니다. 게임 시작 직후처럼 GPU 부하가 갑자기 치솟는 순간에 반복된다면 드라이버보다 전원·발열 쪽을, 특정 그래픽 효과나 특정 게임에서만 재현된다면 드라이버 호환성 쪽을 먼저 좁혀보는 것이 효율적입니다.","faq":[{"q":"게임할 때만 재부팅되면 그래픽카드 문제인가요?","a":"이 문제(0x00000116)는 그래픽 드라이버 문제일 가능성이 높지만 전원 공급이나 온도 문제와 겹치는 경우도 많아, 드라이버 재설치와 함께 온도·전력 상태도 함께 확인하는 것이 좋습니다."},{"q":"쿨링 문제인지 전원 문제인지 구분하는 방법이 있나요?","a":"재부팅 직전 온도를 모니터링 프로그램으로 확인해, 온도가 정상 범위인데도 재부팅된다면 전원 문제일 가능성이 높습니다."}],"decisionSteps":[{"condition":"드라이버 클린 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"보조전원 재체결로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"오버클럭 해제로도 해결되지 않을 때","action":"사례처럼 라이저 케이블이나 PCIe 슬롯 속도를 확인하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["116","00000116","0x116"],"communityCases":[{"title":"PCIe 라이저 케이블 교체로 해결한 사례","summary":"그래픽카드를 세로로 거치하기 위해 PCIe 라이저 케이블을 사용한 뒤부터 이 블루스크린이 반복됐던 사례가 있습니다. 드라이버나 그래픽카드 자체의 문제가 아니라, 라이저 케이블이 PCIe 4.0(Gen4) x16 대역폭의 신호를 안정적으로 전달하지 못해 생긴 간섭이 원인이었습니다. BIOS에서 PCIe 슬롯 속도를 한 단계 낮춘 뒤(Gen4 → Gen3, 또는 x16 → x8) 문제가 사라졌습니다.","insight":"그래픽카드를 라이저 케이블로 연결한 구성(세로 거치, 확장형 케이스 등)에서 이 오류가 나타난다면, 케이블 자체의 신호 품질 문제일 수 있습니다. BIOS에서 PCIe 슬롯 속도를 한 단계 낮춰서 재현 여부를 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x116 VIDEO_TDR_FAILURE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x116---video-tdr-failure"}},{"code":"0x000000B4","title":"VIDEO_DRIVER_INIT_FAILURE","overview":"그래픽 드라이버(NVIDIA, AMD, Intel GPU 드라이버)가 초기화에 실패했을 때 발생합니다. 부팅 시 기본 초기화와 별개로, 게임·그래픽 프로그램 실행 시 드라이버가 추가 초기화를 수행하는 과정에서 그래픽카드와 통신하지 못하면 이 코드가 나타납니다.","summary":"그래픽 드라이버(NVIDIA, AMD, Intel GPU 드라이버)가 초기화에 실패했을 때 발생하며, 주로 게임 실행 중에 나타납니다.","causes":["그래픽 드라이버 손상 또는 호환성 문제(가장 흔함)","그래픽카드 과열 또는 전원 부족","게임이 요구하는 그래픽 기능을 드라이버가 지원하지 않는 경우","그래픽카드 하드웨어 자체의 결함(드라이버를 재설치해도 계속 발생)"],"checks":["제조사(NVIDIA·AMD·Intel) 공식 웹사이트에서 최신 그래픽 드라이버를 설치하세요.","최신 버전에서 문제가 시작됐다면 한두 달 전 안정 버전으로 롤백해 보세요.","HWiNFO나 GPU-Z로 그래픽카드 온도를 확인하고, 80도 이상이면 먼지 제거·쿨링을 점검하세요.","고사양 그래픽카드의 6핀·8핀 보조 전원 연결 상태를 확인하세요.","기본 드라이버 업데이트로 해결되지 않으면 DDU(NVIDIA)나 AMD Clean Uninstall Utility로 드라이버를 완전히 제거한 뒤 재설치하세요."],"link":"error-code-0x000000b4.html","detailPage":"error-code-0x000000b4.html","narrative":"이 코드는 부팅 시의 기본 그래픽 초기화가 아니라, 게임이나 그래픽 프로그램이 실행되면서 드라이버에게 더 높은 성능 모드로 전환할 것을 요청하는 시점에 주로 나타납니다. 그 전환 과정에서 드라이버가 그래픽카드와 정상적으로 통신하지 못하면 초기화가 실패로 끝나는 것입니다. 그래서 평소 사용에는 문제가 없다가 특정 게임을 켤 때만 이 오류가 뜨는 패턴이 흔하고, 드라이버 버전 자체의 문제인지 하드웨어 쪽 문제인지는 이전 버전으로 롤백했을 때 재현되는지로 갈립니다.","faq":[{"q":"게임할 때만 이 오류가 뜨는데 그래픽카드 고장인가요?","a":"꼭 그렇지는 않습니다. 드라이버 손상이나 호환성 문제가 가장 흔한 원인이라, 재설치·롤백으로 먼저 확인하는 것이 순서입니다. 그래도 반복된다면 그때 하드웨어 결함을 의심하세요."},{"q":"최신 드라이버로 업데이트했는데도 계속 발생합니다.","a":"최신 버전 자체의 버그일 수 있습니다. 문제가 특정 업데이트 이후 시작됐다면 한두 달 전 안정 버전으로 롤백해보는 것이 효과적입니다."}],"decisionSteps":[{"condition":"드라이버 업데이트로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"온도가 높게 측정될 때","action":"쿨링 점검을 우선하세요."},{"condition":"DDU 클린 재설치로도 해결되지 않을 때","action":"그래픽카드 자체 결함 가능성이 있으므로 다른 시스템에서 테스트해보세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["b4","000000b4","0xb4","video driver init failure","video_driver_init_failure"],"communityCases":[{"title":"DDU 클린 재설치로 해결한 사례","summary":"특정 게임 실행 시에만 VIDEO_DRIVER_INIT_FAILURE가 반복됐던 사례가 있습니다. 일반적인 드라이버 재설치로는 해결되지 않았지만, DDU로 기존 드라이버를 완전히 제거한 뒤 클린 설치하자 재발하지 않았습니다.","insight":"일반 설치 방식으로 해결되지 않는 드라이버 초기화 오류는 이전 드라이버의 잔여 파일이 원인인 경우가 많아 DDU 같은 클린 제거 도구가 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xB4 VIDEO_DRIVER_INIT_FAILURE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xb4--video-driver-init-failure"}},{"code":"0x00000133","title":"DPC_WATCHDOG_VIOLATION","overview":"시스템이 정해진 시간 안에 지연 프로시저 호출(DPC)을 처리하지 못했을 때 나타나는 코드로, 저장장치나 드라이버의 응답 지연이 주요 원인입니다.","summary":"시스템이 정해진 시간 안에 지연 프로시저 호출(DPC)을 처리하지 못했을 때 나타나는 코드로, 저장장치나 드라이버의 응답 지연이 주요 원인입니다.","causes":["SSD나 NVMe 저장장치의 펌웨어가 오래되었거나 버그가 있는 경우","저장장치 드라이버가 최신 윈도우 빌드와 호환되지 않는 경우","USB 장치나 카드리더의 드라이버 응답 지연","메인보드 칩셋 드라이버가 오래된 경우","디스크 자체의 물리적 결함으로 응답이 느려지는 경우","파워서플라이 노후화나 용량 부족으로 순간적인 전압 강하가 발생해 저장장치·컨트롤러 응답이 늦어지는 경우"],"checks":["저장장치 제조사 홈페이지에서 최신 펌웨어가 있는지 확인하고 업데이트하세요.","저장장치 컨트롤러 드라이버와 메인보드 칩셋 드라이버를 최신 버전으로 업데이트하세요.","최근 연결한 USB 장치나 카드리더를 분리한 뒤 재현 여부를 확인하세요.","디스크 상태 점검 도구(제조사 툴 또는 CrystalDiskInfo 등)로 건강 상태를 확인하세요.","문제가 반복되면 저장장치를 다른 슬롯이나 포트에 연결해 슬롯 자체의 문제인지 확인하세요.","위 점검으로 해결되지 않으면 파워서플라이 상태(용량, 노후화, 케이블 연결)도 점검하세요."],"link":"error-code-0x00000133.html","detailPage":"error-code-0x00000133.html","faq":[{"q":"SSD·NVMe를 바로 교체해야 하나요?","a":"이 문제(0x00000133)만으로 저장장치 고장을 단정하기는 어렵습니다. 슬롯 재장착과 펌웨어 업데이트를 먼저 확인한 뒤에도 반복되면 다른 슬롯이나 드라이브로 교차 테스트해보는 것이 안전합니다."},{"q":"오래된 SSD라서 그런 걸까요?","a":"사용 기간보다는 남은 수명(TBW)과 펌웨어 버전이 더 중요한 지표이므로 진단 도구로 확인하는 것이 좋습니다."}],"decisionSteps":[{"condition":"펌웨어 업데이트로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"드라이버 업데이트로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"파워서플라이 점검으로도 해결되지 않을 때","action":"사례처럼 교체를 검토하세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["133","00000133","0x133","dpc watchdog violation","dpc_watchdog_violation","dcp watchdog violation","dcp_watchdog_violation"],"communityCases":[{"title":"NVMe SSD 드라이버 업데이트로 DPC 오류 해결","summary":"NVMe SSD를 새로 장착한 이후 DPC_WATCHDOG_VIOLATION 블루스크린이 간헐적으로 발생했던 사례가 있습니다. 마이크로소프트 기본 드라이버 대신 제조사 최신 드라이버를 설치하자 이후 재발하지 않았습니다.","insight":"NVMe SSD를 사용 중이라면 윈도우 기본 드라이버보다 제조사 전용 드라이버가 더 안정적일 수 있습니다. 드라이버 업데이트만으로 DPC 응답 지연이 해결되는 경우가 많습니다."},{"title":"파워서플라이 교체로 DPC_WATCHDOG_VIOLATION 해결","summary":"저장장치 펌웨어·드라이버를 모두 최신으로 갱신해도 반복되던 DPC_WATCHDOG_VIOLATION이 파워서플라이를 교체한 뒤로는 재발하지 않았던 사례가 있습니다.","insight":"드라이버·펌웨어 점검으로 해결되지 않는다면, 전원 공급이 불안정해 저장장치나 컨트롤러가 순간적으로 응답하지 못했을 가능성이 있습니다. 다른 원인을 배제했다면 파워서플라이 상태도 점검해 보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x133 DPC_WATCHDOG_VIOLATION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x133-dpc-watchdog-violation"}},{"code":"0x0000003B","title":"SYSTEM_SERVICE_EXCEPTION","overview":"시스템 서비스를 처리하는 도중 예상치 못한 예외가 발생했을 때 나타나는 코드로, 드라이버 결함이나 시스템 파일 손상이 흔한 원인입니다.","summary":"시스템 서비스를 처리하는 도중 예상치 못한 예외가 발생했을 때 나타나는 코드로, 드라이버 결함이나 시스템 파일 손상이 흔한 원인입니다.","causes":["그래픽이나 오디오 등 특정 드라이버의 버그","시스템 파일 일부가 손상된 경우","최근 윈도우 업데이트와 기존 드라이버 간의 호환성 문제","램 불안정으로 인한 잘못된 메모리 접근","보안 소프트웨어와 시스템 서비스 간의 충돌"],"checks":["이벤트 뷰어에서 블루스크린 발생 직전 어떤 드라이버나 서비스가 관여했는지 확인하세요.","sfc /scannow로 시스템 파일 손상 여부를 점검하고 복구하세요.","최근 업데이트된 드라이버를 이전 버전으로 되돌려 재현 여부를 확인하세요.","메모리 진단 도구로 램 상태를 점검하세요.","보안 프로그램을 임시로 비활성화한 뒤 증상이 사라지는지 확인하세요."],"link":"error-code-0x0000003b.html","detailPage":"error-code-0x0000003b.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000003B)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"최근에 설치한 프로그램이 원인일 수도 있나요?","a":"네, 최근 설치한 드라이버나 소프트웨어가 원인인 경우가 많아 시스템 복원 지점으로 되돌리는 것도 방법입니다."}],"decisionSteps":[{"condition":"sfc /scannow로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"드라이버 롤백으로 해결될 때","action":"해당 드라이버의 수정된 버전이 나올 때까지 사용을 자제하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["3b","0000003b","0x3b"],"communityCases":[{"title":"백신 프로그램 재설치로 SYSTEM_SERVICE_EXCEPTION 해결","summary":"특정 백신 소프트웨어를 업데이트한 직후부터 이 블루스크린이 발생했던 사례가 있습니다. 해당 백신을 완전히 제거하고 재설치하자 문제가 사라졌습니다. 불완전한 업데이트로 드라이버 파일이 손상된 것이 원인이었습니다.","insight":"보안 소프트웨어는 커널 수준에서 동작하므로 업데이트 중 파일이 손상되면 이 오류가 발생할 수 있습니다. 최근 보안 프로그램 업데이트 후 발생했다면 제거 후 재설치를 먼저 시도하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x3B SYSTEM_SERVICE_EXCEPTION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x3b--system-service-exception"}},{"code":"0x000000EA","title":"THREAD_STUCK_IN_DEVICE_DRIVER","overview":"그래픽 드라이버나 특정 디바이스 드라이버가 응답 없이 무한 대기 상태에 빠졌을 때 나타나는 코드로, 고사양 그래픽 작업 중 자주 나타납니다.","summary":"그래픽 드라이버나 특정 디바이스 드라이버가 응답 없이 무한 대기 상태에 빠졌을 때 나타나는 코드로, 고사양 그래픽 작업 중 자주 나타납니다.","causes":["그래픽 드라이버가 고부하 상황에서 응답을 멈추는 경우","GPU 과열로 하드웨어 자체가 응답 지연을 일으키는 경우","오래되었거나 손상된 그래픽 드라이버 파일","그래픽카드 전원 공급 불안정","다중 모니터 구성에서 드라이버가 동기화에 실패하는 경우"],"checks":["그래픽 드라이버를 클린 재설치(DDU 도구로 완전 제거 후 재설치)하세요. <a href=\"graphics-driver-guide.html\">무료 도구로 재설치하는 방법 보기 →</a>","GPU 온도를 모니터링해 부하 시 과열 여부를 확인하세요.","그래픽카드 보조 전원 연결과 파워 용량이 충분한지 점검하세요.","다중 모니터를 사용 중이라면 하나만 연결한 상태에서 재현 여부를 확인하세요.","다른 그래픽 집약적 작업(게임, 영상 편집)에서도 동일하게 발생하는지 확인하세요."],"link":"error-code-0x000000ea.html","detailPage":"error-code-0x000000ea.html","faq":[{"q":"게임할 때만 재부팅되면 그래픽카드 문제인가요?","a":"이 문제(0x000000EA)는 그래픽 드라이버 문제일 가능성이 높지만 전원 공급이나 온도 문제와 겹치는 경우도 많아, 드라이버 재설치와 함께 온도·전력 상태도 함께 확인하는 것이 좋습니다."},{"q":"콘센트나 멀티탭도 원인이 될 수 있나요?","a":"드물지만 불안정한 멀티탭이나 정전압 문제가 원인이 될 수 있어, 다른 콘센트로 테스트해보는 것도 방법입니다."}],"decisionSteps":[{"condition":"드라이버 클린 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"온도가 높게 측정될 때","action":"쿨링 시스템(써멀 재도포, 팬 청소) 점검을 우선하세요."},{"condition":"모니터 하나만 연결했을 때 해결될 때","action":"다중 모니터 관련 드라이버 설정을 점검하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["ea","000000ea","0xea"],"officialSource":{"title":"Microsoft Learn: Bug Check 0xEA THREAD_STUCK_IN_DEVICE_DRIVER","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xea--thread-stuck-in-device-driver"},"communityCases":[{"title":"그래픽카드 교체로 해결한 사례","summary":"DDU로 드라이버를 클린 재설치하고, 보조 전원과 파워 용량까지 확인했는데도 고사양 게임에서만 이 코드가 반복됐던 사례가 있습니다. GPU 온도는 정상 범위였지만 다른 PC에 그래픽카드를 옮겨 테스트하니 똑같은 증상이 재현되어 그래픽카드 자체의 결함으로 확인됐고, 교체 후 완전히 해결됐습니다.","insight":"드라이버 재설치와 전원·온도 점검을 모두 마쳤는데도 특정 그래픽 작업에서만 반복된다면, 그래픽카드를 다른 시스템에서 테스트해 하드웨어 자체의 문제인지 먼저 확인해보세요."}]},{"code":"0x0000007E","title":"SYSTEM_THREAD_EXCEPTION_NOT_HANDLED","overview":"시스템 스레드에서 처리되지 않은 예외가 발생했을 때 나타나며, 주로 그래픽이나 칩셋 드라이버의 결함, 혹은 업데이트 직후 호환성 문제로 발생합니다.","summary":"시스템 스레드에서 처리되지 않은 예외가 발생했을 때 나타나며, 주로 그래픽이나 칩셋 드라이버의 결함, 혹은 업데이트 직후 호환성 문제로 발생합니다.","causes":["그래픽이나 칩셋 드라이버가 최신 업데이트와 호환되지 않는 경우","시스템 파일이 손상된 경우","타사 프로그램이 시스템 스레드와 충돌하는 경우","램이나 저장장치의 물리적 불안정","오버클럭 설정으로 인한 시스템 불안정"],"checks":["업데이트 직후부터 증상이 시작됐는지 확인하고, 그렇다면 관련 드라이버를 재설치하세요. <a href=\"graphics-driver-guide.html\">그래픽 드라이버 재설치 방법 보기 →</a>","안전 모드에서 재현 여부를 확인해 드라이버 문제인지 구분하세요.","sfc /scannow로 시스템 파일을 점검하세요.","최근 설치한 타사 프로그램을 제거한 뒤 재현 여부를 확인하세요.","오버클럭 설정이 있다면 기본값으로 되돌리세요."],"link":"error-code-0x0000007e.html","detailPage":"error-code-0x0000007e.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000007E)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"블루스크린 이후 데이터가 손상되나요?","a":"대부분은 강제 재시작만 발생할 뿐 저장된 파일이 곧바로 손상되지는 않지만, 저장하지 않은 작업 내용은 사라질 수 있습니다."}],"decisionSteps":[{"condition":"관련 드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"안전 모드에서는 재현되지 않을 때","action":"최근 설치한 프로그램 제거로 넘어가세요."},{"condition":"sfc /scannow로도 해결되지 않을 때","action":"사례처럼 문제 드라이버 파일을 직접 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["7e","0000007e","0x7e","system thread exception not handled","thread exception not handled","thread_exception_not_handled"],"communityCases":[{"title":"문제 드라이버 파일 직접 삭제로 해결한 사례","summary":"AMD OverDrive 관련 드라이버(AODDRIVER2.sys)가 원인으로 지목됐지만, 설치 프로그램이 손상되어 제어판에서 일반적인 방법으로는 제거할 수 없었던 사례가 있습니다. 시스템 폴더에서 해당 드라이버 파일을 직접 찾아 삭제한 뒤 정상적으로 부팅됐습니다.","insight":"원인 드라이버를 찾았는데도 제어판에서 제거가 안 된다면, 설치 프로그램 자체가 손상됐을 수 있습니다. 이 경우 드라이버 파일을 직접 삭제해야 할 수도 있지만, 시스템 파일을 직접 다루는 작업이라 신중하게 진행해야 합니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x7E SYSTEM_THREAD_EXCEPTION_NOT_HANDLED","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x7e--system-thread-exception-not-handled"}},{"code":"0x0000000A","title":"IRQL_NOT_LESS_OR_EQUAL","overview":"드라이버나 커널 모드 코드가 자신에게 허용되지 않은 메모리 주소에 접근했을 때 나타나는 대표적인 블루스크린 코드입니다.","summary":"드라이버나 커널 모드 코드가 자신에게 허용되지 않은 메모리 주소에 접근했을 때 나타나는 대표적인 블루스크린 코드입니다.","causes":["최근 설치하거나 업데이트한 드라이버의 결함","램 모듈의 물리적 불안정","보안 프로그램과 커널 모드 드라이버 간의 충돌","오버클럭으로 인한 시스템 불안정","손상된 시스템 파일"],"checks":["최근 설치한 드라이버 목록을 확인하고, 문제 시점과 일치하는 항목을 제거하거나 롤백하세요.","메모리 진단 도구로 램 상태를 점검하세요.","보안 프로그램을 임시로 비활성화한 뒤 재현 여부를 확인하세요.","오버클럭 설정을 기본값으로 되돌리세요.","sfc /scannow로 시스템 파일 손상 여부를 점검하세요."],"link":"error-code-0x0000000a.html","detailPage":"error-code-0x0000000a.html","narrative":"IRQL은 코드가 얼마나 급한 일을 처리 중인지를 나타내는 우선순위 개념입니다. 어떤 드라이버가 지금은 건드리면 안 되는 높은 우선순위 상태에서 접근이 금지된 메모리 영역을 건드리면, Windows는 이를 정상적으로 처리하지 못하고 즉시 시스템을 멈춥니다. 이름은 복잡해 보이지만 실제로 따져야 할 건 단순합니다 — 어떤 드라이버가 이 실수를 저질렀는지입니다. 최근 설치하거나 업데이트한 드라이버가 있다면 그게 가장 먼저 의심해볼 대상입니다.","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000000A)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\\\Windows\\\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 롤백으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"해당 모듈을 교체하세요."},{"condition":"안티치트 충돌이 확인될 때","action":"사례처럼 중복 설치된 안티치트 중 하나를 제거하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["a","0a","0000000a","0x0a","0x0000000a"],"communityCases":[{"title":"안티치트 프로그램 충돌로 해결한 사례","summary":"특정 게임을 종료한 직후에만 이 블루스크린이 반복됐던 사례가 있습니다. 드라이버 업데이트, 메모리 검사, sfc 검사까지 해도 해결되지 않았는데, 알고 보니 서로 다른 두 게임에서 각각 설치한 안티치트 프로그램(라이엇 뱅가드, 이지 안티치트)이 백그라운드에서 함께 실행되며 충돌을 일으키고 있었습니다. 둘 중 하나를 완전히 제거한 뒤 재발하지 않았습니다.","insight":"특정 게임 실행·종료 시점에만 반복된다면 드라이버보다 안티치트 프로그램 간의 충돌을 의심해보세요. 여러 게임의 안티치트가 동시에 설치되어 있다면 특히 그렇습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xA IRQL_NOT_LESS_OR_EQUAL","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xa--irql-not-less-or-equal"},"plainExplanation":"'드라이버'는 그래픽카드·랜카드 같은 부품과 윈도우가 서로 대화할 수 있게 해주는 프로그램이고, '메모리(램)'는 컴퓨터가 작업 중 정보를 잠시 올려두는 부품입니다. 이 코드는 그 드라이버 중 하나가 허락되지 않은 방식으로 메모리에 접근하려다 윈도우가 안전을 위해 스스로 멈춘 것입니다. 대부분 특정 드라이버나 램 자체의 문제이며, 아래 순서대로 하나씩 확인하면 됩니다."},{"code":"0x00000024","title":"NTFS_FILE_SYSTEM","overview":"NTFS 파일 시스템 드라이버가 디스크에서 오류를 발견했을 때 나타나는 코드로, 갑작스러운 전원 종료 후 자주 발생합니다.","summary":"NTFS 파일 시스템 드라이버가 디스크에서 오류를 발견했을 때 나타나는 코드로, 갑작스러운 전원 종료 후 자주 발생합니다.","causes":["디스크 파일 시스템 구조 자체가 손상된 경우","갑작스러운 정전이나 강제 종료로 파일 시스템이 비정상 종료된 경우","디스크 배드섹터나 물리적 결함","디스크 컨트롤러 드라이버 문제","외장 디스크를 안전하게 제거하지 않고 분리한 경우"],"checks":["중요한 파일을 먼저 백업하세요. 파일 시스템 손상은 데이터 유실 위험이 있습니다.","명령 프롬프트에서 chkdsk /f /r 을 실행해 디스크 오류를 검사하고 복구하세요.","디스크 진단 도구로 배드섹터나 S.M.A.R.T 상태를 확인하세요.","외장 디스크라면 항상 '안전하게 제거' 기능을 사용해 분리하세요.","디스크 컨트롤러 드라이버를 최신 버전으로 업데이트하세요."],"link":"error-code-0x00000024.html","detailPage":"error-code-0x00000024.html","faq":[{"q":"SSD·NVMe를 바로 교체해야 하나요?","a":"이 문제(0x00000024)만으로 저장장치 고장을 단정하기는 어렵습니다. 슬롯 재장착과 펌웨어 업데이트를 먼저 확인한 뒤에도 반복되면 다른 슬롯이나 드라이브로 교차 테스트해보는 것이 안전합니다."},{"q":"BIOS 설정도 영향을 주나요?","a":"네, SATA 모드(AHCI/RAID)나 고속 부팅 설정이 인식 지연에 영향을 줄 수 있어 BIOS 설정을 함께 확인해야 합니다."}],"decisionSteps":[{"condition":"chkdsk /f /r로 정상 복구되고 재현되지 않을 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"진단 도구에서 배드섹터가 발견될 때","action":"데이터 백업을 최우선으로 하고 디스크 교체를 검토하세요."},{"condition":"chkdsk로도 해결되지 않을 때","action":"디스크 컨트롤러 드라이버를 업데이트하거나 다른 SATA·M.2 슬롯으로 옮겨 재현 여부를 확인하세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["24","00000024","0x24"],"communityCases":[{"title":"CHKDSK 복구 후 디스크 교체로 해결한 사례","summary":"갑작스러운 전원 차단 이후 부팅 시마다 NTFS_FILE_SYSTEM 블루스크린이 발생했던 사례가 있습니다. chkdsk /r 실행으로 일시적으로 해결됐지만 얼마 뒤 재발했고, SMART 검사에서 불량 섹터가 다수 확인되어 결국 디스크를 교체한 뒤 완전히 해결됐습니다.","insight":"이 오류가 반복된다면 임시 복구에 그치지 말고 디스크 상태를 반드시 확인하세요. 불량 섹터가 늘어나고 있다면 데이터 백업과 디스크 교체를 함께 진행하는 것이 안전합니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x24 NTFS_FILE_SYSTEM","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x24--ntfs-file-system"}},{"code":"0x000000F4","title":"CRITICAL_OBJECT_TERMINATION","overview":"핵심 시스템 프로세스나 스레드 객체가 예기치 않게 종료되었을 때 나타나는 코드로, 저장장치 문제와 함께 발생하는 경우가 많습니다.","summary":"핵심 시스템 프로세스나 스레드 객체가 예기치 않게 종료되었을 때 나타나는 코드로, 저장장치 문제와 함께 발생하는 경우가 많습니다.","causes":["부팅 디스크의 연결 불량이나 물리적 결함","부팅 관련 시스템 파일의 손상","저장장치 드라이버 문제","전원 공급 불안정으로 인한 저장장치 접근 실패","최근 시스템 설정 변경으로 인한 충돌"],"checks":["저장장치 연결 상태를 물리적으로 확인하세요.","복구 환경으로 진입해 시스템 파일 복구를 시도하세요.","저장장치 진단 도구로 디스크 상태를 점검하세요.","최근 변경한 시스템 설정이 있다면 되돌려 보세요.","파워 서플라이 용량과 케이블 연결 상태를 점검하세요."],"link":"error-code-0x000000f4.html","detailPage":"error-code-0x000000f4.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x000000F4)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"외장 하드를 연결한 상태에서도 복구를 시도해도 되나요?","a":"외장 장치가 부팅 순서에 영향을 줄 수 있으므로, 복구 시도 전에는 분리하는 것이 좋습니다."}],"decisionSteps":[{"condition":"저장장치 진단에서 이상이 없고 시동 복구로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"진단 도구에서 배드섹터나 경고가 뜰 때","action":"복구 명령보다 데이터 백업을 최우선으로 하고 디스크 교체를 검토하세요."},{"condition":"시동 복구·sfc로도 해결되지 않을 때","action":"최근 설치한 저장장치 컨트롤러 드라이버를 이전 버전으로 롤백해보세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["f4","000000f4","0xf4"],"communityCases":[{"title":"SATA 케이블 교체로 CRITICAL_OBJECT_TERMINATION 해결","summary":"게임 중 불규칙하게 CRITICAL_OBJECT_TERMINATION 블루스크린이 발생했던 사례가 있습니다. 처음엔 소프트웨어 문제로 생각했지만, 메인보드의 SATA 케이블을 교체하자 이후 완전히 재발하지 않았습니다.","insight":"이 오류는 저장장치와의 연결이 끊기거나 불안정할 때 자주 발생합니다. 고사양 작업 중에만 나타난다면 SATA 케이블 품질이나 연결 상태를 점검해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xF4 CRITICAL_OBJECT_TERMINATION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xf4--critical-object-termination"}},{"code":"0x00000019","title":"BAD_POOL_HEADER","overview":"메모리 풀의 구조 정보가 손상되었을 때 나타나는 블루스크린 코드로, 드라이버 오류나 램 문제가 주요 원인입니다.","summary":"메모리 풀의 구조 정보가 손상되었을 때 나타나는 블루스크린 코드로, 드라이버 오류나 램 문제가 주요 원인입니다.","causes":["드라이버가 메모리 풀을 잘못 다루는 경우","램 모듈의 물리적 결함","보안 프로그램과의 충돌","시스템 파일 손상","오버클럭으로 인한 메모리 불안정"],"checks":["최근 설치한 드라이버를 확인하고 제거 또는 롤백해 보세요.","메모리 진단 도구로 램 상태를 점검하세요.","시스템 복원 지점이 있다면 이전 상태로 되돌려 보세요.","보안 프로그램을 임시로 비활성화한 뒤 재현 여부를 확인하세요.","오버클럭 설정을 기본값으로 되돌리세요."],"link":"error-code-0x00000019.html","detailPage":"error-code-0x00000019.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000019)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"최근에 설치한 프로그램이 원인일 수도 있나요?","a":"네, 최근 설치한 드라이버나 소프트웨어가 원인인 경우가 많아 시스템 복원 지점으로 되돌리는 것도 방법입니다."}],"decisionSteps":[{"condition":"최근 드라이버를 롤백한 뒤 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."},{"condition":"오버클럭 해제 후에도 반복될 때","action":"보안 프로그램 재설치나 <code>sfc /scannow</code>로 시스템 파일 손상 여부를 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["19","00000019","0x19"],"communityCases":[{"title":"게임 오버레이 프로그램 재설치로 BAD_POOL_HEADER 해결","summary":"Discord 오버레이가 활성화된 상태에서 게임을 실행할 때 이 블루스크린이 반복됐던 사례가 있습니다. Discord를 완전히 제거하고 재설치하자 문제가 해결됐는데, 오버레이 드라이버 충돌이 원인이었습니다.","insight":"이 오류는 커널 메모리 풀 손상이 원인이며, 오버레이나 훅을 사용하는 프로그램(게임 런처, 녹화 소프트웨어 등)의 드라이버 충돌로 발생하는 경우가 많습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x19 BAD_POOL_HEADER","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x19--bad-pool-header"}},{"code":"0x000000A5","title":"ACPI_BIOS_ERROR","overview":"메인보드의 ACPI/BIOS가 윈도우가 기대하는 표준을 완전히 지원하지 않을 때 나타나는 코드로, 오래되었거나 호환성이 낮은 메인보드에서 자주 발생합니다.","summary":"메인보드의 ACPI/BIOS가 윈도우가 기대하는 표준을 완전히 지원하지 않을 때 나타나는 코드로, 오래되었거나 호환성이 낮은 메인보드에서 자주 발생합니다.","causes":["BIOS/UEFI 펌웨어가 오래되어 ACPI 표준을 완전히 지원하지 못하는 경우","BIOS 설정 중 전원 관리 관련 항목이 잘못 구성된 경우","최근 하드웨어(그래픽카드, 램 등)를 교체한 뒤 호환성 문제가 생긴 경우","바이오스 기본값에서 임의로 변경한 고급 설정이 충돌하는 경우","메인보드 제조사의 알려진 펌웨어 버그"],"checks":["메인보드 제조사 홈페이지에서 BIOS/UEFI 최신 펌웨어를 확인하고 업데이트하세요. <a href=\"bios-boot-guide.html\">업데이트 전 확인할 사항 보기 →</a>","BIOS를 기본값(Load Default/Optimized Defaults)으로 초기화한 뒤 재부팅해 보세요.","최근 교체한 하드웨어가 있다면 제거하고 이전 상태로 재현 여부를 확인하세요.","전원 관리 관련 BIOS 설정(예: ErP, C-State)을 기본값으로 되돌려 보세요.","메인보드 제조사 공식 포럼이나 지원 페이지에서 같은 증상의 사례가 있는지 확인하세요."],"link":"error-code-0x000000a5.html","detailPage":"error-code-0x000000a5.html","faq":[{"q":"화면이 안 나오면 모니터부터 의심해야 하나요?","a":"이 문제(0x000000A5)가 표시된다면 모니터보다 메인보드·그래픽카드의 초기화 단계를 먼저 봐야 합니다. 다른 모니터나 케이블로 교차 확인하는 것도 원인을 좁히는 데 도움이 됩니다."}],"decisionSteps":[{"condition":"BIOS 업데이트 후 재현되지 않을 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"최근 교체한 하드웨어를 제거하니 정상일 때","action":"해당 하드웨어와 메인보드의 ACPI 호환성 문제이므로 제조사 호환 목록을 확인하세요."},{"condition":"BIOS 기본값 초기화·전원 설정 변경 후에도 반복될 때","action":"메인보드 자체의 알려진 펌웨어 버그일 수 있으므로 제조사 공식 포럼이나 베타 바이오스를 확인하세요."}],"relatedSymptom":"hardware-no-display.html","aliases":["a5","000000a5","0xa5"],"communityCases":[{"title":"BIOS 업데이트로 ACPI_BIOS_ERROR 해결","summary":"새 노트북을 구매한 직후 간헐적으로 이 블루스크린이 발생했던 사례가 있습니다. 제조사 홈페이지에서 최신 BIOS 펌웨어를 확인하고 업데이트하자 이후 재발하지 않았습니다.","insight":"이 오류는 BIOS의 ACPI 구현이 윈도우 표준을 충족하지 못할 때 발생합니다. 하드웨어 고장보다 BIOS 업데이트로 해결되는 경우가 많으므로 제조사 지원 페이지를 먼저 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xA5 ACPI_BIOS_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xa5--acpi-bios-error"}},{"code":"0x00000074","title":"BAD_SYSTEM_CONFIG_INFO","overview":"부팅 구성 정보나 레지스트리 정보가 손상되었을 때 나타나는 코드로, 업데이트 실패 후 자주 나타납니다.","summary":"부팅 구성 정보나 레지스트리 정보가 손상되었을 때 나타나는 코드로, 업데이트 실패 후 자주 나타납니다.","causes":["부팅 구성 데이터(BCD)의 손상","레지스트리 하이브 파일의 손상","업데이트 도중 강제 종료로 구성 정보가 일부만 반영된 경우","디스크 오류로 구성 파일을 읽지 못하는 경우","최근 시스템 설정 변경으로 인한 충돌"],"checks":["복구 환경으로 진입해 bootrec 명령으로 부팅 구성 정보를 재생성하세요.","시스템 복원 지점이 있다면 이전 상태로 되돌려 보세요.","디스크 검사(chkdsk)로 저장장치 오류 여부를 점검하세요.","최근 실패한 업데이트가 있다면 업데이트 캐시를 정리한 뒤 재시도하세요.","복구로도 해결되지 않으면 시스템 복구 도구나 재설치를 고려하세요."],"link":"error-code-0x00000074.html","detailPage":"error-code-0x00000074.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x00000074)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"자동 복구가 계속 실패하면 윈도우를 재설치해야 하나요?","a":"명령 프롬프트에서 부팅 복구 명령을 먼저 시도해보고, 그래도 안 되면 초기화나 재설치를 고려하는 것이 순서입니다."}],"decisionSteps":[{"condition":"bootrec으로 부팅 구성 정보가 재생성되고 정상 부팅될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"시스템 복원으로 해결될 때","action":"복원 직전 설치했던 프로그램이나 업데이트가 원인이었을 가능성이 크므로 재설치 시 주의하세요."},{"condition":"chkdsk에서 디스크 오류가 발견될 때","action":"복구 명령보다 데이터 백업과 디스크 상태 점검을 우선하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["74","00000074","0x74"],"communityCases":[{"title":"bootrec 명령어로 BAD_SYSTEM_CONFIG_INFO 복구","summary":"윈도우 업데이트 도중 전원이 꺼진 이후 부팅 시마다 이 블루스크린이 발생했던 사례가 있습니다. 복구 환경에서 bootrec /fixmbr, bootrec /fixboot, bootrec /rebuildbcd를 순서대로 실행하자 정상 부팅이 가능해졌습니다.","insight":"이 오류는 BCD(부팅 구성 데이터) 또는 시스템 레지스트리 손상이 원인인 경우가 많습니다. 복구 환경에서 bootrec 명령어로 먼저 시도해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x74 BAD_SYSTEM_CONFIG_INFO","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x74--bad-system-config-info"}},{"code":"0xC0000225","title":"부팅 장치를 찾을 수 없음","overview":"윈도우가 부팅에 필요한 장치 자체를 찾지 못했을 때 나타나는 오류로, BCD 손상이나 디스크 연결 문제, 부팅 순서 변경이 주요 원인입니다.","summary":"윈도우가 부팅에 필요한 장치 자체를 찾지 못했을 때 나타나는 오류로, BCD 손상이나 디스크 연결 문제, 부팅 순서 변경이 주요 원인입니다.","causes":["부팅 구성 데이터(BCD)가 손상되거나 삭제된 경우","저장장치 케이블 연결이 불량한 경우","BIOS에서 부팅 순서가 다른 장치로 바뀐 경우","디스크 파티션이 손상되었거나 삭제된 경우","새 디스크를 추가한 뒤 BIOS가 잘못된 장치를 부팅 대상으로 지정한 경우"],"checks":["BIOS로 진입해 부팅 순서에서 올바른 디스크가 1순위로 지정되어 있는지 확인하세요. <a href=\"bios-boot-guide.html\">BIOS·부팅 순서 확인 방법 보기 →</a>","저장장치 케이블 연결 상태를 물리적으로 점검하세요.","설치 미디어로 부팅해 복구 환경에서 bootrec /rebuildbcd를 실행하세요.","디스크 관리 도구로 부팅 파티션이 정상적으로 보이는지 확인하세요.","최근 디스크를 추가했다면 제거한 뒤 재현 여부를 확인하세요."],"link":"error-code-0xc0000225.html","detailPage":"error-code-0xc0000225.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0xC0000225)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"복구 화면에서 명령 프롬프트는 어떻게 여나요?","a":"고급 옵션 → 문제 해결 → 고급 옵션 → 명령 프롬프트 순서로 진입할 수 있습니다."}],"decisionSteps":[{"condition":"BIOS 부팅 순서 수정으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"bootrec /rebuildbcd로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"디스크 관리에서 파티션 자체가 안 보일 때","action":"디스크 자체의 물리적 손상 가능성이 크므로 다른 PC나 외장 케이스로 인식 여부를 확인하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["c0000225","0xc0000225"],"communityCases":[{"title":"SATA 우선순위 조정으로 부팅 장치 인식 해결","summary":"하드디스크와 SSD를 함께 쓰던 중 BIOS 업데이트 이후 갑자기 부팅이 안 됐던 사례가 있습니다. BIOS에서 부팅 순서를 확인하니 SSD 우선순위가 밀려 있었고, 순서를 재조정하자 정상 부팅됐습니다.","insight":"이 오류는 실제 저장장치 고장보다 BIOS 설정 변경이나 케이블 접촉 불량으로 인한 인식 실패인 경우도 많습니다. 먼저 BIOS 부팅 우선순위와 케이블 연결을 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Windows startup issues troubleshooting","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/windows-boot-issues-troubleshooting"}},{"code":"0x80070570","title":"파일이 손상되었거나 읽을 수 없음","overview":"설치나 복사 과정에서 파일이 손상되었거나 읽어올 수 없을 때 나타나는 오류로, 설치 미디어 문제나 디스크 불량이 흔한 원인입니다.","summary":"설치나 복사 과정에서 파일이 손상되었거나 읽어올 수 없을 때 나타나는 오류로, 설치 미디어 문제나 디스크 불량이 흔한 원인입니다.","causes":["설치 파일 자체가 다운로드 중 손상된 경우","USB 설치 미디어의 불량이나 손상","대상 디스크의 배드섹터","압축 해제 도중 오류가 발생한 경우","램 불안정으로 파일 복사 중 데이터가 손상되는 경우"],"checks":["설치 파일이나 이미지를 공식 출처에서 다시 받아보세요.","USB 설치 미디어를 다른 USB 포트나 다른 USB 메모리로 새로 만들어 보세요.","대상 디스크의 상태를 chkdsk나 진단 도구로 점검하세요.","다른 저장장치(외장하드 등)에 파일을 저장한 뒤 다시 시도해 보세요.","메모리 진단 도구로 램 상태를 점검하세요."],"link":"error-code-0x80070570.html","detailPage":"error-code-0x80070570.html","faq":[{"q":"SSD·NVMe를 바로 교체해야 하나요?","a":"이 문제(0x80070570)만으로 저장장치 고장을 단정하기는 어렵습니다. 슬롯 재장착과 펌웨어 업데이트를 먼저 확인한 뒤에도 반복되면 다른 슬롯이나 드라이브로 교차 테스트해보는 것이 안전합니다."},{"q":"SSD 상태를 확인하는 무료 도구가 있나요?","a":"CrystalDiskInfo 같은 무료 프로그램으로 SSD의 건강 상태와 온도를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"새로 받은 설치 파일이나 USB로 해결될 때","action":"원본 파일이나 USB 자체의 손상이었으므로, 다음부터는 다운로드 후 체크섬을 비교해 무결성을 확인하세요."},{"condition":"chkdsk에서 배드섹터가 발견될 때","action":"대상 디스크 교체를 검토하고, 우선 다른 정상 디스크에 설치해보세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈 문제로 파일 복사 중 데이터가 손상되고 있을 수 있으므로 모듈 교체를 검토하세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["80070570","0x80070570"],"communityCases":[{"title":"RAM 슬롯 변경으로 파일 손상 오류 해결","summary":"윈도우 설치 중 반복적으로 이 오류가 발생했던 사례가 있습니다. 설치 미디어를 여러 개 바꿔봐도 같은 오류가 났는데, RAM을 다른 슬롯으로 옮기자 설치가 정상적으로 완료됐습니다.","insight":"이 오류가 설치 중 반복된다면 소프트웨어보다 RAM 접촉 불량이나 슬롯 문제를 먼저 의심하세요. RAM을 다른 슬롯으로 이동하는 것만으로 해결되는 경우가 있습니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (1300-1699) — ERROR_FILE_CORRUPT","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1300-1699-"}},{"code":"0x000000C2","title":"BAD_POOL_CALLER","overview":"드라이버나 커널 모드 소프트웨어가 메모리 풀을 잘못된 방식으로 호출했을 때 나타나는 코드로, 특정 드라이버의 결함이 주요 원인입니다.","summary":"드라이버나 커널 모드 소프트웨어가 메모리 풀을 잘못된 방식으로 호출했을 때 나타나는 코드로, 특정 드라이버의 결함이 주요 원인입니다.","causes":["최근 설치한 드라이버의 버그","보안 소프트웨어와 커널 모드 코드 간의 충돌","램 불안정","시스템 파일 손상","타사 프로그램의 잘못된 메모리 관리"],"checks":["이벤트 뷰어에서 오류 발생 직전 관련된 드라이버 파일을 확인하세요.","최근 설치한 드라이버나 프로그램을 제거해 재현 여부를 확인하세요.","메모리 진단 도구로 램 상태를 점검하세요.","보안 프로그램을 임시로 비활성화한 뒤 테스트해 보세요.","sfc /scannow로 시스템 파일 손상 여부를 점검하세요."],"link":"error-code-0x000000c2.html","detailPage":"error-code-0x000000c2.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000C2)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"블루스크린 이후 데이터가 손상되나요?","a":"대부분은 강제 재시작만 발생할 뿐 저장된 파일이 곧바로 손상되지는 않지만, 저장하지 않은 작업 내용은 사라질 수 있습니다."}],"decisionSteps":[{"condition":"최근 드라이버를 제거한 뒤 재현되지 않을 때","action":"해당 드라이버의 수정된 최신 버전이 나올 때까지 사용을 자제하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."},{"condition":"sfc /scannow로도 해결되지 않을 때","action":"보안 프로그램을 다른 제품으로 교체하거나 임시로 제거해 재현 여부를 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["c2","000000c2","0xc2"],"communityCases":[{"title":"마우스 드라이버 제거로 BAD_POOL_CALLER 해결","summary":"새 게이밍 마우스를 연결한 직후부터 이 블루스크린이 발생했던 사례가 있습니다. 마우스 전용 소프트웨어와 드라이버를 완전히 제거하자 오류가 사라졌고, 마우스 제조사 측에서 이후 패치를 제공했습니다.","insight":"이 오류는 드라이버가 메모리 풀을 잘못 사용할 때 발생합니다. 주변기기(마우스, 키보드, 헤드셋) 전용 소프트웨어도 커널 드라이버를 사용하므로 최근 연결한 장치를 점검하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xC2 BAD_POOL_CALLER","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xc2--bad-pool-caller"}},{"code":"0x000000ED","title":"UNMOUNTABLE_BOOT_VOLUME","overview":"윈도우가 부팅 볼륨을 마운트(연결)하는 데 실패했을 때 나타나는 코드로, 디스크 파일 시스템 손상이나 저장장치 연결 불안정이 주요 원인입니다.","summary":"윈도우가 부팅 볼륨을 마운트(연결)하는 데 실패했을 때 나타나는 코드로, 디스크 파일 시스템 손상이나 저장장치 연결 불안정이 주요 원인입니다.","causes":["부팅 파티션의 파일 시스템 손상","저장장치 케이블이나 슬롯 접촉 불량","디스크 배드섹터","갑작스러운 전원 종료로 파일 시스템이 손상된 경우","저장장치 드라이버 문제"],"checks":["저장장치 연결 상태를 물리적으로 확인하세요.","복구 환경에서 chkdsk /r 명령으로 파일 시스템 오류를 검사하고 복구하세요.","디스크 진단 도구로 배드섹터나 S.M.A.R.T 상태를 확인하세요.","복구 환경에서 bootrec 명령으로 부팅 정보를 재구성해 보세요.","중요 데이터는 가능하다면 다른 매체로 미리 백업해 두세요."],"link":"error-code-0x000000ed.html","detailPage":"error-code-0x000000ed.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(0x000000ED)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"외장 하드를 연결한 상태에서도 복구를 시도해도 되나요?","a":"외장 장치가 부팅 순서에 영향을 줄 수 있으므로, 복구 시도 전에는 분리하는 것이 좋습니다."}],"decisionSteps":[{"condition":"chkdsk /r로 파일 시스템 오류가 복구되고 정상 부팅될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"진단 도구에서 배드섹터·SMART 경고가 뜰 때","action":"복구 명령보다 데이터 백업을 최우선으로 하고 디스크 교체를 검토하세요."},{"condition":"chkdsk·bootrec으로도 해결되지 않을 때","action":"저장장치 컨트롤러 드라이버를 업데이트하거나 다른 SATA·M.2 슬롯으로 옮겨 재현 여부를 확인하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["ed","000000ed","0xed"],"officialSource":{"title":"Microsoft Learn: Bug Check 0xED UNMOUNTABLE_BOOT_VOLUME","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xed--unmountable-boot-volume"},"communityCases":[{"title":"SSD 교체로 해결한 사례","summary":"케이블 재연결, chkdsk /r, bootrec로 부팅 정보 재구성까지 모두 시도했지만 며칠 뒤 같은 코드로 다시 부팅이 안 됐던 사례가 있습니다. S.M.A.R.T 진단에서 재할당된 섹터 수치가 계속 증가하고 있는 것이 확인돼 저장장치 자체의 물리적 노후화로 판단, 데이터를 백업한 뒤 SSD를 새 제품으로 교체하고 윈도우를 재설치해 해결했습니다.","insight":"복구 명령으로 매번 넘어가더라도 같은 코드가 재발한다면, S.M.A.R.T 진단으로 재할당 섹터나 배드섹터 수치가 늘고 있는지 확인하세요. 수치가 계속 증가한다면 복구보다 교체와 백업을 우선해야 합니다."}]},{"code":"0x000000F7","title":"DRIVER_OVERRAN_STACK_BUFFER","overview":"드라이버가 자신에게 할당된 스택 버퍼 크기를 초과해 데이터를 기록했을 때 나타나는 코드로, 드라이버 버그가 직접적인 원인입니다.","summary":"드라이버가 자신에게 할당된 스택 버퍼 크기를 초과해 데이터를 기록했을 때 나타나는 코드로, 드라이버 버그가 직접적인 원인입니다.","causes":["특정 드라이버의 버퍼 오버런 버그","오래된 드라이버와 최신 윈도우 빌드 간의 호환성 문제","보안 소프트웨어의 드라이버 후킹 충돌","손상된 드라이버 설치 파일","타사 유틸리티 프로그램의 저수준 드라이버 결함"],"checks":["최근 설치하거나 업데이트한 드라이버를 확인하고 제거 또는 롤백하세요.","안전 모드에서 재현 여부를 확인해 드라이버 문제인지 좁혀보세요.","제조사 홈페이지에서 해당 드라이버의 최신 버전을 다시 설치해 보세요.","보안 프로그램을 임시로 비활성화한 뒤 테스트해 보세요.","최근 설치한 저수준 유틸리티(오버클럭 툴, 모니터링 툴 등)를 제거해 보세요."],"link":"error-code-0x000000f7.html","detailPage":"error-code-0x000000f7.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000F7)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\\\Windows\\\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"최근 드라이버를 롤백한 뒤 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"저수준 유틸리티 제거로 해결될 때","action":"그 프로그램의 수정된 버전이 나올 때까지 사용을 자제하세요."},{"condition":"안전 모드에서도 재현될 때","action":"보안 프로그램이나 시스템 파일 손상 가능성이 있으므로 sfc /scannow를 실행하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["f7","000000f7","0xf7"],"communityCases":[{"title":"보안 프로그램 제거로 스택 오버런 오류 해결","summary":"특정 보안 프로그램을 설치한 뒤부터 이 블루스크린이 간헐적으로 발생했던 사례가 있습니다. 해당 보안 프로그램의 커널 드라이버가 스택 버퍼를 초과해 접근하는 버그가 있었고, 제거 후 문제가 사라졌습니다.","insight":"이 오류는 드라이버가 할당된 스택 버퍼 범위를 넘어 쓸 때 발생합니다. 커널 수준에서 동작하는 보안 프로그램이나 드라이버가 원인인 경우가 많으므로 최근 설치한 보안 소프트웨어를 우선 점검하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xF7 DRIVER_OVERRAN_STACK_BUFFER","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xf7--driver-overran-stack-buffer"}},{"code":"0x000000D8","title":"DRIVER_USED_EXCESSIVE_PTES","overview":"유효하지 않은 참조 포인터를 사용해 객체 참조 카운트가 잘못되었을 때 나타나는 코드로, 드라이버 결함이나 커널 모드 충돌이 주요 원인입니다.","summary":"유효하지 않은 참조 포인터를 사용해 객체 참조 카운트가 잘못되었을 때 나타나는 코드로, 드라이버 결함이나 커널 모드 충돌이 주요 원인입니다.","causes":["드라이버가 이미 해제된 객체를 참조하려 하는 경우","커널 모드 소프트웨어 간의 충돌","메모리 손상으로 포인터 값이 변질된 경우","오래된 드라이버와 최신 시스템 간의 호환성 문제","보안 소프트웨어의 저수준 후킹 충돌"],"checks":["최근 설치한 드라이버나 커널 모드 프로그램을 확인하고 제거해 보세요.","메모리 진단 도구로 램 상태를 점검하세요.","안전 모드에서 재현 여부를 확인하세요.","보안 프로그램을 임시로 비활성화한 뒤 테스트해 보세요.","sfc /scannow로 시스템 파일 손상 여부를 점검하세요."],"link":"error-code-0x000000d8.html","detailPage":"error-code-0x000000d8.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000D8)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"최근에 설치한 프로그램이 원인일 수도 있나요?","a":"네, 최근 설치한 드라이버나 소프트웨어가 원인인 경우가 많아 시스템 복원 지점으로 되돌리는 것도 방법입니다."}],"decisionSteps":[{"condition":"최근 설치한 드라이버를 제거한 뒤 재현되지 않을 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."},{"condition":"sfc /scannow로도 해결되지 않을 때","action":"보안 프로그램을 다른 제품으로 교체하거나 임시로 제거해 재현 여부를 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["d8","000000d8","0xd8"],"communityCases":[{"title":"가상 메모리 크기 조정으로 PTE 고갈 오류 해결","summary":"화면 캡처 소프트웨어와 고사양 게임을 동시에 실행할 때 이 블루스크린이 발생했던 사례가 있습니다. 가상 메모리(페이지 파일) 크기를 수동으로 늘리자 이후 재현되지 않았습니다.","insight":"이 오류는 시스템 PTE(페이지 테이블 항목)가 고갈될 때 발생합니다. 드라이버 문제 외에도 여러 프로그램이 대용량 가상 주소 공간을 동시에 사용하는 상황에서도 나타날 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xD8 DRIVER_USED_EXCESSIVE_PTES","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xd8--driver-used-excessive-ptes"}},{"code":"0x0000009C","title":"MACHINE_CHECK_EXCEPTION","overview":"CPU나 메모리 등 하드웨어가 스스로 심각한 내부 오류를 감지해 시스템에 보고했을 때 나타나는 코드로, 오버클럭이나 전원 불안정이 흔한 원인입니다.","summary":"CPU나 메모리 등 하드웨어가 스스로 심각한 내부 오류를 감지해 시스템에 보고했을 때 나타나는 코드로, 오버클럭이나 전원 불안정이 흔한 원인입니다.","causes":["CPU나 램의 오버클럭 설정이 안정성 한계를 넘은 경우","전원 공급이 불안정하거나 파워 용량이 부족한 경우","CPU나 메인보드의 물리적 결함","발열로 인한 하드웨어 스로틀링 오류","램 접촉 불량"],"checks":["오버클럭 설정을 모두 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","CPU와 시스템 전반의 온도를 모니터링 프로그램으로 확인하세요.","파워 서플라이 용량이 시스템 사양에 충분한지 확인하세요.","메모리 진단 도구로 램 상태를 점검하세요.","램을 재장착하거나 슬롯을 바꿔 접촉 상태를 점검하세요."],"link":"error-code-0x0000009c.html","detailPage":"error-code-0x0000009c.html","narrative":"이 코드가 특별한 이유는 소프트웨어가 아니라 CPU 자신이 문제를 보고한다는 점입니다. 프로세서에는 내부적으로 자기 상태를 감시하는 회로가 있는데, 여기서 정정 불가능한 오류를 감지하면 Windows에 그대로 통보하고 시스템을 멈춥니다. 드라이버 재설치나 업데이트로 고쳐지는 종류의 문제가 아니라는 뜻이기도 합니다. 오버클럭·전압 설정을 만졌다면 그것부터 기본값으로 돌려보는 게 순서고, 손댄 적이 없는데도 반복된다면 전원 공급이나 발열, 또는 CPU 자체의 결함까지 넓게 봐야 합니다.","faq":[{"q":"게임할 때만 재부팅되면 그래픽카드 문제인가요?","a":"이 문제(0x0000009C)는 그래픽 드라이버 문제일 가능성이 높지만 전원 공급이나 온도 문제와 겹치는 경우도 많아, 드라이버 재설치와 함께 온도·전력 상태도 함께 확인하는 것이 좋습니다."},{"q":"전원 공급 장치(PSU) 용량이 부족한지 어떻게 확인하나요?","a":"그래픽카드·CPU 권장 용량의 합을 계산해 PSU 정격 용량과 비교하면 부족 여부를 가늠할 수 있습니다."}],"decisionSteps":[{"condition":"오버클럭 해제 후 재현되지 않을 때","action":"오버클럭을 다시 적용하지 말고 안정적인 기본 설정을 유지하세요."},{"condition":"온도가 높게 측정될 때","action":"쿨링 시스템(써멀 재도포, 팬 청소) 점검을 우선하세요."},{"condition":"메모리 진단·재장착 후에도 반복될 때","action":"CPU나 메인보드 자체의 물리적 결함 가능성이 있으므로 다른 시스템에서 CPU 테스트를 고려하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["9c","0000009c","0x9c","cpu 불량","씨피유 불량","부품 불량","하드웨어 불량"],"officialSource":{"title":"Microsoft Learn: Bug Check 0x9C MACHINE_CHECK_EXCEPTION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x9c--machine-check-exception"},"communityCases":[{"title":"CPU 교체로 해결한 사례","summary":"오버클럭을 전혀 하지 않은 기본 클럭 상태에서도 이 코드가 몇 주에 걸쳐 불규칙하게 반복됐던 사례가 있습니다. 파워서플라이 교체, 램 재장착, 온도 점검까지 모두 진행했지만 해결되지 않았고, 결국 CPU를 교체한 뒤로는 한 번도 재발하지 않았습니다.","insight":"오버클럭을 하지 않았는데도 MACHINE_CHECK_EXCEPTION이 반복된다면, 전원과 온도 점검을 마친 뒤에는 CPU 자체의 결함도 배제하지 않는 것이 좋습니다."}]},{"code":"0x00000077","title":"KERNEL_STACK_INPAGE_ERROR","overview":"커널 스택 데이터를 디스크에서 읽어오는 과정에서 실패했을 때 나타나는 코드로, 디스크 오류나 케이블 문제가 흔한 원인입니다.","summary":"커널 스택 데이터를 디스크에서 읽어오는 과정에서 실패했을 때 나타나는 코드로, 디스크 오류나 케이블 문제가 흔한 원인입니다.","causes":["디스크 배드섹터나 물리적 결함","저장장치 케이블이나 슬롯 접촉 불량","페이지 파일(가상 메모리)이 저장된 영역의 손상","갑작스러운 전원 종료로 인한 디스크 손상","저장장치 드라이버 문제"],"checks":["디스크 상태를 chkdsk나 제조사 진단 도구로 점검하세요.","저장장치 케이블 연결 상태를 물리적으로 확인하세요.","가상 메모리(페이지 파일) 설정을 확인하고 필요시 다른 드라이브로 옮겨보세요.","중요 데이터는 미리 백업해 두는 것이 안전합니다.","저장장치 드라이버를 최신 버전으로 업데이트하세요."],"link":"error-code-0x00000077.html","detailPage":"error-code-0x00000077.html","faq":[{"q":"SSD·NVMe를 바로 교체해야 하나요?","a":"이 문제(0x00000077)만으로 저장장치 고장을 단정하기는 어렵습니다. 슬롯 재장착과 펌웨어 업데이트를 먼저 확인한 뒤에도 반복되면 다른 슬롯이나 드라이브로 교차 테스트해보는 것이 안전합니다."},{"q":"오래된 SSD라서 그런 걸까요?","a":"사용 기간보다는 남은 수명(TBW)과 펌웨어 버전이 더 중요한 지표이므로 진단 도구로 확인하는 것이 좋습니다."}],"decisionSteps":[{"condition":"chkdsk나 제조사 진단에서 배드섹터가 발견될 때","action":"데이터 백업을 최우선으로 하고 디스크 교체를 검토하세요."},{"condition":"진단은 정상인데 페이지 파일이 있는 드라이브에서만 반복될 때","action":"페이지 파일을 다른 정상 드라이브로 옮겨 재현 여부를 확인하세요."},{"condition":"케이블 재장착·드라이버 업데이트 후에도 반복될 때","action":"다른 SATA·M.2 슬롯이나 케이블로 교차 테스트하세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["77","00000077","0x77"],"communityCases":[{"title":"HDD 교체로 KERNEL_STACK_INPAGE_ERROR 해결","summary":"사용한 지 5년이 넘은 HDD를 쓰던 중 이 블루스크린이 간헐적으로 발생하다가 점점 잦아졌던 사례가 있습니다. CrystalDiskInfo로 확인하니 재할당 섹터 수가 급격히 늘어나고 있었고, SSD로 교체 후 문제가 완전히 해결됐습니다.","insight":"이 오류는 디스크에서 커널 스택 데이터를 읽지 못할 때 발생합니다. HDD를 사용 중이라면 SMART 상태를 확인하고, 재할당 섹터 수가 증가하고 있다면 교체를 고려하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x77 KERNEL_STACK_INPAGE_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x77--kernel-stack-inpage-error"}},{"code":"0x000000BE","title":"ATTEMPTED_WRITE_TO_READONLY_MEMORY","overview":"드라이버나 커널 모드 코드가 읽기 전용으로 보호된 메모리 영역에 쓰기를 시도했을 때 나타나는 코드로, 드라이버 결함이 주요 원인입니다.","summary":"드라이버나 커널 모드 코드가 읽기 전용으로 보호된 메모리 영역에 쓰기를 시도했을 때 나타나는 코드로, 드라이버 결함이 주요 원인입니다.","causes":["최근 설치한 드라이버의 메모리 보호 위반","커널 모드 소프트웨어 간의 충돌","램 불안정으로 인한 메모리 손상","보안 소프트웨어의 저수준 후킹 충돌","손상된 드라이버 설치 파일"],"checks":["최근 설치하거나 업데이트한 드라이버를 확인하고 제거 또는 롤백하세요.","메모리 진단 도구로 램 상태를 점검하세요.","안전 모드에서 재현 여부를 확인하세요.","보안 프로그램을 임시로 비활성화한 뒤 테스트해 보세요.","제조사 홈페이지에서 해당 드라이버를 최신 버전으로 재설치해 보세요."],"link":"error-code-0x000000be.html","detailPage":"error-code-0x000000be.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000BE)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"블루스크린 이후 데이터가 손상되나요?","a":"대부분은 강제 재시작만 발생할 뿐 저장된 파일이 곧바로 손상되지는 않지만, 저장하지 않은 작업 내용은 사라질 수 있습니다."}],"decisionSteps":[{"condition":"최근 드라이버를 롤백한 뒤 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."},{"condition":"보안 프로그램을 껐을 때 해결될 때","action":"다른 보안 제품으로 교체를 검토하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["be","000000be","0xbe"],"communityCases":[{"title":"그래픽 드라이버 DDU 클린 재설치로 해결","summary":"그래픽 드라이버 업데이트 이후 게임 중 이 블루스크린이 발생했던 사례가 있습니다. 일반 제거 방식으로 드라이버를 교체해도 재발했는데, DDU를 이용해 완전히 초기화하고 재설치하자 문제가 해결됐습니다.","insight":"이 오류는 드라이버가 읽기 전용으로 표시된 메모리 영역에 쓰려 할 때 발생합니다. 드라이버 잔여 파일이 남아있으면 새 드라이버 설치 후에도 재발할 수 있으므로 DDU를 이용한 완전 제거가 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xBE ATTEMPTED_WRITE_TO_READONLY_MEMORY","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xbe--attempted-write-to-readonly-memory"}},{"code":"0x0000007A","title":"KERNEL_DATA_INPAGE_ERROR","overview":"커널 데이터를 디스크에서 읽어오는 도중 실패했을 때 나타나는 코드로, 저장장치나 메모리, 전원 문제가 복합적으로 얽혀 있을 수 있습니다.","summary":"커널 데이터를 디스크에서 읽어오는 도중 실패했을 때 나타나는 코드로, 저장장치나 메모리, 전원 문제가 복합적으로 얽혀 있을 수 있습니다.","causes":["저장장치의 배드섹터나 물리적 결함","램 모듈의 불안정","전원 공급 불안정","저장장치 케이블 접촉 불량","갑작스러운 전원 종료로 인한 파일 시스템 손상"],"checks":["디스크 검사(chkdsk)로 저장장치 오류 여부를 점검하세요.","메모리 진단 도구로 램 상태를 점검하세요.","저장장치와 전원 케이블 연결 상태를 물리적으로 확인하세요.","파워 서플라이 용량이 충분한지 확인하세요.","중요 데이터는 미리 백업해 두세요."],"link":"error-code-0x0000007a.html","detailPage":"error-code-0x0000007a.html","faq":[{"q":"SSD·NVMe를 바로 교체해야 하나요?","a":"이 문제(0x0000007A)만으로 저장장치 고장을 단정하기는 어렵습니다. 슬롯 재장착과 펌웨어 업데이트를 먼저 확인한 뒤에도 반복되면 다른 슬롯이나 드라이브로 교차 테스트해보는 것이 안전합니다."},{"q":"BIOS 설정도 영향을 주나요?","a":"네, SATA 모드(AHCI/RAID)나 고속 부팅 설정이 인식 지연에 영향을 줄 수 있어 BIOS 설정을 함께 확인해야 합니다."}],"decisionSteps":[{"condition":"chkdsk에서 배드섹터가 발견될 때","action":"데이터 백업을 최우선으로 하고 디스크 교체를 검토하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 꽂아가며 어느 모듈이 문제인지 확인하세요."},{"condition":"둘 다 정상인데 반복될 때","action":"저장장치 컨트롤러 드라이버·펌웨어를 업데이트하고, BIOS에서 SATA 모드(AHCI/RAID)가 설치 당시와 같은지 확인하세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["7a","0000007a","0x7a"],"communityCases":[{"title":"SSD 펌웨어 업데이트로 KERNEL_DATA_INPAGE_ERROR 해결","summary":"SSD를 사용하는 시스템에서 이 블루스크린이 간헐적으로 발생했던 사례가 있습니다. 제조사 홈페이지에서 펌웨어 업데이트가 나와 있어 적용하자 이후 완전히 재발하지 않았습니다.","insight":"이 오류는 SSD/HDD에서 데이터를 읽지 못할 때 발생합니다. SSD를 사용 중이라면 드라이버나 케이블보다 제조사 펌웨어 업데이트를 먼저 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x7A KERNEL_DATA_INPAGE_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x7a--kernel-data-inpage-error"}},{"code":"0x00000124","title":"WHEA_UNCORRECTABLE_ERROR","overview":"CPU, 메모리, 메인보드 전원부, PCIe 장치 등 하드웨어 계층에서 수정 불가능한 오류가 감지되어 WHEA(Windows Hardware Error Architecture)가 시스템을 강제로 정지시킬 때 나타나는 코드입니다. 소프트웨어보다 하드웨어 자체의 불안정성이 원인인 경우가 많아 다른 블루스크린보다 원인 특정에 시간이 걸릴 수 있습니다.","summary":"CPU, 메모리, 메인보드, 전원 공급 장치가 수정할 수 없는 하드웨어 오류를 보고할 때 나타날 수 있습니다.","causes":["CPU나 GPU가 고부하 작업 중 냉각이 따라가지 못해 과열되는 경우","램이나 CPU의 오버클럭, XMP/EXPO 프로파일이 실제 하드웨어 조합에서 불안정한 경우","파워 서플라이 용량 부족이나 노후화로 순간적인 전압 강하가 발생하는 경우","메인보드 전원부(VRM)나 PCIe 슬롯의 접촉 불량, 물리적 결함","CPU나 램 자체의 하드웨어 결함으로 특정 연산에서 오류가 발생하는 경우"],"checks":["오버클럭, XMP/EXPO 설정을 모두 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","CPU와 GPU 온도를 모니터링 프로그램으로 확인해 고부하 시 과열되는지 점검하세요.","이벤트 뷰어에서 WHEA-Logger 항목을 확인해 어떤 구성요소(소스)가 오류를 보고했는지 확인하세요.","CPU, 램, GPU를 각각 따로 부하 테스트(프라임95, 메모리 진단, 퍼니마크 등)해 원인 부품을 좁혀보세요.","파워 서플라이 용량이 시스템 사양에 충분한지, 케이블 연결이 안정적인지 점검하세요."],"link":"error-code-0x00000124.html","detailPage":"error-code-0x00000124.html","faq":[{"q":"게임할 때만 재부팅되면 그래픽카드 문제인가요?","a":"이 문제(0x00000124)는 그래픽 드라이버 문제일 가능성이 높지만 전원 공급이나 온도 문제와 겹치는 경우도 많아, 드라이버 재설치와 함께 온도·전력 상태도 함께 확인하는 것이 좋습니다."},{"q":"쿨링 문제인지 전원 문제인지 구분하는 방법이 있나요?","a":"재부팅 직전 온도를 모니터링 프로그램으로 확인해, 온도가 정상 범위인데도 재부팅된다면 전원 문제일 가능성이 높습니다."}],"decisionSteps":[{"condition":"오버클럭 해제로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"파워서플라이 교체로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"부품별 부하 테스트로도 원인이 좁혀지지 않을 때","action":"사례처럼 WHEA-Logger 18번이 반복된다면 CPU 자체 결함을 의심해보세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["124","00000124","0x124","cpu 불량","부품 불량","하드웨어 불량"],"communityCases":[{"title":"CPU 오버클럭 해제로 WHEA 오류 해결","summary":"게임 중 불규칙하게 WHEA_UNCORRECTABLE_ERROR가 발생했던 사례가 있습니다. 처음엔 메모리 문제로 의심했지만, BIOS에서 CPU 오버클럭 설정을 기본값으로 되돌리자 이후 재발하지 않았습니다.","insight":"이 오류는 CPU, 메모리, 칩셋 등의 하드웨어 오류를 운영체제가 감지했을 때 발생합니다. 오버클럭이나 언더볼팅 설정을 기본값으로 복원하는 것이 가장 먼저 시도해볼 조치입니다."},{"title":"파워서플라이 교체로 WHEA 오류 해결","summary":"오버클럭 해제·드라이버 갱신으로도 해결되지 않고 반복되던 WHEA_UNCORRECTABLE_ERROR가 파워서플라이를 교체한 뒤로는 재발하지 않았던 사례가 있습니다.","insight":"설정·드라이버 쪽에 문제가 없는데도 반복된다면, 노후화되었거나 용량이 부족한 파워서플라이가 부하 순간 전압을 순간적으로 떨어뜨려 하드웨어 오류로 이어졌을 가능성을 의심해 보세요."},{"title":"CPU 교체로 WHEA 오류 해결","summary":"이벤트 뷰어의 시스템 로그에서 이 코드와 함께 WHEA-Logger 이벤트 18번이 반복적으로 기록되던 사례가 있습니다. 오버클럭 해제, 메모리 교차 테스트, 온도·전원 점검을 모두 진행했지만 해결되지 않다가 CPU를 교체한 뒤에야 문제가 해결됐습니다.","insight":"이벤트 뷰어에서 WHEA-Logger 18번이 이 코드와 같은 시각에 반복 기록된다면, 드라이버나 설정보다 CPU 자체의 결함을 먼저 의심해보는 것이 좋습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x124 WHEA_UNCORRECTABLE_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x124---whea-uncorrectable-error"}},{"code":"0x00000139","title":"KERNEL_SECURITY_CHECK_FAILURE","overview":"윈도우 커널이 내부 데이터 구조나 보안 쿠키의 무결성을 검사하는 과정에서 예상과 다른 값을 발견했을 때 강제로 시스템을 정지시키는 코드입니다. 드라이버 버그로 인한 메모리 손상이 가장 흔한 원인이지만, 램 불량이나 악성코드 감염도 후보로 봐야 합니다.","summary":"윈도우 커널의 중요한 데이터 구조가 손상되었거나 예상과 다르게 바뀌었을 때 나타날 수 있습니다.","causes":["특정 드라이버가 커널 데이터 구조를 잘못 덮어써 무결성 검사에 실패하는 경우","램 모듈의 물리적 결함이나 접촉 불량으로 메모리 내용이 손상되는 경우","보안 소프트웨어가 커널 모드에서 다른 드라이버와 충돌하는 경우","시스템 파일이 손상되어 커널 검증 과정에서 오류가 발생하는 경우","맬웨어가 커널 메모리 영역을 변조하려 시도하는 경우"],"checks":["최근 설치·업데이트한 드라이버를 확인하고 제거 또는 이전 버전으로 롤백하세요.","안전 모드에서 재현되지 않는다면 특정 드라이버나 프로그램이 원인일 가능성이 큽니다.","메모리 진단 도구(mdsched.exe 또는 MemTest86+)로 램 상태를 점검하세요.","sfc /scannow와 DISM /Online /Cleanup-Image /RestoreHealth로 시스템 파일 손상 여부를 점검하세요.","백신 프로그램으로 전체 검사를 실행해 맬웨어 감염 여부를 확인하세요."],"link":"error-code-0x00000139.html","detailPage":"error-code-0x00000139.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000139)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\\\Windows\\\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 롤백으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"해당 모듈을 교체하세요."},{"condition":"XMP 해제로 해결될 때","action":"사례처럼 더 낮은 프로파일로 안정화하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["139","00000139","0x139"],"communityCases":[{"title":"RAM 오버클럭 해제로 KERNEL_SECURITY_CHECK 해결","summary":"XMP 프로파일로 메모리를 오버클럭한 상태에서 이 블루스크린이 반복됐던 사례가 있습니다. BIOS에서 XMP를 비활성화하고 기본 속도로 설정하자 재발하지 않았고, 이후 더 낮은 XMP 프로파일을 적용해 안정적으로 사용 중입니다.","insight":"이 오류는 커널 보안 검사에 실패했을 때 발생하며, 드라이버 문제뿐 아니라 메모리 오버클럭(XMP) 불안정으로도 자주 나타납니다. XMP 설정부터 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x139 KERNEL_SECURITY_CHECK_FAILURE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x139--kernel-security-check-failure"}},{"code":"0x000000C4","title":"DRIVER_VERIFIER_DETECTED_VIOLATION","overview":"Driver Verifier(드라이버 검증기)가 활성화된 상태에서 특정 드라이버가 규칙을 위반하는 동작(잘못된 메모리 접근, 자원 미해제 등)을 하면 이를 즉시 감지해 블루스크린으로 표시하는 코드입니다. 검증기를 직접 켠 적이 없어도 드라이버 자체의 결함으로 나타날 수 있습니다.","summary":"Driver Verifier가 드라이버의 잘못된 동작을 발견했을 때 발생하는 블루스크린 코드입니다.","causes":["베타 버전이거나 서명되지 않은 불안정한 드라이버를 설치한 경우","오버클럭 유틸리티나 하드웨어 모니터링 도구가 저수준에서 드라이버 규칙을 위반하는 경우","직접 verifier.exe로 드라이버 검증을 켜둔 채 재부팅한 경우","오래된 드라이버가 최신 윈도우 빌드의 검증 기준과 맞지 않는 경우","여러 보안 프로그램의 커널 드라이버가 서로 충돌하는 경우"],"checks":["verifier /query로 검증기 활성화 여부를 확인하세요.","verifier /reset으로 검증기를 끈 뒤 재부팅해 재현 여부를 확인하세요.","덤프 파일에서 지목된 드라이버(.sys)를 확인하고 제조사 최신 버전으로 재설치하세요.","최근 설치한 오버클럭 툴, 모니터링 프로그램, 베타 드라이버를 제거해 보세요.","안전 모드에서 문제 드라이버를 제거한 뒤 정상 부팅되는지 확인하세요."],"link":"error-code-0x000000c4.html","detailPage":"error-code-0x000000c4.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000C4)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"최근에 설치한 프로그램이 원인일 수도 있나요?","a":"네, 최근 설치한 드라이버나 소프트웨어가 원인인 경우가 많아 시스템 복원 지점으로 되돌리는 것도 방법입니다."}],"decisionSteps":[{"condition":"verifier /reset으로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"덤프에서 지목된 드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"안전 모드에서 제거해도 해결되지 않을 때","action":"여러 보안 프로그램이 충돌하고 있는지 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["c4","000000c4","0xc4"],"communityCases":[{"title":"드라이버 검증 도구 비활성화로 VERIFIER 오류 해결","summary":"이 블루스크린이 갑자기 발생해 당황했던 사례에서, 이전에 문제 해결 목적으로 활성화했던 드라이버 검증 도구(Driver Verifier)가 해제되지 않은 채 남아있던 것이 원인이었습니다. 명령 프롬프트에서 verifier /reset 명령으로 비활성화한 뒤 정상 부팅됐습니다.","insight":"이전에 Driver Verifier를 켰다가 잊은 경우 이 오류가 발생할 수 있습니다. 부팅이 된다면 verifier /reset을, 부팅이 안 된다면 안전 모드에서 실행하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xC4 DRIVER_VERIFIER_DETECTED_VIOLATION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xc4--driver-verifier-detected-violation"}},{"code":"0x800F081F","title":"원본 파일을 찾을 수 없음","overview":"Windows 선택적 기능을 추가하거나 DISM으로 시스템 이미지를 복구할 때, 필요한 구성 요소의 원본 파일을 로컬 저장소나 Windows Update 서버에서 찾지 못해 실패하는 코드입니다. 구성 요소 저장소 손상이나 잘못된 설치 미디어 경로 지정이 대표적인 원인입니다.","summary":"Windows 기능 추가나 복구 과정에서 필요한 구성 요소 원본을 찾지 못할 때 보이는 코드입니다.","causes":["Windows 구성 요소 저장소(WinSxS)의 해당 항목이 손상되었거나 누락된 경우","DISM 명령에 지정한 설치 미디어(install.wim/install.esd) 경로나 인덱스 번호가 잘못된 경우","Windows Update를 통한 원본 파일 다운로드가 정책이나 네트워크 문제로 차단된 경우","그룹 정책에서 Windows Update를 통한 복구가 금지되도록 설정된 경우","설치 미디어의 Windows 버전이나 빌드가 현재 시스템과 일치하지 않는 경우"],"checks":["DISM /Online /Cleanup-Image /ScanHealth로 손상 여부를 먼저 확인하세요.","인터넷에 연결된 상태에서 DISM /Online /Cleanup-Image /RestoreHealth를 실행해 Windows Update에서 원본 파일을 받도록 하세요.","그룹 정책(gpedit.msc)에서 구성 요소 복구 관련 정책이 차단되어 있는지 확인하세요.","설치 미디어를 사용한다면 /Source 옵션에 install.wim이나 install.esd의 정확한 경로와 인덱스를 지정하세요.","현재 Windows 버전과 빌드가 일치하는 설치 미디어를 새로 받아 다시 시도하세요."],"link":"error-code-0x800f081f.html","detailPage":"error-code-0x800f081f.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x800F081F)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트 오류 코드마다 해결법이 다른가요?","a":"공통 원인(구성 요소 정리, 디스크 공간)이 많지만 코드별로 원인이 갈리는 경우도 있어, 코드 자체를 함께 검색해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"RestoreHealth로 원본 파일을 받아 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"설치 미디어 소스 지정으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"그룹 정책 확인으로도 해결되지 않을 때","action":"설치 미디어의 Windows 버전·빌드가 정확히 일치하는지 다시 확인하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["800f081f","0x800f081f"],"communityCases":[{"title":".NET Framework 오프라인 설치로 해결","summary":"특정 프로그램 설치 중 소스 파일을 찾을 수 없다는 오류와 함께 .NET Framework 3.5 활성화에 실패했던 사례가 있습니다. 인터넷 연결 없이 윈도우 설치 미디어를 소스로 지정해 DISM 명령을 실행하자 정상적으로 활성화됐습니다.","insight":"이 오류로 .NET Framework 활성화가 안 된다면 온라인 대신 설치 미디어(USB나 ISO)의 install.wim을 소스로 지정하는 오프라인 방식이 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Fix Windows Update errors (DISM source files)","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/fix-windows-update-errors"}},{"code":"0x800F0831","title":"Windows 구성 요소 저장소 손상","overview":"누적 업데이트나 독립 실행형 업데이트를 설치할 때 필요한 구성 요소 패키지가 누락되었거나 구성 요소 저장소와 레지스트리에 정상적으로 반영되지 않아 설치가 중단될 때 나타나는 오류입니다.","summary":"Windows 업데이트에 필요한 구성 요소 패키지를 찾거나 적용하지 못할 때 나타나는 코드입니다.","causes":["이전 업데이트가 중간에 중단되어 필요한 패키지가 완전히 적용되지 않은 경우","WinSxS 구성 요소 저장소의 매니페스트나 패키지 정보가 손상된 경우","현재 Windows 빌드와 맞지 않는 설치 미디어를 복구 원본으로 사용한 경우","보안 프로그램이나 정리 도구가 업데이트 구성 요소 파일을 격리·삭제한 경우"],"checks":["설정의 Windows Update 기록에서 실패한 KB 번호와 발생 시각을 먼저 기록하세요.","관리자 터미널에서 DISM /Online /Cleanup-Image /ScanHealth를 실행해 구성 요소 저장소 상태를 확인하세요.","이어서 DISM /Online /Cleanup-Image /RestoreHealth와 sfc /scannow를 순서대로 실행하고 재부팅하세요.","CBS.log에서 0x800F0831과 함께 표시된 누락 패키지 또는 KB 번호를 확인하세요.","복구 원본이 필요하다면 현재 Windows 버전·언어·아키텍처와 일치하는 설치 미디어를 사용하세요."],"link":"error-code-0x800f0831.html","detailPage":"error-code-0x800f0831.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x800F0831)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"DISM·SFC 복구로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"CBS.log에서 특정 KB가 확인될 때","action":"해당 KB를 Microsoft Update 카탈로그에서 수동으로 설치하세요."},{"condition":"복구로도 해결되지 않을 때","action":"현재 버전과 일치하는 설치 미디어로 복구 설치(in-place upgrade)를 고려하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["800f0831","0x800f0831","CBS_E_STORE_CORRUPTION","업데이트 구성 요소 저장소 손상"],"communityCases":[{"title":"CBS.log의 누락 패키지 확인 후 복구","summary":"누적 업데이트가 반복해서 실패한 사례에서 CBS.log에 특정 패키지의 매니페스트가 없다는 기록이 남았습니다. 먼저 DISM 복구를 실행하고 현재 빌드와 일치하는 설치 미디어를 원본으로 지정한 뒤 업데이트가 완료됐습니다.","insight":"0x800F0831은 단순히 업데이트 캐시를 지우는 것보다 CBS.log에 기록된 누락 패키지와 Windows 빌드 일치 여부를 함께 확인해야 원인을 좁힐 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: Troubleshoot Windows installation error 0x800F0831","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/troubleshoot-windows-installation-error"}},{"code":"0x800B0101","title":"인증서 유효 기간 오류","overview":"Windows Update나 설치 패키지의 서명 인증서를 확인하는 과정에서 인증서가 현재 시스템 시간 기준으로 유효하지 않다고 판단될 때 나타날 수 있는 오류입니다. 날짜·시간 오류와 인증서 구성 문제를 구분해야 합니다.","summary":"업데이트 파일의 인증서가 만료됐거나 시스템 시간이 잘못되어 서명 검증에 실패할 때 나타날 수 있습니다.","causes":["PC의 날짜·시간 또는 시간대가 실제 시간과 크게 다른 경우","업데이트 패키지 서명 인증서가 만료되었거나 신뢰 체인이 완성되지 않은 경우","오래된 Windows에서 루트 인증서 업데이트가 누락된 경우","WSUS·프록시·보안 프로그램이 HTTPS 연결을 중간에서 검사하면서 인증서 신뢰가 깨진 경우"],"checks":["설정의 날짜 및 시간에서 자동 시간 설정과 시간대를 확인한 뒤 지금 동기화를 실행하세요.","다른 HTTPS 사이트가 정상적으로 열리는지 확인해 PC 시간 문제와 서버 연결 문제를 구분하세요.","회사·학교 PC라면 WSUS 또는 보안 프록시의 인증서 정책을 관리자에게 확인하세요.","Windows Update 로그에서 인증서·서명 검증 실패가 같은 시각에 반복되는지 확인하세요.","TLS를 낮추거나 인증서 검사를 무시하지 말고 Windows와 보안 구성 요소를 최신 상태로 유지하세요."],"link":"error-code-0x800b0101.html","detailPage":"error-code-0x800b0101.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x800B0101)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"시간 동기화 후 해결될 때","action":"재발 방지를 위해 인터넷 시간 자동 동기화를 켜두세요."},{"condition":"다른 HTTPS 사이트도 안 열릴 때","action":"네트워크 자체 문제이므로 시간 문제와 분리해서 접근하세요."},{"condition":"WSUS·보안 프록시 환경일 때","action":"관리자에게 인증서 정책 확인을 요청하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["800b0101","0x800b0101","CERT_E_EXPIRED","인증서 만료","서명 인증서 오류"],"communityCases":[{"title":"시간 동기화 후 업데이트 서명 검증 성공","summary":"인터넷 연결은 정상인데 업데이트 설치만 실패하던 PC에서 시스템 시간이 실제 시간보다 크게 늦어져 있었습니다. 시간대를 바로잡고 자동 동기화를 실행한 뒤 같은 업데이트를 다시 설치하자 정상적으로 진행됐습니다.","insight":"인증서 오류가 보이면 보안 설정을 낮추기 전에 시스템 시간과 시간대를 먼저 확인해야 합니다. 시간 오류는 인증서가 만료된 것처럼 보이게 만들 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: Fix Windows Update corruptions and installation failures","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/fix-windows-update-errors"}},{"code":"0x80070422","title":"필요한 서비스가 비활성화됨","overview":"Windows Update, BITS(백그라운드 지능형 전송 서비스) 등 업데이트에 필요한 시스템 서비스가 중지되었거나 시작 유형이 '사용 안 함'으로 바뀌어 있을 때 나타나는 오류입니다. 최적화 프로그램이나 보안 설정이 의도치 않게 서비스를 꺼버린 경우가 흔합니다.","summary":"Windows Update나 관련 서비스가 중지 또는 비활성화되어 작업을 진행하지 못할 때 나타날 수 있습니다.","causes":["Windows Update(wuauserv) 서비스가 중지되었거나 시작 유형이 '사용 안 함'으로 설정된 경우","PC 최적화·튜닝 프로그램이 불필요한 서비스로 오인해 Windows Update 관련 서비스를 꺼버린 경우","BITS나 암호화 서비스(cryptsvc) 등 연관 서비스가 함께 중지된 경우","그룹 정책이나 레지스트리로 특정 서비스 시작이 제한된 경우","보안 소프트웨어가 서비스 실행을 차단하는 경우"],"checks":["services.msc를 열어 Windows Update 서비스의 상태와 시작 유형을 확인하고 '자동'으로 변경 후 시작하세요.","BITS, 암호화 서비스, Windows Update 서비스가 모두 실행 중인지 함께 확인하세요.","최근 설치한 최적화·튜닝 프로그램이 있다면 서비스 설정을 되돌렸는지 확인하세요.","명령 프롬프트(관리자)에서 sc config wuauserv start=auto 명령으로 시작 유형을 강제 설정해 보세요.","Windows Update 문제 해결사를 실행해 서비스 상태를 자동으로 점검하고 복구하세요."],"link":"error-code-0x80070422.html","detailPage":"error-code-0x80070422.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80070422)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"수동으로 업데이트를 받아 설치해도 되나요?","a":"Microsoft Update 카탈로그에서 해당 KB 번호를 직접 받아 설치하면 자동 업데이트 오류를 우회할 수 있는 경우가 있습니다."}],"decisionSteps":[{"condition":"서비스 시작 유형 변경만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"sc config 명령으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"문제 해결사로도 해결되지 않을 때","action":"그룹 정책이나 레지스트리의 서비스 제한 설정을 확인하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80070422","0x80070422"],"communityCases":[{"title":"Windows Update 서비스 수동 시작으로 해결","summary":"업데이트 창에서 이 오류가 반복됐던 사례에서, 서비스 관리자(services.msc)를 확인하니 Windows Update 서비스가 비활성화된 상태였습니다. 서비스를 수동으로 시작하고 시작 유형을 자동으로 변경하자 업데이트가 정상적으로 진행됐습니다.","insight":"이 오류는 대부분 필요한 서비스가 중지되어 있어서 발생합니다. services.msc에서 Windows Update, BITS, Cryptographic Services 세 가지 서비스가 실행 중인지 먼저 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Windows Update error code list","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x80070070","title":"디스크 공간 부족","overview":"Windows 업데이트나 앱 설치, 임시 파일 생성에 필요한 디스크 여유 공간이 부족할 때 표시되는 코드입니다. 시스템 드라이브뿐 아니라 복구 파티션의 여유 공간까지 함께 확인해야 하는 경우가 많습니다.","summary":"Windows 업데이트, 앱 설치, 임시 파일 생성에 필요한 여유 공간이 부족할 때 나타나는 코드입니다.","causes":["C 드라이브(시스템 드라이브)의 여유 공간이 업데이트에 필요한 최소 용량보다 부족한 경우","이전 업데이트나 설치 작업에서 남은 임시 파일이 디스크 공간을 계속 차지하는 경우","시스템 예약 파티션이나 복구 파티션의 용량이 너무 작아 업데이트 작업 공간이 부족한 경우","다운로드 폴더나 사용자 폴더에 대용량 파일이 누적된 경우","디스크 정리를 한 번도 하지 않아 캐시와 로그 파일이 과도하게 쌓인 경우"],"checks":["설정 > 시스템 > 저장소에서 C 드라이브 여유 공간을 확인하세요.","디스크 정리 도구로 임시 파일과 이전 설치 파일을 정리하세요.","대용량 파일을 외장 드라이브나 다른 파티션으로 이동하세요.","시스템 예약 파티션 용량을 확인하고 부족하다면 확장을 검토하세요.","최소 10~20GB 이상 여유 공간을 확보한 뒤 업데이트를 다시 시도하세요."],"link":"error-code-0x80070070.html","detailPage":"error-code-0x80070070.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80070070)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트를 미루면 보안에 문제가 되나요?","a":"보안 업데이트가 누락되면 취약점 노출 위험이 커지므로, 오류를 바로 해결하지 못했다면 최소한 원인 진단이라도 진행하는 것이 좋습니다."}],"decisionSteps":[{"condition":"디스크 정리만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"대용량 파일 이동으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"여유 공간을 확보해도 해결되지 않을 때","action":"시스템 예약 파티션 용량과 디스크 건강 상태를 함께 점검하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80070070","0x80070070"],"communityCases":[{"title":"임시 파일 정리 후 C 드라이브 공간 확보로 해결","summary":"업데이트 중 이 오류가 발생해 확인해보니 C 드라이브 여유 공간이 2GB 미만이었던 사례가 있습니다. 디스크 정리 도구로 임시 파일과 이전 윈도우 설치 파일을 제거해 공간을 확보하자 업데이트가 정상적으로 완료됐습니다.","insight":"윈도우 업데이트는 임시 파일 생성과 압축 해제에 상당한 공간이 필요합니다. C 드라이브에 여유 공간이 10GB 이상 있는지 확인하는 것이 중요합니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_DISK_FULL","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0xC1900101","title":"업데이트 드라이버 호환성 실패","overview":"Windows 기능 업데이트(대규모 버전 업그레이드) 도중 특정 드라이버가 새 환경으로 전환하거나 이전 버전으로 롤백하는 단계에서 응답하지 않거나 충돌할 때 나타나는 코드입니다. 저장장치·그래픽 드라이버와 외장 장치 드라이버가 가장 흔한 원인으로 지목됩니다.","summary":"Windows 기능 업데이트 중 드라이버가 설치 또는 롤백 단계에서 충돌할 때 자주 보이는 코드입니다.","causes":["저장장치(SSD/NVMe) 컨트롤러 드라이버가 새 Windows 빌드와 호환되지 않는 경우","그래픽 드라이버가 업그레이드 과정에서 초기화에 실패하는 경우","USB로 연결된 외장 장치(프린터, 외장하드, 카드리더 등)의 드라이버가 충돌하는 경우","메인보드 BIOS나 제조사 전용 유틸리티가 오래되어 업그레이드 절차와 맞지 않는 경우","이전 업그레이드 시도의 잔여 파일이 새 시도와 충돌하는 경우"],"checks":["업그레이드 전 불필요한 외장 장치를 모두 분리하세요.","저장장치·그래픽 드라이버를 최신 버전으로 업데이트하세요.","메인보드 제조사 홈페이지에서 BIOS와 칩션 드라이버가 최신인지 확인하세요.","setupact.log에서 실패를 유발한 드라이버를 확인하세요.","설치 미디어를 새로 만들어 클린 업그레이드를 시도해 보세요."],"link":"error-code-0xc1900101.html","detailPage":"error-code-0xc1900101.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0xC1900101)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트 오류 코드마다 해결법이 다른가요?","a":"공통 원인(구성 요소 정리, 디스크 공간)이 많지만 코드별로 원인이 갈리는 경우도 있어, 코드 자체를 함께 검색해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"외장 장치 분리만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"드라이버 업데이트로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"클린 업그레이드로도 해결되지 않을 때","action":"SetupDiag 도구로 원인 드라이버를 특정하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["c1900101","0xc1900101"],"communityCases":[{"title":"구형 드라이버 수동 제거 후 업그레이드 성공","summary":"윈도우 10에서 11로 업그레이드 시도 시 이 오류가 반복됐던 사례가 있습니다. SetupDiag 도구로 분석하니 구형 네트워크 카드 드라이버가 원인으로 지목됐고, 해당 드라이버를 제거한 뒤 업그레이드를 다시 시도하자 성공했습니다.","insight":"업그레이드 중 이 오류가 발생하면 SetupDiag 도구를 먼저 실행해 정확한 원인 드라이버를 찾는 것이 효율적입니다. 원인 드라이버를 제거하고 업그레이드 후 다시 설치하면 됩니다."}],"officialSource":{"title":"Microsoft Learn: Windows 10 upgrade resolution procedures","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/setup-upgrade-and-drivers/windows-10-upgrade-resolution-procedures"}},{"code":"0x80240034","title":"WU_E_UNKNOWN 알 수 없는 업데이트 오류","overview":"윈도우 업데이트 클라이언트가 다운로드나 설치 과정에서 분류되지 않은 오류를 만났을 때 표시되는 포괄적인 코드입니다. 원인이 한 가지로 좁혀지지 않아 캐시, 서비스, 구성 요소 저장소를 순서대로 점검해야 합니다.","summary":"윈도우 업데이트 클라이언트가 다운로드나 설치 과정에서 분류되지 않은 오류를 만났을 때 표시되는 포괄적인 코드입니다.","causes":["업데이트 캐시(SoftwareDistribution)가 손상되어 다운로드나 설치 목록을 제대로 읽지 못하는 경우","Windows Update 관련 서비스(wuauserv, bits, cryptsvc) 중 하나가 중지되었거나 손상된 경우","구성 요소 저장소(WinSxS)에 손상된 항목이 남아있는 경우","이전 업데이트 설치가 중간에 중단되어 잔여 파일이 충돌하는 경우","보안 소프트웨어가 업데이트 프로세스의 파일 접근을 차단하는 경우"],"checks":["Windows Update 문제 해결사를 먼저 실행해 자동으로 진단받아 보세요.","명령 프롬프트(관리자)에서 wuauserv, bits, cryptsvc 서비스를 각각 net stop/net start로 재시작하세요.","SoftwareDistribution과 catroot2 폴더 이름을 바꾼 뒤 업데이트를 다시 시도하세요.","DISM /Online /Cleanup-Image /RestoreHealth 명령으로 구성 요소 저장소를 복구하세요.","그래도 반복되면 업데이트 어시스턴트로 최신 버전을 수동 설치해 보세요."],"link":"error-code-0x80240034.html","detailPage":"error-code-0x80240034.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80240034)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"수동으로 업데이트를 받아 설치해도 되나요?","a":"Microsoft Update 카탈로그에서 해당 KB 번호를 직접 받아 설치하면 자동 업데이트 오류를 우회할 수 있는 경우가 있습니다."}],"decisionSteps":[{"condition":"서비스 재시작만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"캐시 폴더 초기화로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"DISM 복구로도 해결되지 않을 때","action":"업데이트 어시스턴트로 수동 설치를 시도하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80240034","0x80240034","wu_e_unknown"],"communityCases":[{"title":"업데이트 캐시 초기화 후 재시도로 해결","summary":"특정 누적 업데이트가 이 오류로 계속 실패하던 사례가 있습니다. SoftwareDistribution 폴더를 초기화하고 wuauclt /detectnow 명령으로 업데이트를 강제 재확인하자 이후 정상 설치됐습니다.","insight":"업데이트 오류가 특정 항목에서만 반복된다면 캐시된 업데이트 패키지가 손상된 경우가 많습니다. 업데이트 캐시를 초기화하면 대부분 해결됩니다."}],"officialSource":{"title":"Microsoft Learn: Windows Update error code list — WU_E_DOWNLOAD_FAILED","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x8024402C","title":"WU_E_PT_WINHTTP_NAME_NOT_RESOLVED 서버 연결 실패","overview":"윈도우 업데이트 클라이언트가 마이크로소프트 업데이트 서버의 주소를 확인(DNS)하지 못했을 때 나타나는 오류입니다. 네트워크 연결 자체보다 이름 확인이나 프록시 설정이 원인인 경우가 많습니다.","summary":"윈도우 업데이트 클라이언트가 마이크로소프트 업데이트 서버의 주소를 확인(DNS)하지 못했을 때 나타나는 오류입니다.","causes":["DNS 서버가 응답하지 않거나 잘못된 DNS 주소가 설정된 경우","VPN이나 프록시 설정이 업데이트 서버 접속을 가로막는 경우","회사/학교 네트워크의 방화벽이 업데이트 관련 포트를 차단하는 경우","네트워크 어댑터 드라이버가 불안정해 간헐적으로 연결이 끊기는 경우","hosts 파일에 업데이트 서버 도메인이 잘못 등록된 경우"],"checks":["다른 웹사이트는 정상 접속되는지 확인해 전체 네트워크 문제인지 좁혀보세요.","명령 프롬프트에서 ipconfig /flushdns로 DNS 캐시를 지운 뒤 다시 시도하세요.","VPN이나 프록시를 사용 중이라면 임시로 해제하고 업데이트를 재시도하세요.","네트워크 어댑터 속성에서 DNS 서버를 8.8.8.8 같은 공용 DNS로 임시 변경해 재현 여부를 확인하세요.","회사망이라면 네트워크 관리자에게 업데이트 서버 도메인이 차단됐는지 확인을 요청하세요."],"link":"error-code-0x8024402c.html","detailPage":"error-code-0x8024402c.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x8024402C)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트를 미루면 보안에 문제가 되나요?","a":"보안 업데이트가 누락되면 취약점 노출 위험이 커지므로, 오류를 바로 해결하지 못했다면 최소한 원인 진단이라도 진행하는 것이 좋습니다."}],"decisionSteps":[{"condition":"DNS 캐시 초기화만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"공용 DNS로 변경해 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"VPN·프록시 해제로도 해결되지 않을 때","action":"회사망 방화벽의 업데이트 서버 차단 여부를 관리자에게 확인하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["8024402c","0x8024402c"],"communityCases":[{"title":"VPN 해제 후 업데이트 성공한 사례","summary":"회사 VPN에 연결된 상태에서 윈도우 업데이트가 계속 이 오류로 실패했던 사례가 있습니다. VPN 연결을 해제하고 일반 인터넷으로 업데이트를 시도하자 정상적으로 서버에 연결되어 업데이트가 완료됐습니다.","insight":"이 오류는 DNS 이름 확인 실패가 원인입니다. VPN 사용 중이라면 VPN을 끄고 시도하는 것이 가장 빠른 확인 방법입니다."}],"officialSource":{"title":"Microsoft Learn: Windows Update error code list — WU_E_PT_WINHTTP_NAME_NOT_RESOLVED","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x80073712","title":"구성 요소 저장소 손상 오류","overview":"업데이트 설치에 필요한 시스템 파일이 저장된 구성 요소 저장소(WinSxS)의 일부가 손상되었을 때 나타나는 오류입니다. 반복적인 업데이트 실패의 대표적인 원인 중 하나입니다.","summary":"업데이트 설치에 필요한 시스템 파일이 저장된 구성 요소 저장소(WinSxS)의 일부가 손상되었을 때 나타나는 오류입니다.","causes":["이전 업데이트가 비정상 종료되어 구성 요소 저장소 항목이 일부만 기록된 경우","디스크 오류로 저장소 파일 자체가 손상된 경우","타사 시스템 최적화 프로그램이 시스템 파일을 임의로 삭제한 경우","오래 방치된 시스템에서 여러 번의 업데이트 누적으로 저장소 정합성이 깨진 경우","바이러스나 맬웨어 감염으로 시스템 파일이 변조된 경우"],"checks":["명령 프롬프트(관리자)에서 DISM /Online /Cleanup-Image /ScanHealth로 손상 여부를 먼저 확인하세요.","손상이 확인되면 DISM /Online /Cleanup-Image /RestoreHealth로 복구를 진행하세요 (인터넷 연결 필요).","복구 후 sfc /scannow를 실행해 시스템 파일 전체를 다시 검사하세요.","디스크 상태를 chkdsk로 점검해 물리적 오류가 없는지 확인하세요.","복구가 반복 실패하면 설치 미디어의 install.wim을 소스로 지정해 DISM 복구를 다시 시도하세요."],"link":"error-code-0x80073712.html","detailPage":"error-code-0x80073712.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80073712)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트 오류 코드마다 해결법이 다른가요?","a":"공통 원인(구성 요소 정리, 디스크 공간)이 많지만 코드별로 원인이 갈리는 경우도 있어, 코드 자체를 함께 검색해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"ScanHealth 결과 손상이 없을 때","action":"다른 원인(디스크 공간, 서비스 상태)을 이어서 점검하세요."},{"condition":"RestoreHealth 복구로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"설치 미디어 소스 지정으로도 해결되지 않을 때","action":"인플레이스 업그레이드나 초기화를 검토하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80073712","0x80073712"],"communityCases":[{"title":"DISM으로 구성 요소 저장소 복구 후 해결","summary":"누적 업데이트가 이 오류로 반복 실패하던 사례에서 DISM /Online /Cleanup-Image /RestoreHealth를 실행하니 실제로 손상된 구성 요소가 발견됐고, 복구 완료 후 업데이트가 정상 설치됐습니다.","insight":"이 오류가 반복된다면 SoftwareDistribution 초기화보다 DISM으로 구성 요소 저장소 자체를 복구하는 것이 더 근본적인 해결책입니다."}],"officialSource":{"title":"Microsoft Learn: Fix Windows Update errors (component store repair)","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/fix-windows-update-errors"}},{"code":"0x8007232B","title":"DNS 이름을 확인할 수 없음","overview":"업데이트 서버나 활성화 서버의 도메인 이름을 DNS가 확인하지 못했을 때 나타나는 오류입니다. 업데이트뿐 아니라 윈도우 정품 인증, 스토어 접속 실패와 함께 나타나기도 합니다.","summary":"업데이트 서버나 활성화 서버의 도메인 이름을 DNS가 확인하지 못했을 때 나타나는 오류입니다.","causes":["DNS 서버가 응답하지 않거나 설정이 잘못된 경우","공유기나 모뎀의 DNS 캐시가 오래되어 최신 주소를 반영하지 못하는 경우","VPN이나 사설 DNS 확장 프로그램이 이름 확인을 방해하는 경우","네트워크 어댑터 드라이버 문제로 DNS 질의 자체가 실패하는 경우","회사·공용 와이파이의 DNS 필터링 정책에 걸리는 경우"],"checks":["명령 프롬프트에서 ipconfig /flushdns 로 DNS 캐시를 초기화한 뒤 재시도하세요.","네트워크 어댑터 설정에서 DNS 서버를 8.8.8.8, 1.1.1.1 같은 공용 DNS로 바꿔 재현 여부를 확인하세요.","공유기를 재시작해 공유기 자체의 DNS 캐시를 초기화하세요.","VPN이나 DNS 관련 브라우저 확장 프로그램을 임시로 비활성화하세요.","다른 네트워크(모바일 핫스팟 등)에서도 같은 오류가 나는지 확인해 네트워크 문제인지 PC 문제인지 구분하세요."],"link":"error-code-0x8007232b.html","detailPage":"error-code-0x8007232b.html","narrative":"이 오류는 컴퓨터가 인터넷에 연결돼 있는지와는 별개 문제입니다. 웹 브라우징은 멀쩡히 되는데 이 오류만 나는 경우가 흔한데, 활성화·업데이트 서버의 특정 주소만 DNS가 찾지 못하고 있기 때문입니다. 일반적인 웹사이트 접속과 특정 Microsoft 서버 이름 확인이 서로 다른 경로를 탈 수 있어서, '인터넷은 되는데 왜 이것만 안 되지'라는 상황이 자연스럽게 생깁니다. 사용 중인 DNS를 공용 DNS(1.1.1.1, 8.8.8.8 등)로 바꿔보는 것만으로 해결되는 경우가 많은 이유이기도 합니다.","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x8007232B)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"수동으로 업데이트를 받아 설치해도 되나요?","a":"Microsoft Update 카탈로그에서 해당 KB 번호를 직접 받아 설치하면 자동 업데이트 오류를 우회할 수 있는 경우가 있습니다."}],"decisionSteps":[{"condition":"DNS 캐시 초기화만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"공용 DNS로 바꿔 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"공유기 재시작으로도 해결되지 않을 때","action":"VPN이나 보안 프로그램의 DNS 후킹 여부를 점검하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["8007232b","0x8007232b"],"communityCases":[{"title":"DNS 서버 변경으로 활성화 오류 해결","summary":"윈도우 정품 인증 시 이 오류가 나타났던 사례에서, DNS 서버를 ISP 기본값에서 구글(8.8.8.8)로 변경하자 활성화 서버에 연결되어 인증이 완료됐습니다.","insight":"이 오류는 DNS 문제입니다. 업데이트나 활성화에서 이 오류가 나온다면 DNS 서버를 공용 DNS(8.8.8.8, 1.1.1.1)로 바꿔보는 것이 가장 빠른 확인 방법입니다."}],"officialSource":{"title":"Microsoft Learn: Activation error 0x8007232B — DNS name does not exist","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/licensing-and-activation/activation-error-0x8007232b-dns-name-does-not-exist"}},{"code":"0x800f0821","title":"업데이트 패키지 설치 실패","overview":"다운로드까지는 완료됐지만 실제 설치 단계에서 패키지 적용에 실패했을 때 나타나는 코드입니다. 시스템 파일 손상이나 다른 프로세스의 리소스 점유가 흔한 원인입니다.","summary":"다운로드까지는 완료됐지만 실제 설치 단계에서 패키지 적용에 실패했을 때 나타나는 코드입니다.","causes":["설치 대상 시스템 파일이 다른 프로세스에 의해 사용 중인 경우","구성 요소 저장소나 레지스트리 일부가 손상된 경우","업데이트 패키지 자체가 다운로드 중 손상된 경우","디스크 여유 공간 부족","이전 실패한 설치의 잔여 상태가 남아있는 경우"],"checks":["PC를 재부팅한 뒤 업데이트를 다시 시도해 리소스 점유 상태를 초기화하세요.","SoftwareDistribution 폴더를 초기화(이름 변경)한 뒤 재시도하세요.","DISM /Online /Cleanup-Image /RestoreHealth로 구성 요소 저장소를 점검하세요.","디스크 여유 공간을 최소 10GB 이상 확보하세요.","반복 실패 시 업데이트 어시스턴트로 수동 설치를 시도해 보세요."],"link":"error-code-0x800f0821.html","detailPage":"error-code-0x800f0821.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x800f0821)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트를 미루면 보안에 문제가 되나요?","a":"보안 업데이트가 누락되면 취약점 노출 위험이 커지므로, 오류를 바로 해결하지 못했다면 최소한 원인 진단이라도 진행하는 것이 좋습니다."}],"decisionSteps":[{"condition":"SoftwareDistribution 폴더 초기화로 해결될 때","action":"재발 방지를 위해 정기적으로 디스크 정리를 실행하세요."},{"condition":"DISM 복구로 해결될 때","action":"시스템 파일이 손상되고 있었을 가능성이 있으니 디스크 상태도 함께 점검하세요."},{"condition":"업데이트 어시스턴트로도 실패할 때","action":"클린 설치나 복구 설치를 고려하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["800f0821","0x800f0821"],"communityCases":[{"title":"업데이트 어시스턴트로 수동 설치 성공","summary":"특정 기능 업데이트가 이 오류로 계속 실패하던 사례가 있습니다. 윈도우 업데이트 페이지의 자동 설치로는 반복 실패했지만, 마이크로소프트 공식 업데이트 어시스턴트를 사용해 수동으로 설치하자 성공했습니다.","insight":"자동 업데이트로 실패가 반복되면 업데이트 어시스턴트나 미디어 생성 도구를 이용한 수동 설치를 시도해보세요."}],"officialSource":{"title":"Microsoft Learn: Fix Windows Update errors","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/fix-windows-update-errors"}},{"code":"0x8024a105","title":"업데이트 다운로드 실패","overview":"업데이트 파일을 서버에서 내려받는 도중 연결이 끊기거나 검증에 실패했을 때 나타나는 코드입니다. 네트워크 불안정과 캐시 손상이 주요 원인입니다.","summary":"업데이트 파일을 서버에서 내려받는 도중 연결이 끊기거나 검증에 실패했을 때 나타나는 코드입니다.","causes":["다운로드 도중 네트워크 연결이 불안정해진 경우","이전에 받아둔 캐시 파일이 손상되어 검증에 실패하는 경우","디스크 여유 공간 부족으로 다운로드가 중단되는 경우","보안 소프트웨어가 다운로드 파일을 검역소로 이동시키는 경우","절전 모드로 전환되어 다운로드가 중단되는 경우"],"checks":["네트워크 연결 상태(유선/무선)를 확인하고 가능하면 유선으로 다시 시도하세요.","SoftwareDistribution 폴더를 초기화해 캐시를 다시 받도록 하세요.","디스크 여유 공간을 확인하고 부족하면 정리하세요.","보안 프로그램의 최근 검역 항목에 업데이트 관련 파일이 있는지 확인하세요.","업데이트가 진행되는 동안 절전 모드로 전환되지 않도록 전원 설정을 조정하세요."],"link":"error-code-0x8024a105.html","detailPage":"error-code-0x8024a105.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x8024a105)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트 오류 코드마다 해결법이 다른가요?","a":"공통 원인(구성 요소 정리, 디스크 공간)이 많지만 코드별로 원인이 갈리는 경우도 있어, 코드 자체를 함께 검색해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"유선 연결로 전환한 뒤 해결될 때","action":"Wi-Fi 신호 불안정이 원인이었으므로 무선 환경 개선을 검토하세요."},{"condition":"SoftwareDistribution 폴더 초기화로 해결될 때","action":"재발 방지를 위해 정기적으로 디스크 정리를 실행하세요."},{"condition":"전원 설정 조정 후에도 반복될 때","action":"보안 프로그램의 실시간 검사 예외 목록을 확인하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["8024a105","0x8024a105"],"communityCases":[{"title":"유선 연결로 전환 후 다운로드 성공","summary":"무선 환경에서 대형 업데이트 다운로드가 이 오류로 반복 실패하던 사례가 있습니다. 유선 이더넷으로 전환하자 다운로드가 안정적으로 완료됐습니다. 무선 신호가 약해 다운로드 중 연결이 끊기는 것이 원인이었습니다.","insight":"대용량 업데이트 다운로드는 안정적인 연결이 필요합니다. 무선 환경에서 반복 실패한다면 유선으로 전환하는 것이 가장 효과적인 해결책입니다."}],"officialSource":{"title":"Microsoft Learn: Troubleshoot Windows Update download errors","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/troubleshoot-windows-update-download-errors"}},{"code":"0x80070020","title":"파일이 다른 프로세스에서 사용 중","overview":"업데이트나 설치가 필요로 하는 파일을 다른 프로그램이나 프로세스가 이미 점유하고 있어 접근이 거부될 때 나타나는 오류입니다.","summary":"업데이트나 설치가 필요로 하는 파일을 다른 프로그램이나 프로세스가 이미 점유하고 있어 접근이 거부될 때 나타나는 오류입니다.","causes":["백신 프로그램이 실시간 검사 중 해당 파일을 잠근 경우","이전에 실행된 설치 프로세스가 완전히 종료되지 않은 경우","다른 사용자 세션이나 백그라운드 서비스가 같은 파일을 사용 중인 경우","클라우드 동기화 프로그램(원드라이브 등)이 파일을 동기화 중인 경우","이전 업데이트 재부팅이 완료되지 않은 상태에서 새로 시도한 경우"],"checks":["PC를 완전히 재부팅한 뒤 다시 시도하세요 (백그라운드 프로세스 정리 효과).","작업 관리자에서 백신, 클라우드 동기화 프로그램을 잠시 종료하고 재시도하세요.","다른 사용자 계정이 로그인되어 있다면 로그아웃한 뒤 진행하세요.","안전 모드에서 설치나 업데이트를 다시 시도해 다른 프로세스 간섭을 배제해 보세요.","반복되면 어떤 프로세스가 파일을 점유하는지 리소스 모니터로 확인해 보세요."],"link":"error-code-0x80070020.html","detailPage":"error-code-0x80070020.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80070020)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"수동으로 업데이트를 받아 설치해도 되나요?","a":"Microsoft Update 카탈로그에서 해당 KB 번호를 직접 받아 설치하면 자동 업데이트 오류를 우회할 수 있는 경우가 있습니다."}],"decisionSteps":[{"condition":"재부팅으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"백신·클라우드 동기화 예외 처리로 해결될 때","action":"그 예외 설정을 유지하세요."},{"condition":"안전 모드에서 해결될 때","action":"어떤 백그라운드 프로그램이 간섭했는지 리소스 모니터로 특정하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80070020","0x80070020"],"communityCases":[{"title":"백신 실시간 보호 일시 해제로 업데이트 성공","summary":"업데이트가 이 오류로 계속 실패하던 사례에서 백신 프로그램의 실시간 보호를 일시적으로 꺼보니 업데이트가 성공했습니다. 업데이트 파일을 백신이 실시간으로 검사하면서 파일을 잠그는 것이 원인이었습니다.","insight":"이 오류가 백신이 실행 중일 때만 발생한다면 백신의 실시간 보호를 잠시 끄고 시도해보세요. 업데이트 완료 후에는 반드시 다시 활성화하세요."}],"officialSource":{"title":"Microsoft Learn: Windows Update error code list — InstallFileLocked","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x8007000e","title":"메모리 또는 시스템 리소스 부족","overview":"업데이트나 프로그램 실행에 필요한 메모리 또는 시스템 리소스가 부족할 때 나타나는 오류로, 실제 램 부족뿐 아니라 가상 메모리 설정 문제로도 발생할 수 있습니다.","summary":"업데이트나 프로그램 실행에 필요한 메모리 또는 시스템 리소스가 부족할 때 나타나는 오류로, 실제 램 부족뿐 아니라 가상 메모리 설정 문제로도 발생할 수 있습니다.","causes":["실행 중인 프로그램이 많아 실제 사용 가능한 메모리가 부족한 경우","가상 메모리(페이지 파일) 크기가 너무 작게 설정된 경우","디스크 여유 공간 부족으로 페이지 파일을 확장하지 못하는 경우","메모리 누수가 있는 백그라운드 프로세스가 실행 중인 경우","32비트 프로그램이 메모리 주소 공간 한계에 도달한 경우"],"checks":["작업 관리자에서 불필요한 프로그램을 종료한 뒤 다시 시도하세요.","설정에서 가상 메모리(페이지 파일) 크기가 시스템 관리 크기로 되어 있는지 확인하세요.","디스크 여유 공간을 확보해 페이지 파일이 확장될 수 있도록 하세요.","재부팅 후 다른 프로그램 없이 바로 업데이트나 작업을 시도해 보세요.","메모리 진단 도구로 램 자체에 문제가 없는지 확인하세요."],"link":"error-code-0x8007000e.html","detailPage":"error-code-0x8007000e.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x8007000e)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트를 미루면 보안에 문제가 되나요?","a":"보안 업데이트가 누락되면 취약점 노출 위험이 커지므로, 오류를 바로 해결하지 못했다면 최소한 원인 진단이라도 진행하는 것이 좋습니다."}],"decisionSteps":[{"condition":"불필요한 프로그램 종료 후 해결될 때","action":"재발 방지를 위해 시작 프로그램을 정리하세요."},{"condition":"페이지 파일 설정 변경 후 해결될 때","action":"시스템 관리 크기(자동)로 유지하세요."},{"condition":"디스크 공간 확보 후에도 반복될 때","action":"메모리 진단으로 램 자체 결함 여부를 확인하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["8007000e","0x8007000e"],"communityCases":[{"title":"백그라운드 프로그램 종료 후 업데이트 성공","summary":"메모리 사용량이 높은 상태에서 업데이트를 시도할 때 이 오류가 발생했던 사례가 있습니다. 작업 관리자에서 불필요한 프로그램을 모두 종료하고 재부팅 후 곧바로 업데이트를 시도하자 성공했습니다.","insight":"이 오류는 메모리 부족이 원인입니다. 업데이트 전 다른 프로그램을 최대한 종료하고 최소한의 상태에서 시도하는 것이 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_OUTOFMEMORY","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x800705b4","title":"작업 시간 초과","overview":"업데이트나 특정 작업이 정해진 시간 안에 완료되지 못하고 시간 초과로 중단됐을 때 나타나는 오류입니다. 느린 네트워크나 시스템 응답 지연이 주요 원인입니다.","summary":"업데이트나 특정 작업이 정해진 시간 안에 완료되지 못하고 시간 초과로 중단됐을 때 나타나는 오류입니다.","causes":["네트워크 속도가 느리거나 불안정해 다운로드가 지연되는 경우","디스크 응답 속도가 느려 파일 처리가 지연되는 경우","백그라운드에서 다른 무거운 작업이 동시에 실행되고 있는 경우","서버 측 응답이 느린 시간대에 접속한 경우","보안 소프트웨어의 검사로 인해 처리 속도가 느려진 경우"],"checks":["네트워크 상태를 확인하고 가능하면 더 안정적인 연결(유선 등)로 다시 시도하세요.","다른 무거운 프로그램을 종료한 뒤 작업을 다시 시도하세요.","디스크 상태(특히 HDD의 경우 조각모음, SSD의 경우 여유 공간)를 점검하세요.","시간대를 바꿔(예: 트래픽이 적은 새벽 시간) 다시 시도해 보세요.","보안 프로그램의 실시간 검사를 일시적으로 낮춘 뒤 재시도해 보세요."],"link":"error-code-0x800705b4.html","detailPage":"error-code-0x800705b4.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x800705b4)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트 오류 코드마다 해결법이 다른가요?","a":"공통 원인(구성 요소 정리, 디스크 공간)이 많지만 코드별로 원인이 갈리는 경우도 있어, 코드 자체를 함께 검색해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"유선 연결로 전환한 뒤 해결될 때","action":"Wi-Fi 신호 불안정이 원인이었으므로 무선 환경 개선을 검토하세요."},{"condition":"다른 프로그램 종료 후 해결될 때","action":"재발 방지를 위해 백그라운드 프로그램을 정리하세요."},{"condition":"시간대를 바꿔도 반복될 때","action":"서버 측 문제일 가능성이 크므로 며칠 후 다시 시도하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["800705b4","0x800705b4"],"communityCases":[{"title":"새벽 시간대 재시도로 업데이트 성공","summary":"업데이트가 계속 시간 초과 오류로 실패하던 사례에서, 서버 트래픽이 적은 새벽 시간에 다시 시도하자 정상적으로 완료됐습니다. 피크 타임에 서버 응답이 느려지는 것이 원인이었습니다.","insight":"시간 초과 오류가 반복된다면 네트워크와 PC 상태가 동일해도 시간대에 따라 결과가 달라질 수 있습니다. 트래픽이 적은 새벽 시간에 재시도해보세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (1300-1699) — ERROR_TIMEOUT","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1300-1699-"}},{"code":"0x80070003","title":"지정된 경로를 찾을 수 없음","overview":"설치나 업데이트, 파일 접근 시 시스템이 지정된 경로 자체를 찾지 못했을 때 나타나는 오류로, 경로 손상이나 이동된 폴더가 주요 원인입니다.","summary":"설치나 업데이트, 파일 접근 시 시스템이 지정된 경로 자체를 찾지 못했을 때 나타나는 오류로, 경로 손상이나 이동된 폴더가 주요 원인입니다.","causes":["설치 대상 폴더가 삭제되었거나 다른 위치로 이동된 경우","레지스트리에 등록된 경로 정보가 최신 상태와 맞지 않는 경우","네트워크 드라이브 연결이 끊겨 경로에 접근할 수 없는 경우","경로 이름에 시스템이 처리하지 못하는 특수 문자가 포함된 경우","이전 업데이트나 설치 과정에서 폴더 구조가 일부 손상된 경우"],"checks":["오류 메시지에 표시된 경로가 실제로 존재하는지 탐색기에서 확인하세요.","네트워크 드라이브라면 연결이 살아있는지 확인하고 다시 매핑해 보세요.","SoftwareDistribution 캐시를 초기화한 뒤 업데이트를 다시 시도하세요.","sfc /scannow로 시스템 파일과 경로 관련 손상을 점검하세요.","가능하다면 문제 프로그램을 제거 후 재설치해 경로 정보를 새로 등록하세요."],"link":"error-code-0x80070003.html","detailPage":"error-code-0x80070003.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80070003)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"수동으로 업데이트를 받아 설치해도 되나요?","a":"Microsoft Update 카탈로그에서 해당 KB 번호를 직접 받아 설치하면 자동 업데이트 오류를 우회할 수 있는 경우가 있습니다."}],"decisionSteps":[{"condition":"SoftwareDistribution 초기화로 해결될 때","action":"재발 방지를 위해 정기적으로 디스크 정리를 실행하세요."},{"condition":"프로그램 재설치로 해결될 때","action":"경로 정보가 새로 등록되었으므로 재발 여부만 확인하세요."},{"condition":"sfc /scannow로도 해결되지 않을 때","action":"Microsoft Update 카탈로그에서 해당 KB 파일을 수동으로 받아 설치하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80070003","0x80070003"],"communityCases":[{"title":"SoftwareDistribution 초기화로 경로 오류 해결","summary":"업데이트 경로를 찾지 못한다는 이 오류가 발생했던 사례에서, SoftwareDistribution 폴더를 초기화하자 업데이트 경로가 새로 구성되어 정상 작동했습니다.","insight":"이 오류는 업데이트 관련 경로 정보가 손상됐을 때 자주 발생합니다. SoftwareDistribution 초기화가 가장 효과적인 첫 번째 시도 방법입니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_PATH_NOT_FOUND","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x800704CF","title":"이 네트워크에 연결되어 있지 않습니다","overview":"네트워크 어댑터가 활성화되어 있지 않거나 물리적으로 연결이 끊긴 상태에서 인터넷 관련 작업을 시도했을 때 나타나는 오류입니다. 케이블이 꽂혀 있어도 어댑터가 비활성화되어 있으면 같은 메시지가 나타날 수 있습니다.","summary":"네트워크 어댑터가 활성화되어 있지 않거나 물리적으로 연결이 끊긴 상태에서 인터넷 관련 작업을 시도했을 때 나타나는 오류입니다.","causes":["이더넷 케이블이 느슨하게 꽂혀 있거나 손상된 경우","네트워크 어댑터가 장치 관리자에서 비활성화되어 있는 경우","무선 어댑터의 비행기 모드가 켜져 있는 경우","네트워크 드라이버가 손상되었거나 최근 업데이트로 문제가 생긴 경우","공유기나 스위치 포트 자체의 고장"],"checks":["작업 표시줄의 네트워크 아이콘에서 비행기 모드가 꺼져 있는지 확인하세요.","장치 관리자에서 네트워크 어댑터가 활성화 상태인지 확인하고, 비활성화되어 있다면 사용으로 전환하세요.","이더넷 케이블이라면 다른 케이블이나 다른 포트로 교체해 재현 여부를 확인하세요.","네트워크 드라이버를 제조사 최신 버전으로 재설치해 보세요.","다른 기기를 같은 케이블/포트에 연결해 공유기나 스위치 쪽 문제인지 구분하세요."],"link":"error-code-0x800704cf.html","detailPage":"error-code-0x800704cf.html","faq":[{"q":"공유기를 바꾸면 해결되나요?","a":"이 문제(0x800704CF)는 공유기 자체 문제보다 어댑터 드라이버나 전원 관리 설정이 원인인 경우가 많아, 장비 교체 전에 드라이버 업데이트와 절전 설정부터 확인해보세요."},{"q":"공유기를 바꾸면 확실히 해결되나요?","a":"공유기 노후화가 원인이라면 도움이 되지만, PC의 무선랜 드라이버나 절전 설정이 원인이라면 공유기를 바꿔도 재발할 수 있습니다."}],"decisionSteps":[{"condition":"비행기 모드 해제로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"케이블·포트 교체로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"다른 기기도 안 될 때","action":"공유기·스위치 포트 고장 가능성이 크므로 다른 포트로 교체해보세요."}],"relatedSymptom":"hardware-wifi-disconnect.html","aliases":["800704cf","0x800704cf"],"communityCases":[{"title":"드라이버 재설치로 네트워크 미연결 오류 해결","summary":"네트워크 연결 표시는 정상이었는데 업데이트나 스토어 접근 시 이 오류가 발생했던 사례가 있습니다. 네트워크 어댑터 드라이버를 제거하고 재설치하자 정상적으로 인터넷에 연결됐습니다.","insight":"연결 표시가 정상이어도 드라이버 문제로 실제 패킷이 전달되지 않는 경우가 있습니다. netsh winsock reset 명령과 드라이버 재설치를 함께 시도해보세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (1000-1299) — network error range","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1000-1299-"}},{"code":"0x80070035","title":"네트워크 경로를 찾을 수 없음","overview":"공유 폴더나 네트워크 드라이브에 접근하려 할 때 지정한 경로 자체를 찾지 못해 나타나는 오류입니다. 파일 탐색기에서 \\\\컴퓨터명\\공유폴더 형태로 접근할 때 자주 발생합니다.","summary":"공유 폴더나 네트워크 드라이브에 접근하려 할 때 지정한 경로 자체를 찾지 못해 나타나는 오류입니다.","causes":["대상 컴퓨터의 전원이 꺼져 있거나 같은 네트워크에 있지 않은 경우","공유 폴더 설정 자체가 비활성화되어 있거나 삭제된 경우","네트워크 검색이나 파일 공유 기능이 꺼져 있는 경우","방화벽이 파일 공유 관련 포트를 차단하는 경우","컴퓨터 이름이나 IP 주소가 변경되어 기존 경로가 유효하지 않은 경우"],"checks":["대상 컴퓨터가 켜져 있고 같은 네트워크(같은 공유기)에 연결되어 있는지 확인하세요.","설정 > 네트워크 및 인터넷 > 공유 옵션에서 네트워크 검색과 파일 공유가 켜져 있는지 확인하세요.","컴퓨터 이름 대신 IP 주소로 직접 접근을 시도해 경로 문제인지 이름 확인 문제인지 구분하세요.","방화벽에서 파일 및 프린터 공유 규칙이 허용되어 있는지 확인하세요.","대상 폴더의 공유 설정을 다시 확인하고 필요하면 공유를 재설정하세요."],"link":"error-code-0x80070035.html","detailPage":"error-code-0x80070035.html","faq":[{"q":"탐색기가 멈추면 바로 재설치해야 하나요?","a":"이 문제(0x80070035)는 재설치보다 셸 재시작과 원인이 되는 폴더·드라이브 분리로 대부분 해결됩니다. 재설치는 이 단계 이후에도 반복될 때 고려하세요."}],"decisionSteps":[{"condition":"IP로는 접속되는데 컴퓨터 이름으로는 안 될 때","action":"이름 확인 문제이므로 두 PC가 같은 워크그룹인지 확인하거나, hosts 파일에 컴퓨터 이름과 IP를 직접 매핑해보세요."},{"condition":"IP로도 접속이 안 될 때","action":"네트워크 검색·파일 공유가 꺼져 있거나 방화벽이 차단하고 있을 가능성이 크므로 2번과 4번 항목을 다시 확인하세요."},{"condition":"공유를 재설정해도 반복될 때","action":"관리자 권한 명령 프롬프트에서 <code>net use * /delete</code>로 기존 연결 정보를 모두 삭제한 뒤 다시 접근을 시도하세요."}],"relatedSymptom":"windows-explorer-freeze.html","aliases":["80070035","0x80070035"],"communityCases":[{"title":"네트워크 검색 활성화로 공유 폴더 접근 해결","summary":"같은 공유기에 연결된 PC의 공유 폴더에 접근할 때 이 오류가 발생했던 사례가 있습니다. 설정에서 개인 네트워크 프로파일을 확인하니 네트워크 검색이 꺼져 있었고, 활성화하자 공유 폴더에 정상 접근됐습니다.","insight":"이 오류가 네트워크 공유 폴더 접근에서 발생한다면 네트워크 검색과 파일 공유 기능이 켜져 있는지, 네트워크 프로파일이 개인으로 설정되어 있는지 먼저 확인하세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_BAD_NETPATH","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x80070718","title":"IP 주소를 가져올 수 없음","overview":"DHCP 서버로부터 IP 주소를 할당받지 못했을 때 나타나는 오류로, 공유기의 DHCP 기능 문제나 네트워크 혼잡이 흔한 원인입니다.","summary":"DHCP 서버로부터 IP 주소를 할당받지 못했을 때 나타나는 오류로, 공유기의 DHCP 기능 문제나 네트워크 혼잡이 흔한 원인입니다.","causes":["공유기의 DHCP 서버 기능이 꺼져 있거나 오류가 발생한 경우","네트워크에 연결된 기기가 많아 할당 가능한 IP 주소가 소진된 경우","네트워크 어댑터의 IP 설정이 잘못 구성된 경우","이전에 할당받은 IP 주소가 충돌을 일으키는 경우","네트워크 드라이버 문제로 DHCP 요청 자체가 실패하는 경우"],"checks":["공유기를 재시작해 DHCP 서버 기능을 초기화하세요.","명령 프롬프트(관리자)에서 ipconfig /release 후 ipconfig /renew를 실행해 IP를 다시 요청하세요.","네트워크 어댑터 속성에서 IP 주소를 자동으로 받도록 설정되어 있는지 확인하세요.","공유기 관리 화면에서 DHCP 주소 범위와 현재 연결된 기기 수를 확인하세요.","네트워크 드라이버를 최신 버전으로 업데이트한 뒤 다시 시도하세요."],"link":"error-code-0x80070718.html","detailPage":"error-code-0x80070718.html","faq":[{"q":"공유기를 바꾸면 해결되나요?","a":"이 문제(0x80070718)는 공유기 자체 문제보다 어댑터 드라이버나 전원 관리 설정이 원인인 경우가 많아, 장비 교체 전에 드라이버 업데이트와 절전 설정부터 확인해보세요."},{"q":"5GHz와 2.4GHz 중 뭐가 더 안정적인가요?","a":"5GHz는 속도가 빠르지만 벽 등 장애물에 약해 거리가 멀면 오히려 끊김이 잦을 수 있어, 상황에 따라 2.4GHz가 더 안정적일 수 있습니다."}],"decisionSteps":[{"condition":"공유기 재시작으로 해결될 때","action":"재발 방지를 위해 정기적으로 공유기를 재부팅하세요."},{"condition":"ipconfig 갱신으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"DHCP 범위 확인으로도 해결되지 않을 때","action":"네트워크 드라이버 업데이트로 넘어가세요."}],"relatedSymptom":"hardware-wifi-disconnect.html","aliases":["80070718","0x80070718"],"communityCases":[{"title":"공유기 재시작으로 IP 할당 오류 해결","summary":"갑자기 인터넷 연결이 안 되고 이 오류가 나타났던 사례에서, 공유기를 재시작하자 IP가 새로 할당되어 정상 연결됐습니다. 공유기의 DHCP 임시 테이블이 가득 찬 것이 원인이었습니다.","insight":"IP 할당 오류는 대부분 공유기 DHCP 문제입니다. PC를 재시작하기 전에 공유기를 먼저 재시작해보세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (1700-3999) — network/quota error range","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1700-3999-"}},{"code":"0x80072EFD","title":"서버에 연결할 수 없음","overview":"앱이나 서비스가 원격 서버에 접속을 시도했지만 연결 자체가 이루어지지 않을 때 나타나는 오류입니다. 스토어 앱, 계정 로그인, 업데이트 확인 등 다양한 상황에서 공통으로 나타납니다.","summary":"앱이나 서비스가 원격 서버에 접속을 시도했지만 연결 자체가 이루어지지 않을 때 나타나는 오류입니다.","causes":["인터넷 연결이 완전히 끊겼거나 매우 불안정한 경우","방화벽이나 보안 소프트웨어가 해당 앱의 인터넷 접근을 차단하는 경우","프록시나 VPN 설정이 잘못되어 연결이 가로막히는 경우","시스템 날짜/시간이 틀려 보안 인증서 검증에 실패하는 경우","일시적인 서버 측 장애"],"checks":["다른 웹사이트나 앱이 정상적으로 인터넷에 연결되는지 먼저 확인하세요.","방화벽/보안 프로그램에서 해당 앱이 인터넷 접근을 차단당하고 있지 않은지 확인하세요.","VPN이나 프록시를 사용 중이라면 잠시 해제하고 다시 시도하세요.","설정에서 날짜, 시간, 시간대가 정확한지 확인하세요.","시간을 두고 다시 시도해 일시적인 서버 문제였는지 확인하세요."],"link":"error-code-0x80072efd.html","detailPage":"error-code-0x80072efd.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x80072EFD)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트를 미루면 보안에 문제가 되나요?","a":"보안 업데이트가 누락되면 취약점 노출 위험이 커지므로, 오류를 바로 해결하지 못했다면 최소한 원인 진단이라도 진행하는 것이 좋습니다."}],"decisionSteps":[{"condition":"날짜·시간 수정 후 해결될 때","action":"시간 자동 동기화(w32tm) 설정도 함께 확인해 다시 어긋나지 않도록 하세요."},{"condition":"VPN·프록시 해제 후 해결될 때","action":"계속 사용해야 한다면 해당 앱에 대한 VPN 예외 규칙을 설정하세요."},{"condition":"모든 조치 후에도 반복될 때","action":"서버 측 일시 장애일 가능성이 크므로 시간을 두고 다시 시도하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80072efd","0x80072efd"],"communityCases":[{"title":"날짜/시간 동기화로 스토어 연결 오류 해결","summary":"마이크로소프트 스토어에서 앱 다운로드 시 이 오류가 발생했던 사례가 있습니다. 다른 웹사이트는 정상이었는데, 시스템 시간이 30분 정도 틀려 인증서 검증에 실패하는 것이 원인이었습니다. 시간을 동기화하자 바로 해결됐습니다.","insight":"스토어나 업데이트 연결 오류가 발생할 때 시스템 날짜와 시간이 정확한지도 확인해보세요. 시간이 크게 틀리면 보안 인증서 검증에 실패해 이 오류가 발생합니다."}],"officialSource":{"title":"Microsoft Learn: Troubleshoot Windows Update download errors","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/troubleshoot-windows-update-download-errors"}},{"code":"0x80072F8F","title":"보안 연결 실패·시스템 시간 오류","overview":"Windows Update, Microsoft Store 또는 설치 과정에서 서버와 보안 연결을 맺지 못할 때 나타나는 오류입니다. 시스템 날짜·시간이 크게 어긋났거나 시간대가 잘못됐을 때 SSL/TLS 인증서 검증이 실패하는 경우가 흔하지만, 신뢰되지 않는 인증서 체인이나 프록시·WSUS 환경의 보안 설정도 원인이 될 수 있습니다.","summary":"Windows Update나 Microsoft Store가 보안 연결을 만들지 못할 때 나타나며, 날짜·시간과 인증서 신뢰 상태를 먼저 확인해야 합니다.","causes":["PC의 날짜·시간 또는 시간대가 실제 시간과 크게 다른 경우","인터넷 시간 동기화가 실패했거나 Windows Time 서비스가 중지된 경우","관리되는 PC의 WSUS·프록시가 자체 인증서를 사용하지만 클라이언트가 인증서 체인을 신뢰하지 못하는 경우","오래된 Windows에서 루트 인증서·TLS 구성 요소가 갱신되지 않은 경우","보안 프로그램이나 프록시가 Windows Update·Microsoft Store의 HTTPS 연결을 가로채는 경우"],"checks":["설정 > 시간 및 언어 > 날짜 및 시간에서 시간 자동 설정과 시간대 자동 설정을 확인한 뒤 지금 동기화를 실행하세요.","관리자 명령 프롬프트에서 w32tm /query /status로 시간 동기화 상태를 확인하고, 필요한 경우 w32tm /resync를 실행하세요.","다른 HTTPS 웹사이트가 정상적으로 열리는지 확인하고, VPN·프록시를 사용 중이면 잠시 해제한 뒤 같은 작업을 다시 시도하세요.","회사·학교 PC라면 WSUS 또는 보안 프록시의 인증서가 신뢰할 수 있는 루트 인증 기관에 설치되어 있는지 관리자에게 확인하세요. 인증서를 임의로 설치하거나 삭제하지 마세요.","Windows Update 로그에서 80072F8F가 반복되는 시각과 WinHTTP·인증서 관련 메시지를 함께 확인한 뒤 Windows와 보안 구성 요소를 최신 상태로 유지하세요."],"link":"error-code-0x80072f8f.html","detailPage":"error-code-0x80072f8f.html","faq":[{"q":"인터넷은 되는데 왜 이 오류가 나오나요?","a":"일반 웹사이트 접속과 Windows Update의 인증서 검증은 별개입니다. PC의 날짜·시간이 틀렸거나 프록시·WSUS 인증서를 신뢰하지 못하면 인터넷이 연결되어도 보안 연결이 실패할 수 있습니다."},{"q":"시간을 맞췄는데도 계속 실패하면 어떻게 하나요?","a":"VPN·프록시를 해제하고 다른 네트워크에서 재현되는지 비교하세요. 회사·학교 PC라면 WSUS 또는 보안 프록시의 인증서 체인을 관리자가 확인해야 하며 인증서를 임의로 설치하거나 삭제하면 안 됩니다."}],"decisionSteps":[{"condition":"시간 동기화만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"VPN·프록시 해제로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"관리형 PC에서도 해결되지 않을 때","action":"WSUS 인증서 정책을 관리자와 함께 재확인하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["80072f8f","0x80072f8f","80072F8F","0x80072F8F"],"communityCases":[{"title":"시간대가 잘못 설정된 PC에서 업데이트 실패","summary":"다른 웹사이트는 열렸지만 Windows Update만 0x80072F8F로 실패했습니다. 확인 결과 시간대가 실제 지역과 다르게 설정되어 있었고 자동 시간 동기화 후 업데이트가 진행됐습니다.","insight":"인터넷이 연결되어 있어도 HTTPS 인증서 검증에는 정확한 시스템 시간이 필요합니다. 네트워크 초기화보다 날짜·시간과 시간대 확인을 먼저 진행하는 편이 안전합니다."}],"officialSource":{"title":"Microsoft Learn: Troubleshoot Windows Update error 0x80072f8f","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/installing-updates-features-roles/troubleshoot-windows-update-error-0x80072f8f"}},{"code":"0x80070490","title":"요소를 찾을 수 없음 (네트워크 어댑터)","overview":"네트워크 설정을 변경하거나 어댑터 정보를 읽으려 할 때 시스템이 참조하려는 구성 요소를 찾지 못해 나타나는 오류입니다. 네트워크 어댑터 드라이버나 프로토콜 스택 손상과 관련이 깊습니다.","summary":"네트워크 설정을 변경하거나 어댑터 정보를 읽으려 할 때 시스템이 참조하려는 구성 요소를 찾지 못해 나타나는 오류입니다.","causes":["네트워크 어댑터 드라이버가 일부 손상된 경우","TCP/IP 프로토콜 스택 구성이 손상된 경우","최근 네트워크 관련 업데이트 이후 설정 값이 꼬인 경우","네트워크 어댑터를 물리적으로 제거했다가 다시 연결한 뒤 잔여 구성이 남은 경우","타사 VPN 클라이언트가 설치한 가상 어댑터와의 충돌"],"checks":["명령 프롬프트(관리자)에서 netsh winsock reset 명령으로 네트워크 스택을 초기화하세요.","이어서 netsh int ip reset 명령으로 TCP/IP 설정을 초기화한 뒤 재부팅하세요.","장치 관리자에서 네트워크 어댑터를 제거한 뒤 재부팅해 자동으로 재설치되게 하세요.","최근 설치한 VPN 클라이언트가 있다면 제거 후 재현 여부를 확인하세요.","네트워크 어댑터 드라이버를 제조사 최신 버전으로 재설치하세요."],"link":"error-code-0x80070490.html","detailPage":"error-code-0x80070490.html","faq":[{"q":"공유기를 바꾸면 해결되나요?","a":"이 문제(0x80070490)는 공유기 자체 문제보다 어댑터 드라이버나 전원 관리 설정이 원인인 경우가 많아, 장비 교체 전에 드라이버 업데이트와 절전 설정부터 확인해보세요."},{"q":"무선랜 어댑터의 절전 설정을 꺼야 하나요?","a":"네, 전원 관리에서 무선랜 어댑터의 절전 기능을 꺼두면 백그라운드에서 연결이 끊기는 현상을 줄일 수 있습니다."}],"decisionSteps":[{"condition":"winsock·TCP/IP 초기화로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"어댑터 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"VPN 제거로도 해결되지 않을 때","action":"드라이버 재설치로 넘어가세요."}],"relatedSymptom":"hardware-wifi-disconnect.html","aliases":["80070490","0x80070490"],"communityCases":[{"title":"네트워크 스택 초기화로 어댑터 오류 해결","summary":"VPN 클라이언트를 제거한 이후 네트워크 설정이 이상해지면서 이 오류가 발생했던 사례가 있습니다. netsh winsock reset 후 netsh int ip reset을 실행하고 재부팅하자 정상 작동했습니다.","insight":"VPN이나 네트워크 관련 소프트웨어를 제거한 후 이 오류가 발생한다면 가상 네트워크 어댑터나 TCP/IP 스택 잔여 설정이 문제일 수 있습니다. winsock reset이 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (1000-1299) — ERROR_NOT_FOUND","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1000-1299-"}},{"code":"0x8007274C","title":"네트워크 요청 시간 초과","overview":"서버로 보낸 요청이 정해진 시간 안에 응답을 받지 못했을 때 나타나는 오류로, 네트워크 지연이나 서버 응답 지연이 주요 원인입니다.","summary":"서버로 보낸 요청이 정해진 시간 안에 응답을 받지 못했을 때 나타나는 오류로, 네트워크 지연이나 서버 응답 지연이 주요 원인입니다.","causes":["인터넷 속도가 느리거나 순간적으로 끊기는 경우","공유기나 모뎀의 응답이 느린 경우","동시에 여러 기기나 프로그램이 네트워크 대역폭을 과도하게 사용하는 경우","DNS 응답이 느려 요청 자체가 지연되는 경우","서버 측의 일시적인 응답 지연"],"checks":["다른 웹사이트도 느리게 열리는지 확인해 전체 네트워크 문제인지 좁혀보세요.","공유기를 재시작해 응답 속도가 개선되는지 확인하세요.","네트워크를 많이 쓰는 다른 프로그램(다운로드, 스트리밍 등)을 종료한 뒤 재시도하세요.","DNS 서버를 공용 DNS(8.8.8.8 등)로 바꿔 재현 여부를 확인하세요.","시간을 두고 다시 시도해 서버 측 문제였는지 확인하세요."],"link":"error-code-0x8007274c.html","detailPage":"error-code-0x8007274c.html","faq":[{"q":"업데이트를 계속 재시도해도 괜찮은가요?","a":"이 문제(0x8007274C)로 반복 실패한다면 무한정 재시도하기보다 업데이트 구성 요소 정리와 디스크 공간 확인을 먼저 하는 것이 시간을 아낄 수 있습니다."},{"q":"업데이트 오류 코드마다 해결법이 다른가요?","a":"공통 원인(구성 요소 정리, 디스크 공간)이 많지만 코드별로 원인이 갈리는 경우도 있어, 코드 자체를 함께 검색해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"공유기 재시작 후 해결될 때","action":"재발 시 공유기 펌웨어 업데이트도 함께 확인하세요."},{"condition":"DNS 변경 후 개선될 때","action":"그 DNS 설정을 그대로 유지하세요."},{"condition":"모든 조치 후에도 반복될 때","action":"서버 측 문제일 가능성이 크므로 시간을 두고 다시 시도하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["8007274c","0x8007274c"],"communityCases":[{"title":"공유기 재시작으로 네트워크 응답 지연 해결","summary":"인터넷이 느리고 여러 서비스에서 시간 초과 오류가 발생하던 중 이 오류도 나타났던 사례가 있습니다. 공유기를 재시작하자 속도가 회복되고 오류도 사라졌습니다.","insight":"네트워크 응답 시간 초과는 대부분 네트워크 장비 문제입니다. 오류 발생 시 다른 웹사이트도 느린지 확인하고, 공유기 재시작부터 시도하세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (10000-11999) — WSAETIMEDOUT","url":"https://learn.microsoft.com/en-us/windows/win32/winsock/windows-sockets-error-codes-2"}},{"code":"0x80072EE2","title":"서버 작업 시간이 초과되었습니다","overview":"Windows Update, Microsoft Store, 로그인 또는 다운로드 과정에서 서버가 정해진 시간 안에 응답하지 않을 때 나타날 수 있습니다. PC 연결 문제와 서비스 측 지연을 구분해야 합니다.","summary":"서버 응답을 기다리다 시간이 초과된 네트워크 오류입니다.","causes":["Wi-Fi·유선랜 연결이 순간적으로 끊기거나 품질이 낮은 경우","VPN·프록시·방화벽이 서비스 연결을 지연시키는 경우","Microsoft 서비스 또는 공유기·통신사의 일시적인 응답 지연"],"checks":["다른 웹사이트와 다운로드도 느린지 확인해 PC 전체 네트워크 문제인지 구분하세요.","VPN·프록시를 임시로 해제하고 공유기와 PC를 차례로 재시작한 뒤 다시 시도하세요.","특정 시간대에만 반복되면 오류 시각과 서비스 이름을 기록하고 시간을 두고 재시도하세요."],"link":"common-error-codes.html?code=0x80072EE2","detailPage":"common-error-codes.html?code=0x80072EE2","relatedSymptom":"hardware-wifi-disconnect.html","aliases":["80072ee2","0x80072ee2","operation timed out","서버 시간 초과"],"communityCases":[{"title":"프록시 설정 초기화로 업데이트 시간 초과 해결","summary":"인터넷 연결은 정상이었지만 윈도우 업데이트만 계속 이 오류로 실패하던 사례가 있습니다. 명령 프롬프트에서 netsh winhttp reset proxy를 실행해 프록시 설정을 초기화하자 업데이트가 정상 작동했습니다.","insight":"인터넷은 되지만 업데이트만 안 된다면 잘못된 프록시 설정이 원인일 수 있습니다. netsh winhttp reset proxy 명령으로 초기화해보세요."}],"officialSource":{"title":"Microsoft Learn: Windows Update error code list","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x80072EE7","title":"서버 이름 또는 주소를 확인할 수 없습니다","overview":"Windows Update나 Microsoft 서비스가 서버 이름을 IP 주소로 찾지 못했을 때 나타나는 DNS 이름 해석 오류입니다. 인터넷 연결 표시는 정상이어도 DNS·VPN·공유기 설정 때문에 특정 서비스만 연결되지 않을 수 있습니다.","summary":"DNS가 서버 이름을 찾지 못해 연결을 시작하지 못한 네트워크 오류입니다.","causes":["공유기 또는 통신사의 DNS 응답이 일시적으로 실패한 경우","VPN·프록시·보안 프로그램이 DNS 요청을 가로막는 경우","회사·학교 네트워크에서 외부 서비스 접근이 제한된 경우"],"checks":["다른 웹사이트와 Microsoft 서비스의 연결 결과를 비교하세요.","VPN·프록시를 끄고 공유기와 PC를 재시작한 뒤 다시 시도하세요.","회사·학교 네트워크에서는 임의로 DNS를 바꾸기 전에 IT 관리자에게 제한 여부를 확인하세요."],"link":"common-error-codes.html?code=0x80072EE7","detailPage":"common-error-codes.html?code=0x80072EE7","relatedSymptom":"hardware-wifi-disconnect.html","aliases":["80072ee7","0x80072ee7","server name address could not be resolved","DNS 오류","서버 주소 찾기"],"communityCases":[{"title":"hosts 파일 정리로 DNS 오류 해결","summary":"특정 마이크로소프트 서비스만 접속이 안 되던 사례에서, hosts 파일을 확인하니 이전에 광고 차단 목적으로 추가했던 마이크로소프트 도메인 차단 항목이 남아있었습니다. 해당 항목을 제거하자 정상 연결됐습니다.","insight":"이 오류가 특정 마이크로소프트 서비스에서만 발생한다면 hosts 파일에 해당 도메인이 차단되어 있지 않은지 확인해보세요. C:WindowsSystem32driversetchosts 파일을 메모장으로 열어 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Windows Update error code list","url":"https://learn.microsoft.com/en-us/windows/deployment/update/windows-update-error-reference"}},{"code":"0x8007045D","title":"I/O 장치 오류","overview":"파일 복사·설치·백업 중 저장장치와 데이터를 읽거나 쓰는 과정이 실패했을 때 나타납니다. 케이블·USB 포트·외장 저장장치·디스크 상태를 먼저 확인해야 합니다.","summary":"저장장치 입출력 과정에서 읽기 또는 쓰기에 실패한 오류입니다.","causes":["외장 HDD·USB 메모리 케이블 또는 포트 접촉이 불안정한 경우","SSD·HDD의 파일 시스템 또는 물리 상태에 문제가 있는 경우","USB 허브 전원 부족이나 대용량 파일 복사 중 연결이 끊긴 경우"],"checks":["중요한 파일은 복구 명령보다 다른 저장장치로 백업할 수 있는 데이터부터 옮기세요.","허브를 빼고 PC 본체의 다른 USB 포트·케이블에 직접 연결해 보세요.","S.M.A.R.T 건강 상태와 Windows 디스크 검사를 확인하고 반복되면 저장장치 교체를 검토하세요."],"link":"common-error-codes.html?code=0x8007045D","detailPage":"common-error-codes.html?code=0x8007045D","relatedSymptom":"hardware-nvme-delay.html","aliases":["8007045d","0x8007045d","i/o device error","입출력 장치 오류","IO 오류"],"communityCases":[{"title":"USB 포트 변경으로 I/O 오류 해결","summary":"외장하드를 통해 대용량 파일을 복사하던 중 이 오류가 발생했던 사례가 있습니다. USB 허브를 거치지 않고 PC 본체의 USB 3.0 포트에 직접 연결하자 오류 없이 전송이 완료됐습니다.","insight":"I/O 오류는 USB 허브의 전력 부족이나 케이블 불량으로 발생하는 경우가 많습니다. 오류 발생 시 다른 포트나 케이블로 교체해보는 것이 첫 번째 확인 방법입니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_IO_DEVICE","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1000-1299-"}},{"code":"0x800704B3","title":"원격 프로시저 호출(RPC)이 실패했습니다","overview":"네트워크로 연결된 다른 컴퓨터나 서비스와 통신하는 데 필요한 RPC(원격 프로시저 호출)가 실패했을 때 나타나는 오류입니다. 프린터 공유, 원격 관리 작업 등에서 자주 나타납니다.","summary":"네트워크로 연결된 다른 컴퓨터나 서비스와 통신하는 데 필요한 RPC(원격 프로시저 호출)가 실패했을 때 나타나는 오류입니다.","causes":["RPC 관련 윈도우 서비스(RPC, DCOM 서버 프로세스 실행기)가 중지된 경우","방화벽이 RPC 통신에 필요한 포트를 차단하는 경우","대상 컴퓨터와의 네트워크 연결이 불안정한 경우","네트워크 프로필이 공용으로 설정되어 있어 통신이 제한되는 경우","도메인/워크그룹 설정 불일치"],"checks":["서비스 관리자(services.msc)에서 Remote Procedure Call(RPC) 서비스가 실행 중인지 확인하세요.","방화벽 설정에서 원격 관리나 파일/프린터 공유 관련 규칙이 허용되어 있는지 확인하세요.","네트워크 프로필이 '개인'으로 설정되어 있는지 확인하세요 (공용 네트워크는 일부 통신이 제한됩니다).","대상 컴퓨터와의 기본 네트워크 연결(ping)이 정상인지 확인하세요.","두 컴퓨터가 같은 워크그룹이나 도메인에 속해 있는지 확인하세요."],"link":"error-code-0x800704b3.html","detailPage":"error-code-0x800704b3.html","faq":[{"q":"프린터를 재설치하면 바로 해결되나요?","a":"이 문제(0x800704B3)는 드라이버보다 서비스나 권한 문제인 경우가 많아, 재설치 전에 스풀러 서비스 상태부터 확인하는 것이 순서상 더 빠릅니다."},{"q":"네트워크 프린터와 USB 프린터 중 어느 쪽이 더 자주 멈추나요?","a":"네트워크 프린터가 네트워크 상태에 따라 추가 단계에서 더 자주 멈추는 경향이 있어, 유선 연결 상태를 먼저 확인하는 것이 좋습니다."}],"decisionSteps":[{"condition":"RPC 서비스를 시작한 뒤 해결될 때","action":"시작 유형을 자동으로 설정해 재발을 방지하세요."},{"condition":"네트워크 프로필을 개인으로 바꾼 뒤 해결될 때","action":"신뢰할 수 있는 네트워크에서만 개인으로 유지하세요."},{"condition":"워크그룹 불일치가 발견될 때","action":"두 컴퓨터를 같은 워크그룹 이름으로 통일하세요."}],"relatedSymptom":"windows-printer-add-freeze.html","aliases":["800704b3","0x800704b3"],"communityCases":[{"title":"RPC 서비스 재시작으로 프린터 공유 오류 해결","summary":"네트워크 프린터에 연결하려 할 때 이 오류가 발생했던 사례가 있습니다. 서비스 관리자에서 Remote Procedure Call 관련 서비스 상태를 확인하니 일부 서비스가 중지되어 있었고, 재시작하자 정상 연결됐습니다.","insight":"이 오류가 네트워크 프린터나 원격 공유 접근에서 발생한다면 services.msc에서 RPC 관련 서비스가 실행 중인지 먼저 확인하세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes (1000-1299) — network path error range","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1000-1299-"}},{"code":"0x80070102","title":"네트워크 장치가 연결되지 않음","overview":"네트워크 어댑터나 케이블이 시스템에서 인식되지 않을 때 나타나는 오류로, 물리적 연결 문제나 드라이버 미인식이 주요 원인입니다.","summary":"네트워크 어댑터나 케이블이 시스템에서 인식되지 않을 때 나타나는 오류로, 물리적 연결 문제나 드라이버 미인식이 주요 원인입니다.","causes":["네트워크 케이블이나 USB 랜카드가 느슨하게 연결된 경우","네트워크 어댑터 드라이버가 설치되지 않았거나 손상된 경우","메인보드의 내장 랜(LAN) 포트 자체가 고장난 경우","USB 허브를 통한 연결에서 전력 부족으로 장치가 제대로 인식되지 않는 경우","BIOS에서 내장 랜 기능이 비활성화되어 있는 경우"],"checks":["케이블과 어댑터 연결 상태를 물리적으로 다시 확인하세요.","장치 관리자에서 네트워크 어댑터가 목록에 정상적으로 보이는지 확인하세요.","보이지 않는다면 제조사 홈페이지에서 랜 드라이버를 다시 받아 설치하세요.","USB 랜카드라면 허브를 거치지 않고 메인보드에 직접 연결해 보세요.","BIOS에서 내장 랜(LAN) 컨트롤러가 활성화되어 있는지 확인하세요."],"link":"error-code-0x80070102.html","detailPage":"error-code-0x80070102.html","faq":[{"q":"공유기를 바꾸면 해결되나요?","a":"이 문제(0x80070102)는 공유기 자체 문제보다 어댑터 드라이버나 전원 관리 설정이 원인인 경우가 많아, 장비 교체 전에 드라이버 업데이트와 절전 설정부터 확인해보세요."},{"q":"공유기를 바꾸면 확실히 해결되나요?","a":"공유기 노후화가 원인이라면 도움이 되지만, PC의 무선랜 드라이버나 절전 설정이 원인이라면 공유기를 바꿔도 재발할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 재설치로 해결될 때","action":"재발 방지를 위해 제조사 사이트에서 정기적으로 업데이트를 확인하세요."},{"condition":"메인보드에 직결한 뒤 해결될 때","action":"허브의 전력 공급 문제였으므로 전원 공급형 허브 사용을 고려하세요."},{"condition":"BIOS 활성화 후에도 인식되지 않을 때","action":"랜 포트 자체의 물리적 고장 가능성이 크므로 USB 랜카드로 교체를 검토하세요."}],"relatedSymptom":"hardware-wifi-disconnect.html","aliases":["80070102","0x80070102"],"communityCases":[{"title":"내장 랜 드라이버 재설치로 네트워크 인식 해결","summary":"재부팅 후 가끔 네트워크 어댑터가 인식되지 않는 증상이 반복됐던 사례가 있습니다. 메인보드 제조사 홈페이지에서 내장 랜 드라이버를 다시 받아 재설치하자 이후 재발하지 않았습니다.","insight":"이 오류가 간헐적으로 발생한다면 드라이버 불안정이 원인인 경우가 많습니다. 윈도우가 제공하는 기본 드라이버 대신 제조사 전용 드라이버로 교체해보세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — WAIT_TIMEOUT","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"코드 1","title":"이 장치는 올바르게 작동하지 않습니다 (코드 1)","overview":"장치 관리자에서 가장 흔하게 나타나는 오류로, Windows가 장치를 찾았지만 드라이버로 정상 제어하지 못했을 때 표시됩니다. 오디오·네트워크·프린터 등 어떤 장치에서든 나타날 수 있어 코드만으로는 원인을 특정할 수 없고, 장치 이름과 최근 드라이버·전원 변경을 함께 확인해야 합니다.","summary":"장치 관리자에서 가장 일반적으로 보이는 오류로, 하드웨어가 있지만 제대로 작동하지 않는 상태를 나타냅니다.","plainExplanation":"Windows가 장치는 인식했지만 드라이버가 정상적으로 제어를 시작하지 못했다는 뜻입니다. 먼저 어느 장치에서 발생했는지 확인한 뒤 드라이버 재설치, 전원·포트 점검, BIOS 활성화 여부를 차례로 확인하세요.","causes":["드라이버가 설치되지 않았거나 손상된 경우 (가장 일반적)","드라이버 버전이 현재 Windows와 호환되지 않는 경우","USB 장치 등 하드웨어에 전원이 제대로 공급되지 않는 경우","BIOS에서 온보드 오디오·카메라 등 장치 기능이 비활성화된 경우","하드웨어 자체의 물리적 불안정이나 접촉 불량"],"checks":["장치를 우클릭해 속성에서 정확한 장치명과 제조사를 먼저 확인하세요.","장치를 우클릭하고 '드라이버 업데이트 > 컴퓨터에서 드라이버 찾기'로 자동 재설치를 시도하세요.","PC나 부품 제조사 공식 홈페이지에서 정확한 모델용 최신 드라이버를 다운로드해 설치하세요.","USB 장치라면 허브를 거치지 말고 PC 본체의 다른 포트에 직접 연결해보세요.","온보드 오디오·카메라·블루투스처럼 내장 장치라면 BIOS에서 비활성화되어 있지 않은지 확인하세요."],"link":"error-code-device-manager-code-1.html","detailPage":"error-code-device-manager-code-1.html","faq":[{"q":"어떤 장치든 코드 1이 뜨면 원인이 같나요?","a":"아닙니다. 코드 1은 장치 종류와 무관하게 \"드라이버가 정상적으로 제어를 시작하지 못했다\"는 결과만 공통일 뿐, 실제 원인은 장치마다 다릅니다. 어느 장치에서 발생했는지부터 확인하세요."},{"q":"드라이버를 재설치했는데도 코드 1이 계속 뜹니다.","a":"USB 장치라면 전원 공급 문제를, 온보드 장치라면 BIOS에서 비활성화돼 있지 않은지 함께 확인해보세요."}],"decisionSteps":[{"condition":"드라이버 업데이트만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"공식 드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"USB 포트 변경으로도 해결되지 않을 때","action":"드라이버를 완전히 제거한 뒤 재설치하는 방법을 시도하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code1","코드1","이 장치는 올바르게 작동하지 않습니다","this device is not working properly","cm_prob_failed_post","device-manager-code-1"],"communityCases":[{"title":"드라이버 완전 제거 후 재설치로 코드 1 해결","summary":"USB 프린터에서 이 오류가 반복됐던 사례가 있습니다. 장치 관리자에서 '장치 제거'로 드라이버 소프트웨어까지 삭제한 뒤 PC를 재시작해 Windows가 장치를 다시 감지하게 하자 정상 작동했습니다.","insight":"코드 1은 원인이 매우 다양하므로 단순 업데이트보다 드라이버를 완전히 제거한 뒤 재설치하는 방법이 더 효과적인 경우가 많습니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 10","title":"이 장치를 시작할 수 없습니다 (코드 10)","overview":"장치 관리자에서 드라이버 스택의 장치 시작 과정이 실패했을 때 표시되는 오류입니다. USB·유선랜·오디오·블루투스처럼 다양한 장치에서 나타날 수 있으므로, 코드만으로 장치 고장을 단정하지 말고 문제 장치 이름과 최근 드라이버 변경을 함께 확인해야 합니다.","summary":"장치 관리자에서 특정 하드웨어를 시작하지 못했을 때 나타나는 드라이버·장치 초기화 오류입니다.","plainExplanation":"Windows가 장치를 발견했지만, 장치를 실제로 사용할 준비를 시키는 드라이버 과정이 끝나지 않았다는 뜻입니다. 먼저 해당 장치만 제거·재설치하고, 제조사 드라이버와 포트·케이블을 차례로 확인하세요.","causes":["장치 드라이버가 현재 Windows 버전 또는 칩셋·펌웨어와 호환되지 않는 경우","드라이버 설치 파일이나 이전 드라이버 설정이 손상되어 장치 초기화에 실패한 경우","USB 허브·케이블·PCIe 슬롯 등의 연결 또는 전원 공급이 불안정한 경우","BIOS/UEFI에서 해당 장치 관련 기능(예: 내장 랜·오디오·카메라)이 비활성화된 경우","다른 PC·포트에서도 반복되는 장치 자체의 물리적 결함"],"checks":["장치 관리자에서 노란 느낌표가 표시된 장치의 이름·제조사·드라이버 버전과 오류가 발생한 시각을 먼저 기록하세요.","해당 장치를 우클릭해 '장치 제거'를 선택한 뒤 PC를 재시작하세요. 재시작 후 Windows가 장치를 다시 감지하는지 확인합니다.","Windows가 자동으로 설치한 드라이버보다 PC·메인보드·장치 제조사 지원 페이지의 정확한 모델용 드라이버를 우선 설치하세요. 드라이버 검색 프로그램은 사용하지 마세요.","USB 장치라면 허브를 빼고 PC 본체의 다른 포트·케이블에 직접 연결하고, 가능하면 다른 PC에서도 같은 증상이 반복되는지 확인하세요.","내장 장치라면 칩셋 드라이버와 BIOS/UEFI 업데이트 안내를 확인하되, BIOS 업데이트는 현재 문제 장치와의 호환성 개선이 명시된 경우에만 진행하세요."],"link":"error-code-device-manager-code-10.html","detailPage":"error-code-device-manager-code-10.html","faq":[{"q":"장치가 인식이 안 되면 바로 새 제품을 사야 하나요?","a":"이 문제(코드 10)는 장치 고장보다 드라이버나 포트 설정 문제인 경우가 흔합니다. 다른 포트나 다른 PC에서 인식되는지 먼저 확인해보세요."},{"q":"USB 드라이버를 삭제하면 어떻게 되나요?","a":"장치 관리자에서 드라이버를 제거한 뒤 재부팅하면 Windows가 드라이버를 자동으로 다시 설치하며, 이 과정에서 인식 문제가 해결되는 경우가 있습니다."}],"decisionSteps":[{"condition":"장치 재감지만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"공식 드라이버 설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"포트·케이블 교체로도 해결되지 않을 때","action":"다른 PC에서도 재현되는지 확인해 장치 자체 결함 여부를 판단하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code10","코드10","이 장치를 사용할 수 없습니다","이장치를 사용할수 없습니다","이 장치를 시작할 수 없습니다","this device cannot start","cm_prob_failed_start","device-manager-code-10"],"communityCases":[{"title":"드라이버 완전 제거 후 재설치로 코드 10 해결","summary":"USB 오디오 장치에서 이 오류가 발생했던 사례가 있습니다. 드라이버 업데이트를 여러 번 시도해도 해결되지 않았는데, 장치 관리자에서 장치를 완전히 제거(드라이버 파일 삭제 포함)하고 PC를 재시작해 자동 재설치되도록 하자 정상 인식됐습니다.","insight":"코드 10은 장치 시작 실패입니다. 드라이버 업데이트가 아닌 완전 제거 후 재설치가 더 효과적인 경우가 많습니다. 드라이버 파일 삭제 옵션을 꼭 체크하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 12","title":"장치에서 사용할 리소스를 찾을 수 없습니다 (코드 12)","overview":"Windows가 장치를 시작하는 데 필요한 시스템 리소스를 배정하지 못했을 때 나타납니다. 최근에 확장 카드·USB 컨트롤러·도킹 장치를 추가했거나 BIOS 설정을 바꾼 뒤 발생했다면 장치 충돌과 펌웨어 설정을 먼저 확인해야 합니다.","summary":"장치에 필요한 시스템 리소스가 부족하거나 다른 장치와 충돌할 때 나타나는 오류입니다.","causes":["여러 장치가 같은 시스템 리소스를 요구하거나 충돌한 경우","최근 연결한 확장 카드·도킹 장치·USB 컨트롤러가 자원 배정을 바꾼 경우","BIOS/UEFI가 장치에 필요한 자원을 충분히 배정하지 못한 경우"],"checks":["문제가 시작된 직전에 추가한 USB 장치·확장 카드·도킹 장치를 분리한 뒤 재부팅해 보세요.","장치 관리자에서 같은 시각에 노란 느낌표가 표시된 다른 장치가 있는지 확인하세요.","메인보드·노트북 제조사 지원 페이지에서 칩셋 드라이버와 BIOS/UEFI 업데이트 안내를 확인하세요."],"link":"device-manager-codes.html?code=코드%2012","detailPage":"device-manager-codes.html?code=코드%2012","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code12","코드12","리소스 부족","device resources"],"communityCases":[{"title":"PCIe 슬롯 이동으로 리소스 충돌(코드 12) 해결","summary":"PCIe 사운드카드에서 이 오류가 발생했던 사례가 있습니다. 장착된 슬롯에서 다른 PCIe 슬롯으로 이동하자 리소스 충돌이 해소되어 정상 인식됐습니다.","insight":"코드 12는 리소스(IRQ, 메모리 주소 등) 충돌입니다. 같은 확장 카드도 슬롯을 변경하면 충돌이 해소되는 경우가 있습니다. 비어있는 다른 슬롯으로 이동해보세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 14","title":"재시작해야 장치가 정상 작동합니다 (코드 14)","overview":"드라이버나 장치 설정 변경은 끝났지만 재부팅 전 상태라 장치가 아직 정상 시작되지 않은 경우입니다. 고장 코드로 단정하기보다 먼저 일반 재시작을 완료한 뒤 상태가 바뀌는지 확인하세요.","summary":"드라이버 또는 설정 변경을 적용하려면 Windows 재시작이 필요한 상태입니다.","causes":["드라이버 설치·업데이트·제거 직후 재시작을 하지 않은 경우","Windows Update가 장치 관련 변경을 예약한 경우","절전·최대 절전에서 복귀하며 장치 설정 적용이 보류된 경우"],"checks":["작업을 저장한 뒤 '다시 시작'을 실행하세요. 종료 후 전원 켜기보다 재시작이 우선입니다.","재시작 후에도 반복되면 최근 설치한 드라이버를 제조사 버전으로 다시 설치하세요.","업데이트가 보류돼 있다면 Windows Update를 완료하고 한 번 더 재시작하세요."],"link":"device-manager-codes.html?code=코드%2014","detailPage":"device-manager-codes.html?code=코드%2014","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code14","코드14","재시작 필요","restart required"],"communityCases":[{"title":"재부팅으로 해결되는 코드 14 사례","summary":"장치를 연결한 직후 코드 14가 표시됐던 사례가 있습니다. 드라이버를 설치한 뒤 재부팅 요청이 있었지만 무시하고 계속 사용하다가 이 오류가 나타난 것이 원인이었고, 재부팅하자 정상 인식됐습니다.","insight":"코드 14는 재부팅이 완료되지 않아 장치가 정상 동작하지 못하는 상태입니다. 드라이버 설치 후 재부팅 권고가 있었다면 반드시 재부팅하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 18","title":"이 장치의 드라이버를 다시 설치해야 합니다 (코드 18)","overview":"현재 드라이버 구성이 장치를 정상적으로 제어하지 못해 드라이버 재설치가 필요한 상태입니다. 임의의 드라이버 검색 도구 대신 장치 또는 PC 제조사 지원 페이지의 정확한 모델용 드라이버를 사용하세요.","summary":"장치 드라이버를 제거한 뒤 정확한 제조사 드라이버로 다시 설치해야 하는 오류입니다.","causes":["드라이버 파일 또는 설치 정보가 손상된 경우","Windows가 설치한 기본 드라이버가 장치와 완전히 호환되지 않는 경우","이전 드라이버 잔여 설정이 새 드라이버와 충돌한 경우"],"checks":["장치 관리자에서 문제 장치를 제거한 뒤 재시작하세요.","PC·메인보드·장치 제조사 지원 페이지에서 모델과 Windows 버전에 맞는 드라이버를 설치하세요.","재설치 후에도 반복되면 다른 포트·다른 PC에서 장치 자체 문제인지 교차 확인하세요."],"link":"device-manager-codes.html?code=코드%2018","detailPage":"device-manager-codes.html?code=코드%2018","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code18","코드18","드라이버 다시 설치","reinstall driver"],"communityCases":[{"title":"드라이버 수동 설치로 코드 18 해결","summary":"새 장치를 연결했을 때 코드 18과 함께 드라이버를 다시 설치해야 한다는 메시지가 표시됐던 사례가 있습니다. 윈도우 자동 설치가 되지 않아 제조사 홈페이지에서 드라이버를 수동으로 내려받아 설치하자 정상 인식됐습니다.","insight":"코드 18은 드라이버 재설치가 필요하다는 신호입니다. 윈도우가 자동으로 올바른 드라이버를 찾지 못할 때는 제조사 홈페이지에서 직접 다운로드해 설치하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 22","title":"이 장치가 비활성화되어 있습니다 (코드 22)","overview":"장치 관리자에서 장치가 수동으로 사용 안 함 상태가 되었을 때 나타납니다. 드라이버를 지우거나 BIOS를 초기화하기 전에 장치를 다시 사용으로 설정하는 것으로 해결되는지 먼저 확인하세요.","summary":"장치 관리자에서 장치가 비활성화된 상태입니다.","causes":["사용자가 장치 관리자에서 장치를 사용 안 함으로 설정한 경우","관리 도구나 회사 정책이 장치를 비활성화한 경우","문제 해결 과정에서 임시로 꺼 둔 장치가 그대로 남은 경우"],"checks":["장치 관리자에서 해당 장치를 우클릭해 '장치 사용'을 선택하세요.","사용으로 바꾼 뒤에도 다시 비활성화되면 회사·학교 관리 정책 또는 보안 프로그램을 확인하세요.","내장 카메라·오디오·랜 장치라면 BIOS/UEFI에서도 비활성화되어 있지 않은지 확인하세요."],"link":"device-manager-codes.html?code=코드%2022","detailPage":"device-manager-codes.html?code=코드%2022","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code22","코드22","장치 비활성화","device disabled"],"communityCases":[{"title":"장치 활성화로 코드 22 즉시 해결","summary":"장치 관리자에서 특정 장치에 코드 22가 표시됐던 사례가 있습니다. 이전에 리소스 절약을 위해 수동으로 비활성화한 것을 잊고 있었고, 장치 관리자에서 우클릭 후 사용으로 설정하자 바로 작동했습니다.","insight":"코드 22는 단순히 장치가 비활성화된 상태입니다. 장치 관리자에서 우클릭 후 사용(Enable)을 선택하면 바로 해결됩니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 29","title":"펌웨어에서 장치를 비활성화했습니다 (코드 29)","overview":"장치 관리자에서 켜는 것만으로는 해결되지 않고 BIOS/UEFI 펌웨어 설정에서 장치 자원이 꺼져 있을 때 나타납니다. 내장 랜·오디오·USB 컨트롤러처럼 메인보드 설정에 있는 장치에서 우선 확인합니다.","summary":"BIOS/UEFI 펌웨어 설정에서 장치가 비활성화된 상태입니다.","causes":["BIOS/UEFI에서 내장 장치 기능이 꺼진 경우","BIOS 초기화·업데이트 뒤 기본 설정이 바뀐 경우","기업·학교용 PC의 펌웨어 정책이 장치를 제한한 경우"],"checks":["메인보드 또는 노트북 매뉴얼에서 해당 장치의 BIOS/UEFI 메뉴 이름을 확인하세요.","BIOS/UEFI에서 내장 LAN·오디오·카메라·USB 관련 항목을 기본값 또는 사용으로 바꾸세요.","설정을 바꾸기 전 현재 값을 사진으로 기록하고, 메뉴를 찾기 어렵다면 제조사 지원 문서를 확인하세요."],"link":"device-manager-codes.html?code=코드%2029","detailPage":"device-manager-codes.html?code=코드%2029","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code29","코드29","bios 장치 비활성화","firmware disabled"],"communityCases":[{"title":"BIOS에서 컨트롤러 활성화로 코드 29 해결","summary":"메인보드 교체 후 내장 오디오에 코드 29가 표시됐던 사례가 있습니다. BIOS 설정을 확인하니 HD Audio 컨트롤러가 비활성화 상태였고, 활성화 후 재부팅하자 정상 인식됐습니다.","insight":"코드 29는 장치에 필요한 리소스가 할당되지 않은 상태입니다. 메인보드 내장 장치라면 BIOS에서 해당 기능이 활성화되어 있는지 먼저 확인하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 32","title":"장치 드라이버 서비스가 비활성화되어 있습니다 (코드 32)","overview":"드라이버 서비스의 시작 방식이 비활성화되어 Windows가 장치를 시작하지 못하는 경우입니다. 레지스트리 값을 직접 바꾸기보다 장치 드라이버를 제거한 뒤 제조사 버전으로 재설치하는 방법이 안전합니다.","summary":"드라이버 서비스가 비활성화되어 장치를 시작할 수 없는 오류입니다.","causes":["드라이버 서비스의 시작 유형이 비활성화로 바뀐 경우","이전 드라이버 제거 또는 최적화 프로그램이 서비스 설정을 변경한 경우","호환되지 않는 대체 드라이버가 설치된 경우"],"checks":["문제 장치를 제거하고 재시작한 뒤 제조사 드라이버를 다시 설치하세요.","최근 사용한 드라이버 정리·최적화 프로그램이 있다면 되돌리거나 제거를 검토하세요.","서비스·레지스트리 값을 임의로 수정하지 말고 재설치 후에도 반복될 때 제조사 지원을 확인하세요."],"link":"device-manager-codes.html?code=코드%2032","detailPage":"device-manager-codes.html?code=코드%2032","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code32","코드32","드라이버 서비스 비활성화","driver service disabled"],"communityCases":[{"title":"서비스 시작 유형 변경으로 코드 32 해결","summary":"특정 장치 드라이버가 코드 32로 로드되지 않았던 사례가 있습니다. 레지스트리에서 해당 서비스의 Start 값이 4(비활성화)로 설정되어 있었고, 3(수동)으로 변경한 뒤 재부팅하자 정상 로드됐습니다.","insight":"코드 32는 드라이버 서비스의 시작 유형이 비활성화로 설정된 경우 발생합니다. services.msc나 레지스트리에서 해당 서비스의 시작 유형을 확인하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 37","title":"Windows가 장치 드라이버를 초기화하지 못했습니다 (코드 37)","overview":"드라이버 자체가 시작 단계에서 실패했을 때 나타납니다. 코드 10과 비슷해 보이지만 드라이버 초기화 실패에 더 가깝기 때문에 최근 드라이버 업데이트·보안 소프트웨어·장치 펌웨어 변경을 비교하는 것이 중요합니다.","summary":"장치 드라이버의 초기화 과정이 실패한 오류입니다.","causes":["현재 Windows 빌드와 호환되지 않는 드라이버","드라이버 설치 파일 또는 종속 구성 요소 손상","보안 소프트웨어나 다른 장치 드라이버와의 충돌"],"checks":["최근 드라이버 업데이트 직후 발생했다면 이전 안정 버전으로 롤백해 보세요.","장치를 제거한 뒤 재시작하고 제조사 드라이버를 새로 설치하세요.","안전 모드에서 문제가 사라지면 최근 설치한 보안·튜닝 프로그램과 드라이버를 하나씩 확인하세요."],"link":"error-code-device-manager-code-37.html","detailPage":"error-code-device-manager-code-37.html","faq":[{"q":"코드 10과 코드 37은 어떻게 다른가요?","a":"둘 다 드라이버 문제로 보이지만, 코드 37은 드라이버 자체의 초기화 단계 실패에 더 가깝습니다. 최근 드라이버 업데이트나 보안 소프트웨어 설치 시점과 비교해보면 원인을 좁히는 데 도움이 됩니다."}],"decisionSteps":[{"condition":"자동 드라이버 업데이트로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"제조사 공식 드라이버로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"업데이트로도 해결되지 않을 때","action":"이전 버전으로 롤백해보세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code37","코드37","드라이버 초기화 실패","driver initialization failed"],"communityCases":[{"title":"이전 버전 드라이버 롤백으로 코드 37 해결","summary":"USB 장치 연결 시 코드 37이 반복됐던 사례가 있습니다. 드라이버 업데이트 이후 발생했고, 이전 버전 드라이버로 롤백하자 정상 인식됐습니다.","insight":"코드 37은 드라이버가 장치의 API 기능을 반환하지 못할 때 발생합니다. 최근 드라이버 업데이트가 있었다면 이전 버전으로 롤백이 효과적입니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 38","title":"이전 장치 드라이버가 메모리에 남아 있습니다 (코드 38)","overview":"이전에 로드된 같은 드라이버가 메모리에 남아 있어 새 장치 인스턴스를 시작하지 못한 경우입니다. 장치를 반복해서 뽑고 꽂기보다 일반 재시작으로 드라이버를 완전히 정리하는 것이 우선입니다.","summary":"이전 드라이버 인스턴스가 메모리에 남아 새 장치를 시작하지 못하는 오류입니다.","causes":["USB·도킹 장치를 연결 해제한 뒤 드라이버가 완전히 종료되지 않은 경우","절전 복귀 또는 빠른 시작 뒤 드라이버 상태가 꼬인 경우","동일 장치 드라이버의 충돌"],"checks":["작업을 저장하고 Windows를 다시 시작하세요.","재시작 후 장치를 본체 포트에 직접 연결해 다시 확인하세요.","반복되면 장치 제거 후 제조사 드라이버를 재설치하고 절전 복귀 직후에만 발생하는지 기록하세요."],"link":"error-code-device-manager-code-38.html","detailPage":"error-code-device-manager-code-38.html","faq":[{"q":"장치를 뽑았다 다시 꽂으면 해결되나요?","a":"일시적으로는 해결될 수 있지만 근본 원인은 아닙니다. 이전 드라이버 인스턴스가 메모리에서 완전히 정리되도록 일반 재시작을 먼저 시도하는 것이 더 확실합니다."}],"decisionSteps":[{"condition":"케이블·포트 재연결만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"전원 확인으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"USB 허브 우회로도 해결되지 않을 때","action":"완전 재부팅을 시도해 이전 드라이버 인스턴스를 정리하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code38","코드38","드라이버 메모리","previous driver instance"],"communityCases":[{"title":"완전 재부팅으로 코드 38 해결","summary":"장치를 반복해서 탈착하던 중 코드 38이 표시됐던 사례가 있습니다. 이전 드라이버 인스턴스가 아직 메모리에 남아 있던 것이 원인이었고, 완전히 재부팅하자 정상 인식됐습니다.","insight":"코드 38은 이전 드라이버 인스턴스가 아직 메모리에서 완전히 제거되지 않은 상태입니다. 반복 탈착 후 이 오류가 나타나면 단순 재시작보다 완전 재부팅이 필요합니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 40","title":"Windows가 장치의 서비스 정보를 읽을 수 없습니다 (코드 40)","overview":"드라이버 서비스 키 정보가 없거나 잘못 기록돼 Windows가 장치에 접근하지 못하는 경우입니다. 레지스트리를 직접 편집하는 대신 장치 드라이버를 정상 절차로 재설치하세요.","summary":"장치 드라이버의 서비스 정보가 손상되었거나 누락된 오류입니다.","causes":["드라이버 서비스 관련 설정이 손상된 경우","불완전한 드라이버 제거·설치가 남은 경우","정리 도구나 악성 프로그램이 장치 설정을 변경한 경우"],"checks":["문제 장치를 제거하고 재시작한 뒤 제조사 드라이버를 다시 설치하세요.","최근 설치한 드라이버 정리·보안 프로그램의 변경 이력이 있다면 확인하세요.","재설치 후에도 반복되면 시스템 복원 지점 또는 제조사 지원을 먼저 검토하고 레지스트리 직접 수정은 피하세요."],"link":"device-manager-codes.html?code=코드%2040","detailPage":"device-manager-codes.html?code=코드%2040","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code40","코드40","서비스 키","service key"],"communityCases":[{"title":"레지스트리 정리 후 코드 40 해결","summary":"프린터 드라이버를 반복해서 설치·제거하다가 코드 40이 발생했던 사례가 있습니다. 제조사의 전용 드라이버 정리 도구를 사용해 레지스트리를 완전히 정리한 뒤 재설치하자 정상 작동했습니다.","insight":"코드 40은 레지스트리의 드라이버 정보 손상이 원인입니다. 단순 재설치로는 레지스트리 잔여 데이터가 남을 수 있으므로 제조사 정리 도구나 드라이버 전용 클리너를 사용하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 48","title":"Windows가 문제가 있는 장치 소프트웨어를 차단했습니다 (코드 48)","overview":"Windows가 호환성 또는 안정성 문제로 알려진 드라이버의 시작을 차단했을 때 나타납니다. 서명 강제 해제 같은 우회보다 제조사에서 제공하는 최신 호환 드라이버를 찾는 것이 안전합니다.","summary":"Windows가 호환성 문제가 있는 장치 드라이버를 차단한 오류입니다.","causes":["현재 Windows 버전에서 문제가 확인된 오래된 드라이버","제조사가 더 이상 지원하지 않는 장치용 드라이버","Windows 업데이트 뒤 호환성 차단 목록에 포함된 드라이버"],"checks":["장치·PC 제조사 지원 페이지에서 현재 Windows 버전용 최신 드라이버가 있는지 확인하세요.","Windows Update의 선택적 업데이트에 제조사 드라이버가 있는지 확인하세요.","지원되는 드라이버가 없다면 장치 교체 또는 이전 호환 환경 사용을 제조사 안내에 따라 검토하세요."],"link":"device-manager-codes.html?code=코드%2048","detailPage":"device-manager-codes.html?code=코드%2048","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code48","코드48","드라이버 차단","driver blocked"],"communityCases":[{"title":"서명된 최신 드라이버 업데이트로 코드 48 해결","summary":"구형 드라이버를 사용하던 중 윈도우 업데이트 이후 이 오류가 발생했던 사례가 있습니다. 마이크로소프트가 더 이상 지원하지 않는 드라이버였고, 제조사에서 새로 서명된 버전을 제공해 업데이트하자 정상 작동했습니다.","insight":"코드 48은 정책으로 차단된 드라이버를 나타냅니다. 일반적인 해결 방법은 서명이 유효한 최신 드라이버로 업데이트하는 것입니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 52","title":"Windows가 드라이버의 디지털 서명을 확인할 수 없습니다 (코드 52)","overview":"Windows가 장치 드라이버의 디지털 서명을 신뢰할 수 없거나 파일이 손상된 것으로 판단했을 때 나타납니다. 임시로 서명 검사를 끄기보다 공식 제조사 드라이버를 다시 받는 방식이 안전합니다.","summary":"드라이버의 디지털 서명을 확인하지 못해 시작을 차단한 오류입니다.","causes":["서명되지 않았거나 손상된 드라이버가 설치된 경우","오래된 장치의 드라이버가 현재 Windows 보안 정책과 맞지 않는 경우","드라이버 파일 다운로드 또는 설치가 불완전한 경우"],"checks":["장치 제조사 지원 페이지에서 최신 서명 드라이버를 다시 다운로드해 설치하세요.","드라이버 서명 검사 해제·테스트 모드 사용은 보안 위험이 있으므로 일반 해결책으로 사용하지 마세요.","최신 드라이버가 없다면 장치 제조사에 현재 Windows 지원 여부를 확인하세요."],"link":"device-manager-codes.html?code=코드%2052","detailPage":"device-manager-codes.html?code=코드%2052","relatedSymptom":"hardware-usb-not-detected.html","aliases":["code52","코드52","디지털 서명","driver signature"],"communityCases":[{"title":"드라이버 서명 없음으로 코드 52 발생, 서명 버전 요청","summary":"서명 없는 드라이버를 사용하려 할 때 코드 52가 발생했던 사례가 있습니다. 고급 시작 옵션에서 드라이버 서명 적용 사용 안 함 모드로 부팅해 임시로 설치하고 제조사에 서명된 버전 제공을 요청했습니다.","insight":"코드 52는 서명되지 않은 드라이버 차단입니다. 임시 해결보다 제조사에 서명된 드라이버를 요청하는 것이 장기적으로 안전합니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 43","title":"Windows에서 이 장치를 중지했습니다 (코드 43)","overview":"드라이버가 장치에서 하드웨어 오류나 문제를 감지해 윈도우에 보고했을 때 나타나는 코드로, 그래픽카드나 USB 장치에서 특히 자주 나타납니다. 소프트웨어 문제일 수도 있지만 하드웨어 결함의 신호인 경우도 많습니다.","summary":"드라이버가 장치에서 하드웨어 오류나 문제를 감지해 윈도우에 보고했을 때 나타나는 코드로, 그래픽카드나 USB 장치에서 특히 자주 나타납니다.","causes":["그래픽카드가 과열되거나 전원 공급이 불안정한 경우","USB 장치가 순간적으로 과전류를 발생시켜 컨트롤러가 안전을 위해 차단한 경우","드라이버 버그로 장치 초기화에 실패하는 경우","펌웨어가 오래되어 최신 드라이버와 호환되지 않는 경우","하드웨어 자체의 결함(그래픽카드 고장, USB 컨트롤러 손상 등)","외장 그래픽카드를 장착한 상태에서 CPU 내장 그래픽(AMD/Intel)까지 동시에 활성화돼 두 드라이버가 충돌하는 경우"],"checks":["장치를 다른 포트나 슬롯에 연결해 재현되는지 확인하세요.","그래픽카드라면 드라이버를 완전히 제거(DDU 등)한 뒤 최신 버전으로 재설치하세요.","USB 장치라면 다른 PC에서도 같은 증상이 나오는지 확인해 장치 자체 결함인지 구분하세요.","온도와 전원 공급 상태를 점검하세요 (특히 그래픽카드 보조 전원).","제조사 펌웨어 업데이트가 있는지 확인하고 적용해 보세요.","내장 그래픽 장치에서 코드 43이 뜬다면, 모니터가 외장 그래픽카드 단자에 꽂혀 있는지 먼저 확인한 뒤 장치 관리자에서 내장 그래픽을 비활성화해보세요(대부분 외장 카드가 있으면 내장은 꺼둬도 문제 없습니다)."],"link":"error-code-device-manager-code-43.html","detailPage":"error-code-device-manager-code-43.html","faq":[{"q":"게임할 때만 재부팅되면 그래픽카드 문제인가요?","a":"이 문제(코드 43)는 그래픽 드라이버 문제일 가능성이 높지만 전원 공급이나 온도 문제와 겹치는 경우도 많아, 드라이버 재설치와 함께 온도·전력 상태도 함께 확인하는 것이 좋습니다."},{"q":"콘센트나 멀티탭도 원인이 될 수 있나요?","a":"드물지만 불안정한 멀티탭이나 정전압 문제가 원인이 될 수 있어, 다른 콘센트로 테스트해보는 것도 방법입니다."}],"decisionSteps":[{"condition":"포트 변경만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"드라이버 클린 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"온도·전원 점검으로도 해결되지 않을 때","action":"파워서플라이나 메모리 등 다른 부품과의 상호작용을 의심해보세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["code43","코드43","device-manager-code-43"],"communityCases":[{"title":"파워서플라이 교체로 해결한 사례","summary":"RTX 2070에서 코드 43이 발생해 드라이버 재설치, DDU 클린 설치, PCIe 슬롯 교체까지 시도했지만 해결되지 않았던 사례가 있습니다. 자가 진단 도구로는 파워서플라이가 정상으로 나왔지만, 커뮤니티에서는 오래되고 품질이 낮은 파워서플라이 자체를 의심해보라고 권했고, 실제로 파워서플라이를 교체한 뒤 문제가 해결됐습니다.","insight":"전원 공급 장치는 테스트 도구에서 이상 없다고 나와도 실제로는 불안정한 경우가 있습니다."},{"title":"램 슬롯 분리 테스트로 해결한 사례","summary":"RMA로 교체받은 그래픽카드에서 코드 43과 함께 화면에 줄이 가는 증상이 나타났는데, 커뮤니티에서는 그래픽카드 자체보다 램(RAM) 문제일 가능성을 짚었습니다. 서로 다른 시기에 구매한 메모리 키트를 함께 꽂아 쓰고 있었던 것이 원인일 수 있다는 조언에 따라 메모리 키트를 하나씩 분리해서 테스트하는 방법이 제안됐습니다.","insight":"그래픽 관련 오류라고 해서 반드시 그래픽카드만의 문제는 아닐 수 있습니다."},{"title":"내장 그래픽 비활성화로 해결한 사례","summary":"외장 그래픽카드(RTX 50 시리즈)를 쓰는 PC에서 AMD 내장 그래픽 장치에만 코드 43이 표시된 사례가 있습니다. 모니터는 이미 외장 그래픽카드 단자에 연결돼 있어 내장 그래픽이 실제로는 쓰이지 않는 상태였고, 장치 관리자에서 내장 그래픽 장치를 사용 안 함으로 설정하자 오류 표시가 사라졌습니다.","insight":"외장 그래픽카드가 있는데 내장 그래픽에서만 코드 43이 뜬다면, 고장이 아니라 안 쓰는 장치가 충돌 상태로 남아있는 것일 수 있습니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 28","title":"이 장치에 대한 드라이버가 설치되어 있지 않습니다 (코드 28)","overview":"윈도우가 해당 하드웨어를 인식했지만 이를 제어할 드라이버를 찾지 못했을 때 나타나는 코드입니다. 새 하드웨어를 처음 연결했거나 윈도우를 새로 설치한 직후 자주 나타납니다.","summary":"윈도우가 해당 하드웨어를 인식했지만 이를 제어할 드라이버를 찾지 못했을 때 나타나는 코드입니다.","causes":["새로 설치한 윈도우에 기본 제공되지 않는 전용 드라이버가 필요한 경우","인터넷 연결 없이 설치해 자동 드라이버 검색이 이루어지지 않은 경우","제조사 드라이버 설치 프로그램이 도중에 실패한 경우","너무 오래되었거나 반대로 너무 최신인 운영체제와 하드웨어 조합","드라이버 설치 파일 자체가 손상된 경우"],"checks":["장치 관리자에서 노란 느낌표가 있는 장치를 확인하고, 하드웨어 ID로 제조사와 모델을 특정하세요.","제조사 공식 홈페이지에서 정확한 모델명의 드라이버를 다운로드해 설치하세요.","Windows Update에서 선택적 업데이트에 관련 드라이버가 있는지 확인하세요.","인터넷에 연결한 상태에서 '하드웨어 변경 사항 검색'을 다시 실행해 보세요.","다운로드한 드라이버 설치 파일이 완전한지 다시 받아서 재시도하세요."],"link":"error-code-device-manager-code-28.html","detailPage":"error-code-device-manager-code-28.html","faq":[{"q":"장치가 인식이 안 되면 바로 새 제품을 사야 하나요?","a":"이 문제(코드 28)는 장치 고장보다 드라이버나 포트 설정 문제인 경우가 흔합니다. 다른 포트나 다른 PC에서 인식되는지 먼저 확인해보세요."},{"q":"다른 PC에서는 잘 되는 장치인데 인식이 안 되면 뭐가 문제인가요?","a":"장치 자체보다는 현재 PC의 USB 컨트롤러 드라이버나 전원 관리 설정 문제일 가능성이 높습니다."}],"decisionSteps":[{"condition":"제조사 드라이버 설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"Windows Update 선택적 업데이트로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"재다운로드로도 해결되지 않을 때","action":"하드웨어 ID로 검색해 정확한 드라이버 페이지를 다시 확인하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code28","코드28","device-manager-code-28"],"communityCases":[{"title":"제조사 드라이버 수동 설치로 코드 28 해결","summary":"블루투스 어댑터를 연결했을 때 드라이버가 없다는 코드 28이 표시됐던 사례가 있습니다. 윈도우 업데이트에서 자동으로 드라이버를 찾지 못해, 제조사 홈페이지에서 직접 드라이버를 내려받아 설치하자 정상 인식됐습니다.","insight":"코드 28은 드라이버가 설치되지 않은 상태입니다. 윈도우가 자동으로 드라이버를 못 찾는다면 제조사 홈페이지나 장치 이면의 모델 번호로 직접 검색해 설치하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 39","title":"드라이버가 손상되었거나 누락되었습니다 (코드 39)","overview":"장치를 제어해야 할 드라이버 파일 자체가 손상되었거나 누락되어 윈도우가 로드하지 못할 때 나타나는 코드입니다. 오디오나 저장장치 컨트롤러에서 자주 보고됩니다.","summary":"장치를 제어해야 할 드라이버 파일 자체가 손상되었거나 누락되어 윈도우가 로드하지 못할 때 나타나는 코드입니다.","causes":["드라이버 파일이 디스크 오류나 강제 종료로 손상된 경우","맬웨어 감염으로 드라이버 파일이 변조되거나 삭제된 경우","레지스트리에서 드라이버 참조 경로가 잘못된 경우","다른 프로그램이 드라이버 파일을 잘못 덮어쓴 경우","시스템 파일 손상이 드라이버 로드 과정에 영향을 준 경우"],"checks":["명령 프롬프트에서 sfc /scannow를 실행해 손상된 시스템 파일을 복구하세요.","장치 관리자에서 해당 드라이버를 완전히 제거한 뒤 재설치하세요.","백신 프로그램으로 전체 검사를 실행해 맬웨어 감염 여부를 확인하세요.","제조사 홈페이지에서 드라이버를 새로 받아 클린 설치하세요.","디스크 상태를 chkdsk로 점검해 물리적 오류가 없는지 확인하세요."],"link":"error-code-device-manager-code-39.html","detailPage":"error-code-device-manager-code-39.html","faq":[{"q":"소리가 안 나면 스피커나 이어폰부터 바꿔야 하나요?","a":"이 문제(코드 39)는 장치 자체보다 드라이버나 서비스 문제인 경우가 많으니, 다른 장치로 교차 확인한 뒤에 장치 교체를 고려해도 늦지 않습니다."}],"decisionSteps":[{"condition":"SFC에서 손상된 파일을 복구했다고 나올 때","action":"재부팅 후 코드 39가 다시 나타나는지만 확인하고, 재발하면 드라이버 재설치 단계로 넘어가세요."},{"condition":"재설치 직후에도 코드 39가 곧바로 재발할 때","action":"맬웨어가 드라이버 파일을 계속 변조하고 있을 가능성이 크므로 백신 전체 검사를 우선하세요."},{"condition":"chkdsk에서 배드섹터가 발견될 때","action":"드라이버 재설치보다 디스크 자체 교체를 우선 검토하세요. 배드섹터가 있는 디스크는 파일이 다시 손상될 수 있습니다."}],"relatedSymptom":"hardware-sound-not-working.html","aliases":["code39","코드39","device-manager-code-39"],"communityCases":[{"title":"드라이버 파일 포함 제거 후 재설치로 코드 39 해결","summary":"USB 허브의 드라이버 파일이 손상되어 코드 39가 표시됐던 사례가 있습니다. 장치를 삭제하고 드라이버 파일까지 제거한 뒤 재부팅해 자동 재설치하자 정상 인식됐습니다.","insight":"코드 39는 드라이버 파일 손상이 원인입니다. 단순 업데이트보다 드라이버 파일 포함 제거 후 재설치가 더 확실한 방법입니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 31","title":"이 장치가 제대로 작동하고 있지 않습니다 (코드 31)","overview":"드라이버는 로드됐지만 장치가 필요한 정보를 제공하지 못해 정상 동작하지 않을 때 나타나는 코드입니다. 리소스 충돌이나 구형 드라이버가 흔한 원인입니다.","summary":"드라이버는 로드됐지만 장치가 필요한 정보를 제공하지 못해 정상 동작하지 않을 때 나타나는 코드입니다.","causes":["다른 장치와 하드웨어 리소스(IRQ 등)가 충돌하는 경우","드라이버가 오래되어 현재 시스템 구성과 맞지 않는 경우","장치가 절전 상태에서 제대로 복귀하지 못하는 경우","메인보드 칩셋 드라이버가 오래된 경우","장치 자체의 초기화 실패"],"checks":["장치 관리자에서 리소스 탭(있는 경우)으로 다른 장치와의 충돌 여부를 확인하세요.","메인보드 칩셋 드라이버를 최신 버전으로 업데이트하세요.","장치 드라이버를 제거 후 재부팅해 자동 재설치를 유도하세요.","절전 모드에서 복귀한 직후에만 발생하는지 확인해 전원 관리 설정을 점검하세요.","가능하다면 다른 슬롯이나 포트로 장치를 옮겨 재현 여부를 확인하세요."],"link":"error-code-device-manager-code-31.html","detailPage":"error-code-device-manager-code-31.html","faq":[{"q":"장치가 인식이 안 되면 바로 새 제품을 사야 하나요?","a":"이 문제(코드 31)는 장치 고장보다 드라이버나 포트 설정 문제인 경우가 흔합니다. 다른 포트나 다른 PC에서 인식되는지 먼저 확인해보세요."},{"q":"USB 포트 전원 관리 설정이 영향을 주나요?","a":"네, Windows의 USB 선택적 절전 설정이 활성화되어 있으면 일부 장치의 연결이 끊기거나 인식이 지연될 수 있습니다."}],"decisionSteps":[{"condition":"다른 포트로 옮겼을 때 정상 작동할 때","action":"원래 포트의 전력 공급 문제이므로 허브 대신 메인보드 직결 포트를 사용하세요."},{"condition":"칩셋 드라이버 업데이트로 해결될 때","action":"재발 방지를 위해 정기적으로 드라이버 업데이트를 확인하세요."},{"condition":"절전 복귀 후에만 발생할 때","action":"USB 선택적 절전 설정을 끄고 재현 여부를 확인하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code31","코드31","device-manager-code-31"],"communityCases":[{"title":"드라이버 전용 제거 도구로 클린 재설치 해결","summary":"드라이버를 여러 번 업데이트하다가 코드 31이 발생했던 사례가 있습니다. DDU 같은 드라이버 전용 제거 도구로 완전히 정리한 뒤 최신 드라이버를 재설치하자 오류가 사라졌습니다.","insight":"코드 31은 드라이버가 제대로 로드되지 않은 상태입니다. 이전 드라이버의 잔여 파일이 충돌하는 경우가 많으므로 클린 재설치를 권장합니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 34","title":"장치에 필요한 설정 정보를 확인할 수 없습니다 (코드 34)","overview":"윈도우가 장치를 초기화하는 데 필요한 리소스 설정 값을 자동으로 판단하지 못했을 때 나타나는 코드로, 오래된 하드웨어나 레거시 장치에서 종종 나타납니다.","summary":"윈도우가 장치를 초기화하는 데 필요한 리소스 설정 값을 자동으로 판단하지 못했을 때 나타나는 코드로, 오래된 하드웨어나 레거시 장치에서 종종 나타납니다.","causes":["레거시(플러그 앤 플레이를 완전히 지원하지 않는) 하드웨어인 경우","BIOS 설정이 장치가 요구하는 리소스와 맞지 않는 경우","드라이버가 자동 설정 값을 지원하지 않아 수동 설정이 필요한 경우","다른 장치와 IRQ나 메모리 주소가 겹치는 경우","매우 오래된 드라이버가 최신 시스템과 호환되지 않는 경우"],"checks":["장치 제조사에 해당 모델이 현재 윈도우 버전을 공식 지원하는지 확인하세요.","BIOS를 기본값으로 초기화한 뒤 재시도해 보세요.","장치 속성의 리소스 탭에서 수동으로 설정을 조정할 수 있는지 확인하세요 (고급 사용자용).","다른 PCI/PCIe 슬롯에 장치를 옮겨 리소스 충돌 여부를 확인하세요.","구형 하드웨어라면 최신 윈도우 대신 호환 모드 설치나 장치 교체를 고려하세요."],"link":"error-code-device-manager-code-34.html","detailPage":"error-code-device-manager-code-34.html","faq":[{"q":"장치가 인식이 안 되면 바로 새 제품을 사야 하나요?","a":"이 문제(코드 34)는 장치 고장보다 드라이버나 포트 설정 문제인 경우가 흔합니다. 다른 포트나 다른 PC에서 인식되는지 먼저 확인해보세요."},{"q":"USB 드라이버를 삭제하면 어떻게 되나요?","a":"장치 관리자에서 드라이버를 제거한 뒤 재부팅하면 Windows가 드라이버를 자동으로 다시 설치하며, 이 과정에서 인식 문제가 해결되는 경우가 있습니다."}],"decisionSteps":[{"condition":"BIOS 기본값 초기화로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"슬롯 이동으로 해결될 때","action":"리소스 충돌이 원인이었으므로 그 슬롯 사용을 피하세요."},{"condition":"리소스 수동 설정으로도 해결되지 않을 때","action":"장치 교체를 고려하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code34","코드34","device-manager-code-34"],"communityCases":[{"title":"IRQ 수동 설정으로 코드 34 해결","summary":"구형 ISA 방식 장치에서 코드 34가 표시됐던 사례가 있습니다. 장치 관리자의 리소스 탭에서 IRQ를 수동으로 다른 값으로 변경하자 정상 작동했습니다.","insight":"코드 34는 장치의 IRQ나 DMA 리소스를 수동으로 설정해야 할 때 나타납니다. 장치 관리자의 리소스 탭에서 수동 구성 옵션을 확인해보세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 19","title":"레지스트리 정보가 손상되어 장치를 시작할 수 없습니다 (코드 19)","overview":"장치 시작에 필요한 구성 정보가 레지스트리에 불완전하거나 손상된 형태로 저장되어 있을 때 나타나는 코드입니다. 드라이버를 여러 번 재설치해도 같은 문제가 반복될 수 있습니다.","summary":"장치 시작에 필요한 구성 정보가 레지스트리에 불완전하거나 손상된 형태로 저장되어 있을 때 나타나는 코드입니다.","causes":["이전 드라이버 제거 과정이 불완전하게 끝나 레지스트리에 잔여 항목이 남은 경우","레지스트리 정리 도구가 필요한 항목까지 잘못 삭제한 경우","시스템 파일이나 레지스트리 하이브 손상","여러 버전의 드라이버가 충돌하며 설치된 경우","맬웨어가 레지스트리를 변조한 경우"],"checks":["장치 관리자에서 '드라이버 소프트웨어 삭제'를 체크하고 완전히 제거한 뒤 재부팅하세요.","제조사의 전용 드라이버 클린업 도구가 있다면 사용해 잔여 항목을 정리하세요.","sfc /scannow와 DISM 복구 명령으로 시스템 파일 손상을 점검하세요.","레지스트리를 직접 수정하기보다 시스템 복원 지점을 활용하는 것이 더 안전합니다.","백신 프로그램으로 맬웨어 감염 여부를 확인하세요."],"link":"error-code-device-manager-code-19.html","detailPage":"error-code-device-manager-code-19.html","faq":[{"q":"복구 화면에서 초기화를 바로 눌러도 되나요?","a":"이 문제(코드 19)가 반복된다면 초기화 전에 먼저 안전 모드 진입과 최근 변경 사항 확인을 시도해보세요. 초기화는 되돌리기 어려우니 마지막 단계로 남겨두는 것이 좋습니다."},{"q":"자동 복구가 계속 실패하면 윈도우를 재설치해야 하나요?","a":"명령 프롬프트에서 부팅 복구 명령을 먼저 시도해보고, 그래도 안 되면 초기화나 재설치를 고려하는 것이 순서입니다."}],"decisionSteps":[{"condition":"드라이버 완전 제거 후 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"sfc·DISM 복구로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"시스템 복원으로도 해결되지 않을 때","action":"맬웨어 감염이나 심각한 레지스트리 손상 가능성이 있으므로 클린 설치를 고려하세요."}],"relatedSymptom":"windows-auto-repair-loop.html","aliases":["code19","코드19","device-manager-code-19"],"communityCases":[{"title":"UpperFilters/LowerFilters 레지스트리 정리로 코드 19 해결","summary":"CD/DVD 드라이브에 코드 19가 표시됐던 사례가 있습니다. 레지스트리 편집기에서 DVD/CD-ROM 드라이브 항목을 확인하니 UpperFilters나 LowerFilters 값에 제거된 소프트웨어의 필터 항목이 남아 있었고, 해당 항목을 삭제하자 정상 인식됐습니다.","insight":"코드 19는 레지스트리의 중복 또는 잔여 필터 항목이 원인인 경우가 많습니다. 특히 CD/DVD 드라이브에서 자주 발생하며, 레지스트리의 UpperFilters/LowerFilters 값 정리로 해결됩니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 41","title":"드라이버 로드는 됐지만 장치를 찾을 수 없습니다 (코드 41)","overview":"드라이버 자체는 정상적으로 로드됐지만 실제 하드웨어를 찾지 못할 때 나타나는 코드로, 마지막으로 장치를 제거했을 때 드라이버가 완전히 언로드되지 않은 경우 흔히 발생합니다.","summary":"드라이버 자체는 정상적으로 로드됐지만 실제 하드웨어를 찾지 못할 때 나타나는 코드로, 마지막으로 장치를 제거했을 때 드라이버가 완전히 언로드되지 않은 경우 흔히 발생합니다.","causes":["장치를 안전하게 제거하지 않고 물리적으로 뽑은 경우","USB 장치가 절전 모드 진입 중 강제로 연결이 끊긴 경우","드라이버와 장치 펌웨어 버전이 맞지 않는 경우","USB 허브를 통한 연결에서 전력 부족으로 장치가 순간적으로 사라진 경우","가상화 소프트웨어가 장치를 다른 세션으로 전달하며 충돌한 경우"],"checks":["장치를 물리적으로 분리한 뒤 다시 연결해 재인식을 시도하세요.","PC를 완전히 재부팅해 드라이버 상태를 초기화하세요.","USB 허브를 거치지 않고 메인보드에 직접 연결해 전력 문제를 배제해 보세요.","장치 관리자에서 숨겨진 장치 표시를 켜고, 중복 등록된 이전 항목을 제거하세요.","제조사 최신 드라이버와 펌웨어로 업데이트해 보세요."],"link":"error-code-device-manager-code-41.html","detailPage":"error-code-device-manager-code-41.html","faq":[{"q":"장치가 인식이 안 되면 바로 새 제품을 사야 하나요?","a":"이 문제(코드 41)는 장치 고장보다 드라이버나 포트 설정 문제인 경우가 흔합니다. 다른 포트나 다른 PC에서 인식되는지 먼저 확인해보세요."},{"q":"다른 PC에서는 잘 되는 장치인데 인식이 안 되면 뭐가 문제인가요?","a":"장치 자체보다는 현재 PC의 USB 컨트롤러 드라이버나 전원 관리 설정 문제일 가능성이 높습니다."}],"decisionSteps":[{"condition":"재연결·재부팅으로 해결될 때","action":"재발 방지를 위해 항상 \"안전하게 제거\" 기능을 사용하세요."},{"condition":"본체 직결로 해결될 때","action":"허브의 전력 부족이 원인이었으므로 전원 공급형 허브를 사용하세요."},{"condition":"숨겨진 중복 항목 제거로도 해결되지 않을 때","action":"드라이버·펌웨어 업데이트로 넘어가세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["code41","코드41","device-manager-code-41"],"communityCases":[{"title":"부팅 USB 제거 후 정상 인식된 사례","summary":"PC 시작 시 저장장치에 코드 41이 표시됐던 사례에서, 부팅에 사용했던 USB가 계속 꽂혀 있던 것이 원인이었습니다. USB를 제거하고 재부팅하자 저장장치가 정상 인식됐습니다.","insight":"코드 41은 성공적으로 로드된 드라이버이지만 장치가 없다는 신호입니다. 먼저 모든 외장 장치를 제거하고 재부팅해 특정 장치가 충돌을 일으키는지 확인해보세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"오류 1603","title":"설치 중 치명적 오류가 발생했습니다 (오류 1603)","overview":"MSI(Windows Installer) 기반 설치 프로그램이 설치 도중 원인을 특정하기 어려운 치명적 오류를 만났을 때 나타나는 코드입니다. 실제로는 권한, 잔여 파일, 서비스 문제 등 다양한 원인이 이 하나의 코드로 뭉뚱그려 보고됩니다.","summary":"MSI(Windows Installer) 기반 설치 프로그램이 설치 도중 원인을 특정하기 어려운 치명적 오류를 만났을 때 나타나는 코드입니다.","causes":["이전 버전이 완전히 제거되지 않고 잔여 파일이나 레지스트리가 남아있는 경우","설치 대상 폴더나 레지스트리 키에 대한 접근 권한이 부족한 경우","Windows Installer 서비스 자체가 중지되었거나 손상된 경우","설치 파일이 다운로드 중 손상되었거나 불완전한 경우","보안 소프트웨어가 설치 프로세스의 파일 쓰기를 차단하는 경우"],"checks":["제조사의 전용 제거 도구(클린업 툴)로 이전 버전 잔여물을 완전히 정리한 뒤 재설치하세요.","설치 파일을 마우스 우클릭 후 '관리자 권한으로 실행'으로 다시 시도하세요.","서비스 관리자(services.msc)에서 Windows Installer 서비스가 실행 중인지 확인하세요.","설치 파일을 공식 홈페이지에서 다시 받아 무결성을 확인한 뒤 재시도하세요.","보안 프로그램을 임시로 비활성화한 뒤 설치를 다시 진행해 보세요."],"link":"error-code-1603.html","detailPage":"error-code-1603.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 1603)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"설치 로그는 어디서 확인하나요?","a":"%temp% 폴더의 MSI 로그 파일에서 실패 지점을 확인하면 원인을 더 정확히 좁힐 수 있습니다."}],"decisionSteps":[{"condition":"잔여물 정리만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"관리자 권한 실행으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"보안 프로그램 예외로도 해결되지 않을 때","action":"정품 인증 상태를 함께 점검하세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["1603","error1603","오류1603"],"communityCases":[{"title":"윈도우 재설치로 해결한 사례","summary":"그래픽카드를 새로 산 뒤 드라이버 설치할 때마다 이 오류가 발생했던 사례가 있습니다. 드라이버 제거·재설치, DISM, 파워쉘 스캔까지 구글에서 찾을 수 있는 모든 방법을 시도했지만 소용없었는데, 결국 윈도우를 새로 설치한 뒤에야 해결됐습니다. 하드웨어를 교체하면서 윈도우 정품 인증이 풀린 상태였던 것이 원인이었던 것으로 보입니다.","insight":"메인보드나 그래픽카드 같은 주요 부품을 교체한 직후 설치 오류가 반복된다면, 인증 상태가 꼬였을 가능성도 점검해볼 필요가 있습니다."}],"officialSource":{"title":"Microsoft Learn: MSI installation error 1603","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/application-management/msi-installation-error-1603"}},{"code":"오류 1618","title":"다른 설치가 진행 중입니다 (오류 1618)","overview":"이미 다른 Windows Installer 작업이 진행 중이라 새 설치나 제거를 시작할 수 없을 때 나타나는 오류입니다. 실제로는 이전 설치가 멈춰 있거나 비정상 종료된 잔여 프로세스인 경우가 많습니다.","summary":"이미 다른 Windows Installer 작업이 진행 중이라 새 설치나 제거를 시작할 수 없을 때 나타나는 오류입니다.","causes":["이전 설치/제거 작업이 완전히 끝나지 않고 백그라운드에 남아있는 경우","여러 설치 프로그램을 동시에 실행한 경우","이전 설치가 오류로 중단되며 Installer 프로세스가 종료되지 않은 경우","자동 업데이트 프로그램이 백그라운드에서 Installer를 점유하고 있는 경우","시스템 재부팅이 필요한 이전 작업이 완료되지 않은 경우"],"checks":["작업 관리자에서 msiexec.exe 프로세스가 실행 중인지 확인하고, 있다면 종료 후 재시도하세요.","PC를 재부팅한 뒤 다른 프로그램 없이 설치를 다시 시도하세요.","백그라운드 업데이트 프로그램(스토어, 자동 업데이트 유틸리티 등)을 일시 종료하세요.","동시에 여러 설치 프로그램을 실행하지 말고 하나씩 순서대로 진행하세요.","반복되면 시스템을 재부팅해 대기 중인 설치 작업을 완료시킨 뒤 다시 시도하세요."],"link":"error-code-1618.html","detailPage":"error-code-1618.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 1618)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"이전 버전을 지우지 않고 업데이트 설치하면 안 되나요?","a":"일부 프로그램은 가능하지만, 오류가 반복된다면 이전 버전을 완전히 제거한 뒤 재설치하는 것이 안전합니다."}],"decisionSteps":[{"condition":"msiexec.exe 종료만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"재부팅으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"백그라운드 업데이트 종료로도 해결되지 않을 때","action":"대기 중인 재부팅 작업이 남아있는지 확인하세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["1618","error1618","오류1618"],"communityCases":[{"title":"이전 설치 프로세스 종료 후 재시도로 해결","summary":"프로그램 설치 중 이 오류가 발생했던 사례에서, 작업 관리자를 보니 이전 설치 프로세스(msiexec.exe)가 아직 실행 중이었습니다. 해당 프로세스를 종료하고 다시 설치를 시도하자 정상적으로 완료됐습니다.","insight":"이 오류는 이전 설치 작업이 완전히 끝나지 않은 상태에서 새 설치를 시작할 때 발생합니다. 재부팅 후 재시도하거나 작업 관리자에서 msiexec.exe를 종료하세요."}],"officialSource":{"title":"Microsoft Learn: MsiExec.exe error codes — ERROR_INSTALL_ALREADY_RUNNING","url":"https://learn.microsoft.com/en-us/windows/win32/msi/error-codes"}},{"code":"오류 2503","title":"이 설치 패키지를 열 수 없습니다 (오류 2503)","overview":"설치 프로그램을 실행하는 계정에 임시 폴더나 설치 관련 권한이 부족할 때 나타나는 오류로, 관리자 계정에서도 UAC나 폴더 권한 설정에 따라 발생할 수 있습니다.","summary":"설치 프로그램을 실행하는 계정에 임시 폴더나 설치 관련 권한이 부족할 때 나타나는 오류로, 관리자 계정에서도 UAC나 폴더 권한 설정에 따라 발생할 수 있습니다.","causes":["임시 폴더(%TEMP%)에 대한 쓰기 권한이 없는 경우","사용자 계정 컨트롤(UAC) 설정이 설치 프로그램의 권한 요청을 막는 경우","설치 파일이 저장된 폴더나 드라이브의 권한이 제한된 경우","그룹 정책으로 소프트웨어 설치가 제한된 경우","임시 폴더 용량이 가득 찬 경우"],"checks":["설치 파일을 관리자 권한으로 실행해 보세요 (마우스 우클릭 > 관리자 권한으로 실행).","%TEMP% 폴더의 파일과 폴더 속성에서 현재 계정의 쓰기 권한을 확인하세요.","임시 파일을 정리해 %TEMP% 폴더에 충분한 여유 공간을 확보하세요.","설치 파일을 C 드라이브 등 권한 문제가 적은 위치로 옮긴 뒤 다시 실행해 보세요.","회사/학교 PC라면 그룹 정책으로 설치가 제한된 것은 아닌지 관리자에게 확인하세요."],"link":"error-code-2503.html","detailPage":"error-code-2503.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 2503)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"설치 오류가 백신 때문인지 어떻게 확인하나요?","a":"백신을 끄기 전에 차단·격리 기록과 설치 파일의 공식 출처를 확인하세요. 꼭 필요한 경우에만 짧게 보호 기능을 중지해 비교하고 설치가 끝나면 즉시 다시 켜세요."}],"decisionSteps":[{"condition":"관리자 권한 실행으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"임시 폴더 정리로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"설치 위치 이동으로도 해결되지 않을 때","action":"그룹 정책 확인으로 넘어가세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["2503","error2503","오류2503"],"communityCases":[{"title":"관리자 권한으로 설치하여 2503 해결","summary":"프로그램 설치 중 2503 오류가 발생했던 사례에서, 설치 파일을 오른쪽 클릭 후 관리자 권한으로 실행하자 정상 설치됐습니다. 일반 계정에서 설치를 시도해 접근 권한이 없었던 것이 원인이었습니다.","insight":"2503 오류는 설치 디렉토리 접근 권한 문제입니다. 항상 관리자 권한으로 설치 파일을 실행하세요."}],"officialSource":{"title":"Microsoft Learn: Windows Installer error messages","url":"https://learn.microsoft.com/en-us/windows/win32/msi/windows-installer-error-messages"}},{"code":"오류 2502","title":"이 설치 패키지를 열 수 없습니다 (오류 2502)","overview":"오류 2503과 함께 자주 나타나는 코드로, Windows Installer가 임시 설치 폴더를 초기화하지 못했을 때 발생합니다. 두 오류는 원인과 해결 방법이 거의 동일합니다.","summary":"오류 2503과 함께 자주 나타나는 코드로, Windows Installer가 임시 설치 폴더를 초기화하지 못했을 때 발생합니다.","causes":["임시 폴더 권한이나 소유권이 잘못 설정된 경우","이전 설치 실패로 임시 폴더에 잠긴 파일이 남아있는 경우","사용자 프로필이 손상되었거나 임시 폴더 경로가 유효하지 않은 경우","보안 소프트웨어가 임시 폴더 접근을 차단하는 경우","디스크 여유 공간 부족"],"checks":["%TEMP% 폴더로 이동해 파일 속성에서 소유자와 권한을 현재 계정으로 재설정하세요.","임시 폴더 안의 이전 설치 잔여 파일을 정리하세요.","설치 프로그램을 관리자 권한으로 다시 실행해 보세요.","보안 프로그램을 임시로 비활성화한 뒤 재시도하세요.","디스크 여유 공간을 확인하고 부족하면 정리하세요."],"link":"error-code-2502.html","detailPage":"error-code-2502.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 2502)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"설치 로그는 어디서 확인하나요?","a":"%temp% 폴더의 MSI 로그 파일에서 실패 지점을 확인하면 원인을 더 정확히 좁힐 수 있습니다."}],"decisionSteps":[{"condition":"권한 재설정으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"잔여 파일 정리로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"백신 예외 처리로도 해결되지 않을 때","action":"Windows Installer 서비스를 재시작해보세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["2502","error2502","오류2502"],"communityCases":[{"title":"Windows Installer 서비스 재시작으로 2502 해결","summary":"프로그램 설치 중 2502 오류가 반복됐던 사례에서, 서비스 관리자에서 Windows Installer 서비스가 중지되어 있었고 재시작하자 정상 설치됐습니다.","insight":"2502 오류는 Windows Installer 서비스 문제입니다. services.msc에서 Windows Installer 서비스 상태를 확인하고, 중지되어 있다면 시작하세요."}],"officialSource":{"title":"Microsoft Learn: Windows Installer error messages","url":"https://learn.microsoft.com/en-us/windows/win32/msi/windows-installer-error-messages"}},{"code":"오류 0x80070643","title":"설치 중 오류가 발생했습니다 (0x80070643)","overview":"주로 .NET Framework나 특정 재배포 패키지 설치 도중 나타나는 오류로, 구성 요소 손상이나 이전 설치 실패의 잔여 상태가 원인인 경우가 많습니다.","summary":"주로 .NET Framework나 특정 재배포 패키지 설치 도중 나타나는 오류로, 구성 요소 손상이나 이전 설치 실패의 잔여 상태가 원인인 경우가 많습니다.","causes":[".NET Framework 구성 요소가 손상된 경우","이전 설치나 업데이트가 실패한 채로 남아있는 경우","관련 윈도우 업데이트가 누락된 경우","레지스트리에 손상된 설치 기록이 남아있는 경우","디스크 오류로 설치 파일 일부가 손상된 경우"],"checks":[".NET Framework 복구 도구(마이크로소프트 공식 .NET Framework Repair Tool)를 실행해 보세요.","Windows Update에서 관련 누락된 업데이트가 있는지 확인하고 설치하세요.","제어판의 Windows 기능 켜기/끄기에서 .NET Framework를 껐다가 다시 켜 보세요.","sfc /scannow로 시스템 파일 손상 여부를 점검하세요.","설치 로그 파일을 확인해 구체적으로 어떤 구성 요소에서 실패했는지 확인하세요."],"link":"error-code-80070643.html","detailPage":"error-code-80070643.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 0x80070643)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"이전 버전을 지우지 않고 업데이트 설치하면 안 되나요?","a":"일부 프로그램은 가능하지만, 오류가 반복된다면 이전 버전을 완전히 제거한 뒤 재설치하는 것이 안전합니다."}],"decisionSteps":[{"condition":".NET 복구 도구로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"Windows 기능 껐다 켜기로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"sfc /scannow로도 해결되지 않을 때","action":"설치 로그에서 구체적으로 실패한 구성 요소를 확인해 수동으로 설치하세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["80070643","0x80070643"],"communityCases":[{"title":".NET Framework 복구로 0x80070643 해결","summary":"게임 클라이언트 설치 중 이 오류가 발생했던 사례에서, .NET Framework 상태를 확인하니 손상된 파일이 있었습니다. 마이크로소프트 공식 복구 도구로 .NET을 복구하자 설치가 정상 완료됐습니다.","insight":"이 오류는 .NET Framework나 Visual C++ 런타임 손상과 관련이 많습니다. 마이크로소프트 공식 복구 도구로 .NET Framework를 먼저 복구해보세요."}],"officialSource":{"title":"Microsoft Learn: MSI installation error 1603 (0x643)","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-server/application-management/msi-installation-error-1603"}},{"code":"오류 1935","title":"어셈블리 구성 요소 설치 중 오류 (오류 1935)","overview":"설치 프로그램이 .NET이나 Visual C++ 재배포 패키지 같은 어셈블리 구성 요소를 설치하는 과정에서 실패했을 때 나타나는 오류입니다.","summary":"설치 프로그램이 .NET이나 Visual C++ 재배포 패키지 같은 어셈블리 구성 요소를 설치하는 과정에서 실패했을 때 나타나는 오류입니다.","causes":["Visual C++ 재배포 패키지나 .NET Framework가 손상된 경우","Windows Installer 서비스가 손상된 경우","시스템 파일 손상으로 구성 요소 등록에 실패하는 경우","보안 소프트웨어가 구성 요소 설치를 차단하는 경우","디스크 배드섹터로 파일 일부가 손상된 경우"],"checks":["제어판에서 기존 Visual C++ 재배포 패키지를 제거한 뒤 최신 버전을 다시 설치하세요.",".NET Framework를 복구하거나 재설치해 보세요.","sfc /scannow와 DISM 복구 명령으로 시스템 파일을 점검하세요.","보안 프로그램을 임시로 비활성화한 뒤 재시도하세요.","디스크 상태를 chkdsk로 점검하세요."],"link":"error-code-1935.html","detailPage":"error-code-1935.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 1935)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"설치 오류가 백신 때문인지 어떻게 확인하나요?","a":"백신을 끄기 전에 차단·격리 기록과 설치 파일의 공식 출처를 확인하세요. 꼭 필요한 경우에만 짧게 보호 기능을 중지해 비교하고 설치가 끝나면 즉시 다시 켜세요."}],"decisionSteps":[{"condition":"재배포 패키지 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"sfc·DISM으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"chkdsk에서 배드섹터가 발견될 때","action":"디스크 교체를 검토하세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["1935","error1935","오류1935"],"communityCases":[{"title":"Visual C++ 재배포 패키지 재설치로 1935 해결","summary":"프로그램 설치 중 어셈블리 설치 실패 오류 1935가 발생했던 사례에서, Visual C++ 재배포 패키지를 모두 제거하고 최신 버전으로 재설치하자 오류가 사라졌습니다.","insight":"오류 1935는 .NET Framework나 Visual C++ 런타임 문제와 자주 연결됩니다. 마이크로소프트 공식 사이트에서 최신 Visual C++ 재배포 패키지를 재설치해보세요."}],"officialSource":{"title":"Microsoft Learn: Windows Installer error messages","url":"https://learn.microsoft.com/en-us/windows/win32/msi/windows-installer-error-messages"}},{"code":"오류 0x80070005 (설치)","title":"설치 관리자에게 액세스가 거부되었습니다","overview":"프로그램 설치나 제거 시 관리자 권한 부족이나 보안 정책으로 접근이 거부될 때 나타나는 오류입니다. 일반 오류 0x80070005와 원인은 비슷하지만 설치 상황에 특화되어 나타납니다.","summary":"프로그램 설치나 제거 시 관리자 권한 부족이나 보안 정책으로 접근이 거부될 때 나타나는 오류입니다.","causes":["설치 프로그램을 관리자 권한 없이 실행한 경우","설치 대상 폴더의 소유권이나 권한이 제한된 경우","그룹 정책으로 소프트웨어 설치가 제한된 경우","보안 소프트웨어가 설치 프로그램의 시스템 변경을 차단한 경우","사용자 계정 컨트롤(UAC) 설정이 지나치게 엄격한 경우"],"checks":["설치 파일을 마우스 우클릭 후 '관리자 권한으로 실행'으로 다시 시도하세요.","설치 대상 폴더(주로 Program Files)의 권한을 확인하세요.","회사/학교 PC라면 그룹 정책으로 설치가 제한됐는지 확인하세요.","보안 프로그램을 임시로 비활성화한 뒤 설치를 재시도하세요.","UAC 설정을 기본값으로 되돌린 뒤 다시 시도해 보세요."],"link":"error-code-install-access-denied.html","detailPage":"error-code-install-access-denied.html","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 0x80070005 (설치))는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"설치 로그는 어디서 확인하나요?","a":"%temp% 폴더의 MSI 로그 파일에서 실패 지점을 확인하면 원인을 더 정확히 좁힐 수 있습니다."}],"decisionSteps":[{"condition":"관리자 권한 실행으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"폴더 권한 확인으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"UAC 기본값 복원으로도 해결되지 않을 때","action":"그룹 정책 확인으로 넘어가세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["install-access-denied","설치액세스거부"],"communityCases":[{"title":"관리자 계정으로 전환하여 설치 성공","summary":"일반 사용자 계정으로 시스템 폴더에 접근하는 프로그램을 설치할 때 이 오류가 반복됐던 사례가 있습니다. 로컬 관리자 계정으로 전환해 설치하자 정상 완료됐습니다.","insight":"이 오류는 파일 또는 레지스트리 접근 권한 부족이 원인입니다. 관리자 권한으로 실행하는 것과 실제 관리자 계정으로 로그인하는 것은 다를 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_ACCESS_DENIED","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"오류 1719","title":"Windows Installer 서비스를 사용할 수 없습니다 (오류 1719)","overview":"프로그램 설치나 제거에 필요한 Windows Installer 서비스 자체에 접근할 수 없을 때 나타나는 오류로, 서비스가 중지됐거나 레지스트리 등록이 손상된 경우 발생합니다.","summary":"프로그램 설치나 제거에 필요한 Windows Installer 서비스 자체에 접근할 수 없을 때 나타나는 오류로, 서비스가 중지됐거나 레지스트리 등록이 손상된 경우 발생합니다.","causes":["Windows Installer 서비스가 중지되어 있거나 비활성화된 경우","msiexec.exe 실행 파일의 레지스트리 등록이 손상된 경우","그룹 정책으로 Windows Installer 사용이 제한된 경우","타사 프로그램이 Windows Installer 서비스를 변경한 경우","시스템 파일 손상으로 서비스가 제대로 초기화되지 않는 경우"],"checks":["서비스 관리자(services.msc)에서 Windows Installer 서비스 상태를 확인하고 시작으로 설정하세요.","명령 프롬프트(관리자)에서 msiexec /unregister 후 msiexec /regserver를 실행해 재등록하세요.","그룹 정책 편집기에서 Windows Installer 관련 제한 설정이 있는지 확인하세요.","sfc /scannow로 시스템 파일 손상 여부를 점검하세요.","그래도 해결되지 않으면 시스템 복원 지점을 이용해 이전 상태로 되돌려 보세요."],"link":"error-code-1719.html","detailPage":"error-code-1719.html","narrative":"이 오류의 핵심은 '설치하려는 프로그램'이 아니라 '설치를 담당하는 시스템 서비스' 자체에 있다는 점입니다. Windows Installer는 모든 .msi 기반 설치·제거 작업을 처리하는 백그라운드 서비스인데, 이 서비스가 꺼져 있거나 등록 정보가 꼬이면 어떤 프로그램을 설치하려 해도 똑같은 1719 오류가 뜹니다. 그래서 설치 파일을 다시 받기 전에, 이 서비스 자체가 정상 실행 중인지부터 확인하는 게 순서를 절약하는 길입니다.","faq":[{"q":"설치 오류가 나면 프로그램을 다시 받으면 되나요?","a":"이 문제(오류 1719)는 설치 파일보다 Windows Installer 서비스나 잔여 파일이 원인인 경우가 많아, 재다운로드 전에 서비스 상태와 이전 설치 흔적부터 정리해보세요."},{"q":"이전 버전을 지우지 않고 업데이트 설치하면 안 되나요?","a":"일부 프로그램은 가능하지만, 오류가 반복된다면 이전 버전을 완전히 제거한 뒤 재설치하는 것이 안전합니다."}],"decisionSteps":[{"condition":"서비스 시작 상태 변경만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"msiexec 재등록으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"그룹 정책 확인으로도 해결되지 않을 때","action":"시스템 복원 지점을 이용해 이전 상태로 되돌리는 것을 고려하세요."}],"relatedSymptom":"windows-install-failure.html","aliases":["1719","error1719","오류1719"],"communityCases":[{"title":"Windows Installer 재등록으로 1719 해결","summary":"설치 프로그램을 실행할 때마다 Windows Installer 서비스에 접근할 수 없다는 오류 1719가 발생했던 사례가 있습니다. 명령 프롬프트에서 msiexec /unregister 후 msiexec /regserver를 실행해 재등록하자 정상 작동했습니다.","insight":"오류 1719는 Windows Installer 서비스 등록 문제입니다. msiexec /unregister와 /regserver 명령으로 재등록하는 방법이 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Windows Installer error messages","url":"https://learn.microsoft.com/en-us/windows/win32/msi/windows-installer-error-messages"}},{"code":"0xc0000142","title":"응용 프로그램을 정상적으로 시작하지 못했습니다 (0xc0000142)","overview":"프로그램이 실행되는 과정에서 필요한 초기화 작업을 완료하지 못했을 때 나타나는 매우 흔한 오류입니다. DLL 충돌이나 손상된 사용자 프로필, 그래픽 드라이버 문제가 대표적인 원인입니다.","summary":"프로그램이 실행되는 과정에서 필요한 초기화 작업을 완료하지 못했을 때 나타나는 매우 흔한 오류입니다.","causes":["프로그램이 의존하는 DLL 파일이 손상되었거나 버전이 맞지 않는 경우","그래픽 드라이버가 오래되었거나 프로그램과 호환되지 않는 경우","바이러스 백신이 프로그램의 정상적인 초기화 과정을 차단하는 경우","사용자 프로필이나 임시 폴더에 문제가 있는 경우","프로그램 설치 파일 자체가 손상된 경우"],"checks":["PC를 재부팅한 뒤 프로그램을 다시 실행해 보세요.","그래픽 드라이버를 제조사 최신 버전으로 업데이트하세요.","백신 프로그램을 임시로 비활성화한 뒤 재시도해 보세요.","프로그램을 관리자 권한으로 실행해 보세요.","문제가 계속되면 프로그램을 완전히 제거한 뒤 재설치해 보세요."],"link":"error-code-c0000142.html","detailPage":"error-code-c0000142.html","faq":[{"q":"앱이 실행되지 않으면 무조건 재설치해야 하나요?","a":"이 문제(0xc0000142)는 재설치보다 런타임 구성 요소(비주얼 C++ 등) 문제인 경우가 많아, 재설치 전에 필수 구성 요소부터 점검하는 것이 좋습니다."},{"q":"필수 구성 요소(Visual C++ 등)를 어떻게 확인하나요?","a":"제어판의 프로그램 목록에서 Visual C++ Redistributable이 설치되어 있는지 확인하고, 없다면 Microsoft 공식 사이트에서 받아 설치해야 합니다."}],"decisionSteps":[{"condition":"재부팅으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"그래픽 드라이버 업데이트로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"재설치로도 해결되지 않을 때","action":"사용자 프로필 손상 가능성이 있으니 새 계정에서 재현 여부를 테스트하세요."}],"relatedSymptom":"windows-app-not-launching.html","aliases":["c0000142","0xc0000142"],"communityCases":[{"title":"Visual C++ 재배포 패키지 설치로 해결","summary":"오래된 게임을 실행할 때 이 오류가 발생했던 사례가 있습니다. 해당 게임이 요구하는 구버전 Visual C++ 재배포 패키지가 설치되어 있지 않았고, 마이크로소프트 공식 사이트에서 해당 버전을 설치하자 정상 실행됐습니다.","insight":"이 오류는 필요한 DLL이나 런타임 라이브러리가 없을 때 자주 발생합니다. 실행 안 되는 프로그램의 설치 요구사항에 명시된 Visual C++ 버전을 확인하고 설치하세요."}],"officialSource":{"title":"Microsoft Learn: Application Failed to Initialize (0xc0000142)","url":"https://learn.microsoft.com/en-us/archive/blogs/winsdk/what-is-up-with-the-application-failed-to-initialize-properly-0xc0000142-error"}},{"code":"0xc000007b","title":"응용 프로그램을 정상적으로 시작하지 못했습니다 (0xc000007b)","overview":"32비트와 64비트 구성 요소가 서로 맞지 않을 때 나타나는 대표적인 오류입니다. 게임이나 오래된 프로그램을 실행할 때 특히 자주 나타나며, DLL 파일의 아키텍처 불일치가 핵심 원인입니다.","summary":"32비트와 64비트 구성 요소가 서로 맞지 않을 때 나타나는 대표적인 오류입니다.","causes":["32비트용 DLL과 64비트용 프로그램이 섞여 있는 경우","Visual C++ 재배포 패키지가 누락되었거나 손상된 경우","DirectX 구성 요소가 오래되었거나 손상된 경우",".NET Framework가 손상된 경우","프로그램 설치 파일 자체가 손상되었거나 불완전하게 설치된 경우"],"checks":["Visual C++ 재배포 패키지(x86, x64 버전 모두)를 최신 버전으로 재설치하세요.","DirectX 최종 사용자 런타임을 마이크로소프트 공식 사이트에서 다시 설치하세요.",".NET Framework를 복구하거나 재설치해 보세요.","프로그램을 완전히 제거한 뒤 관리자 권한으로 재설치하세요.","그래픽 드라이버를 최신 버전으로 업데이트하세요."],"link":"error-code-c000007b.html","detailPage":"error-code-c000007b.html","faq":[{"q":"앱이 실행되지 않으면 무조건 재설치해야 하나요?","a":"이 문제(0xc000007b)는 재설치보다 런타임 구성 요소(비주얼 C++ 등) 문제인 경우가 많아, 재설치 전에 필수 구성 요소부터 점검하는 것이 좋습니다."},{"q":"호환성 모드로 실행하면 도움이 되나요?","a":"오래된 프로그램이라면 호환성 모드가 도움이 될 수 있지만, 최신 프로그램의 오류라면 다른 원인을 먼저 점검해야 합니다."}],"decisionSteps":[{"condition":"재배포 패키지 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"DirectX·.NET 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"재설치로도 해결되지 않을 때","action":"프로그램이 32비트인지 64비트인지 확인해 시스템 아키텍처와 맞는 버전으로 재설치하세요."}],"relatedSymptom":"windows-app-not-launching.html","aliases":["c000007b","0xc000007b"],"communityCases":[{"title":"64비트 Visual C++ 재배포 패키지로 0xc000007b 해결","summary":"64비트 게임을 실행할 때 이 오류가 발생했던 사례에서, 시스템 폴더에 같은 이름의 32비트 DLL 파일이 설치되어 혼재하는 것이 원인이었습니다. DirectX와 Visual C++ 재배포 패키지를 64비트 정식 버전으로 재설치하자 정상 실행됐습니다.","insight":"이 오류는 64비트 앱이 32비트 DLL을 로드하려 할 때 발생합니다. DirectX, Visual C++ 재배포 패키지를 최신 64비트 버전으로 재설치하는 것이 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Diagnosing STATUS_INVALID_IMAGE_FORMAT","url":"https://learn.microsoft.com/en-us/archive/blogs/dsvc/diagnosing-status_invalid_image_format-c000007b-errors"}},{"code":"0xc0000005","title":"액세스 위반 오류 (0xc0000005)","overview":"프로그램이 접근 권한이 없는 메모리 영역에 접근을 시도했을 때 나타나는 오류입니다. 프로그램 버그, 손상된 파일, 메모리 문제, 보안 소프트웨어 충돌 등 다양한 원인이 있습니다.","summary":"프로그램이 접근 권한이 없는 메모리 영역에 접근을 시도했을 때 나타나는 오류입니다.","causes":["프로그램 자체의 메모리 접근 버그","램 모듈이 불안정하거나 손상된 경우","보안 소프트웨어가 프로그램의 메모리 접근을 잘못 차단하는 경우","프로그램 설치 파일이나 실행 파일이 손상된 경우","다른 프로그램과의 DLL 충돌"],"checks":["메모리 진단 도구로 램 상태를 점검하세요.","보안 프로그램을 임시로 비활성화한 뒤 재시도해 보세요.","프로그램을 완전히 제거한 뒤 최신 버전으로 재설치하세요.","다른 프로그램을 모두 종료한 상태에서 다시 실행해 DLL 충돌 여부를 확인하세요.","윈도우와 해당 프로그램을 모두 최신 버전으로 업데이트하세요."],"link":"error-code-c0000005.html","detailPage":"error-code-c0000005.html","faq":[{"q":"앱이 실행되지 않으면 무조건 재설치해야 하나요?","a":"이 문제(0xc0000005)는 재설치보다 런타임 구성 요소(비주얼 C++ 등) 문제인 경우가 많아, 재설치 전에 필수 구성 요소부터 점검하는 것이 좋습니다."},{"q":"바이러스 때문에 실행이 차단된 걸 수도 있나요?","a":"백신이 오탐으로 실행 파일을 격리했을 수 있으므로, 백신의 격리소·검역소 목록을 확인하는 것도 방법입니다."}],"decisionSteps":[{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."},{"condition":"재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"특정 프로그램에서만 반복될 때","action":"그 프로그램의 버그일 가능성이 크므로 제조사에 문의하거나 업데이트를 기다리세요."}],"relatedSymptom":"windows-app-not-launching.html","aliases":["c0000005","0xc0000005"],"communityCases":[{"title":"메모리 진단으로 RAM 문제 발견 후 교체 해결","summary":"특정 앱 실행 중 이 오류가 반복됐던 사례에서, 처음엔 앱 손상으로 생각해 재설치를 반복했지만 해결되지 않았습니다. Windows 메모리 진단을 실행하니 RAM에서 오류가 발견됐고, RAM을 교체하자 오류가 사라졌습니다.","insight":"이 오류는 소프트웨어 문제뿐 아니라 RAM 불량으로도 발생합니다. 재설치로 해결이 안 된다면 메모리 진단 도구로 RAM 상태를 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Access Violation C0000005","url":"https://learn.microsoft.com/en-us/shows/inside/c0000005"}},{"code":"MSVCP140.dll 오류","title":"MSVCP140.dll이 없어서 프로그램을 시작할 수 없습니다","overview":"Visual C++ 재배포 패키지에 포함된 런타임 라이브러리 파일이 없거나 손상되었을 때 나타나는 오류로, 게임이나 여러 프로그램에서 공통으로 요구하는 파일이라 매우 자주 발생합니다.","summary":"Visual C++ 재배포 패키지에 포함된 런타임 라이브러리 파일이 없거나 손상되었을 때 나타나는 오류로, 게임이나 여러 프로그램에서 공통으로 요구하는 파일이라 매우 자주 발생합니다.","causes":["Visual C++ 재배포 패키지가 설치되어 있지 않은 경우","설치된 재배포 패키지가 손상되었거나 버전이 맞지 않는 경우","다른 프로그램을 제거하는 과정에서 공유 DLL 파일이 함께 삭제된 경우","인터넷에서 개별적으로 받은 DLL 파일을 잘못된 위치에 넣은 경우","시스템 파일 손상"],"checks":["마이크로소프트 공식 홈페이지에서 Visual C++ 재배포 패키지(x86, x64 모두)를 새로 받아 설치하세요.","기존에 설치된 재배포 패키지가 있다면 먼저 제거한 뒤 깨끗하게 재설치하세요.","DLL 파일을 인터넷에서 개별적으로 받아 넣는 방법은 권장하지 않습니다 — 출처가 불분명한 파일은 보안 위험이 있습니다.","sfc /scannow로 시스템 파일 손상 여부를 점검하세요.","문제가 되는 프로그램을 재설치해 필요한 구성 요소를 함께 설치하세요."],"link":"error-code-msvcp140.html","detailPage":"error-code-msvcp140.html","faq":[{"q":"앱이 실행되지 않으면 무조건 재설치해야 하나요?","a":"이 문제(MSVCP140.dll 오류)는 재설치보다 런타임 구성 요소(비주얼 C++ 등) 문제인 경우가 많아, 재설치 전에 필수 구성 요소부터 점검하는 것이 좋습니다."},{"q":"필수 구성 요소(Visual C++ 등)를 어떻게 확인하나요?","a":"제어판의 프로그램 목록에서 Visual C++ Redistributable이 설치되어 있는지 확인하고, 없다면 Microsoft 공식 사이트에서 받아 설치해야 합니다."}],"decisionSteps":[{"condition":"재배포 패키지 재설치만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"프로그램 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"sfc 검사로도 해결되지 않을 때","action":"다른 프로그램에서도 같은 오류가 나는지 확인해 시스템 전체 문제인지 좁혀보세요."}],"relatedSymptom":"windows-app-not-launching.html","aliases":["msvcp140","msvcp140dll"],"communityCases":[{"title":"Visual C++ 2015-2022 재배포 패키지 설치로 해결","summary":"게임이나 프로그램 실행 시 MSVCP140.dll을 찾을 수 없다는 오류가 발생했던 사례가 있습니다. 마이크로소프트 공식 사이트에서 Visual C++ 2015-2022 재배포 패키지(x64, x86 모두)를 설치하자 오류가 사라졌습니다.","insight":"MSVCP140.dll은 Visual C++ 2015 이상의 재배포 패키지에 포함된 파일입니다. 인터넷에서 개별 DLL 파일을 내려받는 것은 위험하므로, 반드시 마이크로소프트 공식 페이지에서 재배포 패키지 전체를 설치하세요."}],"officialSource":{"title":"Microsoft Learn: Latest supported Visual C++ Redistributable downloads","url":"https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist"}},{"code":"이 앱이 PC에서 실행되지 않습니다","title":"이 앱이 사용자의 PC에서 실행되지 않습니다","overview":"프로그램의 아키텍처(32비트/64비트)가 현재 시스템과 맞지 않거나, 윈도우 버전 호환성 문제로 실행이 차단될 때 나타나는 메시지입니다.","summary":"프로그램의 아키텍처(32비트/64비트)가 현재 시스템과 맞지 않거나, 윈도우 버전 호환성 문제로 실행이 차단될 때 나타나는 메시지입니다.","causes":["32비트 전용 프로그램을 지원하지 않는 환경에서 실행하려는 경우 (드물게)","프로그램이 요구하는 윈도우 버전보다 낮거나 호환되지 않는 버전을 사용 중인 경우","다운로드한 설치 파일이 손상되었거나 위조된 경우","스마트스크린이나 보안 정책이 실행을 차단한 경우","그룹 정책으로 특정 프로그램 실행이 제한된 경우"],"checks":["프로그램 공식 홈페이지에서 시스템 요구 사항(윈도우 버전, 32/64비트)을 확인하세요.","설치 파일을 다시 받아 무결성을 확인한 뒤 재설치하세요.","메시지가 뜬 파일을 우클릭 > 속성에서 '차단 해제' 옵션이 있다면 체크하세요.","윈도우를 최신 버전으로 업데이트한 뒤 다시 시도하세요.","회사/학교 PC라면 그룹 정책으로 제한된 프로그램인지 확인하세요."],"link":"error-code-app-cant-run-on-pc.html","detailPage":"error-code-app-cant-run-on-pc.html","faq":[{"q":"앱이 실행되지 않으면 무조건 재설치해야 하나요?","a":"이 문제(이 앱이 PC에서 실행되지 않습니다)는 재설치보다 런타임 구성 요소(비주얼 C++ 등) 문제인 경우가 많아, 재설치 전에 필수 구성 요소부터 점검하는 것이 좋습니다."},{"q":"호환성 모드로 실행하면 도움이 되나요?","a":"오래된 프로그램이라면 호환성 모드가 도움이 될 수 있지만, 최신 프로그램의 오류라면 다른 원인을 먼저 점검해야 합니다."}],"decisionSteps":[{"condition":"시스템 요구사항 불일치가 확인될 때","action":"현재 시스템과 호환되는 버전을 다시 받으세요."},{"condition":"차단 해제로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"그룹 정책 제한이 확인될 때","action":"관리자에게 예외 등록을 요청하세요."}],"relatedSymptom":"windows-app-not-launching.html","aliases":["app-cant-run-on-pc","이앱이실행되지않습니다"],"communityCases":[{"title":"64비트 지원 버전 찾아 설치하여 해결","summary":"인터넷에서 내려받은 구형 설치 파일을 실행하려 했는데 이 오류가 발생했던 사례가 있습니다. 파일이 16비트 또는 매우 오래된 32비트 앱이어서 64비트 윈도우에서 실행할 수 없었습니다. 제조사에서 64비트 지원 버전을 찾아 설치하거나 대안 프로그램을 사용했습니다.","insight":"이 오류는 앱이 현재 윈도우 버전 또는 프로세서 아키텍처와 호환되지 않을 때 나타납니다. 해당 앱의 최신 버전이나 64비트 버전이 있는지 먼저 확인하세요."}],"officialSource":{"title":"Microsoft 지원: Make older apps compatible with Windows","url":"https://support.microsoft.com/en-us/windows/make-older-apps-or-programs-compatible-with-the-latest-version-of-windows-783d6dd7-b439-bdb0-0490-54eea0f45938"}},{"code":"브라우저 응답 없음","title":"브라우저가 응답하지 않습니다","overview":"크롬, 엣지 등 브라우저가 멈추거나 '응답 없음' 상태가 되는 증상으로, 확장 프로그램 충돌이나 과도한 탭, 캐시 문제가 흔한 원인입니다.","summary":"크롬, 엣지 등 브라우저가 멈추거나 '응답 없음' 상태가 되는 증상으로, 확장 프로그램 충돌이나 과도한 탭, 캐시 문제가 흔한 원인입니다.","causes":["너무 많은 탭이나 확장 프로그램이 동시에 실행되어 메모리를 과도하게 사용하는 경우","특정 확장 프로그램이 브라우저와 충돌하는 경우","브라우저 캐시나 프로필 데이터가 손상된 경우","그래픽 하드웨어 가속 기능이 시스템과 맞지 않는 경우","특정 웹페이지의 스크립트가 무한 반복되며 리소스를 소모하는 경우"],"checks":["작업 관리자에서 브라우저 프로세스를 종료한 뒤 다시 실행해 보세요.","불필요한 탭과 확장 프로그램을 정리하세요.","확장 프로그램을 모두 비활성화한 뒤 하나씩 다시 켜서 원인을 찾아보세요.","브라우저 설정에서 캐시와 방문 기록을 정리해 보세요.","브라우저 설정에서 하드웨어 가속 기능을 꺼 보고 재현 여부를 확인하세요."],"link":"error-code-browser-not-responding.html","detailPage":"error-code-browser-not-responding.html","faq":[{"q":"브라우저가 자주 멈추면 다른 브라우저로 바꿔야 하나요?","a":"이 문제(브라우저 응답 없음)는 브라우저 자체보다 확장 프로그램이나 캐시 문제인 경우가 많아, 브라우저를 바꾸기 전에 확장 프로그램 정리부터 시도해보세요."}],"decisionSteps":[{"condition":"확장 프로그램 하나를 켰을 때 다시 멈출 때","action":"그 확장 프로그램을 제거하거나 최신 버전으로 업데이트하세요."},{"condition":"하드웨어 가속을 껐을 때 안정될 때","action":"그래픽 드라이버 문제이므로 드라이버를 최신 버전으로 업데이트하세요."},{"condition":"위 항목이 모두 정상인데 특정 사이트에서만 멈출 때","action":"그 사이트 자체의 리소스 사용량 문제일 수 있으니 다른 사이트와 비교해 확인하세요."}],"relatedSymptom":"windows-browser-not-responding.html","aliases":["browser-not-responding","브라우저응답없음"],"communityCases":[{"title":"확장 프로그램 비활성화로 브라우저 멈춤 해결","summary":"크롬 브라우저가 특정 사이트에서만 응답 없음 상태가 됐던 사례가 있습니다. 확장 프로그램을 모두 비활성화하자 정상 작동했고, 하나씩 다시 활성화해보니 특정 광고 차단 확장이 원인이었습니다. 해당 확장을 업데이트하자 문제가 해결됐습니다.","insight":"브라우저 멈춤의 원인 중 확장 프로그램 충돌이 의외로 많습니다. 시크릿 모드(확장 비활성화)에서 재현되지 않는다면 확장 프로그램부터 점검하세요."}],"officialSource":{"title":"Google Chrome 고객센터: Fix Chrome if it crashes","url":"https://support.google.com/chrome/answer/142063"}},{"code":"Aw Snap 오류","title":"이런! 페이지 로드 중 문제가 발생했습니다 (Aw, Snap!)","overview":"크롬 기반 브라우저에서 특정 탭이 크래시하며 나타나는 오류 화면으로, 메모리 부족이나 확장 프로그램, GPU 드라이버 문제가 흔한 원인입니다.","summary":"크롬 기반 브라우저에서 특정 탭이 크래시하며 나타나는 오류 화면으로, 메모리 부족이나 확장 프로그램, GPU 드라이버 문제가 흔한 원인입니다.","causes":["시스템 메모리가 부족해 탭 프로세스가 강제 종료된 경우","특정 확장 프로그램이 페이지와 충돌하는 경우","그래픽 드라이버가 오래되어 하드웨어 가속 렌더링에 실패하는 경우","브라우저 프로필이나 캐시가 손상된 경우","해당 웹페이지 자체의 스크립트 오류나 과도한 리소스 사용"],"checks":["다른 탭을 정리해 메모리 여유를 확보한 뒤 새로고침해 보세요.","확장 프로그램을 모두 끄고 재현되는지 확인하세요.","그래픽 드라이버를 최신 버전으로 업데이트하세요.","브라우저를 최신 버전으로 업데이트하세요.","새 프로필(사용자)을 만들어 같은 문제가 재현되는지 확인해 보세요."],"link":"error-code-aw-snap.html","detailPage":"error-code-aw-snap.html","faq":[{"q":"브라우저가 자주 멈추면 다른 브라우저로 바꿔야 하나요?","a":"이 문제(Aw Snap 오류)는 브라우저 자체보다 확장 프로그램이나 캐시 문제인 경우가 많아, 브라우저를 바꾸기 전에 확장 프로그램 정리부터 시도해보세요."}],"decisionSteps":[{"condition":"하드웨어 가속을 껐을 때 재현되지 않으면","action":"그래픽 드라이버 문제이므로 드라이버를 최신 버전으로 업데이트하세요."},{"condition":"확장 프로그램 하나를 끄니 안정되면","action":"해당 확장 프로그램을 제거하거나 최신 버전으로 교체하세요."},{"condition":"새 프로필에서는 재현되지 않으면","action":"기존 프로필의 캐시나 설정 손상이 원인이므로, 북마크를 내보낸 뒤 프로필을 삭제하고 새로 만드는 것을 고려하세요."}],"relatedSymptom":"windows-browser-not-responding.html","aliases":["aw-snap","aw스냅"],"communityCases":[{"title":"GPU 가속 비활성화로 Aw Snap 오류 해결","summary":"특정 웹페이지에서만 Aw Snap 오류가 발생하던 사례가 있습니다. 크롬 설정에서 하드웨어 가속(GPU 가속)을 끄자 해당 페이지가 정상적으로 열렸습니다. 그래픽 드라이버와 크롬의 GPU 가속 호환성 문제가 원인이었습니다.","insight":"Aw Snap 오류가 그래픽 콘텐츠가 많은 페이지에서만 발생한다면 GPU 가속 비활성화를 시도해보세요. 크롬 설정 > 시스템 > 하드웨어 가속 사용에서 설정할 수 있습니다."}],"officialSource":{"title":"Google Chrome 고객센터: 페이지 로드 오류","url":"https://support.google.com/chrome/answer/6098869"}},{"code":"0xc0000022","title":"응용 프로그램을 정상적으로 시작하지 못했습니다 (0xc0000022)","overview":"프로그램 실행에 필요한 권한이 거부되어 시작하지 못할 때 나타나는 오류입니다. 보안 정책이나 파일 권한 문제가 주요 원인입니다.","summary":"프로그램 실행에 필요한 권한이 거부되어 시작하지 못할 때 나타나는 오류입니다.","causes":["프로그램 실행 파일이나 폴더의 권한이 제한된 경우","그룹 정책으로 특정 프로그램 실행이 차단된 경우","보안 소프트웨어가 실행 권한을 차단하는 경우","사용자 계정 컨트롤(UAC) 설정 문제","프로그램이 손상되어 필요한 권한 요청 자체가 실패하는 경우"],"checks":["프로그램을 관리자 권한으로 실행해 보세요.","실행 파일이 있는 폴더의 보안 속성에서 현재 계정 권한을 확인하세요.","보안 프로그램을 임시로 비활성화한 뒤 재시도해 보세요.","회사/학교 PC라면 그룹 정책으로 제한된 프로그램인지 확인하세요.","프로그램을 재설치해 권한 관련 파일을 새로 등록하세요."],"link":"error-code-c0000022.html","detailPage":"error-code-c0000022.html","faq":[{"q":"앱이 실행되지 않으면 무조건 재설치해야 하나요?","a":"이 문제(0xc0000022)는 재설치보다 런타임 구성 요소(비주얼 C++ 등) 문제인 경우가 많아, 재설치 전에 필수 구성 요소부터 점검하는 것이 좋습니다."},{"q":"바이러스 때문에 실행이 차단된 걸 수도 있나요?","a":"백신이 오탐으로 실행 파일을 격리했을 수 있으므로, 백신의 격리소·검역소 목록을 확인하는 것도 방법입니다."}],"decisionSteps":[{"condition":"관리자 권한 실행으로 해결될 때","action":"바로가기 속성에서 항상 관리자 권한으로 실행되도록 설정하세요."},{"condition":"그룹 정책 제한이 확인될 때","action":"회사·학교 관리자에게 예외 등록을 요청하세요."},{"condition":"재설치 후에도 반복될 때","action":"비주얼 C++ 재배포 패키지 같은 필수 런타임이 설치되어 있는지 확인하세요."}],"relatedSymptom":"windows-app-not-launching.html","aliases":["c0000022","0xc0000022"],"communityCases":[{"title":"sfc /scannow로 시스템 파일 권한 복구 후 해결","summary":"윈도우 보안 업데이트 이후 특정 시스템 DLL에 대한 접근 권한이 바뀌면서 프로그램이 실행되지 않는 사례가 있었습니다. sfc /scannow로 시스템 파일을 복구하자 정상 실행됐습니다.","insight":"이 오류는 프로그램이 필요한 파일에 접근 권한을 거부당했을 때 발생합니다. 보안 업데이트 이후 발생했다면 sfc /scannow로 시스템 파일 권한을 복구해보세요."}],"officialSource":{"title":"Microsoft Learn: STATUS_ACCESS_DENIED (0xc0000022)","url":"https://learn.microsoft.com/en-us/answers/questions/3997486/failed-to-start-with-the-following-error-0xc000002"}},{"code":"뱅가드 오류","title":"라이엇 뱅가드(Vanguard) 오류로 게임이 실행되지 않음","overview":"발로란트와 리그 오브 레전드가 공용으로 사용하는 안티치트 프로그램 '라이엇 뱅가드'가 정상적으로 시작되지 않아 게임 실행이 막히는 증상입니다. VAN으로 시작하는 오류 코드와 함께 나타나는 경우가 많고, 뱅가드 서비스 자체가 꺼져 있거나 다른 프로그램과 충돌하는 것이 주요 원인입니다.","summary":"발로란트와 리그 오브 레전드가 공용으로 사용하는 안티치트 프로그램 '라이엇 뱅가드'가 정상적으로 시작되지 않아 게임 실행이 막히는 증상입니다.","causes":["뱅가드 커널 서비스(vgc)가 실행되지 않은 상태인 경우","다른 보안 프로그램이나 가상화 소프트웨어가 뱅가드와 충돌하는 경우","뱅가드 설치가 손상되었거나 최신 버전이 아닌 경우","PC를 재부팅하지 않고 여러 번 게임을 재시작한 경우","보안 프로그램이 뱅가드 드라이버 설치 자체를 차단한 경우"],"checks":["작업 관리자의 '서비스' 탭에서 vgc 서비스가 '중지됨'으로 표시되어 있는지 확인하고, 중지되어 있다면 마우스 우클릭으로 시작하세요.","PC를 완전히 재부팅한 뒤 다시 접속을 시도해보세요.","제어판에서 라이엇 뱅가드를 완전히 제거한 뒤 게임 클라이언트를 다시 실행해 새로 설치되게 하세요.","타사 보안 프로그램이나 가상화 소프트웨어(VMware, VPN 등)를 임시로 종료한 뒤 재시도하세요.","그래도 해결되지 않으면 라이엇 공식 지원 페이지의 뱅가드 직접 제거 가이드를 참고하세요."],"link":"error-code-vanguard-error.html","detailPage":"error-code-vanguard-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(뱅가드 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"안티치트 오류는 항상 게임사 문제인가요?","a":"게임사 서버 문제일 수도 있지만, 상당수는 로컬 PC의 드라이버·백신 충돌이 원인이므로 먼저 자가 점검을 해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"vgc 서비스 시작만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"재부팅으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"뱅가드 재설치로도 해결되지 않을 때","action":"타사 보안 프로그램의 차단 기록을 다시 확인하세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["vanguard-error","뱅가드오류","van오류"],"communityCases":[{"title":"vgc 서비스 수동 시작으로 해결한 사례","summary":"발로란트 접속이 갑자기 안 되거나 뱅가드 오류가 반복될 때, 작업 관리자의 서비스 탭에서 'vgc' 서비스가 중지된 상태였던 경우가 많았습니다. 마우스 우클릭으로 서비스를 다시 시작한 뒤 곧바로 정상 접속됐습니다.","insight":"뱅가드 오류가 났을 때 재설치부터 하기보다, 먼저 vgc 서비스 상태를 확인하는 게 훨씬 빠른 해결책인 경우가 많습니다."}],"officialSource":{"title":"Riot 지원: VALORANT 오류 코드 및 해결 방법","url":"https://support.riotgames.com/ko/valorant/performance/error-codes-and-solutions-in-valorant"}},{"code":"이지 안티치트 오류","title":"EasyAntiCheat 오류로 게임 실행 불가 (배틀그라운드 등)","overview":"배틀그라운드, 에이펙스 레전드 등 여러 게임이 공용으로 사용하는 EasyAntiCheat(EAC) 서비스가 초기화에 실패하거나 게임 파일과 충돌할 때 나타나는 오류입니다.","summary":"배틀그라운드, 에이펙스 레전드 등 여러 게임이 공용으로 사용하는 EasyAntiCheat(EAC) 서비스가 초기화에 실패하거나 게임 파일과 충돌할 때 나타나는 오류입니다.","causes":["EasyAntiCheat 서비스가 설치되지 않았거나 손상된 경우","게임 파일 일부가 손상되어 EAC 서명 검증에 실패하는 경우","다른 게임의 안티치트 프로그램과 충돌하는 경우","Windows가 최신 업데이트 상태가 아닌 경우","보안 프로그램이 EAC 서비스를 오탐지해 차단하는 경우"],"checks":["게임 설치 폴더의 EasyAntiCheat 하위 폴더에서 EasyAntiCheat_Setup.exe를 관리자 권한으로 실행해 복구를 시도하세요.","게임 런처에서 파일 무결성 검사(파일 확인/복구) 기능을 실행하세요.","Windows를 최신 버전으로 업데이트하세요.","다른 안티치트 기반 게임을 모두 종료한 뒤 재시도하세요.","보안 프로그램의 최근 차단/격리 목록에 EAC 관련 파일이 있는지 확인하세요."],"link":"error-code-easyanticheat-error.html","detailPage":"error-code-easyanticheat-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(이지 안티치트 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"게임을 재설치하면 확실히 해결되나요?","a":"파일 손상이 원인이라면 해결되지만, 드라이버나 안티치트 자체 문제라면 재설치만으로는 해결되지 않을 수 있습니다."}],"decisionSteps":[{"condition":"EAC 복구 도구로 해결될 때","action":"재발하면 같은 도구로 다시 복구를 실행하세요."},{"condition":"파일 무결성 검사로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"다른 안티치트 게임을 종료한 뒤에도 반복될 때","action":"Windows의 코어 격리(메모리 무결성) 설정을 확인하세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["easyanticheat-error","이지안티치트오류","eac오류"],"communityCases":[{"title":"EAC 서비스 재설치로 이지 안티치트 오류 해결","summary":"게임 업데이트 이후 갑자기 이지 안티치트 오류가 발생해 게임이 실행되지 않던 사례가 있습니다. 게임 설치 폴더의 EasyAntiCheat 폴더에서 EasyAntiCheat_Setup.exe를 관리자 권한으로 실행해 서비스를 재설치하자 정상 실행됐습니다.","insight":"이지 안티치트 오류가 발생하면 게임 전체를 재설치하기 전에 EasyAntiCheat 서비스만 별도로 재설치하는 방법을 먼저 시도해보세요."}],"officialSource":{"title":"Easy Anti-Cheat 공식 지원","url":"https://www.easy.ac/support/articles"}},{"code":"배틀넷 연결 오류","title":"배틀넷 오류로 오버워치 등이 실행되지 않음 (BLZBNTBNA0000)","overview":"블리자드 게임(오버워치, 디아블로 등)을 실행할 때 배틀넷 클라이언트가 서버와 연결하지 못해 나타나는 오류입니다. 코드 뒤에 붙는 숫자에 따라 원인이 조금씩 다르지만, 대부분 네트워크나 캐시 문제입니다.","summary":"블리자드 게임(오버워치, 디아블로 등)을 실행할 때 배틀넷 클라이언트가 서버와 연결하지 못해 나타나는 오류입니다.","causes":["배틀넷 클라이언트의 캐시 파일이 손상된 경우","라우터나 방화벽이 배틀넷 서버 연결을 차단하는 경우","DNS 서버 응답이 불안정한 경우","VPN이나 프록시가 연결을 방해하는 경우","일시적인 배틀넷 서버 측 장애"],"checks":["배틀넷 클라이언트를 완전히 종료한 뒤 Battle.net 폴더 안의 Cache 폴더를 삭제하고 재시작하세요.","공유기를 재시작해 네트워크 연결을 초기화하세요.","DNS 서버를 공용 DNS(8.8.8.8 등)로 바꿔 재현 여부를 확인하세요.","VPN을 사용 중이라면 임시로 해제한 뒤 재시도하세요.","블리자드 공식 서버 상태 페이지에서 현재 장애 여부를 확인하세요."],"link":"error-code-battlenet-error.html","detailPage":"error-code-battlenet-error.html","faq":[{"q":"연결 오류가 나면 인터넷 회선부터 의심해야 하나요?","a":"이 문제(배틀넷 연결 오류)는 회선 자체보다 런처 캐시나 서버 상태 문제인 경우가 많아, 회선 점검 전에 공식 서버 상태부터 확인해보세요."}],"decisionSteps":[{"condition":"캐시 삭제 후 재현되지 않을 때","action":"재발 시 Cache 폴더를 다시 정리하면 대부분 해결됩니다."},{"condition":"공식 서버 상태 페이지에 장애가 표시될 때","action":"로컬 조치가 필요 없으니 공지가 해제될 때까지 기다리세요."},{"condition":"DNS·VPN을 바꿔도 반복될 때","action":"방화벽에서 Battle.net과 게임 실행 파일이 허용되어 있는지 확인하세요."}],"relatedSymptom":"windows-game-connection-error.html","aliases":["battlenet-error","배틀넷오류","blzbntbna"],"communityCases":[{"title":"DNS 변경으로 배틀넷 연결 오류 해결","summary":"배틀넷 클라이언트에서 연결 오류가 반복됐던 사례에서, DNS 서버를 구글 DNS(8.8.8.8)로 변경하자 정상 연결됐습니다. ISP의 DNS 서버가 배틀넷 서버 주소를 올바르게 반환하지 못하는 것이 원인이었습니다.","insight":"배틀넷 연결 문제는 종종 DNS 설정 문제입니다. 네트워크 어댑터 설정에서 DNS를 8.8.8.8이나 1.1.1.1로 변경해보세요."}],"officialSource":{"title":"블리자드 고객지원: Battle.net 연결 문제 해결","url":"https://kr.battle.net/support/ko/article/99037"}},{"code":"로스트아크 실행 오류","title":"로스트아크 게임이 실행되지 않거나 튕김","overview":"스마일게이트 런처를 통해 로스트아크를 실행할 때 게임이 시작되지 않거나, 로딩 중 강제 종료되는 증상입니다. 런처 캐시 손상이나 그래픽 드라이버 문제가 흔한 원인입니다.","summary":"스마일게이트 런처를 통해 로스트아크를 실행할 때 게임이 시작되지 않거나, 로딩 중 강제 종료되는 증상입니다.","causes":["스마일게이트 런처의 캐시나 설정 파일이 손상된 경우","그래픽 드라이버가 오래되었거나 게임과 호환되지 않는 경우","게임 파일 일부가 손상된 경우","백신 프로그램이 게임 실행 파일을 오탐지해 차단하는 경우","Windows나 DirectX 구성 요소가 오래된 경우"],"checks":["런처에서 로그아웃 후 재로그인하거나, 런처를 완전히 재설치해보세요.","그래픽 드라이버를 제조사 최신 버전으로 업데이트하세요.","런처의 '치료' 또는 '파일 검사' 기능으로 게임 파일 무결성을 점검하세요.","백신 프로그램에서 로스트아크 실행 파일이 격리되지 않았는지 확인하세요.","DirectX 최종 사용자 런타임을 다시 설치해보세요."],"link":"error-code-lostark-error.html","detailPage":"error-code-lostark-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(로스트아크 실행 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"같은 오류가 다른 게임에서도 나면 원인이 같은가요?","a":"네, 여러 게임에서 동일한 안티치트나 런처를 공유하는 경우 원인이 같을 가능성이 높습니다."}],"decisionSteps":[{"condition":"런처 재설치로 해결될 때","action":"재발 방지를 위해 정기적으로 파일 검사 기능을 사용하세요."},{"condition":"DirectX 재설치로 해결될 때","action":"그래픽 드라이버도 함께 최신 상태로 유지하세요."},{"condition":"백신 예외 추가 후에도 반복될 때","action":"안티치트 재설치 도구를 사용해보세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["lostark-error","로스트아크실행오류"],"communityCases":[{"title":"백신 예외 추가 후 GameGuard 재설치로 해결","summary":"윈도우 업데이트 이후 로스트아크가 실행되지 않고 오류가 발생했던 사례가 있습니다. 보안 소프트웨어가 GameGuard 파일을 차단하는 것이 원인이었고, 백신 예외 목록에 게임 폴더를 추가하고 게임을 복구하자 정상 실행됐습니다.","insight":"로스트아크 실행 오류는 GameGuard와 보안 소프트웨어의 충돌이 원인인 경우가 많습니다. 게임 폴더를 백신 예외 목록에 추가하거나 게임 파일 무결성 검사를 실행해보세요."}],"officialSource":{"title":"로스트아크 공식 고객센터","url":"https://lostark.support.onstove.com/hc/ko"}},{"code":"메이플스토리 실행 오류","title":"메이플스토리가 실행되지 않거나 로그인 후 튕김","overview":"넥슨 런처를 통해 메이플스토리를 실행할 때 게임이 켜지지 않거나, 로그인 직후 튕기는 증상입니다. 런처나 게임 파일 손상, 호환성 문제가 흔한 원인입니다.","summary":"넥슨 런처를 통해 메이플스토리를 실행할 때 게임이 켜지지 않거나, 로그인 직후 튕기는 증상입니다.","causes":["넥슨 런처 캐시가 손상된 경우","게임 실행 파일이 최신 패치와 맞지 않는 경우","호환성 모드나 관리자 권한 설정이 잘못된 경우","백신/보안 프로그램이 게임 실행을 차단하는 경우","그래픽 드라이버 호환성 문제"],"checks":["넥슨 런처를 완전히 종료한 뒤 다시 실행해보세요.","게임 실행 파일의 속성에서 호환성 모드나 관리자 권한 설정을 기본값으로 되돌려보세요.","런처의 파일 복구 기능을 실행하세요.","보안 프로그램의 실시간 검사에서 메이플스토리 관련 파일이 차단되지 않았는지 확인하세요.","그래픽 드라이버를 최신 버전으로 업데이트하세요."],"link":"error-code-maplestory-error.html","detailPage":"error-code-maplestory-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(메이플스토리 실행 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"안티치트 오류는 항상 게임사 문제인가요?","a":"게임사 서버 문제일 수도 있지만, 상당수는 로컬 PC의 드라이버·백신 충돌이 원인이므로 먼저 자가 점검을 해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"호환성 설정을 초기화한 뒤 해결될 때","action":"다음 업데이트 이후에도 같은 문제가 재발할 수 있으니, 다시 호환성 모드를 임의로 설정하지 마세요."},{"condition":"파일 복구 기능으로 해결될 때","action":"게임 파일이 계속 손상되고 있었을 가능성이 있으니 디스크 상태도 함께 점검하세요."},{"condition":"보안 프로그램 예외 추가 후에도 반복될 때","action":"안티치트 재설치 도구를 사용해보세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["maplestory-error","메이플스토리실행오류"],"communityCases":[{"title":"관리자 권한 실행 및 클라이언트 복구로 해결","summary":"메이플스토리가 보안 프로그램 오류와 함께 실행되지 않던 사례가 있습니다. 게임 런처를 관리자 권한으로 실행하고 클라이언트 복구를 진행하자 보안 모듈 파일이 재설치되어 정상 실행됐습니다.","insight":"메이플스토리 실행 오류는 보안 모듈 파일 손상이 원인인 경우가 많습니다. 넥슨 런처의 게임 복구 기능을 먼저 사용해보세요."}],"officialSource":{"title":"넥슨 에러복구프로그램","url":"https://help.nexon.com/download/restore"}},{"code":"리그오브레전드 패치 오류","title":"리그 오브 레전드 클라이언트 패치/설치 오류","overview":"롤 클라이언트가 업데이트를 받아오지 못하거나, 패치 도중 멈추는 증상입니다. 클라이언트 캐시 손상이나 네트워크 문제가 흔한 원인입니다.","summary":"롤 클라이언트가 업데이트를 받아오지 못하거나, 패치 도중 멈추는 증상입니다.","causes":["클라이언트 캐시나 로그 파일이 손상된 경우","네트워크 연결이 불안정해 패치 파일을 다 받지 못하는 경우","디스크 여유 공간이 부족한 경우","보안 프로그램이 패치 프로세스를 방해하는 경우","이전 패치가 비정상 종료되어 잔여 파일이 충돌하는 경우"],"checks":["클라이언트를 완전히 종료한 뒤 재시작해 패치를 다시 시도하세요.","게임 설치 폴더 안의 Config, Logs 폴더를 정리한 뒤 재시도하세요 (백업 후 진행 권장).","디스크 여유 공간을 확인하고 부족하면 정리하세요.","보안 프로그램을 임시로 비활성화한 뒤 재시도하세요.","그래도 안 되면 클라이언트를 완전히 삭제한 뒤 공식 홈페이지에서 새로 설치하세요."],"link":"error-code-lol-patch-error.html","detailPage":"error-code-lol-patch-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(리그오브레전드 패치 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"게임을 재설치하면 확실히 해결되나요?","a":"파일 손상이 원인이라면 해결되지만, 드라이버나 안티치트 자체 문제라면 재설치만으로는 해결되지 않을 수 있습니다."}],"decisionSteps":[{"condition":"캐시·로그 정리로 해결될 때","action":"재발 방지를 위해 정기적으로 정리하세요."},{"condition":"백신 예외 추가로 해결될 때","action":"게임 폴더를 예외 목록에 계속 등록해두세요."},{"condition":"클라이언트 재설치로도 반복될 때","action":"뱅가드(안티치트) 관련 문제일 수 있으므로 뱅가드를 재설치해보세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["lol-patch-error","롤패치오류","리그오브레전드패치오류"],"communityCases":[{"title":"손상된 패치 파일 삭제 후 재다운로드로 해결","summary":"리그오브레전드 패치 중 특정 파일에서 반복적으로 오류가 발생했던 사례가 있습니다. 오류가 발생한 패치 파일을 수동으로 찾아 삭제하자 런처가 해당 파일을 새로 다운로드해 패치가 완료됐습니다.","insight":"패치 오류가 특정 파일에서 반복된다면 해당 파일이 손상된 것입니다. 라이엇 클라이언트의 복구 기능을 사용하거나 오류 파일만 삭제해 재다운로드하세요."}],"officialSource":{"title":"Riot 지원: League of Legends 패치 문제 해결","url":"https://support.riotgames.com/ko/league-of-legends/client/patching-issues"}},{"code":"서든어택 넷프로텍트 오류","title":"서든어택 넷프로텍트(보안 프로그램) 오류로 실행 불가","overview":"서든어택을 실행할 때 보안 프로그램(넷프로텍트)이 정상적으로 로드되지 않아 게임이 실행되지 않는 증상입니다.","summary":"서든어택을 실행할 때 보안 프로그램(넷프로텍트)이 정상적으로 로드되지 않아 게임이 실행되지 않는 증상입니다.","causes":["넷프로텍트 드라이버가 손상되었거나 미설치 상태인 경우","다른 보안 프로그램과 충돌하는 경우","Windows 업데이트 이후 호환성이 깨진 경우","관리자 권한 없이 게임을 실행한 경우","이전 설치 잔여 파일이 새 설치와 충돌하는 경우"],"checks":["게임을 관리자 권한으로 실행해보세요.","넷프로텍트를 제거한 뒤 게임을 재실행해 새로 설치되게 하세요.","다른 보안 프로그램(백신 등)을 임시로 비활성화한 뒤 재시도하세요.","Windows를 최신 버전으로 업데이트하세요.","게임을 완전히 삭제한 뒤 넥슨 런처를 통해 새로 설치해보세요."],"link":"error-code-suddenattack-error.html","detailPage":"error-code-suddenattack-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(서든어택 넷프로텍트 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"같은 오류가 다른 게임에서도 나면 원인이 같은가요?","a":"네, 여러 게임에서 동일한 안티치트나 런처를 공유하는 경우 원인이 같을 가능성이 높습니다."}],"decisionSteps":[{"condition":"넷프로텍트 재설치로 해결될 때","action":"Windows 업데이트 직후 다시 실행이 안 되면 재설치부터 시도하세요."},{"condition":"보안 프로그램 하나를 껐을 때 해결될 때","action":"그 프로그램의 예외 목록에 게임·넷프로텍트 설치 폴더를 등록하세요."},{"condition":"게임 완전 재설치 후에도 반복될 때","action":"Windows의 코어 격리(메모리 무결성) 설정이 오래된 안티치트 드라이버와 충돌하고 있는지 확인하세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["suddenattack-error","서든어택넷프로텍트오류"],"communityCases":[{"title":"넷프로텍트 완전 제거 후 재설치로 해결","summary":"서든어택 실행 시 넷프로텍트 보안 프로그램 오류가 발생하던 사례에서, 기존 넷프로텍트를 완전히 제거하고 게임 공식 사이트에서 최신 버전을 설치하자 정상 실행됐습니다.","insight":"넷프로텍트 오류는 보안 모듈 손상이나 윈도우 업데이트 이후 호환성 문제로 자주 발생합니다. 완전 제거 후 재설치가 가장 효과적인 방법입니다."}],"officialSource":{"title":"넥슨 서든어택 고객센터","url":"https://cs.nexon.com/helpboard/nexon?gamecode=156"}},{"code":"FC 온라인 실행 오류","title":"FC 온라인(피파) 게임이 실행되지 않음","overview":"넥슨 런처를 통해 FC 온라인을 실행할 때 게임이 켜지지 않거나 로딩 중 멈추는 증상입니다. 런처 캐시나 그래픽 드라이버 호환성 문제가 흔한 원인입니다.","summary":"넥슨 런처를 통해 FC 온라인을 실행할 때 게임이 켜지지 않거나 로딩 중 멈추는 증상입니다.","causes":["넥슨 런처 캐시가 손상된 경우","그래픽 드라이버가 오래되었거나 호환되지 않는 경우","게임 파일 일부가 손상된 경우","백신 프로그램이 실행 파일을 차단하는 경우","해상도나 그래픽 설정이 현재 모니터와 맞지 않는 경우"],"checks":["넥슨 런처를 재시작하거나 재설치해보세요.","그래픽 드라이버를 최신 버전으로 업데이트하세요.","런처의 파일 검사/복구 기능을 실행하세요.","백신 프로그램의 차단 목록을 확인하세요.","게임 설정 파일(옵션 관련)을 초기화한 뒤 재시도하세요."],"link":"error-code-fconline-error.html","detailPage":"error-code-fconline-error.html","faq":[{"q":"게임이 실행되지 않으면 게임을 삭제하고 다시 깔아야 하나요?","a":"이 문제(FC 온라인 실행 오류)는 게임 파일보다 안티치트 드라이버 문제인 경우가 많아, 전체 재설치 전에 안티치트 재설치 도구부터 사용해보세요."},{"q":"안티치트 오류는 항상 게임사 문제인가요?","a":"게임사 서버 문제일 수도 있지만, 상당수는 로컬 PC의 드라이버·백신 충돌이 원인이므로 먼저 자가 점검을 해보는 것이 좋습니다."}],"decisionSteps":[{"condition":"안티치트 재설치 도구로 해결될 때","action":"재발 방지를 위해 백신 예외 목록에 게임 설치 폴더를 추가하세요."},{"condition":"파일 검사·복구 기능으로 해결될 때","action":"게임 파일이 손상되고 있었을 가능성이 있으니 디스크 상태도 함께 확인하세요."},{"condition":"백신 차단 목록에서 게임 파일이 발견될 때","action":"예외를 추가한 뒤 재시도하고, 반복되면 다른 백신으로 교차 테스트하세요."}],"relatedSymptom":"windows-game-launch-error.html","aliases":["fconline-error","fc온라인실행오류"],"communityCases":[{"title":"DirectX End-User Runtime 재설치로 해결","summary":"FC 온라인이 DirectX 관련 오류와 함께 실행되지 않던 사례가 있습니다. DirectX End-User Runtime을 공식 사이트에서 재설치하자 정상 실행됐습니다.","insight":"FC 온라인 실행 오류는 DirectX나 Visual C++ 런타임 파일 손상이 원인인 경우가 많습니다. 공식 마이크로소프트 사이트에서 최신 DirectX End-User Runtime을 설치해보세요."}],"officialSource":{"title":"넥슨 FC 온라인 고객센터","url":"https://cs.nexon.com/helpboard/nexon?gamecode=329"}},{"code":"코드 24","title":"이 장치가 존재하지 않거나 작동하지 않거나 모든 드라이버가 설치되어 있지 않습니다 (코드 24)","overview":"블루투스 어댑터를 포함한 장치가 제거 대기 상태이거나 드라이버가 제대로 로드되지 않을 때 장치 관리자에 나타나는 코드입니다. 블루투스 장치가 검색 목록에 아예 나타나지 않을 때 자주 함께 보입니다.","summary":"블루투스 어댑터를 포함한 장치가 제거 대기 상태이거나 드라이버가 제대로 로드되지 않을 때 장치 관리자에 나타나는 코드입니다. 블루투스 장치가 검색 목록에 아예 나타나지 않을 때 자주 함께 보입니다.","causes":["장치를 방금 제거했거나 제거 대기 중인 경우","드라이버가 손상되었거나 버전이 맞지 않는 경우","USB 절전 설정으로 어댑터 전원이 꺼진 경우","BIOS에서 내장 블루투스가 비활성화된 경우"],"checks":["장치를 재부팅한 뒤 장치 관리자에서 다시 검색하세요.","드라이버를 제거한 뒤 제조사 사이트에서 최신 버전을 재설치하세요.","USB 허브의 절전 관리 옵션에서 전원 절약을 해제하세요.","노트북이라면 BIOS/기능 키에서 블루투스가 켜져 있는지 확인하세요."],"link":"error-code-device-manager-code-24.html","detailPage":"error-code-device-manager-code-24.html","faq":[{"q":"블루투스 장치가 안 잡히면 장치를 바꿔야 하나요?","a":"이 문제(코드 24)는 장치보다 어댑터 드라이버나 페어링 기록 문제인 경우가 많아, 장치 교체 전에 드라이버 재설치와 페어링 재등록을 먼저 시도해보세요."}],"decisionSteps":[{"condition":"재부팅만으로 해결될 때","action":"\"제거 대기\" 상태가 일시적으로 남아 있던 것이므로 추가 조치가 필요 없습니다."},{"condition":"드라이버 재설치 후에도 반복될 때","action":"USB 절전 관리와 BIOS 설정을 함께 점검하세요. 특히 노트북 내장 장치는 BIOS 비활성화가 원인인 경우가 많습니다."},{"condition":"특정 포트에서만 발생할 때","action":"장치보다 그 포트의 접촉이나 전력 공급 문제일 가능성이 큽니다."}],"relatedSymptom":"hardware-bluetooth-not-found.html","aliases":["코드24","device-manager-code-24"],"communityCases":[{"title":"물리적 재장착으로 인식 불가(코드 24) 해결","summary":"PCIe 사운드카드가 코드 24로 인식되지 않던 사례가 있습니다. 카드를 슬롯에서 빼고 다시 단단히 장착하자 정상 인식됐습니다. 먼지나 접촉 불량으로 장치가 불완전하게 인식되고 있었던 것이 원인이었습니다.","insight":"코드 24는 장치가 물리적으로 완전히 인식되지 않은 상태입니다. 드라이버 문제보다 물리적 연결 상태를 먼저 확인하세요. 재장착과 접점 청소가 효과적입니다."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"코드 45","title":"이 하드웨어 장치가 현재 연결되어 있지 않습니다 (코드 45)","overview":"이전에 연결했던 블루투스 장치가 현재 시스템에 연결되어 있지 않을 때 나타나는 코드입니다. 장치 자체보다 드라이버가 이전 연결 기록만 남긴 상태인 경우가 많습니다.","summary":"이전에 연결했던 블루투스 장치가 현재 시스템에 연결되어 있지 않을 때 나타나는 코드입니다. 장치 자체보다 드라이버가 이전 연결 기록만 남긴 상태인 경우가 많습니다.","causes":["장치가 물리적으로 분리되었거나 페어링이 해제된 경우","드라이버 잔여 항목이 남아 있는 경우","다른 USB 포트로 옮긴 뒤 이전 항목이 남는 경우"],"checks":["장치 관리자에서 숨겨진 장치 표시를 켜고 이전 항목을 제거하세요.","블루투스 장치를 페어링 목록에서 삭제한 뒤 다시 등록하세요.","블루투스 어댑터 드라이버를 재설치하세요."],"link":"error-code-device-manager-code-45.html","detailPage":"error-code-device-manager-code-45.html","narrative":"코드 45는 오류라기보다는 '기록의 잔상'에 가깝습니다. Windows는 한 번 연결했던 장치의 드라이버 정보를 시스템에 남겨두는데, 그 장치가 물리적으로 빠져 있거나 꺼져 있으면 장치 관리자에는 흐릿하게 표시된 채로 이 코드가 뜹니다. 즉 지금 당장 뭔가 고장 났다는 신호가 아니라 '전에 연결됐던 그 장치가 지금은 안 잡힌다'는 상태 설명에 더 가깝습니다. 블루투스 기기라면 페어링이 끊긴 것뿐일 수도 있고, USB 장치라면 케이블이나 포트 쪽을 먼저 의심해볼 수 있습니다.","faq":[{"q":"블루투스 장치가 안 잡히면 장치를 바꿔야 하나요?","a":"이 문제(코드 45)는 장치보다 어댑터 드라이버나 페어링 기록 문제인 경우가 많아, 장치 교체 전에 드라이버 재설치와 페어링 재등록을 먼저 시도해보세요."}],"decisionSteps":[{"condition":"연결·재연결 시 항목이 정상으로 바뀔 때","action":"별다른 조치가 필요 없는 정상 동작입니다. 장치를 분리하면 회색으로 표시되는 것이 정상입니다."},{"condition":"숨겨진 장치를 지워도 계속 다시 생길 때","action":"어댑터·컨트롤러 드라이버나 절전 설정을 의심하고 4·5번 단계를 진행하세요."},{"condition":"특정 포트에서만 반복될 때","action":"장치보다 그 포트나 허브의 접촉·전력 공급 문제일 가능성이 큽니다."}],"relatedSymptom":"hardware-bluetooth-not-found.html","aliases":["코드45","device-manager-code-45"],"communityCases":[{"title":"장치 연결 후 드라이버 설치 순서로 코드 45 해결","summary":"장치를 분리한 상태에서 드라이버를 먼저 설치하니 코드 45가 표시됐던 사례가 있습니다. 드라이버를 제거한 뒤 장치를 먼저 연결하고 드라이버를 설치하는 올바른 순서로 진행하자 정상 인식됐습니다.","insight":"코드 45는 드라이버가 연결되지 않은 장치를 기다리는 상태입니다. 제조사 설치 안내에서 드라이버 설치와 장치 연결의 순서를 반드시 확인하세요."}],"officialSource":{"title":"Microsoft 지원: Device Manager error codes","url":"https://support.microsoft.com/en-us/windows/hardware/drivers/error-codes-in-device-manager-in-windows"}},{"code":"탐색기 시작 실패 (검은 화면)","title":"로그인 후 탐색기(Explorer.exe)가 시작되지 않아 검은 화면만 나옴","overview":"로그인은 정상적으로 되지만 바탕화면과 작업표시줄을 그리는 explorer.exe 프로세스가 시작되지 않아 검은 화면 상태로 멈추는 증상입니다. 그래픽 드라이버보다 셸 프로세스 자체의 문제인 경우가 많습니다.","summary":"로그인은 정상적으로 되지만 바탕화면과 작업표시줄을 그리는 explorer.exe 프로세스가 시작되지 않아 검은 화면 상태로 멈추는 증상입니다. 그래픽 드라이버보다 셸 프로세스 자체의 문제인 경우가 많습니다.","causes":["explorer.exe 실행 파일이나 관련 설정이 손상된 경우","최근 설치한 프로그램이 시작 프로그램에서 셸과 충돌하는 경우","디스플레이 드라이버 초기화가 지연되는 경우","사용자 프로필이 손상된 경우"],"checks":["작업 관리자(Ctrl+Shift+Esc)에서 파일 > 새 작업으로 explorer.exe를 직접 실행해보세요.","안전 모드로 부팅해 같은 증상이 재현되는지 확인하세요.","그래픽 드라이버를 최신 버전으로 업데이트하세요.","최근 설치한 프로그램을 안전 모드에서 제거해보세요."],"link":"error-code-explorer-black-screen.html","detailPage":"error-code-explorer-black-screen.html","faq":[{"q":"검은 화면이 뜨면 바로 초기화해야 하나요?","a":"이 문제(탐색기 시작 실패 (검은 화면))는 초기화 전에 explorer.exe 수동 실행과 안전 모드 확인만으로 해결되는 경우가 많으니, 초기화는 이 단계 이후로 미뤄도 됩니다."}],"decisionSteps":[{"condition":"explorer.exe 수동 실행으로 화면이 정상적으로 나올 때","action":"재부팅 후 다시 검은 화면이 된다면 Shell 레지스트리 값이나 시작 프로그램 충돌을 의심하고, 위 2번 항목부터 확인하세요."},{"condition":"안전 모드에서도 검은 화면이 재현될 때","action":"그래픽 드라이버보다 시스템 파일이나 프로필 손상 가능성이 높으므로 <code>sfc /scannow</code>를 실행한 뒤, 새 사용자 계정을 만들어 재현 여부를 비교하세요."},{"condition":"새 계정에서는 정상일 때","action":"기존 프로필 손상이 원인이므로 프로필 복구나 데이터 이전을 고려하세요."}],"relatedSymptom":"windows-black-screen-after-login.html","aliases":["explorer-black-screen","로그인후검은화면"],"communityCases":[{"title":"explorer.exe 수동 재시작으로 검은 화면 해결","summary":"로그인 후 바탕화면 없이 검은 화면만 표시됐던 사례가 있습니다. Ctrl+Alt+Del로 작업 관리자를 열고 새 작업 실행에 explorer.exe를 입력하자 탐색기가 시작되고 정상 화면이 나타났습니다.","insight":"탐색기 시작 실패는 대부분 임시적인 현상으로 explorer.exe 수동 재시작으로 해결됩니다. 반복된다면 시스템 파일 손상이나 셸 확장 충돌을 의심하세요."}],"officialSource":{"title":"Microsoft Learn: Black screen after sign in","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/shell-experience/scenario-guide-black-screen-after-sign-in"}},{"code":"셸 확장 충돌 (작업표시줄 멈춤)","title":"셸 확장 프로그램 충돌로 작업표시줄과 시작 메뉴가 멈춤","overview":"우클릭 메뉴를 추가하는 압축 프로그램, 클라우드 동기화 도구, 시작 메뉴 커스터마이징 도구 등이 탐색기 셸과 충돌하면 작업표시줄이나 시작 메뉴만 멈추는 증상으로 나타납니다.","summary":"우클릭 메뉴를 추가하는 압축 프로그램, 클라우드 동기화 도구, 시작 메뉴 커스터마이징 도구 등이 탐색기 셸과 충돌하면 작업표시줄이나 시작 메뉴만 멈추는 증상으로 나타납니다.","causes":["최근 설치한 셸 확장(우클릭 메뉴 추가 프로그램)이 충돌하는 경우","시작 메뉴/작업표시줄을 변경하는 서드파티 도구와의 충돌","탐색기 캐시나 아이콘 캐시가 손상된 경우"],"checks":["최근 설치한 프로그램(압축, 클라우드 동기화, 꾸미기 도구)을 하나씩 제거해보세요.","작업 관리자에서 탐색기(Windows 탐색기)를 다시 시작해보세요.","아이콘 캐시를 삭제한 뒤 재부팅하세요.","ShellExView 같은 도구로 서드파티 셸 확장을 확인하고 비활성화해보세요."],"link":"error-code-shell-extension-conflict.html","detailPage":"error-code-shell-extension-conflict.html","faq":[{"q":"작업표시줄이 멈추면 매번 재부팅해야 하나요?","a":"이 문제(셸 확장 충돌 (작업표시줄 멈춤))는 재부팅보다 탐색기(Explorer) 재시작만으로도 대부분 풀리며, 반복된다면 최근 설치한 셸 확장 프로그램을 먼저 의심해보세요."}],"decisionSteps":[{"condition":"탐색기 재시작만으로 매번 풀릴 때","action":"근본 원인(특정 셸 확장)을 찾기 전까지는 임시 조치로 반복 사용해도 무방하지만, ShellExView로 원인 프로그램을 특정해두면 재발을 줄일 수 있습니다."},{"condition":"특정 프로그램 제거 후 재발하지 않을 때","action":"그 프로그램의 최신 버전이나 우클릭 메뉴 기능을 끌 수 있는 설정이 있는지 제조사 홈페이지에서 확인한 뒤 재설치하세요."},{"condition":"ShellExView로 특정 확장을 비활성화해도 계속될 때","action":"탐색기 자체보다 시작 메뉴·작업표시줄 관련 시스템 파일 손상 가능성이 있으므로 <code>sfc /scannow</code>를 실행하세요."}],"relatedSymptom":"windows-taskbar-freeze.html","aliases":["shell-extension-conflict","작업표시줄멈춤"],"communityCases":[{"title":"ShellExView로 문제 셸 확장 비활성화 후 해결","summary":"우클릭 메뉴를 열거나 특정 폴더를 열 때 탐색기가 멈추는 문제가 발생했던 사례가 있습니다. ShellExView 프로그램으로 제3자 셸 확장 프로그램을 확인하고 최근 설치한 프로그램의 확장을 비활성화하자 멈춤이 해결됐습니다.","insight":"탐색기 멈춤의 원인 중 셸 확장 충돌이 많습니다. ShellExView나 Autoruns 같은 도구로 어떤 셸 확장이 충돌하는지 찾아보세요."}],"officialSource":{"title":"Microsoft 지원: Explorer shell extension hangs","url":"https://support.microsoft.com/en-us/topic/fix-the-explorer-exe-process-stops-responding-hangs-when-you-use-windows-explorer-that-hosts-a-shell-extension-that-was-created-by-using-mfc-4d8f8a87-94fc-0874-756a-5c6db8023133"}},{"code":"TiWorker.exe 디스크 100%","title":"Windows 모듈 설치 관리자(TiWorker.exe)로 인한 디스크 사용률 100%","overview":"Windows 업데이트를 설치하거나 정리하는 TiWorker.exe 프로세스가 백그라운드에서 디스크 압축·정리 작업을 하면서 디스크 사용률이 100%에 가깝게 오래 유지되는 증상입니다.","summary":"Windows 업데이트를 설치하거나 정리하는 TiWorker.exe 프로세스가 백그라운드에서 디스크 압축·정리 작업을 하면서 디스크 사용률이 100%에 가깝게 오래 유지되는 증상입니다.","causes":["대규모 누적 업데이트 설치 후 정리 작업이 진행 중인 경우","백그라운드 업데이트 정리 작업이 예상보다 오래 걸리는 경우","디스크(특히 HDD)의 처리 속도가 느린 경우"],"checks":["작업 관리자에서 TiWorker.exe의 디스크 사용량과 진행 여부를 확인하세요.","일반적으로 몇 시간 내 자연히 끝나므로, 강제 종료보다 완료를 기다려보세요.","디스크 정리 도구로 이전 업데이트 파일을 정리해 보세요.","반복해서 오래 지속된다면 SFC/DISM으로 시스템 파일 상태를 점검하세요."],"link":"error-code-tiworker-disk-100.html","detailPage":"error-code-tiworker-disk-100.html","faq":[{"q":"디스크 사용률이 100%면 디스크를 교체해야 하나요?","a":"이 문제(TiWorker.exe 디스크 100%)는 디스크 고장보다 백그라운드 서비스가 원인인 경우가 많아, 교체 전에 해당 프로세스가 자연히 끝나는지 먼저 지켜보는 것이 좋습니다."}],"decisionSteps":[{"condition":"몇 시간 내 자연히 끝날 때","action":"정상 동작이므로 별도 조치가 필요 없습니다."},{"condition":"디스크 정리·컴포넌트 정리 후에도 며칠씩 반복될 때","action":"Windows Update 자체의 손상을 의심하고 sfc·DISM 점검으로 넘어가세요."},{"condition":"sfc·DISM에서도 문제를 찾지 못했는데 반복될 때","action":"디스크(특히 HDD) 자체의 처리 속도 저하나 배드섹터 가능성을 SMART로 확인하세요."}],"relatedSymptom":"windows-disk-usage-100.html","aliases":["tiworker-disk-100","디스크사용률100"],"communityCases":[{"title":"업데이트 완료 후 TiWorker 디스크 점유 자연 해소","summary":"TiWorker.exe가 디스크를 90% 이상 점유해 PC가 느려진 사례가 있습니다. 윈도우 업데이트가 진행 중인 상태였고, 업데이트가 완료될 때까지 기다리자 자연스럽게 해소됐습니다.","insight":"TiWorker.exe의 높은 디스크 점유는 업데이트 중이거나 직후에 일시적으로 발생하는 경우가 많습니다. 몇 시간 후에도 지속된다면 업데이트 재시도나 DISM 정리를 고려하세요."}],"officialSource":{"title":"Microsoft Learn: Windows Modules Installer high disk usage","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/superfetch-sysmain-service-spikes-cpu"}},{"code":"SysMain 디스크 100%","title":"SysMain(Superfetch) 서비스로 인한 디스크 사용률 100%","overview":"자주 쓰는 프로그램을 미리 메모리에 올려두는 SysMain(구 Superfetch) 서비스가 특히 HDD 환경에서 디스크를 과도하게 사용해 전체 시스템이 느려지는 증상으로 나타날 수 있습니다.","summary":"자주 쓰는 프로그램을 미리 메모리에 올려두는 SysMain(구 Superfetch) 서비스가 특히 HDD 환경에서 디스크를 과도하게 사용해 전체 시스템이 느려지는 증상으로 나타날 수 있습니다.","causes":["HDD에서 SysMain의 예측 캐싱 작업이 디스크에 부담을 주는 경우","디스크가 이미 조각화되었거나 여유 공간이 부족한 경우","SSD 환경에서 불필요하게 서비스가 계속 활성화된 경우"],"checks":["작업 관리자에서 서비스 호스트 중 SysMain의 디스크 사용량을 확인하세요.","services.msc에서 SysMain 서비스를 임시로 중지해 증상이 나아지는지 확인하세요.","SSD를 사용 중이라면 SysMain을 비활성화해도 무방한 경우가 많습니다.","디스크 조각 모음/최적화를 실행해보세요."],"link":"error-code-sysmain-disk-100.html","detailPage":"error-code-sysmain-disk-100.html","faq":[{"q":"디스크 사용률이 100%면 디스크를 교체해야 하나요?","a":"이 문제(SysMain 디스크 100%)는 디스크 고장보다 백그라운드 서비스가 원인인 경우가 많아, 교체 전에 해당 프로세스가 자연히 끝나는지 먼저 지켜보는 것이 좋습니다."}],"decisionSteps":[{"condition":"서비스를 중지하니 디스크 사용량이 즉시 정상화될 때","action":"SSD라면 사용 안 함으로 유지해도 되고, HDD라면 시작 유형을 자동(지연 시작)으로 낮춰 재현 여부를 다시 확인하세요."},{"condition":"서비스 중지 후에도 디스크 사용률이 여전히 높을 때","action":"SysMain이 원인이 아니므로 작업 관리자에서 Windows Update나 백신 검사 같은 다른 상위 프로세스를 확인하세요."},{"condition":"데이터베이스 재구축 후에도 높은 사용률이 반복될 때","action":"디스크 자체의 속도 저하나 배드섹터 가능성이 있으므로 SMART 상태를 점검하세요."}],"relatedSymptom":"windows-disk-usage-100.html","aliases":["sysmain-disk-100","superfetch디스크100"],"communityCases":[{"title":"SysMain 서비스 비활성화로 HDD 점유율 해결","summary":"HDD를 사용하는 PC에서 SysMain이 항상 디스크를 70-90% 점유해 시스템이 느렸던 사례가 있습니다. SysMain 서비스를 비활성화하자 디스크 점유가 내려가고 속도가 크게 개선됐습니다.","insight":"SysMain(SuperFetch)은 SSD에서는 효과적이지만 HDD에서는 오히려 부담을 줄 수 있습니다. HDD 사용 중 이 서비스가 과도한 점유를 보인다면 비활성화를 고려하세요."}],"officialSource":{"title":"Microsoft Learn: SuperFetch (SysMain) service CPU spikes","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/superfetch-sysmain-service-spikes-cpu"}},{"code":"네트워크 드라이브 탐색기 멈춤","title":"네트워크 드라이브나 공유 폴더 탐색 시 탐색기가 멈춤","overview":"탐색기가 네트워크 드라이브나 공유 폴더의 파일 목록, 썸네일을 가져오려다 응답이 없는 서버나 끊긴 연결 때문에 전체 창이 멈추는 증상입니다. 로컬 폴더는 정상인지 먼저 구분하는 것이 중요합니다.","summary":"탐색기가 네트워크 드라이브나 공유 폴더의 파일 목록, 썸네일을 가져오려다 응답이 없는 서버나 끊긴 연결 때문에 전체 창이 멈추는 증상입니다. 로컬 폴더는 정상인지 먼저 구분하는 것이 중요합니다.","causes":["연결이 끊긴 네트워크 드라이브가 여전히 매핑되어 있는 경우","공유 폴더 서버가 응답하지 않는 경우","썸네일 미리보기 생성이 대용량 폴더에서 지연되는 경우"],"checks":["연결이 끊긴 네트워크 드라이브의 연결을 해제해보세요.","로컬 폴더에서는 탐색기가 정상인지 비교해보세요.","폴더 옵션에서 '항상 아이콘 표시, 축소판 그림 표시 안 함'을 켜서 재현 여부를 확인하세요.","공유 폴더가 있는 기기나 NAS의 상태를 점검하세요."],"link":"error-code-explorer-network-drive-freeze.html","detailPage":"error-code-explorer-network-drive-freeze.html","faq":[{"q":"탐색기가 멈추면 바로 재설치해야 하나요?","a":"이 문제(네트워크 드라이브 탐색기 멈춤)는 재설치보다 셸 재시작과 원인이 되는 폴더·드라이브 분리로 대부분 해결됩니다. 재설치는 이 단계 이후에도 반복될 때 고려하세요."}],"decisionSteps":[{"condition":"특정 드라이브 연결 해제로 바로 풀릴 때","action":"해당 드라이브를 다시 매핑할 때 \"로그온할 때 다시 연결\"을 해제하거나, 연결 대상 기기의 전원·절전 설정을 먼저 확인하세요."},{"condition":"로컬 폴더에서도 느릴 때","action":"네트워크가 아니라 탐색기 자체나 셸 확장 문제일 수 있으므로 <a href=\"error-code-shell-extension-conflict.html\">셸 확장 충돌 페이지</a>를 함께 확인하세요."},{"condition":"자동 검색을 꺼도 특정 공유 폴더에서만 멈출 때","action":"그 공유 폴더를 호스팅하는 기기(NAS·공유 PC)의 응답 지연이나 절전 설정이 원인일 가능성이 큽니다."}],"relatedSymptom":"windows-explorer-freeze.html","aliases":["explorer-network-drive-freeze","네트워크드라이브탐색기멈춤"],"communityCases":[{"title":"오프라인 파일 동기화 비활성화로 멈춤 해결","summary":"네트워크 드라이브가 연결된 상태에서 탐색기를 열 때마다 잠시 멈추는 사례가 있었습니다. 오프라인 파일 동기화 기능을 비활성화하자 멈춤 없이 바로 탐색기가 열렸습니다.","insight":"네트워크 드라이브로 인한 탐색기 멈춤은 오프라인 파일 동기화나 자동 인식 시도가 원인인 경우가 많습니다. 드라이브 연결이 불안정하다면 자동 연결 해제 후 필요할 때만 연결하세요."}],"officialSource":{"title":"Microsoft Learn: Applications freeze accessing network drive files","url":"https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/applications-freeze-concurrently-access-file-network-drive"}},{"code":"Windows Audio 서비스 응답 없음","title":"Windows Audio 서비스가 중지되거나 응답하지 않아 소리가 나오지 않음","overview":"소리 아이콘에 X 표시가 뜨거나 오디오 장치 자체는 정상인데 Windows Audio 서비스가 멈춰 있거나 중지되어 있어 전체 사운드가 나오지 않는 증상입니다. 드라이버 문제와는 원인이 다릅니다.","summary":"소리 아이콘에 X 표시가 뜨거나 오디오 장치 자체는 정상인데 Windows Audio 서비스가 멈춰 있거나 중지되어 있어 전체 사운드가 나오지 않는 증상입니다. 드라이버 문제와는 원인이 다릅니다.","causes":["Windows Audio 서비스가 중지되었거나 시작에 실패한 경우","관련 서비스(Windows Audio Endpoint Builder)가 함께 중지된 경우","최근 업데이트 이후 서비스 설정이 초기화된 경우"],"checks":["services.msc에서 Windows Audio, Windows Audio Endpoint Builder 서비스 상태와 시작 유형을 확인하세요.","두 서비스를 모두 자동으로 설정하고 시작해보세요.","오디오 문제 해결사를 실행해보세요.","그래도 안 되면 재부팅 후 서비스 상태를 다시 확인하세요."],"link":"error-code-windows-audio-service-stopped.html","detailPage":"error-code-windows-audio-service-stopped.html","faq":[{"q":"소리가 안 나면 스피커나 이어폰부터 바꿔야 하나요?","a":"이 문제(Windows Audio 서비스 응답 없음)는 장치 자체보다 드라이버나 서비스 문제인 경우가 많으니, 다른 장치로 교차 확인한 뒤에 장치 교체를 고려해도 늦지 않습니다."}],"decisionSteps":[{"condition":"서비스 시작 시 \"오류 1068\"이 뜰 때","action":"RPC, Multimedia Class Scheduler 서비스가 함께 중지되어 있는지 먼저 확인하고 두 서비스를 자동으로 설정하세요."},{"condition":"서비스는 정상 실행 중인데 소리가 안 날 때","action":"서비스 문제가 아니라 오디오 드라이버 문제일 가능성이 크므로 장치 관리자에서 드라이버를 재설치하세요."},{"condition":"<code>net start audiosrv</code>에서 접근 거부 오류가 날 때","action":"맬웨어나 최적화 프로그램이 관련 레지스트리 권한을 변조했을 가능성이 있으므로 백신 전체 검사를 우선하세요."}],"relatedSymptom":"hardware-sound-not-working.html","aliases":["windows-audio-service-stopped","오디오서비스응답없음"],"communityCases":[{"title":"오디오 서비스 재시작으로 소리 없음 즉시 해결","summary":"갑자기 소리가 나지 않아 확인해보니 Windows Audio 서비스가 중지 상태였던 사례가 있습니다. 서비스 관리자(services.msc)에서 Windows Audio와 Windows Audio Endpoint Builder를 재시작하자 소리가 복구됐습니다.","insight":"갑자기 소리가 완전히 나오지 않는다면 오디오 장치 문제 전에 서비스 상태를 먼저 확인하세요. 드라이버 재설치보다 서비스 재시작이 훨씬 간단한 해결책입니다."}],"officialSource":{"title":"Microsoft 지원: Fix sound or audio problems in Windows","url":"https://support.microsoft.com/en-us/windows/fix-sound-or-audio-problems-in-windows-73025246-b61c-40fb-671a-2535c7cd56c8"}},{"code":"최신 대기 모드 절전 복귀 실패","title":"최신 대기 모드(Modern Standby/S0ix)에서 절전 복귀 실패","overview":"전통적인 S3 절전 대신 최신 대기 모드(Modern Standby)를 쓰는 노트북에서, 화면을 닫았다 열어도 화면이 켜지지 않거나 배터리가 절전 중에도 빠르게 소모되는 증상입니다. 일반 절전 복귀 실패와 원인 계층이 다릅니다.","summary":"전통적인 S3 절전 대신 최신 대기 모드(Modern Standby)를 쓰는 노트북에서, 화면을 닫았다 열어도 화면이 켜지지 않거나 배터리가 절전 중에도 빠르게 소모되는 증상입니다. 일반 절전 복귀 실패와 원인 계층이 다릅니다.","causes":["최신 대기 모드 지원 드라이버(네트워크, 그래픽)가 최신이 아닌 경우","백그라운드 앱이 절전 중에도 계속 깨어있어 완전한 저전력 상태로 못 들어가는 경우","제조사의 전원 관리 유틸리티와 Windows 전원 옵션이 충돌하는 경우"],"checks":["명령 프롬프트에서 powercfg /a로 최신 대기 모드 지원 여부를 확인하세요.","powercfg /sleepstudy 보고서로 절전 중 깨어난 원인을 확인하세요.","네트워크 어댑터와 칩셋 드라이버를 최신 버전으로 업데이트하세요.","제조사 전원 관리 유틸리티가 최신인지 확인하세요."],"link":"error-code-modern-standby-resume-fail.html","detailPage":"error-code-modern-standby-resume-fail.html","faq":[{"q":"절전 모드를 아예 꺼야 하나요?","a":"이 문제(최신 대기 모드 절전 복귀 실패)가 반복된다면 절전 기능 자체를 끄기보다 관련 드라이버와 전원 설정을 먼저 점검해, 절전 기능을 그대로 쓸 수 있는지 확인하는 것이 좋습니다."}],"decisionSteps":[{"condition":"powercfg /a에서 최신 대기 모드 자체가 지원되지 않는다고 나올 때","action":"하드웨어 제약이므로 드라이버 업데이트로는 해결되지 않습니다. 제조사의 지원 공지를 확인하세요."},{"condition":"sleepstudy 보고서에서 특정 장치가 반복적으로 깨움 원인으로 나올 때","action":"위 5번 항목대로 해당 장치의 깨우기 권한을 꺼보세요."},{"condition":"드라이버 업데이트 후에도 배터리 소모가 계속될 때","action":"제조사 전원 관리 유틸리티와 Windows 전원 옵션이 서로 다른 절전 설정을 적용하고 있을 수 있으니 둘 중 하나만 쓰도록 정리하세요."}],"relatedSymptom":"windows-sleep-resume-fail.html","aliases":["modern-standby-resume-fail","최신대기모드절전복귀실패"],"communityCases":[{"title":"BIOS 업데이트로 절전 복귀 실패 해결","summary":"노트북에서 절전 모드 복귀 시 화면이 켜지지 않거나 재부팅이 되는 문제가 반복됐던 사례가 있습니다. 제조사 홈페이지에서 BIOS 업데이트를 진행하자 절전 복귀가 정상적으로 이루어졌습니다.","insight":"절전 복귀 문제는 드라이버보다 BIOS/UEFI 펌웨어 업데이트로 해결되는 경우가 많습니다. 제조사 지원 페이지에서 최신 BIOS 업데이트를 먼저 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Modern Standby","url":"https://learn.microsoft.com/en-us/windows-hardware/design/device-experiences/modern-standby"}},{"code":"인쇄 스풀러 서비스 응답 없음","title":"인쇄 스풀러(Print Spooler) 서비스가 응답하지 않아 프린터 추가가 멈춤","overview":"프린터를 추가하거나 인쇄할 때 내부적으로 동작하는 인쇄 스풀러 서비스가 멈추거나 응답하지 않으면, 프린터 추가 화면이 검색 중 상태로 멈추거나 인쇄 대기열이 쌓이는 증상이 나타납니다.","summary":"프린터를 추가하거나 인쇄할 때 내부적으로 동작하는 인쇄 스풀러 서비스가 멈추거나 응답하지 않으면, 프린터 추가 화면이 검색 중 상태로 멈추거나 인쇄 대기열이 쌓이는 증상이 나타납니다.","causes":["스풀러 서비스가 중지되었거나 손상된 스풀 파일이 쌓인 경우","손상된 프린터 드라이버가 스풀러를 함께 멈추게 하는 경우","대기열에 오래된 인쇄 작업이 남아 있는 경우"],"checks":["services.msc에서 Print Spooler 서비스를 재시작해보세요.","C:\\Windows\\System32\\spool\\PRINTERS 폴더의 대기 파일을 정리한 뒤 서비스를 다시 시작하세요.","최근 설치한 프린터 드라이버를 제거하고 다시 설치해보세요.","여러 프린터가 있다면 하나씩 제거하며 어떤 드라이버가 원인인지 좁혀보세요."],"link":"error-code-print-spooler-not-responding.html","detailPage":"error-code-print-spooler-not-responding.html","faq":[{"q":"프린터를 재설치하면 바로 해결되나요?","a":"이 문제(인쇄 스풀러 서비스 응답 없음)는 드라이버보다 서비스나 권한 문제인 경우가 많아, 재설치 전에 스풀러 서비스 상태부터 확인하는 것이 순서상 더 빠릅니다."},{"q":"제조사 전용 프로그램을 꼭 설치해야 하나요?","a":"Windows 기본 드라이버로도 인쇄는 가능하지만, 제조사 프로그램을 설치하면 고급 기능과 상태 모니터링을 이용할 수 있습니다."}],"decisionSteps":[{"condition":"서비스 재시작만으로 해결될 때","action":"재발 방지를 위해 시작 유형이 \"자동\"으로 되어 있는지 확인하세요."},{"condition":"대기 파일 정리 후에도 반복될 때","action":"특정 드라이버가 스풀 파일을 계속 손상시키고 있을 가능성이 크므로 드라이버 재설치로 넘어가세요."},{"condition":"RPC 서비스가 중지되어 있었을 때","action":"자동으로 설정하고 시작한 뒤, 반복되면 맬웨어나 그룹 정책 변경 여부를 확인하세요."}],"relatedSymptom":"windows-printer-add-freeze.html","aliases":["print-spooler-not-responding","인쇄스풀러응답없음"],"communityCases":[{"title":"스풀러 재시작 및 대기 파일 삭제로 프린터 복구","summary":"프린터가 갑자기 작동하지 않고 인쇄 큐가 비워지지 않던 사례가 있습니다. 서비스 관리자에서 인쇄 스풀러를 중지하고, C:WindowsSystem32spoolPRINTERS 폴더의 파일을 삭제한 뒤 서비스를 재시작하자 정상 작동했습니다.","insight":"인쇄 문제는 스풀러 서비스 재시작과 대기 파일 삭제로 대부분 해결됩니다. 프린터 드라이버 재설치 전에 이 방법을 먼저 시도해보세요."}],"officialSource":{"title":"Microsoft 지원: Fix print spooler service not running errors","url":"https://support.microsoft.com/en-us/windows/hardware/printer/fix-print-spooler-service-not-running-errors-in-windows"}},{"code":"스팀 서버 연결 실패","title":"스팀(Steam)이 서버에 연결하지 못해 로그인이나 상점 접속이 안 됨","overview":"스팀 클라이언트가 로그인 중이나 상점 접속 중 서버 연결에 실패하는 증상으로, 스팀 서버 자체 장애이거나 로컬 네트워크·방화벽 설정이 원인인 경우로 나뉩니다.","summary":"스팀 클라이언트가 로그인 중이나 상점 접속 중 서버 연결에 실패하는 증상으로, 스팀 서버 자체 장애이거나 로컬 네트워크·방화벽 설정이 원인인 경우로 나뉩니다.","causes":["스팀 서버 측 일시적 장애","방화벽이나 백신이 스팀 클라이언트 연결을 차단하는 경우","스팀 설정 파일(ClientRegistry.blob 등)이 손상된 경우","DNS 응답이 불안정한 경우"],"checks":["Steam 공식 서버 상태 페이지에서 장애 여부를 먼저 확인하세요.","스팀을 완전히 종료한 뒤 관리자 권한으로 재시작해보세요.","방화벽에서 스팀 클라이언트가 허용되어 있는지 확인하세요.","공용 DNS(8.8.8.8 등)로 바꿔 재현 여부를 확인하세요."],"link":"error-code-steam-connection-fail.html","detailPage":"error-code-steam-connection-fail.html","faq":[{"q":"연결 오류가 나면 인터넷 회선부터 의심해야 하나요?","a":"이 문제(스팀 서버 연결 실패)는 회선 자체보다 런처 캐시나 서버 상태 문제인 경우가 많아, 회선 점검 전에 공식 서버 상태부터 확인해보세요."}],"decisionSteps":[{"condition":"공식 상태 페이지에 장애가 표시될 때","action":"스팀 서버 자체 장애이므로 로컬에서 추가 조치할 필요 없이 공지가 해제될 때까지 기다리세요."},{"condition":"방화벽에서 차단 기록이 발견될 때","action":"예외를 추가한 뒤 재시도하고, 그래도 안 되면 백신 프로그램의 자체 방화벽·네트워크 보호 기능도 함께 확인하세요."},{"condition":"위 항목이 모두 정상인데 특정 지역 서버에서만 실패할 때","action":"다른 다운로드 지역으로 전환해보고, VPN을 켜거나 꺼서 재현 여부를 비교해 ISP 라우팅 문제인지 구분하세요."}],"relatedSymptom":"windows-game-connection-error.html","aliases":["steam-connection-fail","스팀서버연결실패"],"communityCases":[{"title":"스팀 다운로드 지역 변경으로 연결 오류 해결","summary":"스팀 업데이트나 게임 다운로드 시 연결 오류가 반복됐던 사례에서, 스팀 설정의 다운로드 지역을 한국에서 다른 지역으로 변경하자 정상적으로 연결됐습니다. 특정 스팀 CDN 서버에 문제가 있었던 것이 원인이었습니다.","insight":"스팀 연결 오류가 특정 시간대에 반복된다면 다운로드 지역을 변경해보세요. 스팀 설정 > 다운로드 > 다운로드 지역에서 변경할 수 있습니다."}],"officialSource":{"title":"Steam 공식 지원: 네트워크 연결 문제 해결","url":"https://help.steampowered.com/en/faqs/view/669A-2F68-D1D1-A5EC"}},{"code":"0x0000002E","title":"DATA_BUS_ERROR","overview":"시스템 메모리, CPU 캐시, 혹은 시스템 버스에서 패리티(홀짝 검증) 오류가 감지되었을 때 나타나는 코드로, 마이크로소프트 공식 문서에서도 '거의 대부분 하드웨어 문제'로 명시하는 대표적인 물리적 결함형 블루스크린입니다. 램 자체의 불량, CPU L2 캐시 오류, 그래픽카드 VRAM 불량이 3대 주요 원인으로 꼽히며, 드라이버가 존재하지 않는 물리 주소(0x8로 시작하는 주소 영역 등)에 접근을 시도할 때도 동일한 코드가 나타날 수 있습니다. 윈도우 재설치나 드라이버 업데이트 같은 소프트웨어적 조치만으로는 해결되지 않는 경우가 대부분이라, 처음부터 하드웨어 진단을 우선순위에 두는 것이 효율적입니다.","summary":"시스템 메모리나 캐시, 버스에서 패리티(데이터 무결성) 오류가 감지되었을 때 나타나는 코드로, 마이크로소프트도 '거의 대부분 하드웨어 문제'로 분류하는 대표적인 물리적 결함형 블루스크린입니다.","causes":["램 모듈 자체가 불량이거나 슬롯 접촉이 불량해 데이터 전송 중 패리티 오류가 발생하는 경우","메인보드의 L2 캐시나 메모리 컨트롤러가 물리적으로 손상된 경우","그래픽카드의 비디오 램(VRAM)이 불량하거나 발열로 열화된 경우","최근 하드웨어를 추가하거나 교체한 뒤 슬롯·핀 접촉이 불완전한 경우","드라이버가 존재하지 않는 물리 주소 영역에 접근을 시도하는 경우","메인보드 전원부나 칩셋이 노후화되어 버스 신호 무결성이 떨어지는 경우"],"checks":["메모리 진단 도구(mdsched.exe 또는 MemTest86)로 램 상태를 여러 패스에 걸쳐 점검하세요.","램을 한 개씩 꽂아가며 재부팅해 특정 모듈이나 슬롯에서만 오류가 재현되는지 확인하세요.","최근 추가하거나 교체한 하드웨어가 있다면 제거한 뒤 재현 여부를 확인하세요.","그래픽카드를 사용 중이라면 다른 그래픽카드로 교체 테스트해 VRAM 불량 여부를 좁혀보세요.","이벤트 뷰어나 블루스크린 덤프 파일(*.dmp)에서 오류를 일으킨 모듈 주소를 확인하면 원인 추적 속도를 높일 수 있습니다.","위 방법으로도 원인이 좁혀지지 않으면 서비스센터나 전문 업체에서 메인보드 자체의 하드웨어 진단을 받아보세요."],"link":"error-code-0x0000002e.html","detailPage":"error-code-0x0000002e.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000002E)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"특정 모듈 교체로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"슬롯 교체로 해결될 때","action":"메인보드 슬롯 문제였으므로 그 슬롯 사용을 피하세요."},{"condition":"전원·발열 점검으로도 해결되지 않을 때","action":"메인보드 자체의 결함 가능성을 검토하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["2e","0000002e","0x2e"],"communityCases":[{"title":"MemTest86로 불량 램을 찾아 교체해 해결한 사례","summary":"특별한 이유 없이 DATA_BUS_ERROR 블루스크린이 반복됐던 사례가 있습니다. MemTest86으로 여러 시간에 걸쳐 검사한 결과 램 두 개 중 하나에서만 수백 개의 오류가 발견됐고, 해당 램만 교체한 뒤로는 블루스크린이 완전히 사라졌습니다.","insight":"DATA_BUS_ERROR는 겉보기엔 원인을 알 수 없는 경우가 많지만, 실제로는 램 한 개만 불량이어도 발생할 수 있습니다. 램을 한꺼번에 테스트하기보다 하나씩 분리해서 여러 패스에 걸쳐 테스트해보는 것이 원인을 찾는 데 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x2E DATA_BUS_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x2e--data-bus-error"}},{"code":"0x00000080","title":"NMI_HARDWARE_FAILURE","overview":"NMI(Non-Maskable Interrupt, 무시할 수 없는 인터럽트) 신호가 발생해 시스템이 강제로 정지했을 때 나타나는 코드로, 이름 그대로 하드웨어 자체의 심각한 오류를 의미하는 경우가 대부분입니다. 마이크로소프트 문서에 따르면 복구 불가능한 내부 칩셋 오류, 시스템 메모리의 패리티·ECC 오류, 시스템·주변기기 버스에서 감지된 데이터 손상이 대표적인 트리거로 꼽힙니다. 서버나 워크스테이션급 메인보드는 물리적인 NMI 스위치나 디버그 헤더를 갖춘 경우가 있어, 실수로 눌리거나 접촉되며 같은 코드가 발생하기도 합니다. 다만 일반 데스크톱에서는 램 불량이 압도적으로 흔한 트리거로 보고됩니다.","summary":"NMI(무시할 수 없는 인터럽트) 신호가 발생해 시스템이 강제로 정지했을 때 나타나는 코드로, 하드웨어 자체의 심각한 오류를 의미하는 경우가 대부분입니다.","causes":["램이 불량하거나 규격이 맞지 않아 패리티·ECC 오류가 발생하는 경우","메인보드 칩셋이나 시스템 버스에서 복구 불가능한 내부 오류가 감지된 경우","PCIe 슬롯이나 확장 카드(그래픽카드, 사운드카드 등)의 접촉 불량","전원 공급이 불안정해 하드웨어가 순간적으로 오작동하는 경우","메인보드의 NMI 스위치나 디버그 헤더가 실수로 눌리거나 오작동한 경우(일부 서버·워크스테이션 보드)","케이스 내부 정전기나 접지 불량으로 순간적인 전기 신호 이상이 발생하는 경우"],"checks":["메모리 진단 도구로 램 상태를 점검하고, 가능하면 램을 하나씩 꽂아 테스트하세요.","모든 확장 카드와 케이블을 재장착해 접촉 불량이 없는지 확인하세요.","파워 서플라이 용량과 케이블 연결 상태를 점검하세요.","최근 추가한 하드웨어가 있다면 제거한 뒤 재현 여부를 확인하세요.","이벤트 뷰어에서 WHEA 관련 오류 로그가 함께 기록되는지 확인해 어떤 하드웨어가 오류를 보고했는지 좁혀보세요.","메인보드 매뉴얼에서 NMI/디버그 헤더 위치를 확인해 실수로 점퍼나 스위치가 눌린 상태는 아닌지 점검하세요."],"link":"error-code-0x00000080.html","detailPage":"error-code-0x00000080.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000080)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"메모리 교차 시험으로 해결될 때","action":"사례처럼 문제 모듈을 교체하세요."},{"condition":"최소 구성으로 재현되지 않을 때","action":"장치를 하나씩 되꽂으며 원인 장치를 특정하세요."},{"condition":"전원 점검으로도 해결되지 않을 때","action":"제조사 진단이나 서비스 접수로 넘어가세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["80","00000080","0x80"],"communityCases":[{"title":"MemTest86로 불량 램 슬롯을 특정해 해결한 사례","summary":"몇 주간 불규칙하게 NMI_HARDWARE_FAILURE 블루스크린이 발생했던 사례가 있습니다. MemTest86을 돌려보니 특정 슬롯에 꽂힌 램에서만 수백 개의 오류가 나왔고, 해당 램을 교체한 뒤로 블루스크린이 완전히 멈췄습니다.","insight":"많은 NMI 오류가 램이 완전히 고장 나서가 아니라 슬롯 접촉 불량이나 특정 모듈만의 불량 때문에 발생합니다. 우선 램을 재장착해보고, 그래도 반복되면 MemTest86으로 스틱별로 나눠 테스트해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x80 NMI_HARDWARE_FAILURE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x80--nmi-hardware-failure"}},{"code":"0x0000007F","title":"UNEXPECTED_KERNEL_MODE_TRAP","overview":"CPU가 자체적으로 처리할 수 없는 하드웨어 예외(더블 폴트 등)를 만났을 때 나타나는 코드로, 오버클럭으로 인한 CPU 불안정이나 과열, 메인보드 전원부 문제가 대표적인 원인입니다. 소프트웨어 버그보다 프로세서 자체의 물리적 한계나 전력 공급 불안정과 직접 연결되는 경우가 많아, 다른 블루스크린보다 하드웨어 원인일 가능성이 상대적으로 높은 코드로 꼽힙니다. 특히 블루스크린 화면이나 덤프의 첫 번째 매개변수 값이 8(더블 폴트)로 표시된다면 CPU나 메인보드의 물리적 결함을 강하게 시사합니다.","summary":"CPU가 처리할 수 없는 하드웨어 예외를 만났을 때 나타나는 코드로, 오버클럭으로 인한 CPU 불안정이나 과열이 대표적인 원인입니다.","causes":["CPU나 램의 오버클럭 설정이 시스템 안정성 한계를 넘은 경우","CPU 쿨링이 부족해 부하 시 과열로 오작동하는 경우","메인보드 전원부(VRM)가 CPU에 안정적인 전압을 공급하지 못하는 경우","CPU 자체의 물리적 결함이나 소켓 핀 접촉 불량","램 불안정으로 CPU가 잘못된 명령어나 데이터를 처리하게 되는 경우","메인보드 바이오스가 오래되어 특정 CPU 세대의 전력 관리(C-State 등)를 제대로 지원하지 못하는 경우"],"checks":["오버클럭 설정을 모두 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","CPU 온도를 모니터링 프로그램으로 확인하고, 쿨러 장착 상태와 서멀 그리스 상태를 점검하세요.","메모리 진단 도구로 램 상태를 점검하세요.","CPU를 재장착해 소켓 핀 접촉 상태를 확인하세요(무리한 힘을 주지 않도록 주의).","가능하다면 다른 메인보드나 CPU로 교차 테스트해 부품 자체의 결함인지 좁혀보세요.","블루스크린 화면이나 덤프 분석에서 매개변수(Parameter 1)가 8(더블 폴트)로 나온다면 CPU·메인보드 하드웨어 결함 가능성을 우선적으로 의심하세요."],"link":"error-code-0x0000007f.html","detailPage":"error-code-0x0000007f.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000007F)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"오버클럭·XMP 해제 후 해결될 때","action":"재적용하지 말고 기본 설정을 유지하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"해당 모듈을 교체하세요."},{"condition":"매번 다른 모듈이 지목될 때","action":"하드웨어 불안정 가능성이 크므로 전원·발열 점검을 우선하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["7f","0000007f","0x7f"],"communityCases":[{"title":"새로 추가한 사운드카드의 드라이버 재설치로 해결한 사례","summary":"사운드카드를 새로 장착한 직후부터 이 블루스크린이 반복됐던 사례가 있습니다. GPU·CPU 온도는 모두 정상 범위였는데, 새로 설치한 사운드카드의 드라이버를 완전히 제거하고 제조사 최신 버전으로 재설치한 뒤 문제가 사라졌습니다.","insight":"온도가 정상이라도 오버클럭이나 발열만 의심하지 말고, 최근 추가한 하드웨어의 드라이버 자체를 먼저 점검해보는 것이 좋습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x7F UNEXPECTED_KERNEL_MODE_TRAP","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x7f--unexpected-kernel-mode-trap"}},{"code":"0x00000101","title":"CLOCK_WATCHDOG_TIMEOUT","overview":"멀티코어 CPU에서 특정 코어가 정해진 시간 안에 시스템 인터럽트에 응답하지 못했을 때 나타나는 코드입니다. 오버클럭이나 CPU 자체의 불안정, 오래된 바이오스 펌웨어가 흔한 원인으로 꼽힙니다. 이 오류는 실제로 응답하지 않은 코어 번호가 매개변수에 함께 기록되므로, 이벤트 뷰어나 덤프 분석 시 어떤 코어가 문제였는지 특정할 수 있다는 점이 다른 CPU 관련 블루스크린과의 차이점입니다.","summary":"멀티코어 CPU에서 특정 코어가 정해진 시간 안에 시스템 인터럽트에 응답하지 못했을 때 나타나는 코드입니다.","causes":["CPU 오버클럭 설정이 특정 코어에서만 불안정을 일으키는 경우","CPU 쿨링 부족으로 특정 코어가 스로틀링되며 응답이 지연되는 경우","바이오스/UEFI 펌웨어가 오래되어 최신 CPU 전원 관리를 제대로 지원하지 못하는 경우","CPU 자체의 코어 결함이나 물리적 손상","전원 관리 관련 드라이버나 칩셋 드라이버가 오래된 경우","CPU 소켓 자체의 물리적 결함으로 특정 코어에만 전력·신호가 불안정하게 공급되는 경우"],"checks":["오버클럭 설정을 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","메인보드 제조사 홈페이지에서 최신 바이오스/UEFI 펌웨어로 업데이트하세요.","CPU 온도와 쿨러 장착 상태를 점검하세요.","칩셋 드라이버와 전원 관리 드라이버를 최신 버전으로 업데이트하세요.","CPU 부하 테스트 도구(예: Prime95, Cinebench)로 특정 코어에서만 오류가 나는지 확인해 하드웨어 결함 여부를 좁혀보세요.","가능하다면 BIOS에서 문제 코어만 비활성화(코어 분리)해 재현되는지 테스트하면 하드웨어 결함 코어를 특정하는 데 도움이 됩니다."],"link":"error-code-0x00000101.html","detailPage":"error-code-0x00000101.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000101)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"BIOS 기본값 복원 후 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"XMP·EXPO 해제 후 해결될 때","action":"메모리 프로파일을 다시 켜지 말고 기본 속도로 유지하세요."},{"condition":"온도·전압이 정상인데도 반복될 때","action":"BIOS 업데이트를 검토하거나 CPU 자체 결함 가능성을 확인하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["101","00000101","0x101"],"communityCases":[{"title":"CPU 언더볼팅으로 해결한 사례","summary":"새로 조립한 PC에서 부하가 걸릴 때마다 CLOCK_WATCHDOG_TIMEOUT 블루스크린이 발생했던 사례가 있습니다. CPU에 순간적으로 전압이 부족해지는 것이 원인으로 지목됐고, 오버클럭을 기본값으로 초기화해도 재발해 CPU 코어 전압을 소폭 낮추는(언더볼팅) 방식으로 안정화한 뒤 재발하지 않았습니다.","insight":"이 오류는 전압이 '높아서'가 아니라 특정 부하 상황에서 순간적으로 전압이 부족해질 때도 발생할 수 있습니다. 오버클럭 초기화로 해결되지 않는다면 전압 관련 BIOS 설정과 파워서플라이 상태까지 점검해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x101 CLOCK_WATCHDOG_TIMEOUT","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x101---clock-watchdog-timeout"}},{"code":"0x0000012B","title":"FAULTY_HARDWARE_CORRUPTED_PAGE","overview":"윈도우 메모리 관리자가 하드웨어에 의해 손상된 메모리 페이지를 발견했을 때 나타나는 코드로, WHEA_UNCORRECTABLE_ERROR(0x124)와 마찬가지로 하드웨어 자체의 결함을 직접 가리키는 블루스크린입니다. 마이크로소프트 문서에 따르면 매개변수 3, 4가 모두 0이면 메모리 관리자가 0으로 채워져 있어야 할 페이지에서 단일 비트 오류를 발견한 경우이고, 두 값이 0이 아니면 압축 저장소 관리자가 물리 메모리 손상으로 페이지 압축 해제에 실패한 경우입니다. 대부분 램의 단일 비트 오류나 드라이버의 잘못된 DMA(직접 메모리 접근) 동작이 원인입니다.","summary":"윈도우 메모리 관리자가 하드웨어에 의해 손상된 메모리 페이지를 발견했을 때 나타나는 코드로, 램의 단일 비트 오류가 흔한 원인입니다.","causes":["램 모듈에 물리적 결함이 있어 특정 비트가 손상되는 경우","드라이버나 장치가 DMA(직접 메모리 접근)를 잘못 수행해 물리 메모리를 손상시키는 경우","메인보드나 장치 펌웨어가 전원 전환 과정에서 메모리를 잘못 덮어쓰는 경우","램 오버클럭(XMP/EXPO)이 안정성 한계를 넘은 경우","오래된 램이나 서로 다른 규격의 램을 혼용해 타이밍이 불안정한 경우","바이러스 백신이나 보안 소프트웨어가 메모리를 스캔하는 과정에서 손상된 페이지를 건드려 블루스크린으로 이어지는 경우"],"checks":["메모리 진단 도구(mdsched.exe 또는 MemTest86)로 여러 패스에 걸쳐 램 상태를 점검하세요.","BIOS에서 XMP/EXPO나 오버클럭 설정을 해제하고 기본 클럭으로 되돌린 뒤 재현 여부를 확인하세요.","램을 한 개씩 꽂아가며 재부팅해 특정 모듈이 원인인지 확인하세요.","최근 설치하거나 업데이트한 드라이버(특히 저장장치, 그래픽, 네트워크)를 점검하세요.","이벤트 뷰어에서 WHEA-Logger 관련 이벤트를 확인해 어떤 하드웨어가 오류를 보고했는지 좁혀보세요.","덤프 분석 시 매개변수 3·4가 0인지 아닌지 확인하면 단순 램 불량인지, 장치의 DMA 오작동인지 원인 범위를 좁힐 수 있습니다."],"link":"error-code-0x0000012b.html","detailPage":"error-code-0x0000012b.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000012B)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"메모리를 하나만 장착했을 때 재현되지 않을 때","action":"문제가 있는 모듈을 특정해 교체하세요."},{"condition":"MemTest86에서 오류가 발견될 때","action":"데이터를 먼저 백업한 뒤 해당 모듈을 교체하세요."},{"condition":"XMP·EXPO 해제 후 정상일 때","action":"오버클럭을 다시 적용하지 말고 기본 속도를 유지하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["12b","0000012b","0x12b"],"communityCases":[{"title":"램 증설로 해결한 사례","summary":"게임 중 이 블루스크린이 반복됐던 사례에서, 램 진단 도구로는 특별한 이상이 발견되지 않았습니다. 당시 시스템 램이 게임 실행 중 거의 소진되는 상태였는데, 램을 추가로 증설한 뒤 더 이상 블루스크린이 발생하지 않았습니다.","insight":"이 오류는 램 불량뿐 아니라 메모리 부족 상황에서 페이지 처리 과정의 문제로도 발생할 수 있습니다. 램 진단이 정상으로 나온다면 메모리 사용량과 여유 공간도 함께 확인해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x12B FAULTY_HARDWARE_CORRUPTED_PAGE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x12b---faulty-hardware-corrupted-page"}},{"code":"0x000000F2","title":"HARDWARE_INTERRUPT_STORM","overview":"특정 하드웨어 장치가 인터럽트 신호를 계속 활성 상태로 유지해 시스템이 다른 작업을 처리하지 못하고 멈춰버렸을 때 나타나는 코드입니다. 마이크로소프트 정의상 레벨 트리거 인터럽트 신호가 계속 활성(asserted) 상태로 유지되는 상황을 뜻하며, 시스템이 이를 치명적으로 판단해 즉시 하드 행(bus lock) 처리하는 것이 특징입니다. 장치나 슬롯의 하드웨어 결함, 혹은 두 장치 간 IRQ 충돌이 흔한 원인으로 꼽힙니다.","summary":"특정 하드웨어 장치가 인터럽트 신호를 계속 활성 상태로 유지해 시스템이 멈춰버렸을 때 나타나는 코드입니다.","causes":["특정 확장 카드나 주변장치가 인터럽트 신호를 계속 보내는 하드웨어 결함이 있는 경우","두 개 이상의 장치가 같은 IRQ 리소스를 두고 충돌하는 경우","PCIe 슬롯이나 카드 접촉 불량으로 신호가 불안정하게 유지되는 경우","오래되었거나 손상된 장치 드라이버가 인터럽트를 잘못 처리하는 경우","메인보드 자체의 인터럽트 컨트롤러 결함","BIOS의 레거시 인터럽트 라우팅 설정이 최신 하드웨어와 맞지 않는 경우"],"checks":["최근 추가하거나 교체한 확장 카드·주변장치가 있다면 하나씩 제거해 재현 여부를 확인하세요.","장치 관리자에서 리소스(IRQ) 충돌이 있는지 확인하세요.","모든 카드와 케이블을 재장착해 접촉 상태를 점검하세요.","의심되는 장치의 드라이버를 최신 버전으로 업데이트하거나 재설치하세요.","원인이 좁혀지지 않으면 확장 카드를 다른 슬롯으로 옮겨 재현 여부를 확인하세요.","BIOS/UEFI를 최신 버전으로 업데이트해 인터럽트 라우팅 관련 알려진 버그가 수정되었는지 확인하세요."],"link":"error-code-0x000000f2.html","detailPage":"error-code-0x000000f2.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000F2)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"장치를 분리한 뒤 재현되지 않을 때","action":"하나씩 다시 꽂으며 어느 장치가 원인인지 특정하세요."},{"condition":"드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"BIOS 업데이트로도 해결되지 않을 때","action":"메인보드 자체의 IRQ 라우팅 결함일 수 있으니 다른 메인보드에서 해당 장치를 테스트해보세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["f2","000000f2","0xf2"],"communityCases":[{"title":"보조 하드디스크 캐디 분리로 해결한 사례","summary":"두 번째 하드디스크를 캐디에 장착해 추가한 직후부터 이 블루스크린이 반복됐던 사례가 있습니다. 캐디의 특정 핀이 광학 드라이브 상태를 계속 BIOS에 알리는 신호를 보내면서 인터럽트가 끊이지 않고 발생한 것이 원인이었고, 캐디를 분리한 뒤 문제가 사라졌습니다.","insight":"최근 추가한 저장장치나 확장 카드가 있다면, 드라이버 문제보다 하드웨어 자체가 인터럽트 신호를 계속 보내고 있는 것은 아닌지 의심해볼 필요가 있습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xF2 HARDWARE_INTERRUPT_STORM","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xf2--hardware-interrupt-storm"}},{"code":"0x00000117","title":"VIDEO_TDR_TIMEOUT_DETECTED","overview":"그래픽 드라이버가 GPU 응답을 기다리다 시간 초과(TDR)로 복구를 시도했지만 완전히 회복하지 못했을 때 나타나는 코드로, 0x116(VIDEO_TDR_FAILURE)과 원인이 유사한 GPU 관련 블루스크린입니다. 0x116과 달리 이 코드는 TDR(Timeout Detection and Recovery) 복구 절차 자체가 시간 초과로 실패했음을 명시적으로 가리켜, 드라이버 재시작으로도 GPU가 응답을 회복하지 못했다는 더 심각한 신호로 해석됩니다. 그래픽카드 과열이나 전원 불안정, 오버클럭이 흔한 원인입니다.","summary":"그래픽 드라이버가 GPU 응답을 기다리다 시간 초과(TDR)로 복구를 시도했지만 완전히 회복하지 못했을 때 나타나는 코드입니다.","causes":["GPU가 고부하 상황에서 과도하게 발열되는 경우","그래픽카드 보조 전원 케이블 연결이 불안정한 경우","GPU나 VRAM 오버클럭 설정이 안정성 한계를 넘은 경우","그래픽 드라이버 자체의 버그나 특정 게임·프로그램과의 호환성 문제","그래픽카드가 물리적으로 노후화되어 열화된 경우","레지스트리의 TDR 관련 타임아웃 값(TdrDelay 등)이 너무 짧게 설정되어 정상적인 고부하 작업까지 시간 초과로 처리되는 경우"],"checks":["그래픽 드라이버를 DDU 같은 클린 제거 도구로 완전히 제거한 뒤 최신 버전으로 재설치하세요.","GPU 온도를 모니터링 프로그램으로 확인하고, 쿨러와 서멀 패드 상태를 점검하세요.","그래픽카드 보조 전원 케이블이 완전히 꽂혀 있는지 확인하세요.","GPU나 VRAM을 오버클럭했다면 기본 클럭으로 되돌려 재현 여부를 확인하세요.","가능하다면 다른 그래픽카드로 교체 테스트해 하드웨어 자체의 결함인지 좁혀보세요.","고사양 렌더링·딥러닝 작업이 잦다면 레지스트리의 TdrDelay 값을 신중하게 늘려 정상 작업이 시간 초과로 오인되지 않는지 확인해보세요(변경 전 백업 필수)."],"link":"error-code-0x00000117.html","detailPage":"error-code-0x00000117.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000117)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 클린 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"특정 시점 변경을 되돌려 해결될 때","action":"그 변경을 다시 적용하지 마세요."},{"condition":"오버클럭 해제로도 해결되지 않을 때","action":"보조전원 케이블 연결과 파워 용량을 다시 점검하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["117","00000117","0x117"],"communityCases":[{"title":"그래픽 드라이버 클린 재설치로 해결한 사례","summary":"고사양 게임 실행 중 이 블루스크린이 반복됐던 사례가 있습니다. GPU 온도와 전원 케이블 연결에는 문제가 없었는데, 그래픽 드라이버를 DDU로 완전히 제거한 뒤 최신 버전으로 재설치하자 더 이상 재현되지 않았습니다.","insight":"TDR 관련 블루스크린은 하드웨어보다 드라이버 자체의 잔여 파일이나 손상이 원인인 경우도 많습니다. 온도·전원에 문제가 없다면 드라이버 클린 재설치를 먼저 시도해보는 것이 좋습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x117 VIDEO_TDR_TIMEOUT_DETECTED","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x117---video-tdr-timeout-detected"}},{"code":"0x00000113","title":"VIDEO_DXGKRNL_FATAL_ERROR","overview":"Windows DirectX 그래픽 커널이 더 이상 진행할 수 없는 위반을 감지했을 때 나타나는 블루스크린입니다. 게임·영상 작업·절전 복귀, 특히 내장 그래픽과 외장 그래픽을 함께 쓰는 노트북에서 드라이버·전원 관리 호환성을 함께 확인해야 합니다.","summary":"DirectX 그래픽 커널이 치명적인 오류를 감지해 중지한 그래픽 계열 블루스크린입니다.","causes":["Intel·AMD 또는 내장·외장 GPU 조합의 전원 관리·드라이버 호환성 문제","그래픽 드라이버 손상 또는 최근 Windows·드라이버 업데이트 충돌","GPU 과열·오버클럭·보조전원 불안정으로 그래픽 명령 처리가 실패한 경우"],"checks":["노트북은 GPU 제조사 범용 드라이버보다 PC 제조사 지원 페이지의 권장 그래픽 드라이버를 먼저 비교하세요.","그래픽 드라이버를 안정 버전으로 클린 재설치하고, 오버클럭·언더볼트 설정은 기본값으로 되돌리세요.","절전 복귀에서만 반복되면 절전·최대 절전 사용 여부와 발생 시각을 기록하고 BIOS·칩셋 업데이트 안내를 확인하세요."],"link":"common-error-codes.html?code=0x00000113","detailPage":"common-error-codes.html?code=0x00000113","relatedSymptom":"hardware-no-display.html","aliases":["113","00000113","0x113","video dxgkrnl fatal error","dxgkrnl"],"communityCases":[{"title":"노트북 제조사 권장 그래픽 드라이버로 교체 해결","summary":"게임 중 또는 절전 복귀 시 이 블루스크린이 반복됐던 노트북 사례가 있습니다. NVIDIA 공식 최신 드라이버로는 재현됐지만, 노트북 제조사 지원 페이지의 권장 드라이버 버전을 설치하자 재발하지 않았습니다.","insight":"노트북에서 GPU 관련 블루스크린이 발생한다면 GPU 제조사 최신 드라이버보다 노트북 제조사 권장 드라이버가 더 안정적일 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x113 VIDEO_DXGKRNL_FATAL_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x113---video-dxgkrnl-fatal-error"}},{"code":"0x00000079","title":"MISMATCHED_HAL","overview":"윈도우가 사용하는 HAL(하드웨어 추상화 계층)과 커널의 버전이나 구성이 서로 일치하지 않을 때 나타나는 코드로, 메인보드나 CPU를 교체한 직후 부팅 과정에서 자주 발생합니다. 마이크로소프트 문서에서는 이 코드가 싱글 프로세서용 HAL과 멀티프로세서 커널의 조합, 혹은 그 반대인 경우를 명시적으로 언급하고 있어, 하드웨어 구성 변경 이력이 있는 시스템에서 특히 주의 깊게 살펴봐야 할 코드입니다. 대부분 시스템 파일 손상보다는 하드웨어 구성 변경과 직접 관련이 있습니다.","summary":"윈도우가 사용하는 HAL과 커널의 버전이나 구성이 일치하지 않을 때 나타나는 코드로, 메인보드나 CPU를 교체한 직후 자주 발생합니다.","causes":["메인보드나 CPU를 교체한 뒤 기존 윈도우 설치와 새 하드웨어 구성이 맞지 않는 경우","싱글 프로세서용 HAL이 설치된 시스템에 멀티프로세서 CPU를 장착한 경우(또는 그 반대)","Ntoskrnl.exe나 Hal.dll 파일을 수동으로 교체하거나 손상시킨 경우","부팅 구성 데이터(BCD)가 새 하드웨어 구성을 반영하지 못한 경우","바이오스/UEFI 설정에서 CPU 관련 모드가 최근 변경된 경우","클론(복제)된 디스크를 사양이 다른 PC로 옮겨 설치한 경우"],"checks":["최근 메인보드나 CPU를 교체했다면, 가능하면 이전 하드웨어로 정상 부팅되는지 먼저 확인하세요.","복구 환경에서 sfc /scannow로 시스템 파일 손상 여부를 점검하세요.","BIOS/UEFI 설정에서 CPU 관련 옵션이 최근 변경되었는지 확인하고 기본값으로 되돌려 보세요.","복구로 해결되지 않으면 새 하드웨어에 맞춰 윈도우를 재설치하는 것을 고려하세요.","윈도우 재설치 전 중요한 데이터는 반드시 백업해 두세요.","클론(복제)된 디스크를 사용 중이라면, 클론이 아닌 새 설치로 전환하는 것이 근본적인 해결책이 될 수 있습니다."],"link":"error-code-0x00000079.html","detailPage":"error-code-0x00000079.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000079)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"시스템 파일 원복으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"BIOS ACPI 설정 복원으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"복원 지점으로도 해결되지 않을 때","action":"사례처럼 메인보드를 교체했다면 새로 설치를 고려하세요."}],"relatedSymptom":"hardware-no-display.html","aliases":["79","00000079","0x79"],"communityCases":[{"title":"메인보드 교체 후 재설치로 해결한 사례","summary":"메인보드를 새 제품으로 교체한 뒤 이전 윈도우가 설치된 디스크를 그대로 연결했더니 이 블루스크린이 발생했던 사례가 있습니다. 복구 환경에서 시스템 파일 복구를 시도해도 해결되지 않았고, 결국 새 하드웨어에 맞춰 윈도우를 새로 설치한 뒤에야 정상적으로 부팅됐습니다.","insight":"메인보드나 CPU를 완전히 교체한 경우, 기존 설치를 복구하려 하기보다 처음부터 새로 설치하는 편이 더 빠르고 확실한 해결책이 될 수 있습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x79 MISMATCHED_HAL","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x79--mismatched-hal"}},{"code":"0x000000FE","title":"BUGCODE_USB_DRIVER","overview":"USB 드라이버나 연결된 USB 장치에서 처리할 수 없는 오류가 발생했을 때 나타나는 코드입니다. 마이크로소프트 드라이버 문서 기준으로도 USB 컨트롤러 자체의 결함, 손상된 드라이버, 연결 장치의 하드웨어 결함 세 가지로 원인을 나누고 있어, 장치·포트·드라이버를 순서대로 소거하며 점검하는 접근이 효율적입니다. 장치 자체의 하드웨어 결함이나 USB 컨트롤러의 불안정이 흔한 원인으로 꼽힙니다.","summary":"USB 드라이버나 연결된 USB 장치에서 처리할 수 없는 오류가 발생했을 때 나타나는 코드로, 장치 자체의 하드웨어 결함이 흔한 원인입니다.","causes":["연결된 USB 장치(외장하드, 키보드, 허브 등) 자체에 하드웨어 결함이 있는 경우","USB 포트나 컨트롤러가 물리적으로 손상되었거나 접촉 불량인 경우","USB 드라이버가 손상되었거나 최신 윈도우 빌드와 호환되지 않는 경우","여러 USB 장치를 허브에 과도하게 연결해 전력 공급이 불안정한 경우","메인보드 칩셋 드라이버가 오래되어 USB 컨트롤러 동작이 불안정한 경우","정전기(ESD)로 인해 USB 컨트롤러 칩이 손상된 경우"],"checks":["연결된 모든 USB 장치를 분리한 뒤 하나씩 다시 연결해 어떤 장치가 원인인지 좁혀보세요.","USB 장치를 다른 포트(가능하면 메인보드 후면 포트)에 연결해 재현 여부를 확인하세요.","장치 관리자에서 USB 컨트롤러 드라이버를 최신 버전으로 업데이트하세요.","메인보드 칩셋 드라이버를 제조사 홈페이지에서 최신 버전으로 업데이트하세요.","USB 허브를 사용 중이라면 허브 없이 메인보드에 직접 연결해 전력 공급 문제인지 확인하세요.","정전기 방지 조치 없이 USB 장치를 자주 탈부착했다면, 컨트롤러 손상 가능성을 염두에 두고 다른 시스템에서도 같은 장치가 오작동하는지 교차 확인하세요."],"link":"error-code-0x000000fe.html","detailPage":"error-code-0x000000fe.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x000000FE)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"특정 USB 장치를 분리했을 때 재현되지 않을 때","action":"그 장치의 드라이버를 업데이트하거나 다른 포트를 사용하세요."},{"condition":"본체 직결로 해결될 때","action":"허브 대신 전원 공급형 허브 사용을 고려하세요."},{"condition":"USB 선택적 절전 해제로도 해결되지 않을 때","action":"USB 컨트롤러 드라이버 재설치로 넘어가세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["fe","000000fe","0xfe"],"communityCases":[{"title":"USB 선택적 절전 기능 해제로 해결한 사례","summary":"특정 USB 캡처 장치를 사용할 때마다 이 블루스크린이 반복됐던 사례가 있습니다. 장치와 드라이버를 여러 번 재설치해도 해결되지 않았는데, 전원 옵션에서 'USB 선택적 절전 모드'를 해제한 뒤 문제가 사라졌습니다.","insight":"USB 관련 블루스크린이 장치를 오래 사용한 뒤에만 발생한다면 절전 관련 설정을, 사용 시작부터 바로 발생한다면 드라이버나 포트 자체를 먼저 의심해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0xFE BUGCODE_USB_DRIVER","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xfe--bugcode-usb-driver"}},{"code":"0x0000005C","title":"HAL_INITIALIZATION_FAILED","overview":"윈도우 부팅이나 절전 모드 복귀 과정에서 HAL(하드웨어 추상화 계층)이 초기화에 실패했을 때 나타나는 코드로, 대부분 하드웨어 자체의 문제나 장치 드라이버 결함과 관련이 있습니다. 특히 절전 모드(Sleep/Hibernate) 복귀 시점에 반복된다면 전원 관리와 관련된 특정 드라이버나 펌웨어의 초기화 실패일 가능성이 높고, 부팅 초기 단계에서 발생한다면 하드웨어 자체의 초기화 실패일 가능성이 더 큽니다.","summary":"윈도우 부팅이나 절전 모드 복귀 과정에서 HAL이 초기화에 실패했을 때 나타나는 코드로, 하드웨어 자체의 문제와 관련이 있는 경우가 많습니다.","causes":["메인보드나 CPU 등 핵심 하드웨어가 최근 변경되어 기존 시스템 구성과 맞지 않는 경우","바이오스/UEFI 펌웨어가 오래되어 최신 하드웨어를 완전히 지원하지 못하는 경우","특정 드라이버가 절전 모드 복귀 시 초기화에 실패하는 경우","저장장치나 램의 접촉 불량으로 부팅 초기 단계에서 오류가 발생하는 경우","전원 공급 불안정으로 하드웨어 초기화가 중간에 중단되는 경우","펌웨어(UEFI) 보안 부팅(Secure Boot) 설정과 하드웨어 구성이 맞지 않는 경우"],"checks":["메인보드 제조사 홈페이지에서 최신 바이오스/UEFI 펌웨어로 업데이트하세요.","저장장치와 램의 연결 상태를 물리적으로 다시 확인하세요.","절전 모드 복귀 시에만 발생한다면, 전원 옵션에서 절전 모드 대신 화면 끄기만 사용하도록 임시로 바꿔 재현 여부를 확인하세요.","최근 변경한 하드웨어가 있다면 이전 상태로 되돌려 재현 여부를 확인하세요.","파워 서플라이 용량과 케이블 연결 상태를 점검하세요.","Secure Boot을 일시적으로 비활성화해 재현 여부를 확인해보고, 관련이 있다면 펌웨어 설정을 재구성하거나 업데이트하세요."],"link":"error-code-0x0000005c.html","detailPage":"error-code-0x0000005c.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000005C)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"하드웨어를 원래 상태로 되돌려 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"SATA 모드 확인으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"BIOS 기본값 복원으로도 해결되지 않을 때","action":"시작 복구로 넘어가되, 먼저 반드시 백업하세요."}],"relatedSymptom":"hardware-no-display.html","aliases":["5c","0000005c","0x5c"],"communityCases":[{"title":"HPET 활성화로 해결한 사례","summary":"절전 모드에서 복귀할 때마다 이 블루스크린이 반복됐던 사례가 있습니다. 바이오스/UEFI에서 HPET(고정밀 이벤트 타이머) 관련 설정을 확인해 활성화한 뒤로 절전 모드 복귀 시 블루스크린이 더 이상 발생하지 않았습니다.","insight":"절전 모드 복귀 시에만 반복되는 이 오류는 하드웨어 고장이 아니라 타이머 관련 바이오스 설정 때문인 경우가 있습니다. 하드웨어를 교체하기 전에 바이오스의 전원·타이머 관련 옵션을 먼저 점검해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x5C HAL_INITIALIZATION_FAILED","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x5c--hal-initialization-failed"}},{"code":"0x00000154","title":"UNEXPECTED_STORE_EXCEPTION","overview":"커널 메모리 저장소(Store) 구성 요소가 예기치 않은 예외를 감지했을 때 나타나는 코드로, 저장장치(SSD/NVMe)의 펌웨어나 컨트롤러 드라이버 문제와 관련이 깊습니다. Windows 10/11에서 새로 추가된 비교적 최신 블루스크린 코드로, 0x1E(KMODE_EXCEPTION_NOT_HANDLED)와 함께 나타나는 경우도 있습니다.","summary":"커널 메모리 저장소 구성 요소가 예기치 않은 예외를 감지했을 때 나타나는 코드로, 저장장치 펌웨어나 컨트롤러 드라이버 문제와 관련이 깊습니다.","causes":["SSD·NVMe 저장장치의 펌웨어가 오래되었거나 버그가 있는 경우","저장장치 컨트롤러 드라이버가 손상되었거나 최신 윈도우 빌드와 호환되지 않는 경우","디스크 배드섹터나 파일 시스템 손상으로 저장소 구성 요소가 잘못된 데이터를 읽는 경우","저장장치 전원 관리(절전) 설정이 불안정하게 동작하는 경우","메인보드 칩셋 드라이버가 오래되어 저장장치 통신이 불안정한 경우"],"checks":["저장장치 제조사 홈페이지에서 최신 펌웨어가 있는지 확인하고 업데이트하세요.","저장장치 컨트롤러 드라이버와 메인보드 칩셋 드라이버를 최신 버전으로 업데이트하세요.","명령 프롬프트에서 chkdsk /f 를 실행해 디스크 오류를 점검하고 수정하세요.","전원 옵션에서 저장장치 절전(선택적 USB 절전 포함) 설정을 임시로 꺼서 재현 여부를 확인하세요.","제조사 진단 툴(예: CrystalDiskInfo)로 S.M.A.R.T 상태와 재할당 섹터 수를 확인하세요."],"link":"error-code-0x00000154.html","detailPage":"error-code-0x00000154.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000154)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"SMART 경고가 발견될 때","action":"데이터 백업을 최우선으로 하고 저장장치 교체를 검토하세요."},{"condition":"chkdsk로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"펌웨어 업데이트로도 해결되지 않을 때","action":"메모리 진단으로 넘어가세요."}],"relatedSymptom":"hardware-nvme-delay.html","aliases":["154","00000154","0x154"],"communityCases":[{"title":"NVMe SSD 펌웨어 업데이트로 해결한 사례","summary":"NVMe SSD 교체 이후 간헐적으로 이 블루스크린이 발생했던 사례가 있습니다. 제조사 도구로 SSD 펌웨어를 업데이트하자 이후 재발하지 않았습니다. 초기 펌웨어 버전에 알려진 호환성 버그가 있었습니다.","insight":"SSD 교체 후 이 블루스크린이 발생한다면 SSD 펌웨어 업데이트를 먼저 확인하세요. 새로 출시된 SSD 제품은 초기 펌웨어에 버그가 있는 경우가 있습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x154 UNEXPECTED_STORE_EXCEPTION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x154--unexpected-store-exception"}},{"code":"0x00000109","title":"CRITICAL_STRUCTURE_CORRUPTION","overview":"커널이 중요한 커널 코드나 데이터 구조가 변조된 것을 감지했을 때 나타나는 코드입니다. 드라이버가 커널 영역을 잘못 수정했거나, 램 불량으로 메모리 내용이 깨졌거나, 타사 보안 프로그램이 커널을 강제로 수정하려다 발생하는 경우가 흔합니다. Windows 11에서는 VBS(가상화 기반 보안)가 강화되면서 발생 빈도가 이전 OS보다 높아진 코드이기도 합니다.","summary":"커널이 중요한 커널 코드나 데이터 구조가 변조된 것을 감지했을 때 나타나는 코드로, 드라이버의 커널 영역 침범이나 메모리 손상이 흔한 원인입니다.","causes":["오작동하는 드라이버가 커널 코드나 데이터 영역을 잘못 수정한 경우","메인보드 램이 불안정하거나 오버클럭 설정이 시스템 안정성 한계를 넘은 경우","타사 백신·보안 프로그램이 커널 메모리를 강제로 수정하려다 충돌하는 경우","Windows 11의 VBS(가상화 기반 보안)·코어 격리 기능과 특정 드라이버가 호환되지 않는 경우","악성코드가 커널 영역에 침투를 시도한 경우"],"checks":["장치 관리자에서 최근 설치·업데이트한 드라이버를 확인하고 이전 버전으로 롤백해 보세요.","메모리 진단 도구(mdsched.exe 또는 MemTest86)로 램 상태를 점검하세요.","BIOS에서 XMP나 오버클럭 설정을 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","설정 > 개인 정보 및 보안 > Windows 보안 > 장치 보안에서 코어 격리(메모리 무결성)를 임시로 꺼서 특정 드라이버와의 충돌인지 확인하세요.","최근 설치한 보안 프로그램을 임시로 비활성화한 뒤 증상이 사라지는지 확인하세요."],"link":"error-code-0x00000109.html","detailPage":"error-code-0x00000109.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000109)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"커널 개입 프로그램 제거로 해결될 때","action":"재발 방지를 위해 그 프로그램의 수정된 버전이 나올 때까지 사용을 자제하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."},{"condition":"오버클럭 해제로도 해결되지 않을 때","action":"sfc·DISM으로 시스템 파일 손상 여부를 점검하세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["109","00000109","0x109"],"communityCases":[{"title":"코어 격리 충돌 드라이버 업데이트로 해결","summary":"윈도우 11 업그레이드 이후 이 블루스크린이 발생했던 사례가 있습니다. 설정에서 코어 격리(메모리 무결성)를 끄자 호환되지 않는 드라이버 경고가 표시됐고, 해당 드라이버를 업데이트하자 메모리 무결성을 다시 켜도 재발하지 않았습니다.","insight":"윈도우 11에서 이 오류가 발생한다면 코어 격리와 충돌하는 드라이버가 있을 수 있습니다. 메모리 무결성을 끄고 호환되지 않는 드라이버 경고를 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x109 CRITICAL_STRUCTURE_CORRUPTION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x109---critical-structure-corruption"}},{"code":"0x0000009E","title":"USER_MODE_HEALTH_MONITOR","overview":"csrss.exe처럼 핵심적인 사용자 모드 프로세스를 커널이 주기적으로 감시(헬스 체크)하다가, 해당 프로세스가 정상적으로 응답하지 않는다고 판단했을 때 나타나는 코드입니다. 0xC000021A·0xEF(CRITICAL_PROCESS_DIED)와 증상이 비슷하지만, 프로세스가 완전히 죽은 게 아니라 '응답 없음' 상태로 판정됐다는 차이가 있습니다.","summary":"핵심 사용자 모드 프로세스가 정상적으로 응답하지 않는다고 커널이 판단했을 때 나타나는 코드로, CRITICAL_PROCESS_DIED와 증상이 비슷합니다.","causes":["그래픽 드라이버나 로그인 관련 셸 확장이 응답 없음 상태에 빠진 경우","보안 소프트웨어가 핵심 프로세스의 응답을 지연시키는 경우","디스크 병목이나 배드섹터로 인해 프로세스가 필요한 리소스를 제때 읽지 못하는 경우","최근 윈도우 업데이트가 시스템 프로세스와 충돌하는 경우","맬웨어가 시스템 프로세스 동작을 방해하는 경우"],"checks":["안전 모드로 부팅해 정상 동작 여부를 확인하세요. 정상이라면 최근 설치한 드라이버나 프로그램을 의심하세요.","명령 프롬프트에서 sfc /scannow를 실행해 손상된 시스템 파일을 검사하고 복구합니다.","디스크 상태 점검 도구로 배드섹터나 응답 지연이 있는지 확인하세요.","최근 설치한 보안 프로그램을 임시로 비활성화한 뒤 재현 여부를 확인하세요.","이벤트 뷰어에서 이 코드 발생 직전 어떤 서비스나 프로세스가 관여했는지 확인하세요."],"link":"error-code-0x0000009e.html","detailPage":"error-code-0x0000009e.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000009E)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"감시 소프트웨어 제거로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"저장장치 응답 지연이 확인될 때","action":"디스크 상태 점검으로 넘어가세요."},{"condition":"소프트웨어 업데이트로도 해결되지 않을 때","action":"서버 환경이라면 마이크로소프트 지원에 문의하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["9e","0000009e","0x9e"],"communityCases":[{"title":"안전 모드에서 최근 드라이버 제거로 해결","summary":"새 프린터 드라이버를 설치한 이후 이 블루스크린이 발생했던 사례가 있습니다. 안전 모드로 부팅해 최근 설치한 프린터 드라이버를 제거하자 정상 부팅됐습니다.","insight":"핵심 프로세스 응답 없음 오류는 최근 설치한 드라이버나 프로그램과 관련이 많습니다. 안전 모드를 활용해 최근 변경 사항과의 연관성을 확인하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x9E USER_MODE_HEALTH_MONITOR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x9e--user-mode-health-monitor"}},{"code":"0x00000119","title":"VIDEO_SCHEDULER_INTERNAL_ERROR","overview":"그래픽 드라이버를 관리하는 비디오 스케줄러가 치명적인 오류를 감지했을 때 나타나는 코드로, 0x116(VIDEO_TDR_FAILURE)·0x117(VIDEO_TDR_TIMEOUT_DETECTED)과 함께 GPU 관련 블루스크린의 대표 코드로 꼽힙니다. 그래픽 드라이버가 커널의 잘못되거나 손상된 메모리 주소에 접근하면서 명령 제출에 실패할 때 흔히 발생합니다.","summary":"그래픽 드라이버를 관리하는 비디오 스케줄러가 치명적인 오류를 감지했을 때 나타나는 코드로, GPU 드라이버나 하드웨어 문제와 관련이 깊습니다.","causes":["그래픽 드라이버가 오래되었거나 손상된 경우","그래픽카드가 슬롯에 제대로 장착되지 않았거나 접촉 불량인 경우","GPU 과열이나 전력 공급 불안정으로 명령 처리가 실패하는 경우","램 불량으로 그래픽 드라이버가 잘못된 메모리 주소에 접근하는 경우","그래픽카드나 노트북에 물리적 충격(낙하 등)이 가해진 직후 발생하는 경우"],"checks":["그래픽 드라이버를 제조사(NVIDIA/AMD/Intel) 홈페이지에서 완전히 제거(DDU 등) 후 최신 버전으로 재설치하세요.","그래픽카드가 PCIe 슬롯에 제대로 장착되어 있는지 다시 확인하세요.","GPU 온도와 팬 동작을 모니터링해 과열 여부를 확인하세요.","메모리 진단 도구로 램 상태를 점검하세요.","파워 서플라이 용량과 그래픽카드 보조 전원 케이블 연결 상태를 확인하세요."],"link":"error-code-0x00000119.html","detailPage":"error-code-0x00000119.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000119)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"오버클럭·언더볼팅 해제로 해결될 때","action":"재적용하지 말고 기본값을 유지하세요."},{"condition":"내장 그래픽에서는 정상일 때","action":"그래픽카드 자체의 결함 가능성이 있으므로 다른 시스템에서 테스트해보세요."}],"relatedSymptom":"hardware-gaming-reboot.html","aliases":["119","00000119","0x119"],"communityCases":[{"title":"GPU 드라이버 DDU 클린 설치로 스케줄러 오류 해결","summary":"게임 중 이 블루스크린이 반복됐던 사례에서, 드라이버를 여러 번 업데이트해도 해결되지 않았습니다. DDU 도구로 그래픽 드라이버를 완전히 초기화하고 안정 버전으로 재설치하자 이후 재발하지 않았습니다.","insight":"GPU 스케줄러 오류는 드라이버 잔여 파일이 원인인 경우가 많습니다. 일반 업데이트보다 DDU를 이용한 클린 재설치가 더 효과적입니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x119 VIDEO_SCHEDULER_INTERNAL_ERROR","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x119---video-scheduler-internal-error"}},{"code":"0x0000013A","title":"KERNEL_MODE_HEAP_CORRUPTION","overview":"커널 모드 힙 관리자가 메모리 힙의 손상을 감지했을 때 나타나는 코드로, 사용 후 해제(use-after-free)나 버퍼 오버플로 같은 드라이버 결함, 또는 램 자체의 하드웨어 결함이 흔한 원인입니다. 0x139(KERNEL_SECURITY_CHECK_FAILURE)와 마찬가지로 커널 메모리 손상 계열의 블루스크린입니다.","summary":"커널 모드 힙 관리자가 메모리 힙의 손상을 감지했을 때 나타나는 코드로, 드라이버의 메모리 오용이나 램 결함이 흔한 원인입니다.","causes":["특정 드라이버가 이미 해제된 메모리를 다시 사용하거나 버퍼 범위를 벗어나 쓰는 경우","메인보드 램이 불안정하거나 접촉 불량인 경우","램 오버클럭(XMP)이 시스템 안정성 한계를 넘은 경우","타사 보안 프로그램이나 튜닝 도구가 커널 메모리를 잘못 다루는 경우","최근 설치한 드라이버가 최신 윈도우 빌드와 호환되지 않는 경우"],"checks":["장치 관리자에서 최근 설치·업데이트한 드라이버를 확인하고 이전 버전으로 롤백해 보세요.","메모리 진단 도구(mdsched.exe 또는 MemTest86)로 램 상태를 점검하세요.","BIOS에서 XMP나 오버클럭 설정을 기본값으로 되돌린 뒤 재현 여부를 확인하세요.","최근 설치한 보안·튜닝 프로그램을 임시로 제거한 뒤 재현 여부를 확인하세요.","덤프 파일을 BlueScreenView 등으로 열어 어떤 드라이버(.sys)가 함께 표시되는지 확인하세요."],"link":"error-code-0x0000013a.html","detailPage":"error-code-0x0000013a.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x0000013A)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"덤프에서 특정 드라이버가 지목될 때","action":"그 드라이버를 롤백하거나 최신 버전으로 업데이트하세요."},{"condition":"드라이버 검사기로 원인이 좁혀질 때","action":"확인이 끝나면 반드시 <code>verifier /reset</code>으로 해제하세요."},{"condition":"메모리 진단에서 오류가 발견될 때","action":"램 모듈을 하나씩 장착해가며 어떤 모듈이 문제인지 확인하세요."}],"relatedSymptom":"windows-bsod-critical-process.html","aliases":["13a","0000013a","0x13a"],"communityCases":[{"title":"XMP 오버클럭 해제로 커널 힙 손상 오류 해결","summary":"XMP 프로파일로 메모리를 오버클럭한 상태에서 이 블루스크린이 간헐적으로 발생했던 사례가 있습니다. BIOS에서 XMP를 비활성화하고 기본 속도로 설정하자 이후 재발하지 않았습니다.","insight":"이 오류는 드라이버 버그뿐 아니라 메모리 오버클럭 불안정으로도 발생합니다. MemTest86으로 메모리 안정성을 먼저 확인하고, XMP 설정도 점검하세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x13A KERNEL_MODE_HEAP_CORRUPTION","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x13a--kernel-mode-heap-corruption"}},{"code":"0x00000144","title":"BUGCODE_USB3_DRIVER","overview":"USB 3.0(xHCI) 컨트롤러 스택이 USB 클라이언트의 잘못된 동작을 감지했거나, USB 3.0 컨트롤러·펌웨어 자체에 심각한 문제가 발생했을 때 나타나는 코드입니다. USB 3.0으로 연결된 부팅 장치의 하드웨어 결함으로 발생하는 경우도 있습니다.","summary":"USB 3.0(xHCI) 컨트롤러 스택에서 심각한 오류가 발생했을 때 나타나는 코드로, USB 3.0 컨트롤러·펌웨어나 연결 장치의 결함과 관련이 깊습니다.","causes":["USB 3.0으로 연결된 장치(외장하드, 허브 등) 자체에 하드웨어 결함이 있는 경우","메인보드의 USB 3.0(xHCI) 컨트롤러 드라이버가 오래되었거나 손상된 경우","메인보드·노트북의 USB 관련 BIOS/UEFI 펌웨어가 오래된 경우","USB 허브에 장치를 과도하게 연결해 전력 공급이 불안정한 경우","정전기(ESD)로 인해 USB 3.0 컨트롤러 칩이 손상된 경우"],"checks":["연결된 모든 USB 3.0 장치를 분리한 뒤 하나씩 다시 연결해 어떤 장치가 원인인지 좁혀보세요.","메인보드 제조사 홈페이지에서 칩셋·USB 컨트롤러 드라이버와 BIOS/UEFI 펌웨어를 최신 버전으로 업데이트하세요.","장치를 USB 2.0 포트에 연결했을 때도 같은 문제가 재현되는지 확인해 USB 3.0 컨트롤러 자체의 문제인지 좁혀보세요.","USB 허브를 사용 중이라면 허브 없이 메인보드에 직접 연결해 전력 공급 문제인지 확인하세요.","문제가 특정 USB 부팅 장치에서만 발생한다면 해당 장치를 다른 시스템에서도 테스트해 장치 자체의 결함인지 확인하세요."],"link":"error-code-0x00000144.html","detailPage":"error-code-0x00000144.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000144)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"USB 2.0 포트에서는 정상일 때","action":"3.0 컨트롤러 드라이버 재설치로 넘어가세요."},{"condition":"후면 포트에서 해결될 때","action":"전면 패널 케이블 연결 상태를 점검하세요."},{"condition":"외장 저장장치 전원 문제로 해결될 때","action":"항상 별도 전원이나 Y케이블 두 단자를 모두 사용하세요."}],"relatedSymptom":"hardware-usb-not-detected.html","aliases":["144","00000144","0x144"],"communityCases":[{"title":"USB 3.0 허브 제거로 USB3 드라이버 오류 해결","summary":"USB 3.0 허브를 통해 여러 장치를 연결한 상태에서 이 블루스크린이 반복됐던 사례가 있습니다. 허브를 제거하고 장치를 메인보드에 직접 연결하자 문제가 해결됐습니다.","insight":"USB 3.0 관련 블루스크린이 발생하면 먼저 USB 허브를 제거하고 메인보드 포트에 직접 연결해보세요. 허브의 전력 부족이나 칩셋 호환성 문제가 원인인 경우가 많습니다."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x144 BUGCODE_USB3_DRIVER","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x144--bugcode-usb3-driver"}},{"code":"0x00000164","title":"WIN32K_CRITICAL_FAILURE","overview":"화면 표시와 입력을 담당하는 Win32k(윈도우 관리·그래픽 서브시스템)가 치명적인 오류를 만났을 때 나타나는 코드입니다. 그래픽 드라이버 결함이나 디스플레이 관련 시스템 파일 손상과 관련이 깊고, 로그인 직후나 화면 전환 시점에 반복되며 부팅 루프로 이어지는 경우도 보고됩니다.","summary":"화면 표시와 입력을 담당하는 Win32k 서브시스템이 치명적인 오류를 만났을 때 나타나는 코드로, 그래픽 드라이버 결함이 흔한 원인입니다.","causes":["그래픽 드라이버가 손상되었거나 최신 윈도우 빌드와 호환되지 않는 경우","디스플레이·윈도우 관리 관련 시스템 파일이 손상된 경우","다중 모니터 구성이나 배율(스케일링) 설정 변경 직후 발생하는 경우","최근 윈도우 업데이트가 그래픽 서브시스템과 충돌하는 경우","원격 데스크톱이나 화면 녹화 소프트웨어의 가상 디스플레이 드라이버 충돌"],"checks":["그래픽 드라이버를 제조사 홈페이지에서 완전히 제거(DDU 등) 후 최신 버전으로 재설치하세요.","명령 프롬프트에서 sfc /scannow를 실행해 손상된 시스템 파일을 검사하고 복구합니다.","안전 모드로 부팅이 되는지 확인하세요. 안전 모드에서 정상이라면 그래픽 드라이버나 최근 설치한 프로그램을 의심하세요.","다중 모니터나 화면 배율 설정을 최근에 바꿨다면 이전 설정으로 되돌려 재현 여부를 확인하세요.","부팅 루프가 발생한다면 복구 환경(고급 옵션)에서 최근 업데이트 제거를 시도하세요."],"link":"error-code-0x00000164.html","detailPage":"error-code-0x00000164.html","faq":[{"q":"블루스크린 코드가 한 번 떴는데 계속 지켜봐야 하나요?","a":"이 문제(0x00000164)가 한 번만 발생했다면 즉시 부품을 교체하기보다 재현 여부와 최근 변경 사항을 먼저 기록해두는 것으로 충분합니다. 반복된다면 그때 하드웨어 점검 범위를 넓히세요."},{"q":"덤프 파일은 어디서 확인하나요?","a":"C:\\Windows\\Minidump 폴더에 저장되며, BlueScreenView 같은 도구로 열어 정지 코드와 관련 드라이버를 확인할 수 있습니다."}],"decisionSteps":[{"condition":"그래픽 드라이버 재설치로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"오버레이·화면 녹화 도구 제거로 해결될 때","action":"그 프로그램의 수정된 버전이 나올 때까지 사용을 자제하세요."},{"condition":"업데이트 제거로 해결될 때","action":"다음 누적 업데이트가 나올 때까지 해당 업데이트 설치를 보류하세요."}],"relatedSymptom":"windows-black-screen-after-login.html","aliases":["164","00000164","0x164"],"communityCases":[{"title":"그래픽 드라이버 DDU 클린 재설치로 Win32k 오류 해결","summary":"로그인 직후 또는 화면 전환 시 이 블루스크린이 발생했던 사례가 있습니다. 안전 모드로 부팅해 DDU 도구로 그래픽 드라이버를 완전히 제거하고 최신 버전으로 재설치하자 이후 재발하지 않았습니다.","insight":"Win32k 서브시스템 오류는 그래픽 드라이버 문제와 관련이 많습니다. 안전 모드에서 DDU를 이용한 클린 재설치를 먼저 시도해보세요."}],"officialSource":{"title":"Microsoft Learn: Bug Check 0x164 WIN32K_CRITICAL_FAILURE","url":"https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0x164--win32k-critical-failure"}},{"code":"0x80070079","title":"세마포 제한 시간이 만료되었습니다","overview":"외장 하드나 네트워크 드라이브로 파일을 복사·이동하는 도중 연결이 정해진 시간 안에 응답하지 않을 때 나타나는 오류입니다. 파일이나 폴더 자체보다 전송 경로(케이블, 네트워크, USB 브리지 칩)의 응답 지연이 원인인 경우가 많습니다.","summary":"대용량 파일을 외장 저장장치나 네트워크 드라이브로 복사할 때 연결이 제한 시간 안에 응답하지 않아 나타납니다.","causes":["무선 네트워크 신호 불안정 또는 유선보다 느린 전송 속도","외장 하드케이스의 USB-SATA 브리지 칩이나 케이블 노후화","네트워크 어댑터 드라이버가 오래되었거나 절전 설정과 충돌하는 경우","백신·보안 프로그램이 대용량 전송 중 실시간 검사로 지연을 유발하는 경우","저장장치 자체의 배드섹터나 응답 지연으로 전송이 멈추는 경우"],"checks":["가능하면 무선 대신 유선 랜으로 연결을 바꾼 뒤 재현 여부를 확인하세요.","외장 하드는 케이블과 USB 포트를 바꿔 연결해 접촉 불량인지 확인하세요.","네트워크 어댑터 드라이버를 최신 버전으로 업데이트하고, 전원 관리에서 절전 옵션을 꺼보세요.","백신 실시간 검사를 잠시 끄고 같은 전송을 다시 시도해 원인인지 확인하세요.","디스크 상태 점검 도구로 저장장치의 배드섹터나 건강 상태를 확인하세요."],"link":"error-code-0x80070079.html","detailPage":"error-code-0x80070079.html","faq":[{"q":"세마포 오류가 뜨면 저장장치가 고장난 건가요?","a":"항상 그렇지는 않습니다. 무선 네트워크 불안정이나 케이블 접촉 불량처럼 연결 경로의 문제로도 자주 발생합니다. 유선 연결·케이블 교체부터 확인한 뒤에도 반복되면 저장장치 자체를 의심하세요."},{"q":"외장 하드에서만 이 오류가 나는데 원인이 뭘까요?","a":"USB-SATA 브리지 칩이나 케이블이 노후화되어 대용량 전송 중 응답이 늦어지는 경우가 흔합니다. 다른 케이블·포트로 바꿔 재현되는지 먼저 확인하세요."}],"decisionSteps":[{"condition":"유선 연결로 바꿔 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"케이블·포트 교체로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"드라이버 업데이트로도 해결되지 않을 때","action":"디스크 상태 점검 도구로 배드섹터 여부를 확인하세요."}],"relatedSymptom":"windows-network-drive-error.html","aliases":["80070079","0x80070079","세마포 제한 시간","세마포 시간 제한","semaphore timeout"],"communityCases":[{"title":"유선 랜 연결로 세마포 오류 해결","summary":"무선 네트워크로 NAS에 대용량 파일을 복사할 때마다 반복되던 이 오류가, 유선 랜으로 연결 방식을 바꾼 뒤로는 재발하지 않았던 사례가 있습니다.","insight":"무선 연결의 신호 불안정이 전송 응답 지연으로 이어져 이 오류를 유발하는 경우가 흔합니다. 가능하면 대용량 전송은 유선 연결에서 진행하세요."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_SEM_TIMEOUT","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x00000709","title":"프린터를 기본 프린터로 설정할 수 없습니다","overview":"네트워크로 공유된 프린터를 기본 프린터로 지정하려 할 때 나타나는 오류로, 프린터 이름이 실제 공유 이름과 일치하지 않거나 인쇄 스풀러·드라이버 문제로 프린터를 정상적으로 인식하지 못할 때 발생합니다.","summary":"공유된 네트워크 프린터를 기본 프린터로 설정하려 할 때 프린터 이름을 인식하지 못해 나타날 수 있습니다.","causes":["프린터를 공유하는 호스트 PC에서 프린터 이름이 변경되었거나 공유가 해제된 경우","클라이언트 PC에 해당 프린터 드라이버가 제대로 설치되지 않은 경우","인쇄 스풀러 서비스가 응답하지 않거나 손상된 경우","네트워크 프린터 연결 프로토콜(공유 폴더 권한 등)에 문제가 있는 경우","공유 프린터에 접근할 사용자 권한이 없는 경우"],"checks":["제어판에서 문제의 네트워크 프린터를 제거한 뒤 다시 추가해보세요.","인쇄 스풀러 서비스를 재시작(services.msc)한 뒤 다시 시도하세요.","프린터를 공유하는 호스트 PC에서 프린터 이름과 공유 상태가 그대로인지 확인하세요.","제조사 홈페이지에서 최신 드라이버를 받아 다시 설치하세요.","공유 프린터에 접근할 사용자 계정 권한이 있는지 호스트 PC에서 확인하세요."],"link":"error-code-0x00000709.html","detailPage":"error-code-0x00000709.html","faq":[{"q":"프린터를 삭제하고 다시 추가하면 설정이 다 사라지나요?","a":"기본 인쇄 설정(용지 크기, 품질 등)은 초기화될 수 있지만, 문서나 인쇄 기록이 사라지지는 않습니다. 다시 추가한 뒤 필요한 설정만 다시 지정하면 됩니다."},{"q":"다른 PC에서는 같은 프린터가 잘 되는데 제 PC에서만 안 돼요.","a":"내 PC의 프린터 드라이버가 오래됐거나 손상됐을 가능성이 큽니다. 제조사 홈페이지에서 최신 드라이버를 받아 다시 설치해보세요."}],"decisionSteps":[{"condition":"프린터 재추가로 해결될 때","action":"사례처럼 재발 여부만 지켜보면 됩니다."},{"condition":"스풀러 재시작으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"권한 확인으로도 해결되지 않을 때","action":"호스트 PC의 프린터 이름과 공유 상태를 다시 확인하세요."}],"relatedSymptom":"windows-printer-offline.html","aliases":["00000709","0x00000709","709","프린터 오류 709","기본 프린터로 설정할 수 없습니다"],"communityCases":[{"title":"인쇄 스풀러 재시작으로 해결","summary":"사무실 네트워크 프린터를 기본 프린터로 지정할 때마다 이 오류가 반복됐던 사례가 있습니다. 인쇄 스풀러 서비스를 재시작하고 프린터를 다시 추가하자 정상적으로 설정됐습니다.","insight":"프린터를 다시 추가하기 전에 인쇄 스풀러 서비스부터 재시작해보는 것이 가장 간단하고 효과적인 첫 조치입니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_INVALID_PRINTER_NAME","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--1700-3999-"}},{"code":"0xC004C003","title":"Windows 정품 인증을 받지 않았습니다","overview":"메인보드나 SSD 같은 주요 부품을 교체하거나 대규모 업데이트를 진행한 뒤 Windows 라이선스가 현재 하드웨어 구성과 일치하지 않는다고 판단될 때 나타나는 인증 오류입니다.","summary":"메인보드·SSD 같은 주요 부품을 교체하거나 큰 업데이트를 진행한 뒤 라이선스가 하드웨어와 일치하지 않는다고 판단될 때 나타납니다.","causes":["메인보드를 교체해 디지털 라이선스가 연결된 하드웨어 정보가 바뀐 경우","정품 Windows를 클린 설치했지만 Microsoft 계정과 라이선스가 아직 연결되지 않은 경우","대규모 기능 업데이트 이후 활성화 서버와의 재확인이 지연되는 경우","볼륨 라이선스·KMS 방식으로 인증됐던 PC가 인증 서버와 통신하지 못하는 경우","정품이 아니거나 다른 PC에서 이미 사용 중인 제품 키인 경우"],"checks":["설정 > 시스템 > 정품 인증에서 문제 해결사를 실행해 자동 복구를 먼저 시도하세요.","메인보드를 교체했다면 Microsoft 계정으로 로그인한 뒤 계정과 라이선스를 다시 연결하세요.","인터넷 연결 상태를 확인해 활성화 서버와 정상적으로 통신되는지 점검하세요.","회사·학교 PC라면 관리자에게 볼륨 라이선스·KMS 서버 상태를 확인해달라고 요청하세요.","정식 경로로 구매한 제품 키인지 확인하고, 필요하면 Microsoft 지원팀에 문의하세요."],"link":"error-code-0xc004c003.html","detailPage":"error-code-0xc004c003.html","faq":[{"q":"메인보드를 바꾸면 무조건 재인증해야 하나요?","a":"디지털 라이선스가 Microsoft 계정에 연결되어 있었다면 계정 로그인만으로 자동 복구되는 경우가 많습니다. 연결되어 있지 않았다면 문제 해결사를 실행하거나 지원팀에 문의해야 합니다."},{"q":"정품이 아닌데 이 오류가 뜨는 건가요?","a":"아닙니다. 정품이라도 하드웨어 구성이 크게 바뀌면 일시적으로 이 오류가 나타날 수 있습니다. 문제 해결사와 계정 연결부터 먼저 시도하세요."}],"decisionSteps":[{"condition":"문제 해결사만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"Microsoft 계정 재연결로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"계정 연결로도 해결되지 않을 때","action":"볼륨 라이선스·KMS 상태를 관리자와 함께 재확인하세요."}],"relatedSymptom":"windows-activation-error.html","aliases":["0xc004c003","c004c003","정품인증 오류","windows 정품 인증을 받지 않았습니다"],"communityCases":[{"title":"Microsoft 계정 재연결로 정품 인증 복구","summary":"메인보드를 교체한 뒤 이 오류가 발생했던 사례가 있습니다. Microsoft 계정으로 로그인해 설정에서 라이선스를 다시 연결하자 곧바로 정품 인증이 복구됐습니다.","insight":"부품 교체 전에 Windows가 Microsoft 계정에 연결되어 있었다면, 계정 로그인만으로 대부분 자동 복구됩니다. 문제 해결사부터 먼저 실행해보세요."}],"officialSource":{"title":"Microsoft 지원: Windows 정품 인증 오류 해결","url":"https://support.microsoft.com/windows/windows-활성화-오류-코드-사용-시-Windows-활성화-문제-해결-0424bef9-9a26-4359-2f42-757f5ec62ee5"}},{"code":"0x8007007B","title":"제품 키가 올바르지 않습니다 (재인증 실패)","overview":"Windows를 재인증하거나 제품 키를 다시 입력할 때 네트워크 연결 문제, 잘못된 키 입력, 또는 라이선스 불일치로 인증 서버와 정상적으로 통신하지 못해 나타나는 오류입니다.","summary":"Windows 재인증이나 제품 키 입력 과정에서 인증 서버와 통신에 실패하거나 키가 일치하지 않을 때 나타납니다.","causes":["인터넷 연결이 끊어져 있거나 불안정해 인증 서버와 통신하지 못하는 경우","제품 키를 잘못 입력했거나 다른 Windows 에디션용 키를 입력한 경우","이미 다른 PC에서 사용 중인 라이선스를 중복으로 입력한 경우","손상된 시스템 파일로 인증 관련 서비스가 정상 동작하지 않는 경우","방화벽·보안 프로그램이 인증 서버 접속을 차단하는 경우"],"checks":["인터넷 연결 상태를 확인하고, 가능하면 유선 연결로 다시 시도하세요.","제품 키와 Windows 에디션(Home/Pro 등)이 일치하는지 다시 확인하세요.","명령 프롬프트(관리자)에서 sfc /scannow를 실행해 시스템 파일을 점검하세요.","방화벽·백신을 잠시 끄고 인증을 다시 시도해 차단 여부를 확인하세요.","반복되면 설정 > 정품 인증의 문제 해결사를 실행하거나 Microsoft 지원팀에 문의하세요."],"link":"error-code-0x8007007b.html","detailPage":"error-code-0x8007007b.html","narrative":"이 오류가 헷갈리는 이유는 이름과 달리 '제품 키를 잘못 입력했다'는 뜻만은 아니기 때문입니다. 실제로는 재인증 요청 자체가 인증 서버와 정상적으로 통신하지 못했을 때도 같은 오류가 뜹니다. 그래서 키를 여러 번 다시 입력해봐도 안 되는 경우, 문제는 키 자체가 아니라 그 요청이 서버까지 도달하는 경로(네트워크 연결, 방화벽)에 있을 가능성을 먼저 의심해봐야 합니다.","faq":[{"q":"제품 키를 정확히 입력했는데도 이 오류가 뜨는 이유는?","a":"키 자체보다 인증 서버와의 통신 문제인 경우가 흔합니다. 네트워크 연결부터 점검하고, 방화벽·백신이 차단하고 있지 않은지 확인하세요."},{"q":"다른 PC에서 쓰던 키를 입력해도 되나요?","a":"소매용(Retail) 키가 아니라면 한 번에 한 대의 PC에서만 활성화됩니다. 이미 다른 PC에서 사용 중이라면 이 오류가 발생할 수 있습니다."}],"decisionSteps":[{"condition":"유선 연결로 해결될 때","action":"무선 환경 개선을 검토하세요."},{"condition":"sfc /scannow로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"방화벽 해제로도 해결되지 않을 때","action":"Microsoft 지원팀에 문의하세요."}],"relatedSymptom":"windows-activation-error.html","aliases":["0x8007007b","8007007b","제품키 오류","재인증 실패"],"communityCases":[{"title":"유선 연결로 재인증 성공","summary":"무선 네트워크에서 계속 이 오류가 나던 사례가 있습니다. 유선 랜으로 연결을 바꾼 뒤 재인증을 시도하자 바로 성공했습니다.","insight":"인증 서버와의 통신이 불안정하면 이 오류가 흔히 발생합니다. 키 자체보다 네트워크 연결부터 점검하는 것이 빠릅니다."}],"officialSource":{"title":"Microsoft Learn: System Error Codes — ERROR_INVALID_NAME","url":"https://learn.microsoft.com/en-us/windows/win32/debug/system-error-codes--0-499-"}},{"code":"0x80240FFF","title":"Windows Update 알 수 없는 오류","overview":"Windows Update가 업데이트를 확인·다운로드·설치하는 과정에서 구체적인 원인을 특정하지 못한 채 실패했을 때 나타나는 일반적인 오류입니다.","summary":"Windows Update 진행 중 구체적인 원인 없이 실패했을 때 나타나는 일반 오류 코드입니다.","causes":["Windows Update 구성 요소(캐시, 서비스)가 일시적으로 손상된 경우","이전 업데이트 설치가 비정상적으로 중단되어 잔여 파일이 충돌하는 경우","디스크 공간 부족으로 업데이트 파일을 받거나 설치하지 못하는 경우","타사 보안 프로그램이 업데이트 프로세스를 차단하는 경우","네트워크 연결이 불안정해 다운로드가 중간에 끊기는 경우"],"checks":["Windows Update 문제 해결사(설정 > 시스템 > 문제 해결)를 실행해 자동 복구를 시도하세요.","명령 프롬프트(관리자)에서 Windows Update 서비스를 중지한 뒤 SoftwareDistribution 폴더 이름을 바꾸고 서비스를 다시 시작하세요.","디스크 여유 공간이 충분한지 확인하세요(권장 20GB 이상).","백신·보안 프로그램을 잠시 끄고 업데이트를 다시 시도해보세요.","유선 네트워크로 연결을 바꿔 안정적인 상태에서 다시 시도하세요."],"link":"error-code-0x80240fff.html","detailPage":"error-code-0x80240fff.html","faq":[{"q":"SoftwareDistribution 폴더를 지우면 업데이트 기록이 사라지나요?","a":"이미 설치된 업데이트는 그대로 남고, 다운로드 캐시만 다시 받게 됩니다. 설치 기록이나 시스템 자체에는 영향이 없습니다."},{"q":"매번 다른 코드가 뜨는데도 이 방법이 통하나요?","a":"네, Windows Update 구성 요소 초기화는 원인이 명확하지 않은 대부분의 업데이트 오류에 공통으로 시도해볼 수 있는 기본 조치입니다."}],"decisionSteps":[{"condition":"문제 해결사만으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"캐시 폴더 초기화로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"백신 비활성화·유선 연결로도 해결되지 않을 때","action":"미디어 생성 도구로 제자리 업그레이드를 고려하세요."}],"relatedSymptom":"windows-update-fail-loop.html","aliases":["0x80240fff","80240fff","windows update 알 수 없는 오류"],"communityCases":[{"title":"SoftwareDistribution 폴더 초기화로 해결","summary":"업데이트가 이 오류로 계속 실패했던 사례가 있습니다. Windows Update 서비스를 중지하고 SoftwareDistribution 폴더 이름을 바꾼 뒤 서비스를 재시작하자 정상적으로 업데이트가 진행됐습니다.","insight":"원인이 특정되지 않는 일반 업데이트 오류는 캐시 폴더 초기화만으로 해결되는 경우가 많습니다. 재설치보다 먼저 시도해볼 조치입니다."}],"officialSource":{"title":"Microsoft 지원: Windows Update 문제 해결","url":"https://support.microsoft.com/windows/windows-업데이트-문제-해결-188c2b0a-7a86-4fdb-93d6-4f8f3f3e9f3c"}},{"code":"0x80073CF9","title":"Microsoft Store 앱을 설치·업데이트할 수 없습니다","overview":"Microsoft Store에서 앱을 설치하거나 업데이트할 때 스토어 캐시나 라이선스 구성 요소 문제로 나타나는 오류입니다. Xbox 앱, Store 자체 업데이트 등에서도 같은 코드가 나타날 수 있습니다.","summary":"Microsoft Store 앱 설치·업데이트 도중 스토어 캐시나 라이선스 구성 요소 문제로 나타납니다.","causes":["Microsoft Store 앱 캐시가 손상된 경우","Store 관련 백그라운드 서비스(라이선스 관리자 등)가 응답하지 않는 경우","Windows Update와 Store 업데이트가 서로 충돌하는 경우","시스템 날짜·시간이 실제와 맞지 않아 인증서 검증에 실패하는 경우","네트워크 연결이 불안정해 스토어 서버 응답을 받지 못하는 경우"],"checks":["설정 > 앱에서 Microsoft Store를 선택해 '재설정'을 실행하세요(초기화 아님, 데이터만 삭제).","명령 프롬프트에서 wsreset.exe를 실행해 스토어 캐시를 지운 뒤 다시 시도하세요.","시스템 날짜·시간이 자동으로 맞춰져 있는지 확인하세요.","Windows Update를 최신 상태로 진행한 뒤 다시 시도하세요.","그래도 안 되면 Microsoft Store 앱 자체를 PowerShell로 다시 등록해보세요."],"link":"error-code-0x80073cf9.html","detailPage":"error-code-0x80073cf9.html","faq":[{"q":"Xbox 앱에서도 같은 코드가 뜨는데 원인이 같은가요?","a":"네, Xbox 앱도 Microsoft Store와 같은 라이선스·캐시 구성 요소를 공유하기 때문에 같은 코드가 나타날 수 있고, 같은 방법(wsreset)으로 해결되는 경우가 많습니다."},{"q":"스토어를 재설치하면 해결되나요?","a":"재설치보다 재설정(초기화)이나 wsreset.exe로 캐시를 지우는 방법이 먼저 시도해볼 조치입니다. 대부분 재설치 없이 해결됩니다."}],"decisionSteps":[{"condition":"스토어 재설정으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"wsreset으로 해결될 때","action":"재발 여부만 지켜보면 됩니다."},{"condition":"시간 동기화로도 해결되지 않을 때","action":"Microsoft 계정을 로그아웃한 뒤 재로그인해보세요."}],"relatedSymptom":"windows-store-error.html","aliases":["0x80073cf9","80073cf9","마이크로소프트 스토어 오류","xbox 앱 오류"],"communityCases":[{"title":"wsreset으로 스토어 오류 해결","summary":"Xbox 앱과 Microsoft Store에서 이 오류가 반복됐던 사례가 있습니다. wsreset.exe로 스토어 캐시를 초기화하자 이후 정상적으로 설치·업데이트가 진행됐습니다.","insight":"스토어 오류는 재설치보다 캐시 초기화(wsreset)로 해결되는 경우가 많아 먼저 시도해볼 가치가 있습니다."}],"officialSource":{"title":"Microsoft 지원: Microsoft Store 오류 문제 해결","url":"https://support.microsoft.com/microsoft-store/microsoft-store가-작동하지-않는-문제-해결-9eb2606b-4767-e2f2-86ba-f3c92b60c8a3"}}]});
